"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[332],{8332:function(n,b,x){x.d(b,{c:function(){return t}});let a={"1-1":"بسم الله الرحمن الرحيم وصلى الله على سيدنا ومولانا محمد كتاب الاستبصار فى عجائب الأمصار\n[خطبة الكتاب]\nالحمد لله عالم الأسرار، غافر الإضرار، الواحد القهار، العزيز الجبار، المنزه الذي لا يقبض يديه سهاد الليل والنهار؛ نحمده حمد معترف بوحدانيته، ونشكره شكر مغترف من بحر نعمته، متقلب فى ظل رحمته.\nونصلى على نبيه سيدنا محمد المبعوث بالآيات الباهرة، والبينات القاهرة، الآخذ عن النار بالحجزات، الداعى إلى سبيل ربه بالآيات البينات، وعلى آله الأخيار، وأصحابه الأبرار، صلاة باقية إلى يوم الدين.\nونرضى عن نجله الأطهر ، وسليله الأبر، الإمام المهدى ، الذي جدد رسم الدين بعد البلى، وجاهد فى سبيل الله حق جهاده وأبلى، وإلى طريق الحق [دعا] النفرى والجفلى؛ وعن الخلفاء الراشدين، أئمة الهدى، ومصابيح من رشد واهتدى. ونوالى الدعاء لخليفتهم المبارك الأسعد، سيدنا أمير المؤمنين يعقوب بنصر تتصل أسبابه بسعادته، وفتح يسوقه القدر وفق إرادته.\nوبعد، لما كان العلم أنفس ما يقتنى، وأشرف ما به يعتنى، لم يزل ينقله خلف عن سلف ويحمله ذو شرف عن ذى شرف، وجب أن يكون أفضل ما يهديه مهد أو يستهديه مهدى، رغبة فى الاتسام برسمه، والارتسام والدخول\nفى رعيته، والاستثئار بحيازة مآثر من تواريخ الأمم، وسير العرب والعجم، إذ كان المرء يقف منها على أخبار من غبر، وآثار من ذهب ودثر، ويشاهد ممالك ذهبت وبادت ، كأنها عادت إلى الحياة أو كادت:\nلم يبق شىء من الدنيا أسرّ به ... إلا الدفاتر فيها الشعر والخبر\nمات الذين لهم فضل ومكرمة ... وفى الدفاتر من أخبارهم آثر\nوقديما وضع الناس التواريخ ورتبوها، ودونوا الأخبار وكونوها، حرصا منهم على نظم فرائدها وتقييد شواردها، وما زال واضعوها يتقلبون بين إكثار وإقلال، وإسهاب واختصار، وكلهم يجرى على طريقة إلى غاية يضيفها ويسطرها. وكثيرا ما خلد خدم العقلاء ملوك أزمنتهم بالتواريخ المؤلفة والتواليف المزخرفة، تفننا لمسراتهم وترضيا لمبراتهم، ولولا ذلك لم يحصل الأخر على علم الأول، ولا عرفت أخبار الملل والدول.\nولذلك رأيت الشيخ الأجل المعظم، الأغر الأسنى، الأمجد المكرم، أبا عمران بن الشيخ الأرفع، المرحوم أبى يحيى بن وقتين أدام الله علاهم، ووصل مجدهم وسراهم، قد أبرز على الفضلاء فضلا، وأربى على النبلاء نبلا، وزاد على أهل زمانه فى العلم والحلم، وغبطة بالعلم ووصل العلماء ومراضاة الفقهاء. وكانت همته السامية إلى طراف الأخبار، وإيثار أهل الآثار، إلى أن شادت بذلك الرفاق، وامتلأت بحديثه الآفاق، ونازعتنى الرغبة والتصدى لشكر النعمة، إلى أن أطرز باسمه كتابا يجمع بين الأخبار والصحائف، ويأخذ بطرفى شرائد الطرائف، متضمنا بذلك إحسانه، راجيا بذلك فضله وامتنانه بمنه حسبما أردته. و [لما] اتسق وصفه على ما اخترت، سميته بكتاب الاستبصار فى عجائب الأمصار، بعد أن قصدت فى أكثره التحقيق واطرحت فى مستودعه التلفيق.\nوابتدأت بمكة شرفها الله تعالى، وما يجب ذكره من وصف حرمها، وأسماء الجبال المحيطة بها، وذكر أرباضها، ووصف المسجد الحرام بحسب الوسع، وذرع الكعبة من خارج، ووصفها من داخل. ووصفت الصفا والمروة، وعرفة ومزدلفة، ومنى وجبل الرحمة، مع شريعة إبراهيم عليه السلام وصفة بطن محسّر إلى غير ذلك من المناسك، وصفة مسجد رسول الله صلى الله عليه وسلم بالمدينة. ووصفت منبره عليه السلام، ووصفت عدد أبواب المسجد، وجميع ما فيه من العمد وعدد ما فيه من القناديل، ووصف روضته عليه السلام. ثم وصفت بقية المدينة، وروضة عثمان رضى الله عنه ووصفت مسجد قبا، وقبور الشهداء بأحد رحمة الله عليهم تبركا بذلك وتيمنا بالاستفتاح به.\nثم عدت إلى بلاد مصر وما فيها من العجائب، ووصفت نيل مصر وعدد أمياله، من وسطه إلى موقعه، وذكرت بناء الأهرامات والبرابى ومن بناها، وصورتها وطولها وعرضها وما صنع فيها من العجائب؛ وذكرت من عمرها من الملوك قبل الطوفان وما نزل بها بهذا الطوفان؛ وذكرت فتحها فى أيام سيدنا عمر بن الخطاب رضى الله عنه. ثم عدت إلى مدينة الإسكندرية، ووصفت بناءها وصفة منارها وصفة المرآة التى كانت بها وبناءها وتداول الملوك عليها.\nثم ذكرت بلاد إفريقية وما فيها من العجائب، ووصفت مدينة قرطاجنة وآثارها وعجائبها، ووصفت البلاد الى آخر بلاد المغرب. وقسمت أقطارها قسمين، ورتبتها صنفين: فمنها الصحراوية أو ما قاربها، والساحلية وما يليها.\nولم أذكر شيئا مما سقته إلا ما كاد ينعقد على أكثره الإجماع، ويتفق عليه العيان والسماع، وللمولى أدام الله تأييده ووصل سعوده، أن يقدر عبده فيما أورده، ويحقق فيما رجاه أمله ومعتمده، فإنه وإن كان قد أنفذ وسعه فى الاختيار، وتوسط بين الإقلال والإكثار، حرى بالاحسان\nظنا، ويرى التغميض عن هناته سنا، إذ هو فيما ذكر كمن حمل التمر إلى هجر .\nومنك استعدنا كل غريبة، فأنت غريبة فى عيون الغرائب. وهذا حين أبتدىء بذكر ما أردته فيما أوردته، مستعينا بالله سبحانه، راجيا صفحه وغفرانه، والله سبحانه يمتع الأدب ببقاء المولى، ويشكره ما منح الخلق من يده وأولى:\nالناس يهدون على قدرهم ... وإننى أهدى على قدركا\nيهدون ما يفنى وأهدى الذي ... يبقى على الأزمان من فخركا\nذكر حدود حرم مكة شرفها الله\nحدّ الحرم من ناحية المدينة من ذى طوى على ثلاثة أميال من مكة، وحده من طريق جدّة على عشرة أميال، وحده من طريق اليمن على سبعة أميال، وحده من طريق العراق على ستة أميال، وحده من طريق الطائف على أحد عشر ميلا فعدد أميال الحرم ميلا ، ودور الحرم حول مكة ميلا ؛ وكان النبي - صلى الله عليه وسلم - بنى بالحرمين مسجدا .\n[وصف مكة شرفها الله وأرباضها وأسماء الجبال المحيطة بها]\nجبل أبى قبيس وهو جبل أدكن (أميل إلى البياض) ، فى رأسه منار يذكر أنه منار إبراهيم عليه السلام. وفى أصله الصفا ومن عليه يرقى إليه، ليس له مرقى إلا على أربعة مواضع: على الصفا، وعلى شعب عمر، وعلى شعب على رضى الله عنهما، وعلى شعب أجياد الصغير ، ليس لأبى قبيس طريق يرقى إليه إلا من هذه الأربعة مواضع. وهو أحد الأخشبين فيما يقال، ويقال إنه أول جبل خلقه الله تعالى ووضعه فى الأرض. وإنما سمى بأبى قبيس لأن رجلا كان يسكنه على قديم الدهر يكنى بأبى قبيس فنسب إليه ذلك الجبل. وهو أقرب الجبال إلى المسجد الحرام، يقابل من مكة ويقابل من الكعبة الركن الأسود.\nثم جبل الخندمة وهو الجبل العالى المستعلى على أبى قبيس من ناحية الشرق، وهو جبل أحمر محجر فيه صخرة كبيرة بيضاء كأنها معلقة تشبه الإنسان إذا نظرت إليها من البعد، تراها من المسجد الحرام من باب السهميين الصغير. وفى ذلك الجبل تحصن أهل مكة يوم القرمطى .\nوأسفل من ذلك الجبل، بينه وبين الجبل غار، شعب على رضى الله عنه.\nثم الجبل الأبيض الذي على الأبطح إلى باب منى ، ومن ذلك الجبل إلى الجبل الأحمر السور، وجعل هنالك بابين من خشب مصفحين بالحديد، وهما على المعلى وهما المعروفان بباب منى.\nوعند هذا الباب آبار بعيدة الرشا يستقى الناس منها، وماؤها ليس بعذب\n.\nجدا. وهذا الجبل الأحمر متصل من مسجد الخيف إلى الحجون وفيه الثنية العليا، وعند أصل الثنية بقيع مكة . وفى شعب منه المحصّب فى حوز الشعب الذي يقابل الخيف الذي كان ينزل فيه من سلف من الصدر الأول عندهم من منى إلى آخر أيام التشريق ، فيصلون الظهر والعصر والمغرب والعشاء الآخرة، وكذلك يدخلون مكة.\nوقد صح عن النبي - صلى الله عليه وسلم - أنه فعل ذلك .\nثم الجبل الذي بظهر دار الندوة يسمى قعيقعان ، وهو الذي يقابل أبا قبيس، وهو جبل أخضر. وإنما يسمى قعيقعان لأن مضاض بن جرهم نزل به، ونزل السميدع بن جرهم بجبل أجياد، فدارت بينهما حرب عظيمة فى تلك الأيام، فكانت أجياد- أعنى من سكن بها وهو السميدع وآله- أول من جاد بالدم فى الحرم ودعا إلى القتل، وقالت العرب فيها أجياد لأنها أول من جادت بالدم.\nثم جبل أجياد ، وهو الجبل العالى الأخضر الذي بغربى المسجد الحرام فى رأسه منار يذكر أن أبا بكر رضه أمر ببنائه ، ينادى عليه المؤذن فى رمضان، ويقابل من الكعبة اليمانى؛ ويخرج إليه من باب إبراهيم عليه السلام . وهو يقابل قعيقعان من ناحية الغرب.\nثم جبل ابن عمران ، وهو الجبل الأسود الذي بين أبى قبيس وأجياد، وهو خلفهما. ويظهر من البعد كأنه بينهما، يقابل من الكعبة الجدار اليمانى؛ وهو أميل إلى الركن اليمانى قليلا.\nثم جبل البكا ، وهو خارج على الجبال المحيطة بمكة، وهو فى العطف الذي فى آخر ذى طوى، عن يمينك وأنت خارج تريد التنعيم .\nوهناك عن يسارك المتكا ، وهو الحجر الذي قعد عليه النبي - صلى الله عليه وسلم - واستراح عند إقباله عليه فيما يذكر أهل مكة، رووه عن مشيختهم.\n[عدد أرباض مكة شرفها الله]\nولمكة أربعة أرباض منها الحجون وما حوله إلى المروة ، وربض قعيقعان وما حوله إلى باب ذى طوى ، وربض أجياد الكبير","1-2":"مع شعب أبى بكر رضه إلى المسفلة إلى باب اليمانيين، ثم إلى الأبطح وما حوله من باب منى إلى شعب على مع شعب عثمان .\nذرع الكعبة كرمها الله من خارج\nطول وجه الكعبة وهو الشق الذي فيه الباب، من الركن الأسود إلى الركن الشامى ذراعا . وعند الثلث الباقى من هذا الجدار من ناحية الركن الشامى، يوقف منبر الخطيب يوم الجمعة ويرفع فى سائر الأيام، وهو منبر كبير مفصل على ثلاثة قطع . وطول مؤخرها وهو الشق الغربى، من الركن اليمانى إلى الركن الغربى، ذراعا- طول الذراع الذي به هذا الذرع أصبعا . وعرضها من ناحية اليمانى إلى الركن الأسود ذراعا\nونصف ذراع ، وعرضها من ناحية الشام وهو الشق الشامى وهو الذي عليه الميزاب ، من الركن الغربى إلى الركن الشامى، ذراعا .\nهذا ذرع البيت من خارج. وذرعه من داخل: طول الجدار الذي يقابلك إذا دخلت البيت الذي فيه محاريب الفضة ، وهو الذي صلى عليه النبي - صلى الله عليه وسلم -، من الركن الغربى إلى الركن اليمانى، ذراعا .\nوطول الجدار الذي فيه الباب، من الركن الأسود إلى الركن الشامى، ذراعا ؛ بسبب الركن الذي بناه الحجاج بن يوسف فى داخل البيت فى الركن الشامى، وجعل فيه سلما من داخل الركن يرقى منه إلى ظهر الكعبة لتعليق الكسوة . وعرض الجدار الشامى، الذي بين الركن الغربى والركن الشامى، ذراعا ونصف ذراع ، نقص ذرّع الجدار\nمن أجل ذلك الركن المذكور. وعرض الجدار اليمانى، من الركن الأسود إلى الركن اليمانى، ذراعا ونصف ذراع . وذرع قاع البيت مكسرا ذراعا ونصف ذراع .\nهذا ذرعه من داخل وتكسير قاعه. وغلظ جدار الكعبة أشبار . وارتفاع البيت من خارج، من الأرض إلى أعلى البيت ذراعا: طول جدار البيت منها ذراعا، وعليه طرابزين وارتفاعه ذراع، تعلق منه الكسوة وقد استعلت عليه ذراعا، وكمل بذلك ارتفاع البيت ذراعا . هذا ارتفاعه من خارجه.\nوارتفاعه من داخله: جدره كلها من قاع البيت إلى السماء الأولى ذراعا، ومن السماء الأولى إلى السقف الأعلى ذراعان .\nهذا ارتفاعه من داخله. وذكر أن إبراهيم الخليل عليه السلام إنما بنى البيت الحرام يوم بناه فى ارتفاع أذرع\nغير مسقف ، فلما بنته قريش واقتصرت عن طوله أذرع تركت ذلك فى الحجر، وزادّت فى ارتفاع البيت أذرع، فكان البيت يومئذ من ذراعا\nفى الارتفاع\n. فلما احترق فى زمان عبد الله بن الزبير رضه وأمر ببنائه وزاد فيه ما كان أنقصته قريش، ظهر له عند ذلك قصير الارتفاع، فزاد فى ارتفاعه أذرع. وقال إن قريشا زادت فيه أذرع وأنا أزيد فيه ٩، فصار البيت من يومئذ من ذراعا\nفى ارتفاعه، لم يزد فيه أحد من يومئذ.\n[صفة البيت من داخله وفضله وفضل الصلاة فيه]\nينبغى لمن يحج أن يرغب فى داخل البيت وفى الصلاة فيه، فإن فى ذلك فضيلة كثيرة\n. فإذا دخل فيه أحد فليتركع وليلح بالدعاء والرغبة إلى الله، فإنه مشهد كريم. وليخلع نعليه ولا يبصق ولا يمتخط ولينزه ما استطاع فإنها بقعة مكرمة مقدسة مطهرة، كرمها الله عز وجل وشرفها على بقاع الأرض كلها. وهو قبال البيت المعمور الذي يحجه الملائكة فى السماء كما يحج هذا بنو آدم فى الارض .\nوصفة قاع البيت هو مبسوط بالرخام الأبيض، وفى رخامة منها عند دخولك من باب الكعبة مسمار فضة، وكذلك جميع جدره مرخمة بالرخام الأبيض قدر أذرع\n، وما فوق ذلك منقوش مذهب بفراشة الذهب ليس بصفائح\nإلى سماء البيت. وفى ترخيم جدر\nالبيت ألواح حمر وخضر، يقال إن الوليد ابن عبد الملك بعث تلك الألواح من الشام مع الرخام الذي رخم به البيت، ومع ذلك الف دينار، وأمر أن يرخم البيت ويذهب، وهو أول من كساه بالرخام وذهبه.\nفمن تلك الألواح فى الجدار الغربى مقابل من داخل البيت ألواح:\nحمر و أخضران\n. وبين هذه الألواح الخمسة فى ذلك الجدار محاريب فضة، طول كل محراب منها أشبار وعرضه أشبار؛ بين كل محراب منها منقوش: \xabأقبل على صلاتك ولا تكن من الغافلين\xbb . وفى جهة كل محراب منها منقوش: \xabلا إله إلا الله محمد رسول الله\xbb . وفى ذلك الجدار أيضا مما يجاور الركن اليمانى، فى أعلى الترخيم على رأس اللوح الأحمر، محراب ذهب طوله شبران وعرضه شبر ونصف\n. وعلى رأس تلك الألواح والمحاريب بحر مرخم فيه مكتوب بالمسك المحلول: \xabلا إله إلا الله محمد رسول الله\xbb مكرر فى سطرين.\nوبعد ذلك: \xabالإمام المطيع لله أمير المؤمنين\xbb\n. وفى سطر تحته\n: \xabالإمام المقتدر بالله أمير المؤمنين\xbb .\nوفى الجدار اليمانى من تلك الألواح ٤: أخضران وأحمران، فوقهما بحر مرخم فيه مكتوب: \xabإن أول بيت وضع للناس للذى ببكة\nمباركا وهدى للعالمين، فيه آيات بينات\nمقام ابراهيم، ومن دخله كان آمنا\xbb .\nوفى الجدار الذي كان فيه الباب من تلك الألواح ٣: أخضر بين أحمرين، وفوقهم بحر مرخم مكتوب من طرف عتبة الباب: \xabولله على الناس حج البيت من استطاع إليه سبيلا ومن كفر فإن الله غنى عن العالمين\xbb\n؛ \xabبسم الله الرحمن الرحيم. إن الله وملائكته يصلون على النبي يا أيها الذين آمنوا صلوا عليه وسلموا تسليما\xbb .\nوفى الجدار الشامى من تلك الألواح أيضا: أخضر بين أحمرين، وفوقهما بحر مرخم فيه مكتوب: \xabوإذ جعلنا البيت مثابة للناس وأمنا واتخذوا من مقام إبراهيم مصلى وعهدنا إلى إبراهيم وإسماعيل أن طهرا بيتى للطائفين والعاكفين والركع السجود\xbb\n. هذه صفة البيت من داخله وخارجه .\n[صفة سقف البيت وعمده]\nوسقف البيت على ثلاثة عتب أطرافها من الجدار الشرقى إلى الجدار الغربى\n. والعتب على ثلاثة أعمدة من خشب مخروطة على قواعد من خشب فيها مسامير فضة. وهى مصطفة من الجدار الشامى إلى الجدار اليمانى، بين العامود الأول والجدار الشامى أذرع، وبين ذلك العامود والعامود الأوسط أذرع، وبين الأوسط والثالث الذي يليه الجدار اليمانى أذرع، وبين العامود الثالث والجدار اليمانى أذرع .\nوسماء البيت مذهب فى خضرة ليس بمنقوش إنما هو دائر فى خضرة مذهبة.\nوفى سماء البيت أربعة روازن، للضوء، جميعها مغطاة بحجر أبيض يسمى الطلق، يذكر أن عبد الله بن الزبير بعث به من اليمن فغطى منه\nالروازن ليدخل منها\nالضوء ولا يدخل منها الماء. واحدة من الروازن على الحجر\nالأسود، والثانية على وسط البيت بإزاء رأس العامود الأوسط، وثالثة\nعلى الركن الشامى، ورابعة\nعلى الركن اليمانى . وفى الركن عمود به قصبة فضة\n، وهى التى كانت بها قرط مارية والتميمة وقرن الكبش . وليس بها اليوم إلا قنديلان من فضة كبيران منقوشان، ومعلاق فضة بقنديلين آخرين لا غير .\n[صفة باب الكعبة وذرعه وعتبته]\nعتبة الباب من ساج أسود مكتوبة من داخل البيت مذهبة من خارجه.\nوطول باب البيت أذرع ونصف ذراع، وعرضه أذرع الا أربعة أصابع . وهو مكسو بصفائح الفضة المذهبة، وله حلقتان من فضة بيضاء غير مذهبتين. وكان قفل البيت من نحاس أحمر مذهب، بعضه قد انكشف وبقى بعضه مذهبا، وهو اليوم حديد مكسو بالفضة ،\nطول القفل شبر. والباب فى الجدار الشرقى، بينه وبين الركن الأسود أذرع، ويسمى هذا الموضع الملتزم ، بينه وبين الركن الشامى ذراعا، وارتفاع الباب من الأرض أذرع .\n[صفة الحجر الأسود وارتفاعه فى الركن وفضله]\nالحجر الأسود على ثلاثة أذرع من الأرض ، وطول ما يظهر منه فى الركن شبر غير أصله فى الجدار شبر . وهو مصدوع مكسور على ثلاثة قطع: اثنتان كبيرتان وواحدة صغيرة ، ذكر أن عبد الله ابن الزبير كان ألصقه وشده بالفضة وأدخله فى الركن. وكان قد بقيت القطعة الصغيرة منه عند بنى شيبة، فلما رده القرمطى بعد أخذه، ألصق بالّك وأضاف إليه بنو شيبة القطعة الثالثة، وأفرغ حوله الفضة ودارت الفضة بينها حتى صار كشبه العين .\nوفيه أيضا طرق كثيرة غير الصدع؛ فأكثر من استلامه ومن الركن اليمانى، فإن ذلك يحط الخطايا . وتقول عند استلامه:\nبسم الله، والله أكبر، اللهم إيمانك وتصديقا لما جاء به نبيك عليه السلام.\nصفة الحجر وذرعه\nالحجر مكعب يشبه الصهريج ليس بالمربع، مرخم قاعه وحوائطه بالرخام الأبيض، طرفاه ليسا بملصوقين بركن البيت، يقابلان من الأركان الشامى والغربى. بين طرفى حائط الحجر الواحد والركن الشامى أذرع، وبين الطرف الثانى والركن الغربى أذرع، وهما بابا الحجر من حيث يدخل إليه . ودور الحجر ذراعا ونصف ذراع ،","1-3":"وطوله من جدار البيت إلى آخر جوف الحجر ذراعا ، وعرض ما بين طرفيه ذراعا لأن طرفه الواحد يخرج عن ركن البيت الشامى قدر ذراع وكذلك مقابله. والميزاب فى وسط ذلك الجدار الذي على الحجر فى وسط ما بين طرفى الحجر، لاصق بجدار الكعبة رخامتان خضراوان تجر إلى صفرة، ملصوقتان بالرصاص يقع عليهما ماء الميزاب. وارتفاع حائطه أشبار، وعرض غلظه أربعة أشبار، مسطح أعلاه بالرخام الأبيض. وعلى ظهر الحائط فى وسطه مما يقابل الميزاب رخامة خضراء، تجعل صدرك عليها للدعاء فى تمام كل أسبوع؛ هذه صفة الحجر.\n[صفة المقام]\nحجر لونه بين الدكنة والحمرة، منقط بنقط سوداء، له رأسان مختصر الوسط مخروم جدا، وعمق الأقدام فى الحجر أكثر من ثلثى الشبر يزيد نصف أصبع .\nصفة القدمين في الحجر: وصفة القدمين فى الحجر إبهام الواحد إلى كعب الثانى. وأصابع القدم اليمنى مما يلى مستقبل المقام، وكعب ذلك القدم إلى البيت الحرام، وأصابع القدم الشمال إلى البيت الحرام، وكعبه مما يلى مستقبل\nالمقام، وبين القدمين غلظ مما يلى البيت الحرام ثلاثة أصابع، ثم يضيق فيرجع فى وسط المقام إلى أصبعين مغلقين، ثم يضيق حتى يرجع فى آخر الجبهة مما يلى مستقبله إلى أقل من غلظ أصبع .\nذكر صفة المقام: والمقام مكسو بغاشية فضة، فى الرأس الأعلى منقوش فى الغاشية مقابل مستقبله \xabسبحان الله\xbb ، وفى الجهة التى تلى زمزم \xabوالحمد لله\xbb ، وفى الجهة التى تلى البيت الحرام \xabلا إله إلا الله\xbb ، وفى الجهة التى تقابل دار الندوة \xabوالله أكبر\xbb . وفى المقام، فى رأسه الأسفل، مقابض فضة ملصقة فى الغاشية يرفع بها المقام عند تحريكه وغسله. وهو قاعد فى وسط حويض من رخام أبيض مربع مكسو بغاشية فضة، عمق الحويض أصابع مغلقة فيه حلقتان. تنزل على المقام مكبّة من خشب ارتفاعها أشبار، وتدخل تلك الحلقتان فى فتح فى المكبّة ويضرب عليهما قفلان الواحد من جانب زمزم والآخر من جانب دار الندوة. ولها مكبة أخرى من حديد فإذا قرب الحج وكثر الناس وأتى المرور، رفعت مكبة الخشب وأنزلت مكبة الحديد ، ويوضع عن يمين المكبة وعن يسارها كرسيان من خشب يجعل عليهما ثوران من نحاس عليهما شمع من قير. وبين المقام والكعبة ذراعا، وبينه وبين حد الطواف ذراعا. فعرض الطواف هنالك ذراعا، وليس يقابل باب الكعبة إنما يقابل وسط جدارها.\nصفة بئر زمزم وذرعها وذرع قبتها وما فيها من الماء وفضلها\nيستحب لمن حج أن يستكثر من ماء بئر زمزم ، ويكون منه شرابه ووضوؤه ما أقام بمكة، ويكثر من الدعاء عند شربه وليقل إذا شربه: \xabاللهم إنى أسألك علما نافعا وشفاء من كل داء\xbb ، فإنه لما شرب. ويستحب لمن حج أن يتزود منه لبلده فإنه شفاء لمن استسقى موقنا ببركته . قال ابن عباس:\n\xabاشربوا من شراب الأبرار وصلوا فى مصلى الأخيار\xbb ؛ قال وشراب الأبرار ماء زمزم ومصلى الأخيار تحت الميزاب . وغور بئر زمزم من أعلاها إلى قاعها ذراعا ، ومن وجه الماء إلى أعلى البئر ذراعا، ومن وجه الماء إلى قعر البئر ؛ ذراعا ؛ ويذكر أنها تقرب ليلة النصف من شعبان فى وسط الليل . وذكر أيضا أنه ليس يبقى أحد بمكة إلا يطهر منها تلك الليلة، فيخرج منها من الماء ما لا يعلمه إلا الله تبارك وتعالى، فما زادت ولا نقصت ولا تغير الماء عن حاله. وكذلك فى المواسم ما نقصت شيئا إلا\nأن الماء يتمكن قليلا فى المواسم. وقيل إنها غارت فى سنة وعطلت أياما، وكانت تجم ليجتمع فيها الماء. وذكر أيضا أنها جفت فى بعض تلك السنين حتى أن رجلا دخل فيها فصلى فى قاعها ركعتين .\nودور سعة البئر ذراعا ، وذرع سورها أذرع ، وعليها قبة مربعة على سارية منقوشة كلها ، و أركان معلقة بشراجيب الحديد ترجع إلى باب لطيف من ناحية قبة الشراب، ويعرفها أهل مكة بساقية زبيدة . قاعها مبسوط بالرخام، وسقفها ملبس منقوش من داخله بخشب الساج ، معمول من خارجه بالفسيفساء، مصنوع من زاج قد جعل فيه فرشة الذهب. وفى أعلى القبة قبيبة فيها سلسلة من نحاس، يوقد على جميعها الشموع ليلة الختمة فى رمضان. وعليها يرتفع الداعى لأمير المؤمنين بالدعاء ، وله مرتب على ذلك.\nوقبة زمزم هذه تقابل من الكعبة الملتزم وهو ما بين الركن الأسود وباب الكعبة ، وركن القبة خارج عن ركن الكعبة؛ ودور القبة من داخل: صهاريج يصب فيها الماء، يتوضأ الناس منها للصلاة.\nصفة قبة الشراب\nوبإزاء بئر زمزم\nقبة الشراب، وهى مقبوة على أرجل من خشب، مغلوف بينها بالشرجب، ترجع إلى باب صغير من جانب دار الندوة. وذرع القبة ذراعا، وقاعها معمول بالجيار فيه خواب مملوءة بالماء يسقى الناس منها من المغرب إلى العتمة؛ سقفها معمول بالفسيفساء، فى أعلاها زج يشبه صورة طائر من نحاس تديره الرياح؛ بينها وبين قبة زمزم ذراعا.\nصفة بيت اليهودية\nهو داخل المسجد الحرام، وهو بيت مربع أعلاه مشرف، جدره ملبسة بالجيار. وليس فى المسجد الحرام بناء غير ما وصفت.\n[صفة المسجد الحرام وذرعه وما فيه من الصنع]\nوفى المسجد الحرام أربع أئمة: فالإمام الشافعى إلى المقام، والإمام المالكى إلى الركن الغربى، والإمام الحنفى إلى الميزاب، والإمام الحنبلى يصلى إلى الركن اليمانى . وطول المسجد الحرام من ركن بنى شيبة، وهو الباب الذي يدخل الناس منه أول ما يدخلون المسجد الحرام، إلى ركن بنى جمح الذي عند باب السهميين الكبير أذرع . وعرضه من باب السهميين، وهو ركن\nبنى جمح، إلى ركن منى وأجياد الكبير الذي على باب اليمانيين ذراعا .\nهذا ذرع المسجد الحرام فى الطول وفى العرض.\nوللمسجد الحرام خمس منائر : منارة فى ركن أجياد، ومنارة على ركن أبى قبيس- وفى ركن ذلك المنار مما يلى دار إبراهيم الخليل عليه السلام الميل الأخضر الذي منه ابتداء الهرولة- ومنار ثالث على ركن بنى شيبة، ومنار رابع على باب دار الندوة، ومنار خامس على باب جمح، ويعرف بباب السّدّة.\n[عدد أبواب المسجد الحرام شرفها الله]\nله من الأبواب بابا منها فى الشق الغربى وهو الذي يلى باب جمح وبنى سهم أبواب : باب السهمين الكبير وهو باب العمرة ومنه يخرج الناس إلى التنعيم لعمل العمرة، وهو حنية كبيرة بلا سارية. ثم باب\nابراهيم عليه السلام وهو أقواس على أعمدة من آجر ملبسة بالجيار، تدخل منه قبل وصولك إلى المسجد، إلى دار كانت دار الحنطة زادتها زبيدة . وهى دار مربعة طولها ذراعا وعرضها كذلك ؛ وهى سقائف محمولة على أعمدة من آجر ملبسة بالجيار تشتمل على عمودا.\nثم تمضى منها إلى صحن المسجد؛ وخارج هذا الباب على ضفة الوادى بئر غدورة وبئر ابراهيم ، وهما بعيدا الرشا ملحان لا يشرب منهما. ثم باب جعفر ، وهو المعروف بباب اليمانيين، وهو قوسان على سارية.\nوفى الشق الذي إلى جانب الوادى وأبى قبيس أبواب : باب البقالين وهو باب أجياد الكبير، ويقابل هذا الباب دار أبى جهل، وهو قوسان على سارية، ثم باب الغزالين وهو قوسان على سارية؛ ثم باب الصفا وهو باب بنى مخزوم، ومنه يخرج إلى الصفا وهو أقواس على سوار؛ ثم باب الخياطين وهو باب بنى طلحة، وهو قوسان على سارية وفى هذا الباب يبيع البدو أطعمتهم إذ يأتون إلى مكة.\nوفى الشق الذي إلى جانب المسعى أبواب : باب على ابن أبى طالب رضه، وهو أقواس على ساريتين- وفى مقابل السارية الواحدة التى إلى جانب باب النبي - صلى الله عليه وسلم - الميل الأخضر الذي فى ركن دار جعفر لصق دار العباس؛ وهو رجل ملبس بالجيار، قد صبغ بالخضرة، بناه المهدى، جعله علما حيث تنقطع الهرولة. ثم باب النبي - صلى الله عليه وسلم - وهو قوس\nصغير بلاسارية، ومنه يخرج إلى الحدائق وإلى الصيادلة؛ وعنده طبل عظيم عرضه أشبار وهو من خشب تنم عليه رائحة الزنجبيل وهو مجلد من ناحية، يضرب من أول ذى الحجة عند كل صلاة. ثم باب بنى شيبة وهو أقواس على ساريتين، ومنه دخل النبي - صلى الله عليه وسلم -، ومنه يدخل كل من دخل مكة حاجا أو معتمرا. وعتبته من القوس الأول إلى القوس الثالث هبل الصنم الأعظم الذي كان فى الكعبة، وكانت قريش تعبده من دون الله فغيره الإسلام عن حاله وجعله عتبة لهذا الباب تطأه الأقدام؛ وإنما قصد به هذا الباب لأن الناس يدخلون عليه من جميع الآفاق ، والحمد لله على نعمة الإسلام. وفى هذا الشق المسعى وهو ما بين الصفا والمروة ، وهو بطن المسيل ، وفيه سوق مكة يجتمع فيه الباعة للمطاعم والصناع.\nوفى الشق الذي يلى دار الندوة أبواب : باب السوارى وهو قوس صغير بلا سارية؛ ثم باب الندوة وهو قوسان على سارية، يدخل منه إلى دار الندوة التى زيدت فى المسجد . وهى دار مربعة يدخلها تبنيق من جانب دار العجلة ، وهى سقائف من كل جانب على أعمدة آجر ملبسة بالجيار .\nطول الدار ذراعا، وعرضها مثل ذلك، وجميع ما فيها من العمد عمودا؛ ولها باب آخر يدخل منها إلى المسجد أيضا يعرف أيضا بباب الندوة ،\nوهو قوسان على سارية مما يلى دار العجلة. ثم باب الطبرى وهو قوس صغير بلا سارية، يقال له باب السّدّة، ومنه يخرج إلى دار جعفر الصادق. وفى هذا الشق أيضا ستة أبواب إلى الدور التى تجاور المسجد الحرام ليست من المسجد فى شىء.\n[عدد سوارى المسجد الحرام وذكر معجزة النبي - صلى الله عليه وسلم - فى ابتياعه السارية الحمراء]\nوجميع ما فى المسجد الحرام من السوارى سارية؛ هذا فى السقائف خاصة، وفى أبواب المسجد سارية ليست من العدد الأول. وفى الدارين المزيدتين فى المسجد: دار الندوة ودار الحنطة عمودا فكمل بذلك عدد السوارى والأعمدة عمودا . والمسجد الحرام من كل جانب بلاطات فى كل شق من تربيعه . وفى طول المسجد من ناحية الصحن قوسا، وفى عرض المسجد من جهة الصحن أيضا قوسا ، وفى الوجه الذي يلى دار الندوة- فى وسط المسافة- سارية حمراء كانت ليهودية، وطلبها النبي - صلى الله عليه وسلم - ليبتاعها منها فأبت أن تبيعها منه إلا بوزنها من ذهب، فابتاعها منها - صلى الله عليه وسلم - فأخذها عليه السلام بهذا الشرط. فوضعت السارية فى كفة الميزان ووضع\nالنبي - صلى الله عليه وسلم - فى الكفة الثانية مثقالا فرجح المثقال ببركته - صلى الله عليه وسلم -، فأخذها عليه السلام ووزنها مثقالا واحدا فهذا من براهينه - صلى الله عليه وسلم -. ووجه كل بلاط من ناحية الصحن منزول بالفسيفساء.\nعدد قناديل المسجد الحرام وما فيه من الحطيم والثريا\nداخله أرجل من خشب مصفحة بالنحاس تسمى كل واحد منها بالحطيم، تجعل عليه القناديل وتعلق منه بأكواس من زجاج فى رمضان. فمنه حطيم صاحب بغداد وحطيم شاه ملك العجم وحطيم سنجار ملك الفرس وحطيم السيدة؛ وهذه من ناحية المقام موقفة. وحطيم الحنيفية من ناحية الشام ينظر إلى الركن الغربى. فحطيم بغداد يتعلق منه قنديلا، وحطيم شاه يتعلق منه قناديل، وحطيم سنجار يتعلق منه قناديل أيضا، وحطيم الحنيفية يتعلق منه قناديل. ويتعلق من الذي على زمزم قناديل، ويتعلق من الأربعة الباقية قنديلا، فعدد ما يتعلق منها قنديلا . ويتعلق من سقائف المسجد الحرام\nقنديلا و ثريات: واحدة على باب إبراهيم الخليل عليه السلام، والثانية على باب الصفا، وثالثة على باب شيبة، ورابعة على باب السوارى، والخامسة على باب بنى جمح .\nوأرض المسجد الحرام رملة فى قوام السميد ؛ وقد رتب فيه نفسان بأيديهما وضفان يرقعانها عند كل صلاة .\n[صفة الصفا والمروة]\nوالصفا حجر أزرق عظيم قد بنى عليه درج ، ومن عليه يصعد إلى أبى قبيس، وعدد درجاته درجة وإلى آخر موضع الوقوف منها درجة. والمروة أيضا حجر عظيم كأنه قد انقسم فصار بعضه كذا وبعضه كذا وصار ما بينهما فرجة نحو ذراعا، بنى فى تلك الفرجة درج نحو العشرة إلى موضع الوقوف عليها، وبنى فى أسفلها من ناحية الشرق محراب.\nوليس يرى من البيت من أعلى المروة إلا قدر ذراعين .\nذرع المسعى: وذلك من الصفا إلى الميل الأخضر الأول، الذي فى ركن المنار الذي على باب الوادى، وهو ذراعا. ومن ذلك الميل إلى الميل\nالأخضر الثانى، الذي فى ركن دارى جعفر والعباس ذراعا، ويقابل كل واحد من الميلين الأخضرين مثلهما على شكلهما. ومن ذلك الميل إلى المروة ذراعا؛ فجميع ما بين الصفا والمروة ذراعا .\nصفة منى والجمرة ورميها\nإذا دخلت منى فقل اللهم هذه منى وهى مما دللتنا عليه من المناسك ، فأسألك أن تمن علينا فيها مما مننت به على أوليائك وأهل طاعتك وعبادك الصالحين. ومنى شبه القرية التى بنيت على ضفتى الوادى النازل من عرفات . وفى وسط ذلك الوادى الجمرتان : والجمرة الأولى\nهى جمرة العقبة أول ما تلقى منى فى رأس العقبة على يسار الداخل فى منى من ناحية مكة، فارمها من أسفلها من بطن الوادى بسبع حصيات. وتقول مع كل حصاة : \xabلا إله إلا الله والله أكبر على رغم الشياطين أو الشيطان وخزيه\xbb . فإن رماها قبل الفجر لم تجز وأعاد رميها بعد الفجر ولا ذم عليه.\nوالحصاة قربان فما تقبل منه رفع، وما لم يتقبل منه بقى . وليس على الخارج بمنى صلاة العيد وإنما صلاتهم فى ذلك اليوم وقوفهم بالمشعر الحرام .\nوأيام منى أيام ذكر الله، قال الله تعالى: \xabوأذكروا الله فى أيام معدودات\xbb فالمعدودات أيام منى الثلاثة، ترمى فيها الجمار وهى أيام التشريق وليس يوم النحر منها لقوله تعالى: \xabفمن تعجل فى يومين فلا إثم عليه\xbb فلو كان منها لقال فمن تعجل فى ثلاثة. فالنفر هو فى اليوم الثانى من الثلاثة التى بعد يوم النحر ، والأيام المعلومات يوم النحر واليومان اللذان بعده، واليوم الرابع للمعدودات خاصة. فإذا رميت جمرة العقبة نحرت هديك واستقبلت به إلى القبلة، وقلت: \xabباسم الله اللهم منك ولك فأسألك أن تتقبل منى كما تقبلت من إبراهيم خليلك عليه السلام\xbb . وفى سفح الجبل على جمرة العقبة مسجد وفى حائطه من ناحية الجوف حجر مبسوط أدكن فيه أثر قدم إسماعيل عليه السلام ولد إبراهيم الخليل حين أضجعه للذبح فركض برجله فلان له الحجر\nفغرق رجله فيه - صلى الله عليه وسلم - . وفى هذا الموضع أثر الكبش وأسفل من ذلك فى جوف الشعب عند طلوعك إلى العقبة عن يسار الطريق مسجد بيعة الأنصار التى كانت فى الإسلام، بقى أثره إلى اليوم . ثم تدخل منى فتلقى الجمرة الثانية عن يسارك على باب مضرب السيل ومضرب المعتز، بينهما وبين جمرة العقبة ذراع ؛ ثم الجمرة الثالثة وهى وسط المحجة بينها وبين الجمرة الوسطى ذراعا . وترمى الجمرات الثلاث بسبع حصيات، وتقول إذا رميتها مثل ما تقدم من القول. وليعلن الحاج بالتكبير أيام منى، ويذكر الله ويكبر فى أى ساعات النهار شاء، ولا يقطع التكبير حتى يصلى الظهر والعصر بالمحصّب . فإذا دخلت مكة وطفت طواف الإفاضة فقل: \xabاللهم لك الحمد على تسليمك إياى حتى قضيت حجتى مفلحا، قد غفرت لى ذنبى وقضيت لى حوائجى، إنك على كل شئ قدير\xbb .\nفإذا ودعت البيت وصدرت عنه، فلا ترد له ظهرك حتى تغيبه؛ وتقول عند ذلك: \xabاللهم اجعله حجا مبرورا وذنبا مغفورا وعملا مقبولا وسعيا مشكورا يا أرحم الراحمين. اللهم لا تجعله آخر العهد من بيتك المعظم ومن زيارة قبر نبيك المكرم واقلبنى سالما إلى أهلى إنك على كل شئ قدير\xbb .\nصفة مسجد الخيف وذرعه وذكر الغار الذي بقربه\nالمسجد فى أصل الجبل يمين الطريق إذا سرت إلى المزد لفة من منى.\nوهو مبنى من حجارة مطرورة أكثرها آجر ملبسة بالجيار؛ البيت منه على ثلاث بلاطات، وحول الحصن من جانب سقيفة على أقواس معقودة على أرجل من آجر ملبسة بالجيار؛ جميع ما فى المسجد كله رجلا . وطول المسجد ذراعا وله أبواب وباب ثامن صغير فى قبلة المسجد قريب من المحراب إلى دار الإمام . وفى وسط صحنه منار قد تثلم أعلاه .\nوبالقرب من المسجد فى أصل الجبل غار دخله النبي - صلى الله عليه وسلم - منحنيا فلم يتمكن له فيه جلوس حتى لان له فيه الحجر فغرق فيه مرفقه ورأسه - صلى الله عليه وسلم - ؛ فكل من دخله لا يتمكن له فيه جلوس حتى يضع مرفقه ورأسه فى الموضع الذي وضعه فيه النبي - صلى الله عليه وسلم - . وفى هذا الغار أنزلت عليه سورة \xabالمرسلات\xbb فيعرف بغار المرسلات.\nصفة مسجد المزد لفة\nومسجد المزدلفة أسفل من المسجد الحرام على يسارك إذا مضيت إلى عرفات؛ وفيه يجمع ما بين المغرب والعشاء إذا نفرت من عرفات، لقول النبي - صلى الله عليه وسلم -:\n\xabالصلاة أمامك\xbb . وهو مبنى بحجارة مطرورة دون سقف؛ إنما هو حائط\nمن جميع جهاته الثلاثة، والوجه الرابع غير قائم وليس له محراب. وفى القبلة منه حجر منقوش. وطول المسجد ذراعا، وعرضه ذراعا ، وارتفاع حائطه أذرع. والمزدلفة كلها مشعر الابطن محسّر . ولا تدع التكبير والتهليل فى نزولك بالمزدلفة، وفى دفعك منها إلى منى وقل:\n\xabاللهم إنى أسألك جوامع الخير كله\xbb ، واسأله ما شئت فإنه موقف عظيم؛ وخذ حصيات الجمرات من المزدلفة فإنه أحسن .\nصفة المشعر الحرام\nوهو موضع مرتفع، عن يمين الطريق إذا مضيت إلى عرفات، من أصل جبل بنى قزح فى ذلك إلى الارتفاع. وهو منار من حجارة مطرورة بالجيار ؛ ارتفاع ذلك المنار ذراعا، ودور غلظه ذراعا ونصف ذراع. ويرقى إليه من داخله على درجة؛ وله باب صغير نحو الكعبة. وحيثما وقفت من المشعر الحرام فكله موقف؛ وارتفع عن بطن محسّر فتحرك فيه بكل حال إن كنت ماشيا أو كنت راكبا، فهرول حتى تخرج منه فإنها السنة.\nصفة عرفات وجبل الرحمة\nوعرفات قرية صغيرة فى جانب بنى ضبّة، غربيها تحت الموقف، عن يمينك إذا استقبلت الموقف. وجبل الرحمة الذي يطلع الناس إليه للدعاء هو أقرب الجبال إلى الموقف؛ وهو جبل صغير ليس بالعالى جدا ينقطع من كل جانب.\nوهو على الموقف، وقد بنى حوله شبه الساقية، يرتقى منه إلى الجبل من ثلاثة مواضع من ناحية الموقف، فى الواحد منها درجة، وفى الاثنين عشر.\nوفى أسفل الجبل منها صهاريج للماء ؛ وفى أعلى المبنى مسجد لأم سلمة زوج النبي - صلى الله عليه وسلم - .\nصفة شريعة ابراهيم عم\nوهو حائط مبنى من كل جهاتها غير مسقف، وقد انهدم أكثرها فما بقى منها إلا جدار القبلة وفيه المحراب؛ وعن يمينك إذا استقبلت المحراب أقواس معقودة يدخل منها الناس. وموضع المنبر هناك عن يمين مستقبل المحراب، طول الشريعة ذراعا وعرضها ذراعا. وبقبلى الشريعة بركة للماء، وخلف تلك البركة منبت الأراك ؛ وهو بطن عرنة، قريبة إلى العلمين اللذين هما حد الحرم. وهناك يجب الارتفاع للماشى والراكب؛ ومن وقف عليه عشية الوقوف فقد فسدت حجته لقوله عليه السلام: \xabعرفة كلها موقف وارتفعوا عن بطن عرنة \xbb . وقيل إنه من الحرم؛ وعرض ذلك الوادى قدر ذراع إلى العلمين .\nصفة بطن محسّر وفى أى موضع هو من المزدلفة\nبطن محسّر فى أول دخولك إلى المزدلفة من ناحية الغرب إلى الشرق يشقه الطريق؛ وهو بطن مسيل عرضه ذراع، ثم تفصل عنه إلى موضع مرتفع وأنت خارج إلى المزدلفة؛ وسقاية عباس هناك عن يمينك، وهى بركة عظيمة ليس بها ماء عظيم اليوم.\nصفة المأزمين\nهما جبلان فى فم المضيق إذا خرجت عن المشعر الحرام تريد إلى عرفات، وتوقد هناك فى ليلة النحر مشاعل كثيرة عن يمين الطريق وعن يساره.\nقال المؤلف رحمه الله تعالى: تم جمع ما شرطنا من وصف مكة- شرفها الله تعالى- فلنذكر الآن صفة مسجد النبي - صلى الله عليه وسلم - بالمدينة وصفة روضته وصفة البقيع وصفة قبور الشهداء رضى الله عنهم.","1-4":"صفة مسجده - صلى الله عليه وسلم -\nومسجد النبي - صلى الله عليه وسلم - مستطيل غير مربع، يزيد طوله على عرضه ذراع . وسماء المسجد منقوشة مدهونة محفورة مذهبة، كلها على عتب منقوشة على أعمدة خرز أسود بعضه على بعض ملبّسة بالجيار .\nوهو ليس على أقواس إلا ما كان إلى الصحن، فإنه أقواس معقودة وجوهها منزولة بالفسيفساء على أعمدة من خرز ملبسة بالجيار. والأعمدة التى إلى صحن المسجد هى أقصر من التى عليها سماء المسجد، وتلك الأقواس التى إلى صحن المسجد مغلفة بشر اجيب الساج؛ مقدم المسجد خمس بلاطات معترضة، ومؤخره مثل ذلك ، ومجنبة المسجد الشرقية فيها بلاطات معترضة، ومجنبته الغربية بلاطات ؛ ومن مقدم المسجد إلى الصحن قوسا، وكذلك من مجنبته الأخرى. وطول المسجد من ركن منار بلال رضه وهو الذي بإزاء قبر النبي - صلى الله عليه وسلم - إلى ركن مؤخره، وعرضه من باب جبريل عليه السلام وهو الذي بإزاء قبر النبي - صلى الله عليه وسلم - إلى باب الرحمة التى بجنب دار السيدة ذراعا.\n[صفة الروضة التى بين القبر والمنبر]\nطول الروضة التى بين قبره - صلى الله عليه وسلم - والمنبر ذراعا . وذرع الموضع المرخم الذي فى وسطه الروضة، وهو الموضع الذي كان يقعد فيه النبي - صلى الله عليه وسلم -، ويستند إلى تابوت من خشب كان يرفع فيه حوائجه - صلى الله عليه وسلم -، فذلك الموضع اليوم شبه الحوض، مرخم عمقه قدر شبر وطوله أذرع. والتابوت فيه باق إلى اليوم، وعليه قفل من حديد ما فتحه أحد ولا يعلم ما فى داخله؛ والتابوت فى قبلة الحوض منزول منه إلى الأرض بمقدار ما يتحرك .\nصفة الروضة التى فيها قبر النبي - صلى الله عليه وسلم -\nقبره - صلى الله عليه وسلم - فى ثلث البلاط الأوسط من ناحية الشرق، وهو فى روضة مخلّقة ولها أركان: فى الحائط الذي ينظر إلى القبلة منها، فى الركن منه من ناحية المنبر، وجه النبي - صلى الله عليه وسلم - إلى القبلة؛ وعند قدر وسطه عليه السلام وجه أبى بكر رضه، وقبال ذلك مسمار فضة علامة لموضع وجهه رضه؛ وعند قدر وسط أبى بكر وجه عمر رضه ومن ذلك الحائط إلى حائط القبلة ذراعا، وطول هذا الحائط ذراعا، وطول الحائط الذي يلى باب جبريل عليه السلام ذراعا،\nوبين هذا الحائط وحائط المسجد الشرقى أذرع. وطول الثلاثة أوجه سوى هذه ذراعا، وارتفاعها من الأرض نحوا من ذراعا، وهى مرخمة كلها، وعليها مما يلى سقف المسجد شباك الحديد، وهى مكشوفة ليس لها سقف، ولها سماء إلى سقف المسجد . وقد أسدلت عليها أستار من الديباج الملون إلى قدر ثلثى الحيطان، والثلث الباقى من ناحية القبلة والغرب ملطخ بالعنبر والمسك والزعفران.\nوفى الركن الذي عند رأس النبي - صلى الله عليه وسلم - رخامة خضراء ما رأى أحد أجمل منها، جعلت علامة لموضع رأسه - صلى الله عليه وسلم -.\n[صفة المنبر]\nهو من درجات يقعد الخطيب منها فى الدرجة السابعة، والثامنة عليها مكبّة من خشب لئلا يرقى عليها أحد لأنها الدرجة التى كان يقف عليها النبي عم. وبين المنبر وحائط القبلة ذراعا، وبينه وبين المقصورة ذراعا، وبين وجه المقصورة وحائط القبلة أذرع .\nوفى جانب المنبر من ناحية الروضة حلقة فضة على كوكب فضة تدور لها صوت\nإذا حركت، كان النبي - صلى الله عليه وسلم - يشغل بها الحسن والحسين رضه عنهما.\nوفى قبلة المنبر، مائلا إلى الشرق قليلا، عمود من أعمدة المسجد قد قطع فيه قدر شبر، ودخل فى جوف العمود الجذع الذي حن لرسول الله - صلى الله عليه وسلم -.\n[صفة المحراب]\nالمحراب ليس فى وسط حائط القبلة، إنما هو أميل إلى الشرق ب ذراعا . والقبلة مرخمة وعلى الترخيم مكتوب، من باب الرحمة إلى باب السلام، من أول سورة \xabوالشمس وضحها\xbb إلى آخر سورة \xabقل أعوذ برب الناس\xbb الخ. وعلى جانب المحراب كوكب كبير، وفى وسطه حجر من ياقوت أزرق يذكر أنه وسط عقد فاطمة الزهراء رضه. وفى قبلة المسجد عن يمين المحراب باب صغير، تحت المقصورة فى وسط البلاط، يهبط منه على درج إلى باب كان يسكن فيه آل عمر رضه.\n[عدد أبواب مسجد النبي - صلى الله عليه وسلم -]\nوللمسجد بابا: منها فى الجانب الشرقى أبواب مربعة بمصاريع مشرجبة؛ وفى الجانب الغربى كذلك منها باب صغير بدفة، وهو قوس\nليس للمسجد باب بقوس غيره . وفى الجانب الحوفى أبواب أيضا كبار؛ وباب فى القبلة، وباب تحت المقصورة التى تقدم ذكرها .\nعدد ما فى المسجد من العمد\nوجميع ما فى المسجد من العمد عمودا . وللمسجد منائر على أركان : منها على ركن القبلة الشرقى منار، وعلى الغربى منار، وعلى ركن مؤخر المسجد منار. والمسجد مبسوط مقدمه ومؤخره ومجنبّته بالحصى الأدكن. وكان فى البلاط الأوسط عام [١١٣٤] وطاء طبرى مبطّن. وجميع جدره مرخّمة قدر قامتين أو أزيد قليلا، وصحنه مبسوط بالحصى، وهو مغروس بالنخيل. فى البلاط الشرقى بناء قائم يشبه المحراب، ذكر أنه كان موضع صلاة فاطمة رضه. وفى الجوف ، فى وجه البلاط فى الصحن، بناء قائم كأنه بيت، ذكر أنه مخزن المسجد.\n[عدد ما فيه من القناديل]\nوفى المسجد من القناديل قنديلا ؛ وكان يحرق كل ليلة أرطال من الزيت.","1-5":"صفة بقيع المدينة\nبقيع المدينة من ناحية الشرق؛ فأول ما تلقى إذا خرجت إلى البقيع قبر مالك رضه، وهو قبر مهمل مبنى بالحجر والطين مرتفع من الأرض نحو أشبار، وعند رأسه حجر أدكن منقوش تاريخه من يوم مات. ثم تسير منه قليلا وقد بصقت القبور موتاها ورفضت الأرض جميع ما دفن فيها من صغير وكبير، ولم يبق فى بطنها منهم شئ إلا رفضته على وجهها. فلم يبق عضو من أعضائها ولا عظم من عظامها، ولو كان مقدار خردلة إلا وخرج على الأرض من ناس أهل المدينة خاصة. وترى البقيع شبه المقتلة من دفن قديم وحديث وجماجم الموتى بالية قديمة وأخرى حديثة، فهذا عبرة لمن اعتبر. ثم تسير قليلا فتلقى روضة العباس بن عبد المطلب رضه، ثم روضة إبراهيم ولد النبي عم، ثم روضة عثمان بن عفان رضه، وروضات كثيرة .\nصفة مسجد قبا\nوهو مسجد على ثلاثة أميال من المدينة، تصلى فيه إذا مررت به.\nوهو مسجد مربع طوله ذراعا وعرضه كذلك، مقدمه بلاطات، ومؤخره مع مجنبته سقيفة واحدة على أعمدة من خرز ملبسة بالجيار عددها\nعمودا ، وله أبواب بلا مصارع . وعلى ركن مؤخر المسجد مكتوب عن يسار من استقبل المحراب: \xabإن النبي - صلى الله عليه وسلم - دخل على أم أيمن وهى حزينة فقالت له ليس عندى ما أحج به فقال لها صومى أيام العشر ثم ايت مسجد قبا يوم عرفة فصلى فيه ركعتين تنقلبى بثواب حجة\xbb . ومكتوب أيضا أن سعد بن أبى وقاص رضه قال: \xabلئن آت مسجد قبا فأصلى فيه ركعتين أحب إلى من أن أزور بيت المقدس مرتين. ولو علم الناس ما فى مسجد قبا لضربوا إليه آباط الإبل\xbb .\nوبئر قبا التى مضمض النبي - صلى الله عليه وسلم - ومج فيها وكانت ملحة فعذبت ببركته - صلى الله عليه وسلم -، وهو بغربى المسجد. وبيت سعد بن خيثمة الأنصارى الذي كان يقيم فيه النبي - صلى الله عليه وسلم - بين المسلمين، هو قريب من ركن المسجد الغربى .\nومن مقدم المسجد والشجرة التى كانت تحتها البيعة سقف، وذلك السقف جزع وهو مغطى بالألواح .\n[صفة قبور الشهداء بأحد رحمة الله عليهم]\nوقبور الشهداء فى أصل جبل أحد ، أقرب ما يكون منها بأحد حظير مبنى من حجارة ارتفاعه إلى المحزم ، فيه من القبور قبرا\nمغطاة بالجندل. وقبر العروسين معاذ بن عمرو بن الجموح وصاحبه معاذ بن عمر اللذين أمر النبي - صلى الله عليه وسلم - أن يدفنا فى قبر واحد ، وهما بغربى ذلك الحظير، بينهما قدر رميتين بحجر؛ وعليه لوحان مكتوبان الواحد من مسن المدينة والآخر من خشب. وقبراهما مقبو عليهما، ارتفاعه قدر القامة عنده قبرا. وأسفل من الحظير قبر حمزة بن عبد المطلب ، وقد بنى حوله حظير، وقطع منه مسجد وقبر. والقبر فى الحظير أمام المسجد غير ممهد، عند رأسه لوح من مسن المدينة فيه مكتوب: \xabهذا قبر حمزة بن عبد المطلب عم رسول الله - صلى الله عليه وسلم -، أسد الله وأسد رسوله، سيد الشهداء وقائدهم إلى الجنة؛ شهد بدرا وقتل يوم أحد رضه\xbb . وعند ظهره لوح مكتوب فيه: \xabإن الله أشترى من المؤمنين أنفسهم وأموالهم بأن لهم الجنة يقاتلون فى سبيل الله فيقتلون ويقتلون\xbb إلى آخر الآية . وعند رجله لوح مكتوب فيه: \xabإن الله وملائكته يصلون على النبي يا أيها الذين آمنوا صلوا عليه وسلموا تسليما\xbb . \xabهذا قبر حمزة بن عبد المطلب، أسد الله وأسد رسوله، شهد بدرا وقتل يوم أحد شهيدا\xbb .\nومن ذلك الحظير على يساره إذا مضيت إلى أحد، عن يمينك قبل أن تبلغ قبر حمزة، مبنى ارتفاعه إلى المحزم، عليه لوح مكتوب من خشب: \xabهذا قبر سهل بن قيس بن سعد، صاحب لواء رسول الله صلى الله عليه وسلم، شهد بدرا وقتل يوم أحد شهيدا .\nقال المؤلف رحمه الله تعالى: انتهى ما قصدته من ذكر مكة شرفها الله، وما سقته معها من ذكر المناسك، ووصف مسجد النبي عم بالمدينة. والآن أشرع فيما أشترطه من ذكر البلاد بمبلغ الوسع والاجتهاد، والله الموفق للصواب.","2-1":"ذكر بلاد مصر وما فيها من العجائب\nبلاد مصر فى أول الإقليم الرابع، لها من البروج الجوزاء، ومن النجوم عطارد . وهى من أسوان إلى الإسكندرية، وخصبها وزرعها وفواكهها كثير جدا، يسقى جميعا بالنيل . والنيل من عجائب العالم لا يعرف له منبع من تحت جبل القمر ، وراء خط الاستواء بتسع درجات ونصف درجة، يخرج من عينا هنالك، يجتمع فى بحيرتين هناك كالبطائح ، ثم ينبعث من كل بطحة أنهار، منها نيل مصر وغيره من الأنهار الكبار التى يأتى ذكرها إن شاء الله تعالى. وذلك فى البلاد المحترقة الجنوبية التى لا يكون فيها نبات ولا حيوان، لقرب الشمس من ذلك الموضع .\nقيل ينبعث نيل مصر فى رمال وجبال، ثم يخترق أرض السودان مما يلى بلاد الزنج، ثم ينبعث منه خليج يشق بلاد الزنج يصب فى بحر الزنج . وتظهر فى هذا الخليج الزيادة التى تظهر فى نيل مصر؛ وفيه التمساح الكائن فى نيل مصر، ويسمى الورل الذي يكون فى الصحراء والبرارى إنما أصله من التمساح.\nوذلك أن التمساح يخرج من النيل فيسرح على السواحل، فربما قبض عنه الماء فيبقى فى البر، فيتناسل فيكون منه الورل المشهور. والتمساح لا يوجد إلا فى نيل مصر، أو فى نهر أصله من ماء واحد مع نيل مصر .\nوفى نيل مصر السمك الرعاد ؛ من صاده لم تزل يده ترتعد ما دام فى شبكته أو فى صنارته. وعلى النيل جبل هامد، يراه أهل تلك الجهة، من انتضى سيفه ثم أولجه فيه، وقبض على مقبضه بيديه جميعا، اضطرب السيف فى يده\nفارتعد، ولا يقدر على إمساكه ولو كان أشد الناس. وإذا أحدّ بحجارة هذا الجبل سكين أو سيف لا يؤثر فيه حديد أبدا، وجذب الإبر والمسال أشد جذبا من المغنطيس، ولا يبطل الثوم عمله كما يبطل المغنطيس. وحجر الجبل نفسه لا يجذب الحديد، فإن حدّ عليه الحديد، جذب ذلك الحديد ؛ وهذا من العجائب.\nويقال إن نيل مصر يجرى على وجه الأرض فرسخ، ويجرى فى غير عمران مسيرة أشهر، وفى بلاد السودان مسيرة شهرين، وفى بلاد مصر مسيرة شهر، من أسوا نإلى أن يصب فى البحر بحلق رشيد بشرقى الإسكندرية . وذكر هورشيش الرومى فى تاريخه أن منبعه إلى موقعه ٩٩٠٨٣٠ ميلا . والنيل مخالف لكل نهر من أنهار الأرض: لأن كل نهر يستقبل الجنوب، والنيل يستقبل الشمال، فهو مخالف لجميع أنهار الدنيا؛ وعلة ذلك أن منبعه من الجنوب؛ قال الشاعر:\nبلاد مصر شأنها عجيب ... ونيلها تجرى به الجنوب\nقيل وليس فى الدنيا نهر يسمى بحرا ويمّا غير النيل؛ قال الله تعالى: \xabفإذا خفت\nعليه فألقيه فى اليم\xbb ؛ والعرب تسميه بحرا. وليس فى الدنيا نهر يفيض على الأرض ويزرع عليه ويغنى عن المطر غير النيل. وقيل إن بلاد مصر أشهر درة بيضاء، و أشهر مسكة سوداء، و أشهر زمردة خضراء، و أشهر سبيكة حمراء. وتفسير ذلك أن النيل إذا استوى، طما جميع أرض مصر فتبقى قراها وضياعها فى رواب وتلال كأنها الكواكب، ويتصرف الناس بينها فى الزوارق فتكون الأرض كدرة بيضاء. ويمكث عليها الماء أشهر، فإذا قبض عنها الماء أخذ الحراثون فى بذر الزرع، فتمكث الأرض سوداء إلى أن ينبت الزرع وتظهر خضرته أشهر، فكأن الأرض مسكة سوداء، وأيضا فإنها تفوح منها رائحة طيبة عطرة. فإذا كبر الزرع وظهرت خضرته، كانت الأرض كأنها زبرجدة خضراء. وبقيت كذلك أشهر، إلى أن يصفر الزرع وييبس ويتناهى، كانت الأرض عند ذلك كأنها سبيكة ذهب حمراء، وبقيت كذلك أشهر حتى يتم الحصاد .\nوذكر أن مصر فى كتب الأوائل مصوّرة وسائر البلاد مادة اليها أيديها تستطعمها ، ومعنى ذلك أنها أكثر بلاد الله زروعا. وذكر أن هارون الرشيد صورت له مدائن مصر ومدائن الدنيا فما استحسن منها غير عمل مدينة أسيوط؛ وهى بسيط واحد لو قطرت فيه قطرة فاضت على جميع نواحيه، يبذر فيها جميع الحبوب، فإذا اخضر فلا يكون على الأرض بساط أعجب\nمنه . والجانب الغربى من هذه المدينة جبل أبيض كأنه طيلسان ، ويحيط بها من الجانب الشرقى النيل كأنه جدول فضة، قد تشبكت عليه فى الأرض الأشجار والكروم، فلا تسمع فيه الكلام من شدة أصوات الطيور .\nولنيل مصر فى زيادته ونقصانه عجائب كثيرة، عرضنا عن ذكرها لكثرة معرفة الناس بها. وليلة الغطاس بمصر من أعجب شىء؛ وتسمى فى هذا الزمان كسر الخليج، وهى لعشر تمضى من كانون الآخر وهو بلغة الروم ينّير؛ وذلك الوقت يستوى مد النيل ويأخذ فى الانحطاط. وأصفى ما يكون ما النيل فى ذلك الوقت. ولهذه الليلة بمصر شأن عظيم، وذلك أنه يخرج تلك الليلة جميع البشر ممن يقدر على الخروج تلك الليلة وقد أعدوا ما أمكنهم من الأطعمة والأشربة، ولبسوا أحسن ما عندهم من الملابس، وأظهروا ما أمكنهم من الجواهر وأوانى الذهب والفضة، وأحضروا جميع الملاهى. ويدخل الناس فى الزوارق، ومنهم من يدخل فى الدور المشرفة على النيل، ويشعلون المشاعل والشمع الكثير. ويشعل صاحب مصر الشمع على جانب النيل ، فيحرق فى تلك الليلة بمصر من الشمع ما لا يحصى عدده؛ فترى الناس على شطوط النيل فى الزوارق، ومنهم فى الدور المشرفة على النيل بالطبول والأبواق وجميع الملاهى.\nوهى أحسن ليلة تكون بمصر وأكملها سرورا؛ ويغطس أكثر الناس فى النيل، ومن لم يغطس يرش عليه من الماء، ويزعمون أن ذلك أمان من المرض .\nقال عمرو بن العاص: \xabولاية مصر تعدل الخلافة\xbb ، لأنها جعلها الله متوسطة بين الإقليم الثالث والرابع؛ سلمت من حر الإقليم الأول والثانى، ومن برد الإقليم الخامس والسادس. وقال الجاحظ: \xabأهل مصر أعقل الناس صغارا","2-2":"وأحمقهم كبارا\xbb . وقيل إن مصر لم يجعل الله فى أرزاق أهلها ولا فى أقواتهم نصيبا مما قسم على عباده: من الرحمة بالغيث الذي جعله الله عمارة البلاد.\n[نبذ من أخبار ملوك مصر من لدن عمارتها]\nيقال والله أعلم إن أول من ملك مصر عند قسمة الأرض بين ولد آدم، زمن أنوش، بوصية آدم عليه السلام، ملك يقال له نقراوش بن أضرم. وهو أول من اتخذ المصانع، وعمل الطلسمات وأقام الأساطين، وزبر عليها التواريخ، وبنى المدن . وهو الذي حفر النيل وعمقه ووسعه؛ وكان قبل ذلك ينقطع ويستنقع.\nوعمل للتماسيح على شاطىء النيل فى آخر بلاد النوبه مبنيين، وزبر عليهما أحرفا منعت التماسيح أن تنحدر فى النيل. وكانت كتابتهم بالقلم الخلقطير وهو قلم آدم عليه السلام. وكان عالما كاهنا وكان له رأى من الجن؛ ويقال وقع إليه بعض العلوم التى كان رزآبيل الملك علمها آدم عم، فعمل بها عجائب: منها صورة طائر على اسطوانة عالية يصفر فى كل يوم مرتين، عند طلوع الشمس، وعند غروبها، تصفيرا مختلفا يستدل به على ما يكون من الحوادث. وعمل فى مدينة برسان، وهى التى بناها لابنه مصرام، قبة ذهب على منار عال، لا تزال على تلك القبة سحب تمنعها من الشمس. وعمل على باب المدينة أصناما موجهة إلى نواح مختلفة، إذا قصد أرضهم قاصد بسوء أرسلت عليه نارا فأحرقته. فكان ملكه سنة.\nفلما مات جزع عليه قومه أشد جزع، فقاموا يطوفون به على أعناقهم سنة .\nثم ملكهم من بعده ابنه مصرام، وكان يعبد زحلا، وحارب أمة من الجن حتى أدخلهم فى طاعته بالعزائم الشداد. وبنى فى صحراء المغرب مدائن معلقة على أساطين رخام، تحيط بها شباك من ذهب، وجعل فيها خزائن الحكمة.\nوجعل لها أبوابا تحت الأرض لا يدخل إليها إلا منها؛ وجعل لها أقفالا ومفاتيح مدبرات. وكانت مدن فى كل مدينة خزائن، فيها عجائب العلم وطرائف الحكمة ورموز الصنعة، وأجرام من الماء المعقود لا يتحلل، ومن الهواء المجمد لا يضمحل. وفيها مطهرة من ماء الحياة الإلهى الصنع، وفيها صورة الكواكب فى بيوت شرفها، وعلى رؤوسها أكاليل الغلبة، وبإزائها صور الحكماء المقيمين لأمورها بأيديهم مصاحف الصنعة، وجميع الطلسمات والعلوم، ومن دروب الأحجار الرفيعة والجواهر النفيسة والأجرام العجيبة: من الدر الخطير، وسبائك الذهب والفضة، والحجارة الرفيعة، والعقاقير المكنونة والأدوية المؤلفة. وصور هذه الخزائن فى كل بربى من برابى مصر، قد زبروا عليها بخطوطهم، وخبرها مشهور فى جميع مصاحفهم القديمة وهياكلهم المرسومة.\nوبنى هذا الملك مدينة بالقرب من هذه المدن الثلاث على هيئة الجنة بزعمه، وجعل لها أسرابا تحت الأرض، يوصل منها إلى هذه المدائن الثلاث، وتوصل من بعضها إلى بعض .\nأخبرنى رجل دخل بلادا كثيرة، أن الغاوى الذي بجبل ألموت إمام الحشيشية، يرى اغتيال الملوك عند مدينة تحت الأرض على هذه الصورة.\nيدخل فيها المستجيب له، فإذا عاين ما أعد له فيها، يقال له: هذا لك إذا قتلت فلانا فى الموضع الفلانى. ويكون إدخاله فى تلك المدينة وهو قد سقى المرقّد، فينتبه فيها.\nفإذا أريد إخراجه، سقى المرقد أيضا، ويخرج فينتبه فى منزله، ويتذكر ما رأى،\nفيقصه على من أمامه. فيقول له: إنك رأيت هذا فى منامك وهو بشرى لك، فلا تنثى عما أمرت به ويبشره بالمثوبة عليه، ويرفع له خنجرا مسموما معدا عنده من حينه .\nقال المؤلف فلما هلك الملك نقراوش المتقدم الذكر، ملك بعده ابنه سورت. وكان موحدا مؤمنا. فغلق هياكل الكواكب فقل النيل فى أيامه، فرفضه بنو أبيه وخلعوه وملكوا أخاه الأصغر مصرام المتقدم الذكر. وكان جبارا فزاد فى هياكل الكواكب، واحتفل فى شكرها وبر سدنتها وزاد فى دخلها وقرابينها. وكان له ربّى فأمره أن يحتجب عن الناس، وألقى على وجهه نورا حتى لم يتمكن أحد من النظر إليه؛ وذلل له الأسد فركبها، وادعى الإلهية ودعا الناس إلى عبادته، وغاب عن الناس نحو سنة. وركب فى غيبته أنواعا من الدواب العظام من الوحوش والسباع لها منظر يهول. ومضى به ذلك الربّى حتى أوقفه على البحر الأسود، فبنى فى وسطه صنما من حجر أسود أبيض، وزبر عليه اسمه وجعله قربانا للشمس، وعمل قلعة الفضة التى فى البحر الأسود وخبرها مشهور.\nذكر ذلك الموس الكاهن فى سير الملوك القدماء. وزبر على ذلك الصنم:\n\xabأنا مصرام الحبار جامع الأخبار وكاشف الأسرار والعالم القهار: وأظهرت الحكمة العجيبة وكشفت الأمور الغريبة؛ ونصبت الأعلام الهائلة على البحار السائلة ليعلم من بعدى أنه لا ملك مثل ملكى\xbb . وقيل إنه ركب فى مدينة برسان شجرة تؤكل منها كل فاكهة، وعمل عجائب وغرائب يطول وصفها .\nفلما هلك مصرام ملك بعده من بنيه عدة ملوك، كل واحد منهم يعمل فى وقته عجائب وغرائب فى البناء، وغير ذلك من الطلسمات والصور والأصنام المركبة من الجواهر الغالية؛ إلى أن ملك من بنيه شوندين بن سلمون صاحب الأهرام.\nوكان ملكا عاقلا عالما محبا للعلماء، وكان أوتى من العلم والحكمة ما لم يسبقه إلى ذلك ملك ولا غيره، وكان يتعهد من مصالح الرعية ما لم يتعهده سواه من الملوك، وكان ينفق على الزمناء والضعفاء من ماله. واتخذ مرآة من أخلاط\nوأقامها على منار فى وسط قصره، فكان ينظر فيها جميع الأمم والأقاليم وغير ذلك، ويقابل ذلك بما يصلحه. وكان قد عهد إلى رئيس كهنته ان يأمرهم بالنظر فى كل يوم ما يحدث فى العالم، ويخلد ذلك فى كتاب؛ فجمع إليه العلماء والكهنة والمنجمون من جميع أقطار الأرض، وحققوا له ما أراد وتم له ذلك. وعملت له الغرائب والعجائب فى البناء والطلسمات، وغير ذلك، وفى أيامه بنيت الأهرام التى بأرض مصر. فيقال إنه ليس على وجه الأرض حجر موضوع على حجر أغرب من بناء أهرام مصر.\nوكان سبب بناء هذ الأهرام أن الملك شوندين رأى رؤيا هائلة، وذلك أنه رأى الكوكب المعروف بالبانية فى صورة طير أبيض وكأنه يختطف العالم ويلقيهم بين جبلين، وكأن الجبلين انطبقا عليهم، وأن الكواكب المنيرة مظلمة كاسفة كلها. فأخبر بذلك رؤساء الكهان والعلماء وأمرهم أن ينظروا ما تدل عليه الكواكب مما يحدث فى العالم، فأقاموا الكواكب فى مراكزها فى وقت مسألة فدلت على آفة نازلة من السماء وخارجة من الأرض. فلما بان لهم ذلك أخبروه به، فقال ما هو ذلك فنظروا فى خفى أمورها ودقائق علمها، فوجدوها مفسدة للأرض وأهلها وحيوانها وجميع ما فيها، وقالوا إن هذه الآفة محيطة بجميع أقطار الأرض إلا اليسير، وذلك إذا نزل قلب الأسد بأول دقيقة من السرطان، وتكون الشمس والقمر فى أول دقيقة من الحمل. فلما تيقن الملك شوندين من ذلك، وعلم أن تلك الآفة تكون ماء يغرق الأرض ومن عليها،. مر ببناء الأهرام - وهى البرابى لتخليد علومهم وصناعاتهم وسير ملوكهم وسننهم فى رعيتهم وأهل مملكتهم- وبنيان أعلام عظام تكون خزائن لأموالهم وكنوزهم وذخائرهم، وتكون أيضا قبورا لهم ولأهل بيتهم، تحفظ أجسادهم من الفساد وتبقى علمهم صحيحا ، وأمر بأن يبنى ذلك كله من حجر صلد لا يغيره الدهر ولا يفسده الطوفان.\nويقال إنه أمر أن تبنى هذه الأهرام والبرابى من حجارة ومن طين. فإذا كان الحادث ماء ذهبت التى من طين وبقيت التى هى من حجارة، وإن كانت نارا ذهبت التى هى من حجارة وبقيت التى هى من طين . فكان ذلك الحادث ماء فذهبت الطين وبقيت الحجارة. ثم أمر الملك وزراءه فمشوا مع المنجمين والكهان فاختاروا موضعا لبناء تلك الأعلام، وهى الأهرام والبرابى، فاختاروا موضعا بقرب النيل فى الجانب الغربى فبنيت فيه مدينة مرقة، معناه بلسانهم \xabمطلب الحكمة\xbb . ثم أمر الملك بجمع الناس والفعلة فجمع لقطع الحجارة ونحتها، ومثلهم لهندستها، وأضعافهم للبناء. وعمل قضبان الحديد واستخرج الرصاص، فكانوا ينصبون البلاطة ويجعلون فى وسطها عامود حديد قد نفذها، والعامود قائم قد ضبط بالرصاص المسبوك، وتركب عليها بلاطة أخرى فى قدرها وهندستها، مثقوبة بقدر دخول القضيب فيها، ثم يسكب الرصاص حول العامود وعلى البلاطتين معا، حتى أتى بنيانا ما بني فى العالم قط مثله . وطول حائط الهرم ذراعا بأذرعهم، وفى عرضه مثل ذلك وارتفاعه فى الفضاء ذراع . ويقال إن عمقها تحت الأرض مثل ارتفاعها فوق الأرض؛ وعرض الحائط من حيطانها ذراعا بأذرعهم.\nفلما تم بنيان هذه الأهرام والبرابى، أمر الملك أن يكتب على حيطان البرابى وسقوفها جميع الأشياء وغوامض الأمور: من دلائل النجوم وعللها وسائر الصنائع والطباع ومكنونها، والنواميس العظام وعمل الأدوية وتأليفها، ومعرفة العقاقير وأسمائها وصورها، وعلم صنعة الكيمياء وغير ذلك مما ينفع ويضر.\nكل ذلك ملخص مفسر لمن عرف كتابتهم وفهمها. ونقش فى حيطانها وسقوفها جميع الطلسمات وكتب على كل طلسم خاصيته ونفعه وضرره، وكما وضع فى تلك الأهرام فنونا من الذهب والفضة والكيمياء وحجارة الزبرجد الرفيعة والجواهر النفيسة ما لا يحصّله وصف واصف. وكذلك فعل بنوه من بعده.\nفلما تمت هذه الأهرام والبرابى على ما أراد الملك قال لهم أنظروا هل تفسد هذه الأعلام، فنظروا فوجدوها باقية لا تزول. فقال لهم هل يفتح منها موضع، أو هل يدخل إليها، فنظروا فقالوا له يفتح فى الهرم الفلانى فى الجانب الشمالى منه، فقال لهم حققوا النظر فى معرفة الموضع بعينه، فنظروا وعرفوه بالموضع.\nفقال لهم عرفونى متى يكون ذلك، فنظروا فعرفوه أنه يكون ذلك لمدة دورة للشمس والدورة سنة. فقال لهم أنظروا مقدار ما ينفق فى فتح هذا الموضع؛ فنظروا فعرفوه بالقدر، فقال لهم اجعلوا فى الموضع الذي يوصل منه إلى داخل الهرم ذهبا بمقدار ما ينفق على فتحه. ثم حثهم على الفراغ من بناء الأهرام والبرابى، ففرغوا منها فى سنة. وأمر أن يكتب عليها: \xabبنينا هذه الأهرام فى سنة فليهدمها من يهدمها فى سنة، على أن الهدم أهون من البناء\xbb . ثم قال لهم أنظروا هل يكون بعد هذه الآفة كون مضر غيرها، فنظروا فإذا الكواكب تدل فى وقتهم وتظهرهم على آفة أخرى نازلة من السماء، وتكون فى آخر الزمان وهى ضد الأولى، وهى نار محرقة لأقطار العالم، فأخبروه بذلك. فقال لهم فهل من خبر آخر توقفونا عليه بعد هذه الأمور، فقالوا له ننظر فى ذلك؛ فنظروا على آلاف السنين، وقالوا له إذا قطع قلب الأسد ثلثى دورة، وهى آخر دقيقة من برج العقرب، لم يبق من حيوان الأرض متحرك إلا تلف، فإذا استتم دورة تحللت عقد الفلك. فقال لهم فى أى يوم تتحلل عقد الفلك، فقالوا له اليوم الثانى من وجود الفلك. قال فتعجب الملك من ذلك، وأمر بكل ما قاله العلماء من هذه الحكم أن تخلّد فى الكتب، وتستودع فى تلك الأهرام؛ فيقال إن فيها علم الأولين والآخرين.\nنرجع الآن إلى حديث الثلمة: قيل فلما كان فى زمان المأمون بن هارون الرشيد، وفرغ من حرب التيماء وأقام بمصر ، أراد هدم الأهرام، فعرفه بعض شيوخ المصريين أن ذلك غير متمكن، وقال له ولا يحسن بأمير المؤمنين أن يطلب شيئا ولا يبلغه ؛ فقال له لابد أن أعلم ما فيها. ثم أمر بفتح هرم من أعظم الأهرام، ففتح فيه ثلم من جانبه الشمالى، لقلة دوام الشمس على من يعمل فيه؛ فلما ابتدءوا عمله وجدوا حجرا صلدا يكل فيه الحديد. فكانوا يوقدون النار عند الحجر، فإذا حمى رش بالخل ورمى بالمنجنيق فزبر الحديد؛ وأقاموا على ذلك أياما حتى فتحوا الثلمة التى فيه الآن، فمنها يدخل إلى ذلك الهرم. ووجدوا بنيانه بالحديد والرصاص ووجدوا عرض الحائط ذراعا؛ وبالقرب من الموضع الذي فتحوا مطهرة من حجر أخضر فيها مال على حول الدنانير العريضة، وزن كل دينار منها مثقالا وثلثى مثقال. فقال المأمون زنوه فوزنوا الجملة فوجدوا فيها مالا معلوما، وكان المأمون رحمه الله فطنا، فقال رحمه الله ارفعوا ما أنفقتم على فتح هذه الثلمة، ففعلوا فوجدوه موازنا لما وجدوا من المال. فعجب أمير المؤمنين من ذلك، ومن معرفتهم بالموضع الذي يفتح منه ذلك الهرم على طول الزمان، وازداد فى علم النجوم يقينا. قال فمشى المأمون حتى دخل الهرم، ومشى فيه فوجد صنما أخضرا مادا يده وهو قائم فلم يعلم خبره. ونظر إلى الزلاقة والبئر الذي فى الهرم، وأمر بالدخول والنزول فيه.\nقال فنزل فيه قوم من رجاله من درجة إلى درجة حتى أفضوا إلى صنم أحمر، عيناه مجزعتان سواد فى بياض كأنهما حدقتا إنسان ينظر إليهم، فهالهم أمره وقدروا أن له حركة، فجزعوا منه فخرجوا وعرفوا أمير المؤمنين الحال.\nقال فجرأه ذلك على طلب مخابىء كثيرة. ويقال إنه وجد فيه مالا كثيرا.\nقيل فسأل المأمون عمن وجد بمصر من العلماء بتاريخ العالم: هل لهذه الأهرام أبواب يدخل إليها منها؟ فقيل له إن لها أبوابا تحت الأرض، فى آزاج مبنية بالحجارة، طول كل زج منها ذراعا، له باب من حجر واحد يدور بكوكب، إذا أطبق لم يعرف أنه باب، وصار كالبنيان لا يدخل الذر فى خصاصته، ولا يوصل إليه إلا بكلام وقرابين وبخورات معروفة. وإن فى هذه الأهرام قبورا من الذهب والفضة والكيمياء وحجارة الزبرجد الرفيعة النفيسة ما لا يسعه وصف واصف.\nوفيها من الكتب المستودعة فيها طرائف الحكمة وكمال الصنعة، ومن التماثيل الهائلة من الذهب الملون على رؤسها التيجان الفاخرة مكللة بالجواهر النفيسة، ما يستدل به على عظيم ملكهم؛ وجعلوا على ذلك من الطلسمات ما يمنع منه، ويدفع عنه إلى أوقات معلومة وأمد لابد منه. وإنما قصدوا بذلك أن تكون تلك الأشياء ذخيرة لأعقابهم، ولمن يكون من بعدهم، علما على عظيم ملكهم. قال ووضعوا أساس تلك الأعلام فى وقت السعادة، وجعلوا فى أساس كل علم منها صنما، وزبروا فى صدورها دفع المضار والآفات عنها. وفى كل صنم منها آلة كالبوق، وهو واضعه على فيه. وفى وسط كل هرم منها شرفات موجهة إلى آزاج ضيقة المنافذ واسعة المداخل، تجتذب الرياح إليها على طول الزمان، وتخرج من وجه الداخل إليها، ولها صفير فمن لم يحس دفعها أهلكته. قال فعجب المأمون من ذلك ولم يتعرض إلى شىء من تلك الأعلام.\nوقيل إنه عمل تحت تلك الأهرام أسرابا تخرج إلى نواح مختلفة: منها ما يخرج إلى الفيوم وهى على نحو يوم ونصف من مصر، وإلى ناحية المغرب على مسيرة يومين وأزيد، وفى أسفلها مسارب للماء تفضى إلى النيل. قيل ووكل بكل هرم من تلك الأهرام روحانيين، فجعل فى الهرم الغربى روحانى فى صورة امرأة عريانة مكشوفة الفرج لها ذؤابتان حسنة الخلق. وإذا أرادت تستفز الإنسان ضحكت إليه، واستجرته إلى نفسها، فإن تبعها أهلكته.\nذكر ذلك من رآها مرارا. ووكل بالهرم القبلى روحانى فى صورة غلام أمرد عريان حسن الخلق يفعل كذلك. وقد رؤى من خارج مرة بعد مرة ثم يغيب فى الهرم. وفى الهرم الملون صورة شيخ عليه ثياب الرهبان، وبيده مجمرة كأنه يتبخر. وكذلك وكل بجميع البرابى . وببلد إخميم يشاهد أهله أن روحانى\nالبربى الذي بها فى صورة غلام أسود بيده عصا، فلا يقدر أحد أن يدخل البربى من بعد العصر إلى الصبح. وكذلك بربى مدينة سمنود فيه روحانى فى صورة رجل طويل، أدم اللون صغير اللحية أشيب. وأما بربى قفط، فجارية سوداء معها صبى صغير أسود تحمله . ولكل بربى من البرابى قربان وكلام يطيع به ذلك الروحانى، ويدل على علوم البربى وكنوزه. ويقال إن ذا النون الإخميمى إنما قدر على ما قدر عليه من علوم البربى حتى عمل الصنعة الكبيرة، وهى الكيمياء والجوهر، وحمل من مصر إلى بغداد فى ليلة واحدة، وغير ذلك مما كان عنده من الغرائب وخبره مشهور.\nفيقال إنه خدم راهبا كان بإخميم يقال له ساس مدة صباه، فعلمه قراءة الخط الذي فى البربى، وعلمه القربان والبخور واسم الروحانى؛ وأوصاه أن يكتم ذلك.\nفلما علم ذو النون ما علم من علم الكيمياء وغيرها، عمد إلى طين الحكمة، فطمس به صنعة الكيمياء حتى لا يبلغ إليها أحد غيره؛ وهذا الطين لا ينقطع أبدا.\nوهذا القلم هو المسطر فى كتاب السياسة الأوسط وهو كتاب مشهور:\nاب ت ث ج ح خ د ذ ر ز ط ظ ك ل م\nن ص ض ع غ ف ق س ش هـ ولا ى .\nوبها من الكيمياء. وفى بعض أخبار مصر أن قوما قصدوا الأهرام، فنزلوا فى تلك الآبار، وطلبوا أن يدخلوا فى تلك المضايق التى تخرج منها الرياح، واحتملوا معهم سرجا فى أوان رخام. فلما حصلوا فى تلك المضايق، خرجت عليهم ريح شديدة وأخرجتهم منها عنفا، وأطفأت أكبر سرجهم. فأخذوا أحدهم وكان أقواهم جأشا وأشدهم عزما وأصلبهم قلبا؛ فربطوا وسطه بالحبال، وقالوا ادخل فإن رأيت شيئا تكرهه جذبناك، فلما دخل المغرور وزاحم تلك الرياح، انطبق عليه ذلك الفتح، فجذبوه فانقطعت حبالهم، وبقى الرجل فى ذلك الشق وهم لا يعلمون له خبرا؛ فصعدوا هاربين حتى خرجوا من البئر، واغتموا لما أصاب صاحبهم. فجلسوا عند الثلمة مفكرين فى أمر صاحبهم، وفى أمرهم وما أقاموا عليه، فبينما هم كذلك إذ انفجرت من الأرض فرجة كالكوة، وأثارت لهم ذلك الرجل عريانا مشوه الخلق ميت الدم جامد العينين، وهو يتكلم بكلام عجيب لا يفهم، فلما فرغ من كلامه سقط ميتا. فازداد وجلهم وتضاعف حزنهم وجزعهم، وعلموا أنهم خالصون من أمر عظيم . قال فاحتملوا صاحبهم، واتصلت أنباؤهم بوالى مصر وهو ابن المدبر فى أيام المتوكل ، فسألهم عن أمرهم؛ وأخبروه بذلك فعجب. وأمر أن يكتب الكلام الذي قال ذلك الرجل الذي مات، حسب ما قاله، وأقام ابن المدبر يطلب من يفسره إلى أن وجد رجلا يعرف شيئا من ذلك اللسان، ففسره: \xabهذا جزاء من طلب ما ليس له وأراد الكشف على ما يخفى، فليعتبر من رآه\xbb . قال فمنع حينئذ ابن المدبر أن يتعرض أحد للأهرام.\nوفى خبر آخر أن جماعة دخلوا الأهرام فوجدوا فى بعض البيوت زلاقة إلى بئر، فنزلوا فيها فوجدوا سربا، فساروا فيه نصف يوم حتى انتهوا إلى حفير عميق وفى عدوته باب لطيف. وكانوا يتبينون منه شعاع الذهب والفضة والجواهر النفيسة. ومن رأس الحفير مما يليهم إلى ذلك الباب المحاذى لهم، الذي فيه الذهب والجوهر، عامود حديد قد ألبس محورا من حديد يدور عليه ولا يستمسك فى دورانه. فاحتالوا فى وقوفه وذهاب حركته فلم يقدروا على ذلك، فربطوا أحدهم فى حبل، وتعلق بالعامود ليصل إلى الجانب الآخر، فدار به المحور فتحير وسقط وانقطع الحبل الذي كان فيه، فخرجوا هاربين لا يلوون على شئ.\nوفى خبر آخر أن قوما دخلوا بعض الأسراب التى فى الهرم، فانتهوا إلى صنم أخضر على صورة شيخ، وبين يديه أصنام صغار كأنه يعلمهم. ثم ساروا فوجدوا فوارة تحت قبة يقع فيها ماء من أعلى تلك القبة، فيكون له نشيش شديد كأنه يطفئ نارا، ثم يفيض هناك ولا يتبين. ثم داروا فوجدوا بيتا مسدودا لا يظهر له باب غير حجر صلد، وفيه دوى شديد لا يدرى ما هو؛ ووجدوا عنده شبه المطهرة الكبيرة فيها ماء ودنانير، منقوش فى الوجه الواحد صورة أسد وفى الوجه الثانى صورة طير، فأخذوا من تلك الدنانير شيئا، فلم يقدروا على حركة ولا كلام حتى تركوها فى موضعها.\nوأما البرابى ففيها من الطلسمات والكتابة، وعمل الصناعات وتصوير جميع الآلات وتعليم جميع الصناعات، كل ذلك منقوش فى الحجر الصلد، وإن الناس يمشون إليها فيأخذون فوائد كثيرة . قال الوصيفى :\nرأيت فى بربى إخميم صورة عقرب فألصقت عليها شمعا فلم أتركها فى موضع إلا أن انحاشت العقارب إليها من كل موضع، وإن كانت فى تابوت اجتمعت\nحول التابوت وتحته. فطلبها منى بعض إخوانى فرجعت إلى إخميم فوجدت تلك الصورة قد نقرت وأفسدت. وفى هذا البربى، عند الباب الذي يدخل منه إلى المصعد على يسار الداخل، صورة رأس إنسان عظيم اللحية كثير الشعر كأنه رأس روحى بغير جسد، فذكر أن الأولين كانوا يبخرون ذلك الرأس، ببخور لهم معروف عندهم، فكل من بخره وجد عنده دينارا؛ فكان فى ذلك معونة لأهل المسألة. قال الوصيفى: تصفحت الموضع الذي بقرب ذلك الرأس، فوجدت أثر البخور والطيب بينا فيه. وذكر أن على باب إخميم طلسم، وهو قطعة من الحجر فى صورة القلنسوة، معقبة الرأس كأنه منقار طائر، يقال إن تحته مال عظيم، وقد جهد جماعة من الولاة على إخميم فى قلعها أو كسرها فلم يقدروا على ذلك، وتنكسر المعاول كلها ولا يتثلم منها شئ.\nوأخبرنى رجل بأنه رأى هنالك صورة استحسنها، وهى صورة إنسان على رأسه طائر وإلى جنبه كلب رابض وتحت رجليه كتابة، قال فأخذتها وصورتها فى قرطاس كما رأيتها فأقمت ثلاثة أيام فلم أهجع ولم آكل ولم أشته شيئا من الطعام ولم أدر ما السبب لذلك حتى فكرت فى الصورة التى عندى فنزعتها عنى فاشتهيت الطعام وأكلت ونمت\xbb\n. وحدث رجل من أهل إخميم أن رجلا من أهل المشرق نزل عندهم وكان بصيرا بهذه العلوم فتذاكروا معه أمر البربى فقال ذلك المشرقى لبعضهم إن وجدت فيه صورة إنسان عريان مؤتزر بمئزر وفى يده اليمنى فأس له رأسان وفيه ورقة معلقة فأنسخه لى وما حوله من الكتابة.\nقال ففعلت ذلك وأتيت بها إليه وسألته عن خاصيتها، فأطعمنى فيها وقال ليس ينتفع عندها أو تفسد البربى. قال فمشيت إليها فخدشتها بمنقار حتى أفسدتها وطمستها ثم سألته عن علمها فخلط على ولم يعطنى فائدة. فلما كان بعد ذلك تحدثت به مع قوم أهل المشرق فتلهف أحدهم فسألته عن أمرها فقال إن تلك الصورة إذا جعلت فى موقع فيه كنز ارتفع من الموضع غبار فيعلم أن فيه خيرا وهى دلالة على الكنوز فغمنى أن كنت أفسدتها. وكذلك يتحدث أهل سمنود عن البربى الذي عندهم بعجائب كثيرة منها أن بعض من دخله كتب على كفه صورة من تلك الصور أعجبته، فأطبقت عينه الواحدة حتى أتاه من كتب على كفه الصورة المحاذية لها فانفتحت عينه.\nقال الوصيفى: وأخبرنى من أثقه أنه رأى ببربى سمنود صورة شيطانين تحوط بهما سلسلة بكتابة، وهما يمسكان طرفى السلسلة وبينهما كتابة، قال: فصورت ذلك كما هو، وأمسكته عندى إلى أن جاءنى من عرفها، فقال لى: هذا حرز عظيم من جميع السباع، ومن كل من يروم الإذاية، ولو جعل على هذا الطلسم لحم، وجوع كلب أو سبع وقرب منه لم يقدر على أخذ شىء منه بوجه ولا بحال، قال فعجبت من قوله فامتحنت الطلسم فوجدته كما قال. ومن المتعارف عند أهل إخميم، أنه كان فى البربى الذي كان عندهم، صورة شيطان قائم على رجل واحدة وله يد واحدة قد رفعها إلى الهواء، وفى جبهته وحواليه كتابة، وله إحليل ظاهر ملتصق بالحائط. فقيل من احتال لذلك الإحليل حتى ينقب عليه، وينزعه من غير أن ينكسر، ويعلقه فى وسطه لم يزل منعظا إلى أن ينزعه، ويجامع ما أحب ولا ينكس ما دام عليه. وقيل إن ابن الغمر لما ولى إحميم أخبر بذلك، فطلب تلك الصورة فى البربى فلم يجد منها غير واحدة قرب سقف البربى، فاحتال عليها حتى أخذ الإحليل، فكان يستعمله فيخبر عنه بعجب؛ وقيل إنه كان فى البربى منه صور كثيرة فلم [تزل] تؤخذ حتى فقدت .\nقال الوصيفى: حدثنى من أثقه أنهم وجدوا فى بعض البرابى أشنانة زجاج أحمر مربعة الشكل موضوعة فى طاق وفيها ماء أصفر، فلم يدروا لم يصلح ذلك الماء فاهرقوه منها، وأخذ أحدهم تلك الأشنانة. قال فأقامت عنده مدة إلى أن رآها رجل غريب نزل عليه ضيفا، فاستظرفها فسأله عنها فأخبره بخبرها وبخير الماء الذي كان فيها؛ فتلهف ذلك الرجل على الماء، وقال أضعتم علما عظيما وخيرا كثيرا. وقال إنكم لو حميتم الفضة وغمستموها فى ذلك الماء لصارت ذهبا؛ قال فندمت على التفريط فى ذلك الماء. ثم قال لى أتريد أن أريك فى هذه الأشنانة عجبا؟ قلت نعم قال زنها، قال فوزنتها فوجدت بها أرطال سواء، فقال لى املأها ماء أو ما أحببت، قال ففعلت، قال لى زنها فوزنتها، فوجدت وزنها واحد وهى ممتلئة مثل وزنها وهى فارغة أرطال لا تزيد ولا تنقص شيئا ،\nفعجبت من ذلك. وشاع خبرها حتى اتصل ببعض الولاة فوجه إلى فأخذها منى.\nوكان فى هذه البرابى عجائب من الطلاسم فى قبور شتى قد درس أكثرها، وتهدم أكثر البرابى. وأما الأهرام فهى باقية على حالها ما اختل منها شئ؛ فيقال إن كل ما تهدم من هذه الهياكل وتغير، مثل بربى بوصير وبربى سمنود وغير ذلك من الهياكل، أن المنجمين تركوا الاستقصاء فى أخذ الطالع وتصحيحه فى وقت وضع الأساس، وكذلك ما بقى منها فلقرب الطالع من الصحيح. ولا شك أن الذين بنوا هذه البرابى كانوا على بعد من الملوك، ولم يكونوا بحضرتهم ولا تحت نظرهم، فيستقصوا النظر كما اتفق فى بناء الأهرام، وكان بالقرب من صاحب مصر فكان يتفقدها. والبرابى أكثر إنما هى فى الكور. قيل ولكل بربى من هذه البرابى خاصة ومنفعة فى الموضع الذي يكون فيه وما والى جهته؛ وأهل تلك الديار لا يشكون أنه لما هدم بربى سمنود، وحملت حجارته إلى أشتوم دمياط ، أن اليوم الذي فرغ فيه من هدم الحائط الغربى، دخل حباسة الإسكندرية وخربها ، وكثرت الرمال فى أسباب البحر بها حتى انقطع النيل عنها فى شهور الصيف، وكان يمر عليها صيفا وشتاء؛ وقلت زكاة الزرع وكثر الفأر فيه والجراد والفساد الذي لم يعهد قبل ذلك. ومن العجائب المذكورة بأرض مصر فى قرية يقال لها بدرسانة ، كنيسة قديمة للروم فيها بيت يصعد إليه قى نيف وعشرين مرقى، وهناك سرير عليه صبى ميت، وتحت السرير صورة ثور عظيم من زجاج فى جوفه باطية زجاج فيها أنبوبة نحاس موضوع فيها فتيل كتان، ويصب عليه يسير زيت فما تلبث أن تمتلىء\nالباطية من الزيت حتى يفيض إلى جوف الثور، فيأخذ قيم الكنيسة ذلك الزيت دائما، فيسرج منه قناديل الكنيسة كلها، ولا ينقطع نماؤه وزيادته على مرور الدهور والأيام. فإن أزيل الصبى الميت، طفيت النار ولم يفض الزيت، فإذا أعيد عاد الزيت إلى ما كان عليه. وقد سار إلى هذه الكنيسة جماعة من الناس رأوا ذلك وأفرغوا الباطية تم أسرجوها بيسير من الزيت، ففاضت وبدا منها ما ذكرنا.\nثم نرجع إلى ذكر الملك شوندين .\nقال فلما هلك الملك شوندين بعد أن ملك سنة ودفن فى الهرم الغربى، ملك بعده ابنه قمناوش وكان جبارا فظلم وجار وسفك الدماء واغتصب النساء؛ واستخرج كثيرا من الكنوز، فبنى بها قصور الذهب والفضة ورصعها بالجواهر الغالية، وعمل بركا فصب فيها الجواهر وأرسل عليها الماء، وفعل من مثل هذه الأشياء ما لم يفعل غيره من الملوك؛ واستجهل من مضى من آبائه، واستعبد الناس واستخف بالهياكل. فلما هلك ملك بعده ابنه فترك الظلم وتحبب إلى الناس، وطلب العلم وأعاد الهياكل كل إلى ما كانت عليه فى أزمان أجداده، وجمع المنجمين والكهان، وعملت فى أيامه من العجائب والغرائب ما كانت تعمل فى أيام آبائه ؛ وملك مدة ولم يكن له ولد. وطلب النسل من امرأة، فلم يقدر عليه لأن أرحام النساء عقمت فى أيامه. وفى وقته شاع خبر نوح عم. قال فلما لم يكن له ولد ولا أخ، خاف على ذهاب ملكه فأشرك فى أمره فرعان، وكان من بنى عمه، وكان أحد الجبابرة ففتح البلاد وقهر الأمم؛ فوافقته امرأة من نساء الملك على أن يقتل الملك ويلى الملك ففعل، واحتوى على المملكة فتجبر وعلا وقهر. وأصل الفراعنة مشتقة منه ومن اسمه .\nوكتب إليه ذو ميشيل بن عدبيل بن درشيل الأكبر يخبره بأمر نوح، فكتب إليه فرعان يشير عليه بقتل نوح فهلكا فى الطوفان.\n[ذكر أول من نزل مصر بعد الطوفان]\nيقال إن أول من نزل مصر بعد الطوفان مصر بن ينصر بن حام بن نوح عم، بدعوة سبقت له من جده نوح عم. روى عن ابن عباس أنه قال دعا نوح عم لمصر بن ينصر بن حام، وهو أبو القبط، فقال: \xabاللهم بارك فيه وفى ذريته وأسكنه الأرض المباركة، التى هى أم البلاد وغوث العباد، التى نهرها أفضل أنهار الدنيا؛ واجعل فيها أفضل البركات وسخر له ولولده الأرض وذللها لهم وقوهم عليها\xbb . قيل وكان السبب فى نزول مصر أرض مصر، وبه سميت، أن فليمون الكاهن صدق نوحا عم وآمن بالله تعالى، وسأل نوحا أن يحمله بأهله وولده معه فى السفينة فحمله. قال فلما انجلى الطوفان، قال فليمون لنوح عم يا نبى الله اجعل لى رفعة وقدرا أذكر به بعدى؛ فزوج نوح [مصر بن] ينصر بن حام من بنت فليمون فولدت له ولدا فسماه فليمون على اسم جده لأمه. فلما أراد نوح قسمة الأرض بين بنيه قال له فليمون: يا نبى الله إن بلدى خير البلاد وأولى الناس به ابنى مصر، فابعثه معى إليه أظهره على كنوزه وأوقفه على علومه ورموزه. قال فأنفذه معه فى جماعة من أهل بلده، قيل إن عددهم كان رجلا فقطعوا الصخور وبنوا المصانع والمعالم، وبنوا مدينة سماها ماقة، ومعنى ماقة بلغتهم وهى مدينة منف. وأطلع فليمون صهره مصر بن ينصر على\nكنوز مصر وعلومها، وعلمه خط البرابى، وأخرج له المعادن من الذهب والفضة والزبرجد والفيروز وغير ذلك من الجواهر، وأطلعه على عمل الصنعة فى الجبل الشرقى فسمى به المقطم.\nوتزوج الملك امرأة من بنات الكهنة، فولدت له أربعة من الولد منهم قطيم وإليه عهد بعد موته. فلما حضرته الوفاة أمر أن يحفر له سرب بين جبلين طوله ذراعا، ويفرش بالمرمر، ويجعل فى وسطه مجلس مصفح بالذهب له أبواب، على كل باب تمثال من الذهب عليه تاج مرصع بنفيس من الجوهر، جالس على كرسى من الذهب قوائمه من الزبرجد. ونقشوا فى صدر كل تمثال آيات عظاما وأسماء من أسماء الله تعالى مانعة من أخذه، وجعلوا جسده فى تابوت من زبرجد مصفح بالذهب، وجعلوا معه فى ذلك المجلس ألف قطعة من الزبرجد المخروط، وألف تمثال من الجوهر النفيس، وألف إناء مملوءة من در الدر الفاخر. ووضعوا هنالك الصنعة الإلهية والعقاقير السرية، ومعها الطلسمات العجيبة، وأكوام من سبائك الذهب بعضها فوق بعض، ثم كتبوا على المجلس: \xabمات مصر بن ينصر بن حام بن نوح عم بعد سنة مضت من أيام الطوفان، ولم يعبد الأصنام إذ لا هرم ولا أسقام، ولا عوز ولا اهتمام، وحصن مجلسه بأسماء الله تعالى العظام، التى لا يصل إليها أحد من الأنام، وكان يدين للملك الديان، ويؤمن بالمبعوث بالقرآن، الداعى إلى الإيمان، الظاهر فى آخر الزمان\xbb . ثم دهموا ذلك بالصخور العظام وجعلوا فوقها الرمال، وذلك بين جبلين متقابلين، وجعلوا فيها علامات .\nثم ولى ابنه قطيم وهو أبو الأقباط؛ وكان جبارا عظيم الخلق وفى أيامه هلكت عاد بالريح، فكان ملكه سنة. وكان قد عمل\nلنفسه قبل موته سربا تحت الأرض معقودا على آزاج فى الجبل الغربى.\nوجعل فيه من الذخائر والغرائب والتماثيل، ومن الطلسمات والعجائب التى يطول وصفها، كما كان فى نواويس آبائه.\nقال، فما زال هؤلاء الملوك من ذرية. مصر بن ينصر يتوارثون الملك خلف عن سلف، إلى أن كان منهم ملك يسمى عديم، وكان عاقلا عالما، وهو أول من صلب. وكان سبب ذلك أن امرأة ورجلا زنيا فى أيامه، فأمر بهما فصلبا على منارين بناهما لهما، وجعل ظهر كل واحد منهما إلى ظهر الآخر، وطلاهما بأطلية مانعة لفناء جثتيهما، وزبر على المنارين اسماهما وما فعلا، وتاريخ الوقت الذي عمل بهما ذلك فيه؛ فانتهى الناس فى أيامه عن الزنا. وناووس عديم هذا من أعاجيب الدنيا، وهو فى صحراء قفط على وجه الأرض، وهو قبة عظيمة من زجاج أخضر براق، معقودة على ثمانية آزاج، قدر قطرها ذراع وارتفاعها فى الهواء ذراع، يخضر بخضرتها ما حولها من الأرض وعلى رأس القبة طائر من الذهب منشور الجناحين موشح بجوهر نفيس، وهو طلسم تلك القبة؛ يمنع الوصول إليها وإلى ما فيها. وذكر أن قوما قصدوا ذلك الناووس فى صحراء قفط، ورأوا القبة وعاينوا ما فيها، وأقاموا عليها أياما لا يقدرون عليها؛ وكانوا منها على قدر أذرع، وكانوا إذا قصدوها دارت القبة على يمينهم وشمالهم. وذكروا أنهم عاينوا ما فيها من العجائب، وأنهم رأوا الملك وهو على سرير من ذهب، مشبك عليه ثياب منسوجة بالذهب منظمة بنفيس الجواهر، وهو مكشوف الوجه، فقدروا وجهه بذراع ونصف، وقدروا طول بدنه ب أذرع، وله لحية كبيرة. وفى جانب القبة مصحفا من مصاحف الحكمة، وفيها موائد على كل مائدة أوانيها: فمنها مائدة در رمانى وآنيتها منها، ومنها مائدة ذهب أحمر يختطف الأبصار وهو الذهب الذي يعمل منه تيجان الملوك وآنية المائدة منها، ومنها مائدة من حجر الشمس المضىء وآنيتها منها، ومائدة من الزبرجد الذي إذا نظرت إليه الأفاعى سالت عيونها، ومنها مائدة كبريت أحمر مدبر على ما ذكروه من تدبيره فى مصاحف حكمتهم وآنيتها منها، ومائدة ملح أبيض براق يكاد نوره أن يخطف الأبصار\nوآنيتها منها، ومنها مائدة زئبق معقود وحافاتها وقوائمها زئبق أصفر معقود وآنيتها من زئبق أحمر معقود. وقيل وجعل معه فى القبة جواهر عظيمة، وأوانى من الفضة المدبرة، وجعل حوله سبعة أسياف صاعقية وسبعة كاهنية، وفى القبة معه تماثيل أفراس من ذهب، وعليها سروج من ذهب، وعدة توابيت مملوءة بالدنانير التى ضربها وصور عليها صورته. وفى تلك القبة أشياء من العجائب والغرائب يطول وصفها .\nوقيل إنه ملك من ذرية هؤلاء الملوك ملك يسمى ساوس، وهو أول من عبد البقر. وقيل إن السبب فى ذلك أنه اعتل بعلة يئس فيها من نفسه، وأنه رأى فى منامه صورة روحانى عظيم الخلق يخاطبه ويقول له: لا يخرجك من علتك إلا عبادة البقر، لأن الطالع كان حلوله بك فى صورة ثور. فأمر ذلك الملك بأخذ ثور أبلق حسن الصورة، فبنى له مجلسا فى وسط قصره عليه قبة مذهبة، ووكل به سادنا، وكان يبخره له ويطيبه. وكان يعبده سرا من أهل مملكته، فبرأ من علته وعاد إلى أحسن حاله. وقال آخرون وكان السبب فى ذلك أن هذا الملك كان يتفقد بلاده ويطوف عليها؛ وهو أول من عملت له العجل، وعملت عليها قباب من خشب مذهبة وفرشت بالفرش.\nوكانت البقر تجره فيطوف على جميع بلاده، فإذا مر بالمكان الخرب أمر بعمارته.\nفقيل إنه نظر ذات يوم إلى ثور من تلك البقر التى كانت تجر تلك العجلة التى كان فيها الملك، وكان ثورا أبلقا حسن الهيئة، فأعجبه فأمر بإزالته من جر العجلة وسوقه بين يديه، وجعل عليه حللا من فاخر الديباج. فتفرد به يوما ينظر إليه، فبينما هو قائم بين يديه خاطبه الثور فقال له: لو رفعتنى أيها الملك كفيتك جميع أمورك، وأعنتك على ما تريد، وقويتك على ملك وأزلت عنك جميع عللك.\nفارتاع الملك من كلامه، وأمر به حينئذ وغسل وطيب وبنى له هيكلا، وأمر بعبادته. وكان فى ذلك الثور آية أنه لا يروث ولا يبول ولا يأكل إلا أطراف ورق الشجر مرة واحدة فى الشهر. قال فافتتن الناس به، وصار ذلك أصلا لعبادة البقر بأرض مصر. وصار ذلك الثور يعبد مدة ثم إن ذلك الثور أمرهم أن يصنعوا صورة مثل صورته من ذهب مجوفة، ويؤخذ من رأسه شعرات ومن ذنبه ومن تحت قرونه ومن أظلافه ويجعل فى ذلك التمثال. وعرفهم أنه لاحق\nبعالمه، وأمرهم أن يجعلوا جسده فى حرز من حجارة وينصب فى الهيكل، وينصب تمثاله عليه، ويكون ذلك وزحل فى شرفه، والشمس مسعودة تنظر إليه من تثليث، والقمر زائد، وتنقش على التمثال علامات الكواكب السبعة. فأمر الملك فعملت صورة الثور من ذهب، وكللت بأصناف الجوهر، وصنعوا سائر ما أمرهم به ذلك الثور، وفى الوقت الذي حدد لهم. وكان ذلك التمثال يخبرهم ما أمرهم به ذلك الثور، وفى الوقت الذي حدد لهم. وكان ذلك التمثال يخبرهم بالعجائب وما يحدث وقتا وقتا، ويجيبهم عن جميع ما يسألونه عنه، فعظم أمر ذلك التمثال، فنذرت له النذور وقربت له القرابين، وقصده الناس من الآفاق فكان يخبرهم بما يريدون. وبقيت عبادة البقرسنة فى دولة ذلك الملك يتوارثونها خلف عن سلف ، إلى أن ملك منهم ملك يقال له ما ليق، وكان موحدا على دين من سبق من أجداده، قطيم ومصر، فكانت القبط تذمه لذلك؛ وكانت القبط تعبد الكواكب والبقر. وكان هذا الملك يستعمل الغزو والجولان على البلاد؛ وزعم بعض أهل مصر أن الله تعالى أيده بملك من الملائكة يوعظه ويرشده، وربما أتاه فى نومه فأخبره بالأشياء وأمره ونهاه. فجمع جيوشا عظيمة وأتخذ سفنا كثيرة فى البحر، وغزا جموع البربر برا وبحرا وهزمهم وأستأصل أكثرهم، وبلغ إفريقية وقتل أكثر أهلها وكانوا على الكفر. واتخذ فى بحر الروم سفينة، وكان لا يمر بأمة إلا أبادها إلى أن غزا بلاد الأندلس. ومشى إلى بلاد الافرنج وكان بها ملك عظيم، فحشد أمم نواحيه وأقام يحاربه شهرا ثم طلب السلامة والأمان، وأهدى إليه هدايا كثيرة. فسار عنه ودوخ الأمم المتصلة بالبحر الأخضر وأطاعه أكثرها، وعمل أعلاما على البحر الأخضر، وزبر عليها اسمه وتاريخ الوقت الذي عملها فيه. وخرب مدن البربر حيث كانت حتى الجأهم إلى ذرى الجبال، ثم رجع إلى مصر، فتلقاه أهل مصر بصنوف اللهو والطيب، وفرشت له الطرقات بأنواع الرياحين والأزاهير، ودخل قصره وهو غانم موفور؛ وذلك صنع الله لمن وحده ولم يشرك به شيئا. وأمر أن يبنى له ناووس فكان يتعبد فيه، فلما حضرته الوفاة أمر أن يدفن فيه، وألا يدفن معه ذهب ولا فضة ولا جوهر. فلم يدفن معه سوى الطيب، وصحيفة مكتوبة بخطه: هذا ناووس فلان\nابن فلان الملك، مات مؤمنا بالله لا يعبد معه غيره، بريئا من الأصنام وعبادتها، مؤمنا بالبعث والحساب والمجازاة على الأعمال، فمن أحب النجاة من عذاب الآخرة فليؤمن بما أومن به .\nوكان من ذرية هؤلاء الملوك، كلكن الملك الجبار، كان يعقد التاج على رأسه، وكانت دار مملكته منف، وهى كانت دار الملوك قبله. وكان يحب الحكمة؛ وإظهار الحكمة والعجائب، ويقرب العلماء والمنجمين وأهل الصنعة، فلم تعمل الكيمياء قط فى وقت من الأوقات كما عملت فى أيامه، حتى أستغنى أهل ذلك العصر عن معادن الذهب فلم يشتروها، ولم يكن الذهب أكثر منه فى أيامه، ولا الصنعة أقوى منها فى وقته. كان يطرح المثقال من مثاقيل الكيمياء على القناطير الكثيرة من الفضة فيصبغها. ويحكى القبط عنه أنه اخترع أشياء تخرج عن حد العقل حتى أنهم يسمونه حكيم الملوك؛ غلب جميع الكهنة فى علمهم حتى كان يخبرهم بما غاب عنهم فخافوه. وفى وقته كان نمرود ابراهيم الخليل عم ؛ وكان نمرود جبارا شديد البأس، وكان ملكه بالعراق، وكان قد أوتى قوة وبطشا فغلب على أكثر الأرض، فأراد أن يستوزر كلكن الملك. وبعث إليه فى ذلك فخافه كلكن وأجابه إلى ذلك، ووجه إليه أنه يريد أن يلقاه منفردا من أهله وحشمه، ليريه من حكمته وسحره؛ فسار النمرود إلى موضع يلقاه فيه كلكن. فأقبل كلكن تحمله أربع أفراس ذوات أجنحة، وقد أحاط به نور كنار، وهو فى صورة مهيبة؛ فدخل بها وهو متوشح تنينا عظيما، والتنين فاغرفاه، ومعه قضيب آس؛ فكلما رفع التنين رأسه ضربه بالقضيب الذي بيده، فلما رأى النمرود هاله ما رآه، واعترف له بجليل حكمته وسأله أن يكون له ظهيرا ففعل. وتزعم القبط أن كلكن الملك كان يجلس إلى الهرم الغربى، وهو أعظم الأهرام، فى قبة على رأس الهرم. وكان يجمع إليه رعيته وحشمه ويأمرهم وينهاهم من أعلى الهرم، ويقيم\nبذلك الموضع أياما كثيرة لا يأكل ولا يشرب؛ ثم إنه غاب عنهم فلم يقفوا على موته ولا على شىء من أمره. وكان عهد إلى أخيه ماليا فلما غاب عنهم أقاموا ماليا أخاه مقامه، فكان همه فى الأكل والشراب والرياسة، غير ناظر فى شىء من الحكمة، وانما استقام له الأمر بهيبة أخيه كلكن، وتقديرهم أنه لم يمت وأنه سيرجع إليهم. وكان لماليا ولد كان أكبر ولده، وكان جبارا جريئا شديد البأس، وكان يستجهل أباه لخلوده إلى الراحة، فأعمل الحيلة فى قتله وحملته على ذلك أمه وبعض وزراء أبيه، فهجم على أبيه فى رواقه وهو سكران فقتله، وقتل معه امرأة له من بنات الملوك كانت قد غلبت على أمره، فقتلها وصلبها وجلس على سرير ملك أبيه. وكان مهيبا شديد البأس كثير القتل، فتزعم القبط أنه أول الفراعنة بمصر، وأنه فرعون ابراهيم عم .\nوالفراعنة سبعة وهو كان أولهم. وقيل إنما سمى فرعون لأنه أكثر القتل حتى قتل قرابته وأهل بيته وخدمه ونساءه وكثيرا من الكهنة والحكماء. وكان حريصا على الولد فلم يرزق ولدا غير ابنة واحدة سماها حورية، وكانت عاقلة حكيمة، وكانت تسدد أباها كثيرا، وتمنعه من كثير من الشر والقتل. فلما رأت أمره يزداد فسادا خافت على زوال ملكه فسمته، فمات بعد أن ملك سبعين سنة.\nفتنازعوا فى تمليكها عليهم ثم اجتمعوا عليها إلا أهل مدينة أبريت فانهم ملكوا عليهم رجلا منهم، وكان من ولد أبريت بن مصر الملك المتقدم الذكر، وبه سميت مدينة أبريت، يقال له أبراحش. فجرت بينهم حروب كانت الدائرة فيها على أبراحش، فهرب خوفا من حورية إلى الشام، وكان بها الكنعانيون من ولد عمليق؛ فاستغاث بملكهم فأخبره بأمره وقرب عليه مصر، وسول له تصييرها إليه.\nفجهز ملك الشام مع أبراحش جيشا عظيما ، وقدم عليه رجلا من قواده، فلما قرب من مصر بعثت حورية طيرا لها إلى جيرون تقول له: إن فلانة سمعت بك وأحبتك، وهى تريد زواجك وأن تكون لها أهلا، وتعطيك بلاد مصر. فسر جيرون بما سمع منها ورغب فيما قالت له، ثم عقدت معه أن يقتل أبراحش. فقال\nلها وكيف أصنع؟ فأخرجت له سما، فسم به أبراحش فمات فى الحين. فلما أراد أن يصل إليها بعثت إليه أنه لا يجوز أن أتزوجك حتى تظهر فى بلادى قوتك وحكمتك لكى أعذر فى زواجك، وأريد أن تبنى لى مدينة عجيبة أدخل معك فيها، فإنى أكره الدخول عليك فى بلادى وبين أهل بلدى. وأن مدينة فى بلاد مصر كانت لأوائلنا قد خربت، فانظر موضعها واظهر حكمتك فيها، وبعثت معه من يريه الإسكندرية.\nقيل فجد جيرون فى بنائها، وبعثت إليه حورية من مصر مائة ألف صانع، فأقام فى بنائها مدة وأنفق جميع ما كان معه من المال، فلما فرغ من بناء المدينة، وجه إليها يعلمها بتمام المدينة ويحثها على القدوم عليه. فوجهت إليه فرشا كثيرة فاخرة وآلات عجيبة، وقالت له: \xabقسم جيشك أثلاثا وابعث الثلث الأول، حتى إذا بلغت نصف الطريق فابعث إلى الثلث الثانى، فإذا بلغت الثلثين من الطريق، فابعث إلى الثلث الثالث حتى يكون الجيش من ورائى ومن أمامى، لئلا يرانى أحد إذا دخلت عليك؛ ولا أحب أن أجد معك سوى صبية تخدمك. ثم أقامت تجهز له الجهاز والأموال حتى أيقن بإقبالها، فوجه إليها ثلث جيشه. فعملت لهم الأطعمة والأشربة المسمومة وخرجت إليهم فى خيولها وخدامها، فلما لقوها أنزلتهم وأمرت حشمها فأقبلوا عليهم بالأطعمة والأشربة والطيب، كل ذلك من مسموم، فلم تصبح منهم عين تطرف . ثم سارت فلقيها الثلث الثانى من الجيش، ففعلت بهم كذلك. ثم سارت فلقيها الثلث الثالث، ففعلت بهم مثل ذلك، وهى تبعث إليه وتقول: إنى بعثت الجيش إلى مصر يحفظها بعدى، إلى أن دخلت على جيرون هى وطير لها وجوار كن معها، فرشقت طيرها عليه، فارتعدت مفاصله وخارت قواه، ولم يملك نفسه شيئا فأيقن بالهلاك؛ وقال جيرون: \xabمن ظن أنه يغلب النساء فقد كذبته نفسه\xbb . فقيل إنها فصدته وأسالت دمه حتى مات، فقالت: \xabدماء الملوك شفاء النفوس\xbb .\nوأخذت رأسه فوجهت به إلى قصرها فنصبته عليه، وحملت بيوت أمواله إلى منف دار مملكتها، وبنت حينئذ منار الإسكندرية، وزبرت عليه اسمها واسمه، وما أراد وما فعلت به، وتاريخ الوقت الذي كان فيه ذلك. ويذكر فى بناء منار الإسكندرية غير ذلك مما سيأتى ذكره إن شاء الله تعالى. قيل فلما اتصل خبر حورية بالملوك وما فعلت بالجيش الذي دخل بلادها، هابوها وعظمت فى أعينهم، فمن كان\nينازعها ويروم أخذ بلادها كف عن ذلك فاشتد ملكها وعظم أمرها، وبنت حصونا على بلاد مصر من ناحية النوبة، وعملت طلاسم كثيرة وأعلاما وأشياء كثيرة يطول وصفها .\nقيل فلما ضعفت حورية عن الملك عهدت إلى بنت عم لها تسمى دليفة. فلما هلكت حورية ضعفت دليفة عن الملك، وخرج عليها أيموش يطلب ثأر خاله أبراحش، واستنصر بملك العماليق صاحب الشام فأجابه، وخرج فى نصرته لما كانت حورية فعلمت بقائده وبجيشه فيما تقدم. وقدم جيش أيموش، فخرجت إليه دليفة تحاربه فغلبها، فلما أيقنت بالغلبة سمت نفسها فهلكت فى الحين.\nثم إن ملك الشام العمليقى غلب على مملكة مصر، وكان اسمه الوليد بن دومع، وأصل العمالقة من العرب العاربة، وكان شديد البأس فأباد الأمم ودوخ البلاد حتى بلغ فيما يقال إلى جبل القمر الذي ينبعث من تحته النيل، وإنما سمى جبل القمر لأن القمر يطلع عليه أبدا لخروجه عن خط الاستواء، وبلغ هيكل الشمس وأرض الذهب، وهى أرض تنبت قضبان الذهب، واستعبد هذا الملك القبط وملكهم سنة ثم هلك. ويقال إنه ركب ذات يوم فرسا وخرج متصيدا فركض به الفرس فقتله، ودفن فى بعض تلك الأهرام . ثم ملك بعده ابنه الريان بن الوليد، وهو فرعون يوسف عم، والقبط تسميه نقراوش، وكان عظيم الخلق جميل الوجه عاقلا محسنا إلى الناس. لما ولى بعد أبيه أسقط الخراج عن الناس سنين، وفتح خزائن الأموال وفرق على الضعفاء فأحبه الناس وشكروه.\nوكان يميل إلى الراحات وغلبت عليه اللذات، وملك أمر الناس رجلا من أهل بيته يقال له قطفير، وهو الذي يسميه أهل الأثر العزيز. وقد ذكره الله تعالى فى القرآن العظيم فى قصة يوسف عم ، وكان رجلا عاقلا حصيف الرأى نزيه النفس مؤثرا العدل، وأمر أن ينصب له فى قصره سرير من الفضة يجلس\nعليه والوزراء والكتاب بين يديه، وقام بجميع أمور الملك الريان وكفاه أحسن الكفاية؛ والملك مشتغل بلذاته عاكف عليها، قد صنعت له مجلس من الزجاج الملون ومن البلّور الشفاف والبلّور المصبوغ، وأرسل حواليها المياه ووضع فيها السمك، فكانت الشمس إذا وقعت على ذلك الموقع أرسلت شعاعا عجيبا يبهر العيون. وعملت له متنزهات على النيل وعلى غير النيل على عدد أيام السنة، وكان ينتقل كل يوم إلى متنزه منها، وكان فى كل متنزه من الفرش الغريبة والآنية العجيبة ما ليس فى غيره. وفى أيامه كان من أمر يوسف عليه السلام ما قصه الله تعالى فى محكم تنزيله، وخبره مع امرأة العزيز وهى زليخة بنت صاحب عين الشمس، وعين الشمس مدينة عظيمة من مدن أهل مصر فيها عجائب.\nوكانت زليخة بنت عم العزيز، واسم العزيز قطفير بلغة القبط، واسم الملك نقراوش بلغة القبط، وقد ذكر الله تعالى اسم العزيز فى كتابه العزيز .\n[ذكر ما نقله القبط من خبر يوسف عم]\nقيل إن فى كتب تواريخ القبط أنه أدخل مصر غلام من أهل الشام كان قد باعه أخوته، وكانت قوافل الشام تعرس بناحية الموقف اليوم، فأوقف غلام فنودى عليه وهو يوسف عم فبلغ زنته ذهبا، فاشتراه قطفير وهو العزيز ليهديه للملك. فلما أتى به منزله ورأته زليخه امرأته، قالت له أتركه لنا نربيه ففعل؛ فكان من أمر افتتانها به ما قصه الله تعالى إلى أن رأى الملك الرؤيا؛ فأخرج يوسف من السجن، وأمر بغسله وكساه الثياب الرفيعة، وحمل إليه فلما دخل عليه ورآه امتلأ به سرورا وألقيت عليه منه المحبة والهيبة، وسأله عن الرؤيا ففسرها له كما ذكر الله تعالى؛ فقال له الملك ومن يقوم لى بذلك؛ فقال له يوسف أنا، فإنى حفيظ عليم. قيل فرأى الملك امتحان يوسف عم ومعرفته فأمر له بعمل الفيوم، وكان موضعا يفيض فيه ماء النيل، فأقام تلك الأرض وأتى بتلك الحكمة\nالمعجزة والآية البينة فى أشهر، وقيل فى يوما، وشق تلك الخلجان الثلاثة فلما فرغ يوسف عم من عمل الفيوم وأعلم بذلك الملك، خرج هو ووزراؤه وأهل دولته ينظرون إلى ما صنع يوسف عم، فلما نظر الملك إلى حكمة صنع ذلك الموضع فى مدة يسيرة، قال الملك لوزرائه: هذا عمل ألف يوم؛ فسمى الفيوم من حينئذ. قيل فسر الملك بيوسف سرورا عظيما وخلع عليه وألبسه تاجا مكللا بفاخر الجوهر، وأمر الجيش أن يركب معه ويطاف به ويرد إلى القصر ويجلس على سرير العزيز. وكان العزيز قد مات فاستخلفه الملك على ملكه، وسماه العزيز وزوجه امرأته زليخة، فدخل بها يوسف عم فوجدها عذراء فقال لها هذا أصلح مما أردت، فقالت له اعذرنى فإن زوجى كان عنينا، ولم تكن تراك امرأة فى حسنك وجمالك إلا صبا قلبها إليك.\nقيل فلما جاءت سنين الخصب أخذ يوسف فى توفير الغلات والاستكثار من الأقوات، وبنى لاختزان الزرع مخازن عظيمة، ويقال إن بعضها باق إلى الآن فإن الطعام كان يختزن بسنبله كما ذكر الله تعالى. فلما جاءت سنين الجدب ونقص فيض النيل وتوالى نقصانه فأحسن يوسف عم السياسة والتدبير فى تلك المجاعة، وقسط بيع الزرع بين الناس فلا يبيع لأحد إلا بقدر حتى ساوى بين الناس؛ ولولا ذلك لهلك الناس. وقيل إنه صار ليوسف جميع أموال أهل مصر بما باع منهم من الطعام، فإنه باع منهم بالذهب والفضه والحلى والثياب والدواب والأبنية والعقار، وبجميع ما بأيديهم من الأموال، حتى أنه يقال إنهم باعوا منه أولادهم ونساءهم وأنفسهم حتى صاروا له كلهم عبيدا، وتلك كرامة من الله أكرمه بها لأجل ما بيع ببلدهم . فمن ذلك الوقت صارت أرض مصر كلها للسلطان ليس للرعية فيها ضيعة ولا فدان. وقد اعترضهم بعض ولاة مصر فى أيام بنى عبيد الذين كانوا بها قبل اليوم ملوكا، وأراد أخذ ديارهم واحتج عليهم بهذا القول. قيل وقحط أهل الشام فى ذلك الوقت، فكان من أمر يوسف مع أخوته ما قصه الله تعالى فى كتابه. فوجه يوسف عم إلى أبيه وحمله من الشام إلى مصر بجميع أهله وولده، فلما قرب يعقوب عم من مصر خرج\nإليه يوسف فى وجوه أهل مصر، وتلقاه وأدخله على الملك، وكان يعقوب عم نبيا جليلا فصيحا فأعظمه الملك وأحبه. قيل فدعاه يعقوب إلى توحيد الله تعالى ونبذ الأصنام، وكان يوسف قد قدر عنده ذلك فتمكن من استبصار الملك وآمن.\nفيقال إنه كتم إيمانه خوفا من ذهاب ملكه، ثم لم يزل يعقوب عليه السلام مكرما معظما حتى حضرته الوفاة، وذلك فى حياة الملك الريان بن الوليد، فأوصى يعقوب أن يدفن فى مكانه ومكان آبائه بالشام، فوضع فى تابوت وخرج به يوسف ووجوه أهل مصر حتى بلغوه إلى موضعه. قيل فمنعهم عيصوم أخو يعقوب أن يدفنوه هناك لأن إسحاق عم آباهما وهب لعيصوم ذلك الموضع حتى اشتراه يوسف منه ودفن فيه يعقوب. ثم انصرف يوسف إلى مصر، وولد له بعد ذلك أولاد كثير.\nثم هلك الملك الريان واستخلف ابنه دريموس بن الريان، وهو فرعون الرابع ويسميه أهل الأثر دارم، وكان الملك الريان قد أوصى ابنه دريموس أن يبقى يوسف على ما كان عليه من استخلاف وحجابة وأن يسمع من رأيه، فبقى يوسف على ما كان عليه . وكان الملك دريموس يسمع من رأيه غير أنه خالفه فى دينه وما كان اعتقده أبوه، فكان يخدم القمر لأنه كان طالعه، فكان يصنع له أصناف الفضة وينصبها فى قصر الرخام الذي بناه أبوه فى شرقى النيل. قيل وقبض يوسف عم بعد سنين من ولاية هذا الملك، فجزع عليه جزعا شديدا وكذلك أهل مصر، وأمر الملك أن يكفن فى ثياب الملوك، وجعل فى تابوت من رخام، ودفن فى الجانب الغربى من النيل عاما فأخصب ذلك الجانب ثم نقل إلى الجانب الشرقى عاما فأخصب أيضا ذلك الجانب، فلما ظهرت لهم بركته رأوا رأيا أن يجعل التابوت فى وسط النيل، فشدوه بالحبال ودلوه فى وسط النيل فأخصب الجانبان كلاهما جميعا .\nويقال إن الملك الريان بن الوليد صاحب يوسف عليه السلام لم يمت وانه عاش إلى زمان موسى؛ وإنه فرعون موسى عم المذكور فى القرآن، وإنه لما أطال الله فى عمره أدركه الإعجاب فتأله ودعا الناس إلى عبادته، وقيل غير ذلك.\nوتنازع الناس فى أمر فرعون موسى عم، فمنهم من رأى أنه من العماليق، ومنهم من رأى أنه من لخم من الشام، ومنهم من رأى أنه من الفرس من مدينة اصطخر، ومنهم من رأى أنه من ولد مصر المتقدم المذكور والقبط أثبتت ذلك، وزعم قوم من الأعاجم أنه من الأندلس من مدينة قرمونة، وذكر أن اسمه الوليد بن مصعب. وكان سبب ملكه أنه دخل مدينة منف من البادية يحمل خمرا للبيع على أتان له، وكان أهل منف قد اختلفوا فى تولية ملك عليهم فأجمعوا أن يملكوا أول من يدخل فى ذلك اليوم، فكان أول داخل ذلك اليوم على باب المدينة فرعون، فولوه الملك. ومدينة منف كانت فى ذلك الزمان قاعدة مدن مصر ودار مملكتها، فلما تمكن ملك فرعون ببلاد مصر بذل الأموال وجمع الجيوش وقتل من خالفه وناوأه ومدن المدن وخندق الخنادق فاستقر له الأمر، وكان جبارا معجبا يدعو الناس إلى عبادته، ويقول لهم أنا ربكم الأعلى كما حكى الله تعالى عنه فى كتابه العزيز . واستعبد بنى اسرائيل فكان من أمره مع موسى ما قصه الله تعالى. ثم ملك موسى بلاد مصر والشام لبنى اسرائيل يتوارثونها ملك عن ملك، ومنهم كان داود وسليمان عم إلى أن بعث الله تعالى عيسى عم، وظهر دين النصرانية، ملك أرض مصر النصارى وكانوا يتوارثونها ملك عن ملك إلى أن جاء الله تعالى بالإسلام، فدخل المسلمون بلاد مصر وملكوها فى أيام عمر بن الخطاب رضه.","2-3":"[ذكر فتح مصر]\nقال عبد الرحمن بن عبد الله بن [عبد] الحكم : لما كان سنة من الهجرة [٦٤٠] فى خلاقة عمر بن الخطاب رضه وقدم عمر رضه الجابية، خلا به عمرو ابن العاص وقد كان دخل مصر فى الجاهلية وجرى له بها خبر الكرة ، فكان عمرو بن العاص يعرف أحوال مصر، فجعل يعظم عند عمر بن الخطاب أمرها، ويعرفه بكثرة جبايتها ويهون عليه أمرها وفتحها، حتى ركن لذلك عمر رضه.\nفعقد له على وجهزهم معه، وقال له: \xabسر وأنا مستخير الله تعالى وسيأتيك كتابى سريعا بما أرى إن شاء الله تعالى، فإن أدركك كتابى آمرك فيه بالانصراف قبل أن تدخل أرض مصر فانصرف، وإن أنت دخلتها قبل أن يأتيك كتابى فامض لوجهك واستعن بالله واستنصر به\xbb . فسار عمرو بن العاص فى جوف الليل ولم يشعر به أحد، ثم استخار عمر فكأنه تخوف على المسلمين فكتب إلى عمر ويأمره بالانصراف بمن معه، فأدركه الكتاب وهو فى رفح فتخوف عمرو إن قرأ الكتاب يكون فيه الأمر بالانصراف، فلم يأخذ الكتاب من الرسول ودافعه حتى نزل قرية فيما بين رفح والعريش، فسأل عنها فقيل له إنها من أرض مصر، فدعا بالكتاب فقرأه على المسلمين ثم قال لهم: ألستم تعلمون أن هذه القرية من أرض مصر؟ فقالوا بلى. فقال لهم إن أمير المؤمنين عهد إلى إن لحقنى كتابه وأنا لم أدخل أرض مصر أن أرجع بمن معى، وإن كتابه لم يلحقنى حتى دخلت أرض مصر فسيروا على بركة الله. فساروا حتى توسطوا بلاد مصر فنزلوا بموضع على النيل وهو الفسطاط، ولم يكن فيه حينئذ مدينة وإنما بنى الفسطاط عمرو. وكان ملك مصر فى ذلك الزمان المقوقس وهو الذي أهدى\nلرسول الله - صلى الله عليه وسلم - مارية القبطية، فلما سمع المقوقس دخول المسلمين بلاده ونزولهم فى موضع الفسطاط ولم يكن له بهم علم راعه ذلك، ونظر فى توجيه الجيوش إليهم. فكتب عمرو بن العاص إلى عمر بن الخطاب رضه يستمده، فأمده بأربعة الآلاف. ويقال إن أسقفا كان بالإسكندرية من أهل العلم بالكوائن، لما بلغه قدوم عمرو مع المسلمين إلى بلاد مصر كتب إلى القبط يعلمهم أن ملكهم قد انقطع، ويأمرهم بتلقى عمرو والطاعة له؛ فأطاعه كثير من القبط فاستعان بهم على من سواهم. ثم سار عمرو إلى البلد الذي كان فيه الملك المقوقس، وكان حصنا عظيما مانعا وقد خندقوا حوله وجعلوا للخندق أبوابا وعلقوا شبك الحديد على تلك الأبواب، فكان عمرو يفرق أصحابه على جوانب الحصن ليرى العدو أنهم أكثر مما هم، ويغدوا بهم فى الأسحار ويصففهم على أبواب الخندق عليهم السلاح والدروع.\nثم إن أمير المؤمنين عمر بن الخطاب رضه بعث الزبير بن العوام فى الفا فتقوى المسلمون، فجعل عمرو يلح بالقتال ووضع المنجنيق، فلما أبطأ الفتح على المسلمين قال الزبير بن العوام رضه: أنا أهب نفسى لله وأرجو أن يفتح الله على المسلمين. فوضع له سلم إلى جانب الحصن فرقى ثم قال لهم إذا سمعتم تكبيرى أجيبونى، فما شعر أهل الحصن إلا والزبير على رأس الحصن يكبر والسيف بيده منتضى، فتحامل المسلمون على السلم حتى نهاهم عمرو خوفا أن ينكسر بهم، فهرب أهل الحصن جميعا. وعمد الزبير إلى باب الحصن ففتحه واقتحم المسلمون فيه، فلجأ الروم والقبط إلى الفوق وهو قصر منيع فى الحصن، فحاربهم المسلمون نحو شهر، وكان فى ذلك القصر المقوقس مع أكابر الروم والقبط، فخاف المقوقس على نفسه وعلى من معه فخرج من باب خفى وترك فى القصر جماعة يقاتلون، وسار إلى الجزيرة موضع دار الصناعة اليوم، وأمر بقطع الجسر . ثم أرسل المقوقس إلى عمرو بن العاص: \xabإنكم قوم قد دخلتم بلادنا وطال مقامكم بأرضنا وإنما أنتم عصبة يسيرة، وقد اضلتكم الروم وجهزوا إليكم الجيوش، وقد أحاط بكم هذا النيل وأنتم أسارى بأيدينا، فابعثوا إلينا رجلا منكم نسمع كلامه فعسى أن يتأتى الأمر بيننا وبينكم على ما تحبون ونحب،\nوينقطع عنا وعنكم هذا القتال قبل أن تغشاكم جيوش الروم فتندموا. فرد عمرو مع رسله أنه ليس بيننا وبينكم إلا إحدى ثلاث خصال: إما أن تدخلوا فى الإسلام فكنتم إخواننا وكان لنا ما لكم وعلينا ما عليكم؛ فإن أنتم أبيتم أعطيتم الجزية عن يد وأنتم صاغرون؛ أو جاهدناكم بالصبر والقتال حتى يحكم الله بيننا وبينكم، وهو خير الحاكمين. فلما رجعت رسل المقوقس قال لهم كيف رأيتموهم، قالوا رأينا أقواما الموت أحب إلى أحدهم من الحياة والتواضع أحب إليهم من الرفعة، ليس لأحدهم فى الدنيا رغبة، إنما جلوسهم على التراب وأكلهم على الركب وأميرهم كواحد منهم، يغسلون أطرافهم بالماء، فإذا حضرت صلاتهم لم يتخلف عنها أحد منهم ويتخشعون فى صلاتهم تخشيعا كثيرا. فقال المقوقس والذي يحلف به لو أن هؤلاء استقبلوا الجبال لزلزلوها وما يقوى على قتال هؤلاء أحد، وإن لم يغننا صلح هؤلاء القوم وهم محصورون بهذا النيل فإنهم لن يجيبوننا إذا تمكنوا من الأرض. وكان ذلك وقت خروج النيل وفيضه، والمسلمون قد أحدقت بهم المياه من كل جانب لا يقدرون على النفوذ إلى الصعيد ولا إلى غيره. ثم بعث إليهم عمرو بن العاص رجال أحدهم عبادة ابن الصامت، وكان أسود اللون من العرب، وأمرهم أن يكون متكلم القوم فإنه كان فصيحا، وأمرهم أنه لا يجيبهم إلا إلى إحدى ثلاث خصال وهى المتقدم ذكرها.\nفركبوا السفن ودخلوا على المقوقس؛ فتقدم عبادة للكلام فهابه المقوقس لسواده وقال نحوا عنى هذا الأسود وقدموا غيره، فقالوا جميعا إن هذا الأسود سيدنا وأفضلنا رأيا وعلما. فكلمه عبادة ثانيا، فقال المقوقس لأصحابه: لقد هبت منظره وإن قوله عندى لأهيب، وإن هذا وأصحابه إنما خرجوا إلى خراب الأرض وما أظن ملكهم إلا سيغلب على الأرض كلها. وقال نعطى كل من فى الجيش دينارين ونعطى أميرهم دينار ونبعث إلى خليفتهم دينار؛ فلم يجبه عبادة إلا إلى إحدى ثلاث خصال. فقال المقوقس لأصحابه ماذا ترون؟\nفقالوا: أما ما أرادوا من دخولنا فى دينهم فهذا ما لا يمكن ولا نترك دين المسيح إلى دين لا نعرفه، وأما ما أرادوا [من] أن يجعلونا عبيدا فالموت أيسر من ذلك، فإن رضوا بأن نضعف لهم ما أعطيناهم وينصرفوا عنا كان أهون علينا.\nفانصرف عنهم عبادة بن الصامت وأصحابه ولم ينعقد بينهم صلح على شىء، فألح عليهم المسلمون بالقتال حتى أذعن المقوقس لإعطاء الجزية عن القبط خاصة.\nوأما الروم فيخيرون فى المقام على الجزية والخروج إلى أرض الروم، وتم ذلك بينهم وبين المسلمين؛ قيل فأحصى يومئذ جميع من بمصر أعلاها وأسفلها من القبط فكانوا ألف ممن بلغ الحلم، سوى الشيخ الفانى والصغير الناشئ والنساء. وفرض على كل رجل منهم دينارين فى السنة فكانت فريضتهم ألف دينار، ورفع ذلك عرفاؤهم بالأيمان المؤكدة ثم زادت بمن استقر بها من النصارى وغيرهم من النوبة دينار. فجعل عمرو يبحث عن الأموال ويضمها إلى بيت مال المسلمين، فذكر له أنه عند عظيم الصعيد مال كثير، فبعث إليه فيه فقال له ما عندى مال فسجنه. وسأل عمرو من كان يدخل إليه هل سمعوه يذكر أحدا، فقالوا له سمعناه يكثر ذكر راهب بالطور، فبعث عمرو فأتوا بخاتم المسجون فكتب كتابا على لسانه إلى ذلك الراهب بالرومية وختم عليه، وبعث به إلى ذلك الراهب فأتى بقدرة نحاس مختومة بالرصاص فإذا فيها كتاب فيه: يا بنى إذا أردتم ما لكم فاحفروا تحت الفسقية. فبعث عمرو الأمناء إلى الفسقية وهى الساقية، فحفروا تحتها فاستخرجوا أردب دنانير، والأردب نحو قنطار ونصف.\nثم أمر عمرو المسلمين ببناء دور يسكنونها بالفسطاط وهى مدينة مصر اليوم، وإنما سميت مدينة مصر بالفسطاط لأن عمرو بن العاص حين دخل مصر ضرب فسطاطه بذلك الموقع، فلما أراد التوجه إلى الإسكندرية لقتال من بها من الروم أمر بنزع الفسطاط فإذا فيه يمام قد فرخ، فقال عمرو لقد تحرم هذا منا بحرم، فأمر الفسطاط فأقر مكانه وأوصى عليه. فقام المسلمون من الإسكندرية بعد فتحها وقال الناس أين ننزل فقيل الفسطاط، لفسطاط عمرو الذي تركه فى المنزل مضروبا بالموضع الذي يعرف اليوم بدار الحصى. ثم بدأ عمرو ابن العاص ببناء المسجد وكان موضعه حدائق وأعناب فقطعت، ووضعوا أيديهم على البناء فلم يزل عمرو ومن حضر من أصحاب رسول الله - صلى الله عليه وسلم - قياما حتى وضعت القبة، فلما أتمه اتخذ فيه منبرا فكان يخطب عليه.\nوقال أبو تميم الجهانى: فوصل ذلك عمر بن الخطاب رضه فكتب إلى عمرو ابن العاص: أما بعد فإنه بلغنى أنك اتخذت منبرا ترقى فيه على رقاب المسلمين\nالثالثة نقيطة. وكان على كل واحدة منها سور، وقيل إنه كان على الإسكندرية مدن كبار و أسوار ب خنادق. وكان أصل بنائها أن الإسكندر استقام له ملكه فى بلاده، وكانت بلاده رومة وما إلى ذلك من بلاد الروم، وكان فيما يقال روميا، فيقال إنه خرج يختار أرضا صحيحة الهواء والتربة والماء يبنى بها مدينة يسكنها، فأتى موضع الإسكندرية فأصاب به أثر بنيان وعمد رخام منها عمود عظيم مكتوب عليه بالقلم المسند ، وهو القلم الأول من أقلام حمير وملوك عاد: \xabأنا شداد بن عاد، سددت بساعدى الوادى وقطعت عظيم العماد من شوامخ الجبال والأوطاد، وبنيت إرم ذات العماد التى لم يخلق مثلها فى البلاد.\nأردت أن أبنى هنا مدينة كارم وأنقل إليها كل ذى قدم من القبائل والأمم، فأصابنى ما أعجلنى وعما ذهبت إليه قطعنى، فارتحلت عن هذه الدار، لا لقهر ملك جبار ولا بخوف جيش جرار، ولكن لتمام المقدار، وانقطاع الآثار، وسلطان العزيز الجبار. فمن رأى أثرى وعرف خبرى وطول عمرى فلا يغتر بالدنيا بعدى\xbb . قيل فلما رأى الإسكندر طيب أرض ذلك المكان وصحة هوائه وما به عزم على بنيان مدينة بذلك الموضع، فبعث إلى البلاد فحشد الصناع واختط الأساس، واستجلب العمد والرخام وأنواع المرمر الملون والأحجار فى البحر من جزيرة صقلية وبلاد إفريقية وأقريطش.\nفلما اختط أساس المدينة كلها وحفره أراد أن يكون إنزال البناء فى وقت سعادة وبقاء على الدهور، فوضع على حفير الأساس عمود رخام وعلى كل\nقطعة من الأرض خشبة قائمة، ووصل بها حبالا منوطة بعضها ببعض يرجع جميعها إلى عمود الرخام، وعلى العمود جرسا عظيما وعلى كل قطعة من تلك الحبال جرسا صغيرا، فإذا حركوا حبل الجرس الكبير على العمود وخفق تحركت سائر الحبال وخفقت الأجراس. وأقام الإسكندر يرقب الوقت المحمود، وأمر الصناع إذا سمعوا تحريك الأجراس أن يضعوا الأساس دفعة واحدة وقد كانوا استعدوا لذلك. فبينما الإسكندر يرقب الوقت أصابته سنة، فوقع غراب على حبل الجرس الكبير فحركه فتحركت جميع الأجراس، فوضع البناؤون فى تلك الساعة الأساس . وارتفع الضجيج بالتحميد والتسبيح فاستيقظ الإسكندر لضجيجهم، فسأل عن الخبر فأعلن، فعجب من ذلك، وقال: \xabأردت أمرا فأراد الله غيره ويأبى الله إلا ما يريد، أردت طول بقائها وأراد الله سرعة بنائها\xbb .\nثم تمادى على عملها وبنى المدينة على آزاج وطبقات قد عمل لها مخاريق ومتنفسات للضوء، يسير الفارس وبيده رمح طويل فلا يضيق به طريق من تلك الآزاج حتى يدور جميع الإسكندرية. وكذلك كانت أسواقها مقنطرة فلا يصيب أهلها المطر. وبنى أسوارها من أنواع الرخام الأبيض والملون، وكذلك جميع قصورها ودورها، فكانت تضيء بالليل بغير مصباح لشدة بياض الرخام، وربما علت على أسوارها شقاق الحرير الأخضر لاختطاف بياضها أبصار الناس . وبنى عليها أسوار وأمام كل سور خندق، وبين كل خندق وسور فصيل.\nويقال إنها كانت أعظم مدينة بنيت فى معمور الأرض وأغربها بنيانا، فقيل إنه كان سكان البحر يؤذون الناس ويختطفونهم بالليل، فاتخذ الإسكندر الطلسمات مصورة على أعمدة رخام على هيئة شجرة السرو، طول العمود منها ذراعا، وهى باقية إلى هذه الغاية. يقال إنها على أعمدة نحاس قد خرقت الأرض فصورت\nفيها أشكال وصور تمنع وتدفع . وبنى المنار على طرف اللسان الداخل فى البحر من البر، وجعله على كرسى من زجاج على هيئة السرطان فى جوف البحر ، وجعل طوله فى الهواء ألف ذراع ، وجعل فى أعلاه المرآة.\nوكانت المرآة قد ركبت من أخلاط غريبة فيبصر فيها ما يأتى من مراكب العدو على مسيرة أيام فيتأهب لهم، فإن قربت المراكب من البلد عملت أخلاط بأدهان يعرفونها وطليت بها المرآة وعكس شعاعها على تلك المراكب فأحرقتها.\nوجعل فى المنار تماثيل من نحاس وطلاسم كثيرة تمنع وتدفع ولها خواص، فمنها تمثال قد أشار بسبابة يده اليمنى نحو الشمس حيث كانت من مشرق أو مغرب أو أفق فيدور معها، وتمثال يشير بيده نحو العدو إذا كان منه على مقدار ليلة، فإن دنا وأمكن أن يرى بالبصر يسمع لذلك التمثال صوت هائل على ميلين أو ثلاثة.\nوتمثال آخر كلما مضى من الليل أو من النهار ساعة سمع له صوت طرب بخلاف الصوت الذي كان منه قبل ذلك. وقد اختلف الناس والرواة فى أمر بناء هذا المنار فمنهم من رأى أنه من بناء الإسكندر؛ ومنهم من رأى أن دلوكه الملكة بنتها؛ ومنهم من رأى أن جيرون الملك المتقدم الذكر بناها. وقيل إن الذي بنى الأهرام بناها، وقيل إن الذي بنى رومة المدينة العظمى بنى الإسكندرية وبنى منارتها. وإنما أضيفت الإسكندرية إلى الإسكندر لسكناه بها وغلبته ممالك الأرض منها. وقيل إن الإسكندر كان لا يخاف أن يطرقه عدو فى البحر ولا يهاب ملكا يرد عليه فيجعل لذلك مرقبا وحراسا. قال عبد الله بن عمرو\nابن العاص إن أول من ملك الإسكندرية فرعون واتخذ فيها مصانع ومجالس، وهو أول من عمرها ثم تداولها الملوك بعده، وإن سليمان بن داود عم اتخذها مسكنا وبنى فيها قصورا ومصانع عجيبة من بناء الجن، وبنى فى المنار مسجدا متقنا وهو باق إلى الآن. والأصح أن الإسكندر بناها من أولها واختط أساسها وبنى المنار فيها وعمل المرآة فى أعلاها، فيقال إنه ما ظهر العدو فى البحر ولا ضرب بأسيافه الإسكندرية إلا بعد زوال تلك المرآة، وكان زوالها فى خلافة الوليد بن عبد الملك بن مروان. وذلك أن ملك الروم أعمل الحيلة فى زوال المرآة من المنار، فبعث خادما من خواص خدمه ذا دهاء ورأى ومعرفة بما يتناول من أشغاله، فجاء مستأمنا إلى بعض الثغور. فحمل إلى أمير المؤمنين الوليد بن عبد الملك بن مروان فأعلمه أنه كان من خواص ملك الروم وأنه أراد قتله لموجدة لم يكن لها حقيقة، وأنه هرب منها ورغب فى الإسلام فأسلم بين يدى الوليد؛ وأظهر له النصح فى أشياء خدمه فيها. ثم إنه استخرج له دفائن فى بلاد دمشق وغيرها من بلاد الشام بكتب كانت عنده، فلما رأى ذلك الوليد شرهت نفسه وتمكن طمعه وباحثه عما عنده من هذا الفن؛ فقال له إن الإسكندر استولى على ممالك العالم، واحتوى على الأموال والذخائر التى كانت لشداد بن عاد وغيره من ملوك العرب والعجم والفرس وغيرهم من الأمم؛ فبنى لها الآزاج والأسراب والأخباء، وأودعها تلك الذخائر والأموال والجواهر ثم بنى فوقها تلك المنارة التى بالإسكندرية. فلو هدم ذلك المنار استخرج من تحته من الأموال والذخائر والكنوز وما لا عين رأت؛ فصدق ذلك الوليد وطمع فيه، وبعث معه من خواصه وثقاته من يقف على هدم المنار، وأمر صاحب الإسكندرية أن يعينه على جميع ما يريد، فهدم ذلك الرومى قدر نصف المنار وأزال المرآة التى كانت غرضه وأراد هدم الكل، فضج أهل\nالإسكندرية، وعلموا أنها مكيدة وحيلة. فلما استفاض ذلك خشى الرومى على نفسه، وهرب فى الليل فى مركب كان قد أعده لذلك الوقت؛ وبقيت المنارة على ذلك المقدار إلى هذا الوقت.\nصفة المنارة اليوم: هى اليوم أحزم؛ أما الحزام الأول فهو مربع البناء، قد عمل أحسن عمل بحجارة مربعة قد خفى التصاقها حتى صارت كالحجر الواحد لم يغيره الزمان، ارتفاعه ذراعا. ثم ترك فى أعلاه قدر غلظ الحائط وهو أصابع ونحو أذرع سوى ذلك الغلظ ؛ ورفع على ما بقى من البناء بناء مثمن الشكل طوله ذراعا . ثم ترك قدر غلظ حائطه وهو أقل من غلظ الأسفل وهو نحو أذرع سوى ذلك [الغلظ] ؛ ثم أقيم عليه بناء مربع الشكل ارتفاعه ذراعا ونحوها. وفى أعلا ذلك مسجد محكم البناء ويقال إنه مسجد سليمان . وفى الناحية الشمالية من البناء كتابة من النحاس لم يقدر أحد على فكها ولا معرفة ما هى. وباب المنارة حديد لا يعلم له عهد، ويرقى إلى الباب من أسفل المنارة فى علوة لا تتبين، وكذلك إلى أعلا الحزام الأول فى طريق يمشى فيه فارسان متناكبان فى أرض سهلة لا يكاد الراقى يعلم فيه","2-4":"أما بحسبك أن تقوم قائما والناس من تحتك، فعزمت عليك إلا كسرته. ثم اختط عمرو داره التى هى اليوم عند باب المسجد بينهما الطريق، وكذلك اختط جميع من أراد السكنى بمصر من المسلمين دارا لنفسه. وكان الزبير بن العوام اختط دارا وجعل فيها السلم الذي صعد عليه إلى الحصن المتقدم الذكر، فلما ولى عبد الملك بن مروان اغتصبها من الزبير وأصفاها لنفسه، فلما [ولى] أبو جعفر المنصور من بنى العباس ردها على هشام بن عروة بن الزبير .\nذكر المشهور من مدن أرض مصر\nمنها مدينة مصر وهى الفسطاط الذي ذكرنا آنفا: وهى حاضرة بلاد مصر فيها من المبانى والمصانع والبساتين والغرف المشرفة على النيل والقصور ما يبهج العيون ويطرب المحزون.\nمدينة القاهرة: محدثة من بناء العبيديّين الشيعة الذين كانوا بها، بينها وبين مصر نحو أميال. وهى مدينة كبيرة فيها من القصور والمبانى ما يعجز الوصف عنه وكانت دار مملكة العبيديين. وكان الحاكم من بنى عبيد قد بنى بين الفسطاط والقاهرة مسجدا عظيما على مشاهد كانت هناك، وجعل فيه سدنة وخدما يوقدون فيه السرج الليل كله. وذكر أنه أراد أن ينقل إليه جثة النبي - صلى الله عليه وسلم -، وقد كانت توجهت له الحيلة فى ذلك غير أن الله دفع وأظهر الله تعالى أهل المدينة على ذلك وقاية لرسوله - صلى الله عليه وسلم - وردا لكيد عدوه. وذلك أن الحاكم بذل الأموال لرجال من شيعته فمشوا إلى المدينة فاشتروا دارا تلاصق مسجد رسول الله - صلى الله عليه وسلم -، وبذلوا فيها ما لا كثيرا، وأخذوا ذرع ما بين الدار والقبر، واحتفروا سربا عظيما حتى كادوا أن يصلوا إلى القبر المكرم، فأطلع الله أهل المدينة على ذلك، فقتلوا أولئك البغاة الفسقة ومثلوا بهم وردموا ذلك الحفير بالحجارة وأفرغوا عليها الرصاص فلا يطمع فى الوصول إلى مثل ذلك طامع أبدا\nمدينة منف: مدينة عظيمة أزلية قديمة. وهى كانت دار مملكة الملوك القدماء ، وكان بها فرعون موسى عليه السلام. وكان اتخذ لها بابا وفصل حيطان المدينة بالحديد والصفر، وفيها كانت الأنهار تجرى من تحت سريره وكانت أنهار. ذكر رجل من ولد على بن أبى طالب رضه، قال: رأيت بمنف دار فرعون، وكنت أمشى فى مشارفها ومجالسها وغرفها وجميع سقائفها وحجورها فإذا ذلك كله حجر واحد منقور. فإن كان بناء قد أحكم حتى صار فى الاستواء كحجر واحد لا يستبان فيه جمع حجرين ولا ملتقى صخرتين فذلك عجب، وإن كان جبلا واحدا فنقر الرجال فيه بالمناقير حتى خرقت فيه تلك المخارق فهو أعجب وأعجب .\nمدينة دلاص: هى مدينة قديمة أزلية عجيبة البناء فيها غرائب؛ وهى كانت مجتمع سحرة مصر .\nمدينة إخميم: وهى مدينة كبيرة أزلية قديمة فى الضفة الشرقية من النيل، وفيها أسواق وحمّامات ومساجد كثيرة. وداخل سورها البربى المتقدم الذكر، لم يتغير منه شئ. وفيها من عجيب المبانى والآثار ما يعجز الوصف عنه .\nمدينة أسيوط: وهى مدينة قديمة أزلية مسورة على الجانب الغربى من النيل، جميلة القصبة كثيرة الفوائد وهى أكثر بلاد الله قصب السكر وأطيب؛ وفى وسط سوقها بربى تهدم بعضه .\nمدينة عين الشمس: هذه مدينة قديمة أزلية وهى كانت مدينة فرعون، وفيها آثار كثيرة ومبانى عجيبة من أساطين الرخام وتماثيل ونقوش، وفيها بركة عظيمة وقد نقرت فى حجر صلد وحواليها كراسى من رخام، فكان يجلس فرعون عليها وتملأ بالخمر وحواليها أنهار العسل وأنواع المشروبات؛ وبالقرب منها صورة من رخام يخيل للناظر أنها تتكلم ، ذكر أنها كانت ماشطة فرعون.\nوبالقرب منها صنمان من حجارة كل صنم منها طوله أذرع، أحدهما يبكى والآخر يضحك. وهذه المدينة كانت فى طاعة والد زليخة زوجة العزيز، وكانت تعرف ببنت صاحبها .\nمدينة أنصنا: وهى كانت مدينة السحرة فى زمن فرعون وأكثرها خراب.\nوكان بها أيضا بربى لم يبق منه اليوم إلا بيت واحد كأنه من صخرة واحدة.\nويقال إن مارية القبطية التى أهداها المقوقس إلى النبي - صلى الله عليه وسلم - كانت من كورة أنصنا، من قرية يقال لها جفن. ومدينة أنصنا لا يقربها التمساح والناس منه آمنون هناك. وأكثر ما يكون التمساح عدوانا بالشاطئ الذي يقابل أنصنا فى قرية يقال لها الأشمون، لا يقدر أحد أن يقرب من شاطئها، فإذا صارت التماسيح فى حد أنصنا تحولت على ظهورها حتى تجاوز حدها ، وكذلك تصنع بفسطاط مصر فوق المدينة بنحو أميال حتى تخرج عن حد المدينة بمثل ذلك.\nمدينة قوص : هى مدينة كبيرة أزلية قديمة فيها آثار كثيرة للأوائل، وبينها وبين مدينة أسوان غير ان منحوتة فى جبال هنالك فيها قبور الأموات لا يعلم لها عهد، تستخرج منها المومياء الطيبة ، وهم يجدونها فى رممهم وبين أجفانهم. ويقال إن فى تلك الصحراء التى بين قوص وأسوان معادن الذهب، غير أن البجاة وهم جنس من الحبشة تمنع منه؛ وبلادهم بين بحر القلزم ونيل مصر، ويسكن عندهم جماعة من العرب من ربيعة بسبب هذا\nالمعدن . ويتصل ببلادهم معدن الزمرد الفائق الذي ليس له مثيل بعمور الأرض، وهو بموضع يعرف بالخربة فى مفازة وجبال محمية بالبجاة، وإليهم يؤدى الخفارة من يرد لحفر الزمرد. وبين هذا الموضع والنيل أكثر من مرحلة، وبين هذا المعدن والعمران مسيرة سبعة أيام. ولا يعرف معدن للزمرد غيره إلا ببلاد البلهرى من بلاد الهند ولا يلحق بهذا . والهندى هو الذي يعرف بالمكى لأنه يحمل إلى عدن فيؤتى به مكة فاشتهر بهذا الاسم.\nوالزمرد الذي يقطع من الخربة هو أربعة أنواع: فأعلاها الذي يعرف بالمرو، وهو كثير المائية تشبه خضرته السلق إلا أنه يضرب إلى السواد. والنوع الثانى هو البحرى فى لون ورق الآس، وإنما غلب عليه اسم البحرى لأن ملوك الهند والسند والصين يرغبون فيه، ويفضلونه على غيره من الزمرد. والنوع الثالث يعرف بالمغربى لأن ملوك المغرب والأفرنج والأندلس والجلاقة يتنافسون فيه.\nوالصنف الرابع وهو المسمى بالأصم، وهو أدناها وأقلها ثمنا لقلة مائه وخضرته وكثرة ركوده. وأكثر حجارة الزمرد الفائق يبلغ وزن العدسة دنانير، وهذا المعدن قد انهارت غيرانه وتهدمت لبعد العمارة عنه وانقطاع الناس.\nولا خلاف عند جميع من يقرب من موضع ذلك المعدن أن الحيات والأفاعى وسائر الحيوان المسموم لا يقرب هذا المعدن ولا حومته، وقيل إن هذه الحيوانات إذا بصرت بالزمرد الفائق سالت عيونها، وإن الملسوع إذا سقى منه وزن دانق برئ باذن الله تعالى. وكانت ملوك اليونانيين من أرباب الحكمة تفضله على جميع الأحجار، وأهل الحكمة يقولون إن شعاعه نورى وخضرته تقوى بزيادة القمر وامتلائه، والله تعالى فى علمه أسرار مخفية .\nمدينة قفط: هى مدينة متوسطة المقدار أزلية لها سور، وبينها وبين مدينة قوص أربعة أميال وفيها بربى وبقربها شعراء كثيفة .\nمدينة أسوان: هى آخر مدن مصر لأنها ثغر متصل ببلاد النوبة وهم كفرة، ولولا ما بين بلاد مصر وبلادهم من الجبال والأوعار التى تحول بينهم لأفسد النوبة بلاد مصر. والنيل إنما يهبط من بلاد النوبة على صخور وأوعار ولا يدخل ذلك الموضع مركب . ومن أسوان الطريق إلى عيذاب؛ وعيذاب مدينة على ضفة البحر الغربى المعروف ببحر القلزم. ومن عيذاب يعبر إلى ساحل الحجاز إلى جدة، ومن عيذاب يسلك إلى بلاد اليمن والهند وغير ذلك من البلاد .\nومن مدن مصر تنّيس ودمياط: وهما مدينتان قد غلب على أكثر أرضهما ماء البحر. فمدينة تنيس مدينة كبيرة أزلية فيها آثار كثيرة للأول، وأهلها ذو يسار وثروة وأكثرهم حاكه، وبها تحاك ثياب الشروب التى لا يصنع مثلها فى الدنيا. ويصنع فيها لصاحب مصر قميص لا يدخل فيه من الغزل سداة ولحمة غير أوقيتين وينسج من الذهب دينار، قد أحكمه صانعه حتى لم يحوج إلى تفصيل ولا خياطة غير الجيب والبنائق ، والذي تبلغ القيمة فيه دينار. وقد أحكمه صانعه حتى لم يحتاج إلى تفصيل ولا خياطة غير ما قلنا، وكذلك إلى الآن يصنع لكل ملك من ملوك مصر هذا الثوب فى كل عام.\nويسمى هذا القميص البدنة، وليس فى جميع الدنيا طراز ثوب كتان يبلغ الثوب\nمنه وهو سادج دون ذهب دينار عينا غير طراز تنيس ودمياط. ويسكن بجزيرة تنيس ودمياط نصارى هم الآن تحت الذمة بحمد الله؛ ونحن فى سنة [٥] . وأهل تنيس يصيدون السمان وغير ذلك من الطير على أبواب دورهم، فإنهم يمدون شباكا فى سككهم عند أبواب دورهم، والسمان طير يجزع عند خروجه من البحر فيقع فى تلك الشباك. وكانت تنيس أخصب بلاد الله وأكثرها ثمارا وفاكهة، وكانت مقسومة بين ملكين أخوين من ولد أبريت بن مصر، وكان أحدهما مؤمنا والآخر كافرا. فأنفق المؤمن فيها من أمواله فى وجوه البر حتى باع من أخيه الكافر حصته فى تنيس، فزاد فيها الكافر غروسا وأنهارا وبنى فيها مصانع، فاحتاج أخوه إلى ما فى يده فمنعه وسطا عليه بماله وحشمه وحقره لفقره، فقال له أخوه المؤمن: مالى أراك غير شاكر لله تعالى على ما رزقك ويوشك أن ينزع ذلك منك ويغير نعمته عنك.\nفأرسل الله تعالى على جناته ومصانعه الماء فأضحت خاوية على عروشها ؛ فهما اللذان عنى الله تعالى فى سورة الكهف عز وجل: \xabواضرب لهم مثلا رجلين جعلنا لأحدهما جنتين من أعناب وحففناهما بنخل وجعلنا بينهما زرعا فكلتا الجنتين آتت أكلها ولم تظلم منه شيئا\xbb إلى آخر الآيات المحكمات .\nوتركب السفن من تنيس إلى الفرما وهى [على] ساحل البحر.\nمدينة الفرما: وهى مدينة كبيرة قديمة أزلية فيها آثار كثيرة عجيبة تدل على أنها كانت دار مملكة. ويقال إن الذي بناها هو الفرما الملك، ويذكر أهل مصر أن [ابن] المدبر لما ولى مصر وجه إلى الفرما لهدم أبواب من رخام بها فى شرقى الحصن احتاج إلى أن يعمل منها فرشا فى داره فمنع من ذلك أهل الفرما، وخرجوا إلى رسله بالسلاح، وقالوا هذه الأبواب التى ذكرها الله تعالى على لسان يعقوب: \xabيا بنى لا تدخلوا من باب واحد وأدخلوا من أبواب متفرقة\xbb . ومن عجائب الدنيا نخل الفرما فإنها تثمر حين ينقطع البسر والرطب من جميع البلاد، فيكون رطب نخل الفرما بكانون الأول حين تلد النخل فى كل مكان فلا ينقطع أشهر، ولا يوجد هذا فى بلد من البلاد سوى الفرما؛ وهو تمر كبير يوجد فى وزن التمرة درهما وطولها فتر .\nمدينة رشيد: وهى مدينة كبيرة على كثيب رمل عظيم، إذا هبت الريح الغريبة، وهى تشتد عندهم، ملأت عليهم سككهم وبيوتهم رملا فلا يقدرون على التصرف فى أسواقهم. وهم على ضفة النيل قرب البحر، ومن أعجب منتزهات الدنيا ضفة النيل من مصر إلى مدينة رشيد هذه، ولا غلة لثمار الأرض كغلة هذه الناحية. قال أبو عبيد البكري أن رجلا أخبره، من أهل تلك النواحى، أنه رأى ضيعة ما لأحد المصريين تغل فى رمانها وموزها خاصة ألف مثقال فى العام . قال، وهناك كانت ضيعة الليث بن سعد رحمه الله، قال قتيبة سمعت الليث بن سعد يقول: \xabيدخل على فى كل سنة ألف دينار ما وجبت عليها الزكاة قط، يعنى أنها من الفواكه التى لا تجب فيها الزكاة .\nذكر الفيوم: وهو قطر كبير فيه قرى كثيرة، يقال إن فيه من القرى عدة ما فى قطر مصر كله من القرى، فإن يوسف عم حين صنعه أنزل فى كل قرية أهل بيت من قرى مصر؛ وسير لكل قرية من الماء بقدر ما يروى أرضها من غير زيادة ولا نقصان. ويقال أيضا إن بالفيوم قرية على عدد أيام السنة لا تقصر عن الرى أبدا لحكمة شربها، فإذا نقص النيل فى سنة من السنين وغلا السعر بمصر مارت كل قرية منها مصر يوما. وحجر اللاهون بالفيوم من عجائب الدنيا واللاهون قرية كبيرة من قرى الفيوم. وهذا الحجر شاذروان مبنى بأحكم صنعة، مدرج على درجة فيها فوارات\xbb\nفى أعلاها وفى وسطها وفى أسفلها. فتسقى العليا الأرض العليا، والوسطى الأرض الوسطى، والسفلى الأرض السفلى بوزن وقدر لا ينقص لأحد من دون حقه ولا يزاد له فوق حقه. وهو من أحكم البنيان وأتقنه؛ قيل من ذلك الوقت عرفت الهندسة؛ وذكر كثير من الناس أن يوسف عم عمله بالوحى. ولم تزل الملوك من الأمم تقصد هذا الموضع ويتأملون حسن صنعته ويتعجبون من غرائب حكمته، ويقال إن الملك المعاصر ليوسف عم لما تأمله قال هذا من ملكوت السماء، وهو من البناء الذي يبقى على غابر الأزمان؛ ويقال إنه عمل من أشياء: من الفضة والنحاس والزجاج؛ وفى الضفة الغربية منه مسجد يوسف عليه السلام. والفيوم يشرب من ذراعا، وليس بأرض مصر موضع يشرب من ذراعا غير الفيوم لحكمة بنيان حجر اللاهون، وإنما رى أرض مصر من ذراعا، فإذا زاد النيل على قطع الماء عن الفيوم. فإذا كان يوم زيادته سد حجر اللاهون، وحضر ذلك شهود أهل تلك الجهة والمهندسون وأمروهم بالطبول والبنود فلم يكن لمن يدعى نقصان الماء عذر، وخرجت الإرسال عند ذلك بالبشائر إلى مصر، وهو عندهم يوم سرور ونزهة. وأهل الفيوم يزدرعون والماء باق على جميع أرض مصر ولم يتم جريه، فإذا كان حصاد أهل مصر كان\nذلك أول السقية الثانية لأهل الفيوم فإنهم يزدرعون فى العام مرتين، ويزدرعون السقية الثانية القمح والشعير والأرز فضلا عن القطانى. والفيوم أخصب بلاد الله تعالى وأكثرها فاكهة، لا يعدم بها التمر والرطب شتاء ولا صيفا، ولذلك غلتها أكثر جبايات بلاد مصر.\nقال عبد الملك بن حبيب إنما سميت الفيوم لأن أخراجها ألف دينار كل يوم.\nوالفيوم فى وسط بلاد مصر فلا يؤتى إلى كورة الفيوم من ناحية من النواحى إلا من صحراء أو مفازة، ذكر ابن عفر وغيره أن عمرو بن العاص لما فتح بلاد مصر أقام سنة لا يعلم أين موضع الفيوم ولا حيث مكانه حتى بعث عمرو قيس بن الحارث إلى ناحية الصعيد يبحث عن الفيوم، فسار حتى أتى القيس وبه سميت. فأبطأ على عمرو خبره فقال من يأتنا بخبر قيس، فقال ربيعة بن حبيب أنا آتيك به، فركب فرسا له أنثى فجاز بها النيل من الجهة الشرقية وكان معه عمرو بن ربيعة بن حبيب بن الصدفى وأصحابهم، فمشوا فلما سلكوا فى المجابة لم يروا شيئا وهموا بالانصراف، ثم ساروا قليلا فطلع له سواد الفيوم فطلبوا قيسا فوجدوه فى القيسيين فأتوا عمرو بخبر الفيوم .\nمدينة الإسكندرية: ذكر أن اسمها بردة ولها كورة، قالوا كانت الإسكندرية مدن كبار بعضها بجنب بعض: منها شنة وهى موضع المنار وما إلى ذلك؛ والإسكندرية اسم قصبة السلطان وموضعه وهى باقية إلى اليوم؛ والمدينة\nهل هو راق أو ماش؛ فى كل عطف من هذا المصعد باب دار داخلها بيوت مربعة، سعة كل بيت منها ذراعا إلى أذرع، قد فتح له مضاو ومنافس للهواء لئلا تهدمها الرياح. وعدد ما فى المنار من البيوت بيتا\xbb\n، وعطف مطالعها من أسفلها إلى أعلاها عطفا وفى كل عطف درجة. وبيوتها كلها آزاج معقودة، وبناء المنار كله معقود بخشب الساج، وعدة أبوابها الظاهرة خارجا بابا، فتحت لتخرقه الرياح ولولا ذلك لهدمته. وهذا المنار من دخله ولم يعرف مسالكه تاه فيه وضل لأن فيه طرقا تولى إلى أسفله وإلى سرطان الزجاج المتقدم الذكر وإلى البحر. ويقال إن جيش صاحب المغرب حين وصل الإسكندرية وذلك فى خلافة المقتدر ، دخل جماعة منهم المنار على خيولهم ليروا ما فيه من الغرائب، فتاهوا وتهوروا هم ودوابهم وفقد منهم عدد كثير. وقد كان البحر أثر فى أسفل المنارة من غربيها كالكهف العظيم فسد بعض أمراء مصر- أظنه من العبيديين - ذلك الثلم بأساطين الرخام بعضها فوق بعض. فالبحر يضرب اليوم فى تلك الأساطين فلا يؤثر فيها شيئا.\nوفى جهة الشمال من المنار بناء عظيم عريض ارتفع من قعر البحر حتى ظهر على وجه الماء، يدل على أنه كانت عليه مصانع قد ذهبت، ويسمى ذلك البنيان الفاروس؛ تحته ترسو السفن لأنه يكف عنها الرياح والموج. وقد زعم قوم أن ذلك الظاهر ليس بيتا وإنما هو ما هدم من حجارة المنار الذي ذكرنا.\nقال بعض العارفين إذا أردت أن تبصر ارتفاع المنار وعلوه من الجو فاخرج من الإسكندرية من باب أشتوم ، وتسير على ضفة البحر نحو نصف ميل ثم تسير نحو الشمال مقدار ذلك ثم تسير على بناء فى البحر كالقناطر ولها منافس والبحر يضرب من ناحيتها نحو خطوه، فإذا خرجت من ذلك البناء سرت\nفى فضاء داخل فى البحر كأنه جزيرة والمنارة فى أعلا هضبة منها. وقد أحاط البحر بالمنارة من جهات: من ناحية الشمال والغرب والجنوب؛ فتنظر حينئذ إلى المنارة فتراها كأنها سحابة قد ارتفعت فى الجو، فتظن أنها ترتعد من انعكاس شعاع الشمس وضرباته فى المنارة .\nولهذه المنارة بالإسكندرية مجتمع فى العام يسمونه بخميس العدس ، وهو أول خميس فى شهر مايه لا يختلف فى مدينة الإسكندرية عن الخروج إلى المنار فى ذلك اليوم أحد. وقد أعدوا لذلك اليوم الأطعمة والأشربة، ولابد فى ذلك الطعام من العدس. فيفتح بابها للناس ويدخلون فيها، فمن ذاكر لله تعالى ومن مصل ومن لاه ومتفرج، فيقيمون إلى نصف النهار ثم ينصرفون .\nومن ذلك اليوم بعينه يحترس البحر. وفى المنارة قوم مرتبون يوقدون النار الليل كله فى الحزام الأول، فيؤم أهل السفن سمت تلك النار من جميع البلاد؛ ويوقد صاحب السفينة النار فى سفينة فإذا رأى المحترسون النار فى البحر، زادوا فى وقود النار وأوقدوها من جهة المدينة؛ فإذا رأى ذلك محترسو المدينة ضربوا البوقات والأجراس حذرا من العدو.\nوكان حول المنار مغائض يستخرج منها أنواع من الأحجار يتخذ منها فصوص الخواتم، مثل الاسبادشيخ ومثل الكركهن والباقلمون وغير ذلك من الأحجار الغريبة التى لا توجد فى هذا الزمان ولها خواص. وهذا الباقلمون حجر يتلون ألوانا مختلفة عند النظر إليه كلون ريش الطواويس الهندية؛ فإن ألوان ريشها أحسن ألوانا من هذه الطواويس التى بهذه البلاد. ولطواويس الهند جمال عظيم وخلق عجيب، تتمازج ألوان ريشها وتترادف فيها فيرى لها منظر عجيب؛ وأصلها من الهند وما خرج منها من ديار الهند صغر حجمه وكدر لونه كما يفعل ما نقل من النارنج والأترج من بلاد الهند، فإنها تصغر وتعدم تلك الروائح العطرية لعدم ذلك الهواء والتربة. قيل وكان حول المنار من تلك الجواهر كثير، فيقال إن الإسكندر أغرق ذلك حول المنار فيوجد هناك إذا طلب، ويكون ذلك الموضع أبقى لها ويرى الناس على مر الدهور عظيم ملكه\nوما قدر عليه لوجود ما عز عند غيره مطلبه. وقيل أيضا إنها كانت آلات شراب الإسكندر، فيما مات كسرتها أمه ورمت بها فى تلك المواضع غيرة أن ينتفع بها أحد . والقصر الأعظم الذي كان بالإسكندرية، لم يكن له على معمور الأرض نظير، هو اليوم خراب. وهو على ربوة عظيمة بإزاء باب المدينة طوله ذراع وعرضه على النصف من ذلك ولم يبق منه إلا بعض سواريه؛ وبابه من أحكم بناء وأتقنه على عضادة من حجر واحد، وعتبته حجر واحد؛ فيه نحو أسطوانة قائمة غلظ كل واحدة نحو عشرة أشبار .\nوفى نحو الشمال منه أسطوانة عظيمة لم يسمع بمثلها، غلظها شبرا وهى من العلو بحيث لايدرك أعلاها قاذف بحجر، وعليها رأس محكم الصناعة يدل على أن بناء كان عليها، وتحتها قاعدة من حجر أحمر مربع الشكل محكم عرض كل ضلع من أضلاعه شبرا فى ارتفاع أشبار. والأسطوانة منزلة فى عامود من حديد قد خرقت به الأرض، فإذا اشتدت الرياح رأيتها تتحرك وربما جعلت تحتها الحجارة فتطحنها لشدة حركتها . وهذه الأسطوانة من إحدى أعاجيب الدنيا، ويقال إن الجن صنعتها لسليمان بن داود عم. وكانت وسط قبة وحولها أساطين، وأعلا الكل قبة تشبه الصحفة من حجر واحد رخام أبيض بأحسن صنعة وأغرب إتقان. فلما مات سليمان بن داود عم ، رفعت الجن تلك القبة ورمت بها فى البحر، فإنها كانت من غرائب ما عملت الجن لسيدنا سليمان بن داوود عم . قال حمزة بن محمد المصرى إن بعض ملوك مصر دخل الإسكندرية ورأى قصرها فنظر إلى قصر عجيب الشأن غريب البنيان من بناء الأولين، فعا الصناع وسألهم أن يبنوا له مصله فقالوا له لا نقدر على ذلك، فعزم عليهم فقالم إليه شيخ وقال: أنا أبنى لك مثله وأحسن منه إن فعلت لى ما أريد، قال بلى، قال: ايتوني بثورين مطيقين وعجلة فأمر له بذلك فدخل\nمقابر الأولين واحتفر قبرا منها واستخرج جمجمة عظيمة، فوضعها فى العجلة فما جرها الثوران إلا بعد مشقة وجهد، فجاءه فقال أصلح الله الأمير إن أعطيتنى من تكون رؤوسهم مثل هذا الرأس بنيت لك مثل هذا القصر، فعلم أنه لا يقدر على ذلك . وقال حمزة بن محمد أيضا: رأيت بالاسكندرية قصابا عنده ضرس يزن به اللحم زنته أرطال . وكان بالإسكندرية دار ملعب قد تهدم أكثرها، وكانت قد بنيت بضروب من الحكمة، وكانوا يجلسون فيها لقضاء حوائجهم، فكان كل جالس فيها إنما جلسوه تلقاء وجه صاحبه ولا يخفى على أحد منهم شئ من حال غيره، يتساوى قريبهم وبعيدهم فى ذلك. وكان لهم يوم مهرجان يجتمعون فيه فى هذا الملعب، ويحضره رؤساؤهم وأبناء ملوكهم وعامتهم، ويلعب فيه الصبيان والفتيان بالصوالج وبينهم كرة . فإن دخلت تلك الكرة كم رجل ممن حضر فى ذلك اليوم فلابد له من ولاية مصر؛ كان هذا عيدهم معروف لا ينكره أحد. وكان عمرو بن العاص رحمه الله قد سافر إلى الإسكندرية فى الجاهلية تاجرا بالقطن والأدم، فحضر ذلك الملعب فى ذلك اليوم، فلعبوا فيه بالكرة فدخلت كم عمرو بن العاص حتى أتى الله بالإسلام فكان ما قدر الله تعالى من دخول عمرو مصر وولايتها مرات .\nوالإسكندرية تعجب كل من رآها لبهجتها وحسن منظرها، وارتفاع مبانيها وإتقانها وسعة شوارعها وطرقاتها. وهى برية بحرية، وفيها من النعم والأرزاق والفواكه ما ليس ببلد مع طيب هوائها وتربتها. وقد ذهب بعض المفسرين\nإلى أن إرم ذات العماد هى الاسكندرية . وقال الناظرون فى الأعمار فى جميع الأقاليم والأمصار: لم تطل أعمار الناس فى بلد من البلدان كطولها بمريوط ووادى فرغانة؛ ومريوط قرية من قرى الإسكندرية بالقرب منها؛ وهى كبيرة ولها بساتين كثيرة ومنها تجلب الفواكه إلى الإسكندرية. ويروى أن عوف بن مالك حين دخل مدينة الإسكندرية قال لأهلها : \xabما أحسن مدينتكم\xbb ، فقالوا له إن الإسكندر حين بناها قال: \xabأبنى مدينة إلى الله فقيرة وعن الناس غنية\xbb فبقيت بهجتها على مر الدهور. وكان الفرما أخو الإسكندر بنى مدينة الفرما وقال: \xabإنى أبنى مدينة عن الله غنية وإلى الناس فقيرة\xbb ، فذهبت بهجتها ولا يزال ينهدم منها كل يوم شئ لا يجبر أبدا ويقال إن عمر بن عبد العزيز لما دخل الإسكندرية، وكان إذ ذاك والى مصر، ورأى عظمتها وسعة آثارها وعلم أنها كانت مدينة كبيرة قال لعاملها وكان من أهلها: \xabأخبرنى كم كان عدد سكان الإسكندرية فى أيام الروم\xbb ؛ فقال له: \xabوالله لا أدرك علم ذلك أحد إلا الله وحده، ولكنى أخبرك كم كان عدد رؤسائهم ورؤسائها وملوكها فإن ملك الروم أمر بإحصائهم، وكتب ذلك فى تواريخهم وكتبهم، فوجدهم ألف ملك .\nوالدليل على عظم شأنها وكثرة ملوكها أن المطر إذا نزل فيها نزولا شديدا وسال ترابها مع الماء، خرج من فيها من الرجال والنساء والصبيان والضعفاء يلتمسون حواليها، فيجدون قطع الذهب والفضة من الحلى وغيره والياقوت والزمرد وأنواع الجواهر، وليس يرجع أحدا منهم بغير شىء.\nومدينة الاسكندرية أعظم مدن مصر؛ وبلاد مصر كلها فيها من العجائب والغرائب ما يعجز عنه الواصفون. ذكر أن أحمد بن طولون كان صاحب مصرفى سنة نيف ومائتين وكان مولعا بمعرفة هذه الآثار القديمة والعجائب ، فذكر له أن رجلا من الأقباط بأرض الصعيد، وهى من أعالى بلاد مصر، له نحو سنة، وهو ممن عنى من لدن حداثته بالعلم والإشراف على الآراء وانتحل من مذاهب المتفلسفين وغيرهم، وأنه علامة بالممالك والملوك ومعرفة بهيئة الأفلاك والنجوم؛ وكان نصرانيا على مذهب اليعاقبة. فبعث ابن طولون إليه قائدا من قواده فحمله إليه فى النيل مكرما؛ وكان الشيخ قد انفرد عن الناس فى بنيان قد اتخذه وسكن فى أعلاه، وكان قد رأى الرابع عشر من ولده. فلما وصل إلى أحمد بن طولون أكرمه وأبره وأسكنه بعض مقاصيره ومهد له موضع جلوسه وحمل إليه لذيذ المأكل والمشرب، فأبى الشيخ أن يتغذى أو يلبس إلا ما حمل مع نفسه من كعك وسويق ونحوها، وقال هذه بنية قوامها بما ترون من الغذاء والملبس فإن أنتم سمتمونى النقل على العادة كان ذلك سبب انحلال البنية ويفوتكم منى ما تطلبونه، فتركه ابن طولون وما يريده. ثم أحضره مجلسه مع أهل الدراية من أصحابه وخواص مجلسه وصرف إليه همته وغرضه؛ فلما سأله عن بحيرة تنيس ودمياط المتقدم ذكرهما، قال كان موضع البحيرة أرضا لم يكن بديار مصر مثلها لطيب التربة وذكاء الربيع؛ وكانت جنات متصلة ولم يكن بمصر كورة يقال إنها تشبه الفيوم إلا هى وحدها، وكانت أكثر فاكهة منه؛ وكان الماء ينحدر إلى قرى موضع البحيرة صيفا وشتاء يسقون منه متى شاءوا، وفضلة الماء تصب فى البحيرة. وكان بين العريش وقبرص طريق مسلوكة فى يبس، وبينهما اليوم مسير طويل فى البحر، فلما كان قبل استفتاح المسلمين بلاد مصر ب سنة طما ماء البحر وزاد فأغرق القرى التى كانت فى موضع البحيرة، وما كان منها فى البقاع المرتفعة فهى باقية إلى الآن قد أحاط بها الماء. وقال وعند هذه الزيادة التى زادها ماء البحر، طغى الماء على القنطرة التى كانت بين بلاد الأندلس وبين\nساحل طنجة من أرض المغرب. وكانت قنطرة عظيمة لا يعلم فى معمور الأرض مثلها، مبنية بالحجارة، تمر عليها الإبل والدواب من ساحل المغرب إلى الأندلس، وكان طولها ميلا فى عرض واسع وسمو كبير؛ وربما بدت هذه القنطرة لأهل السفن تحت الماء فعرفوها.\nوسئل عن ممالك الحبشة والأحابيش التى على النيل، فقال ألفيت منهم ملكا كل ملك منهم ينازع من يليه. قال وبسبب استحكام النارية فى بلادهم، تكون عندهم معادن الذهب كثيرة، فإن حرارة الشمس ويبسها يغير الفضة ذهبا، فإذا طبخ ذلك الذهب بالملح والزاج والطوب، خرج ما فيه من الفضة.\nوسئل عن منتهى النيل فى أعلاه، فقال أصله من البحيرة التى لا يدرك طولها ولا عرضها، وهى تحت خط الاستواء تحت قنطرة الفلك المستقيم؛ وهو الموضع الذي فيه الليل والنهار متساويان الدهر كله.\nوسئل عن الأهرام، فقال إنها قبور الملوك؛ وكان الملك إذا مات وضع فى حوض من رخام ثم أطبق عليه وبنى له هرم على قدر همة وليه ، ثم يوضع الحوض فى وسط الهرم ويصنع باب الهرم تحت الحوض، ثم يحفر له طريق فى الأرض ويعقدونه آزاجا. فقيل له فكيف هذه الأهرام المملسة وكيف كانوا يصعدون لبنائها؛ فقال كانوا يبنون الهرم مدرجا ويصعدون لبنائه فإذا فرغوا من عمله نحتوه. قيل له وكيف كانوا يصنعون بهذه الحجارة العظيمة التى لا يقدر رجل منا أن يزحزحوا منها حجرا واحدا؛ قال كانت لهم فراقل قد دبروها بأخلاط من المعادن وأنواع من الحكم، فكانوا يضربون بها الحجر الكبير فينقسم لهم على القدر الذي يريدون ويتأتى لهم النحت، ومع هذا فإنه كان لهم صبر وجلد على أعمالهم ليس لمن بعدهم. قال الوصيفى ، قال رجل قبطى، وقد أجرينا من هذا الذي ذكرنا ، إنهم أصابوا فى بعض الكنائس فى طاق سفطا فى سلة ففتحوها فوجدوا فيها فرقلة فعجبوا منها ولم يدركوا لها معنى، فطرحوها فى النار فكانت تثب من النار حتى تبلغ سقف الكنيسة فكسروها ، ثم ندموا على فسادها.\nقال: الناظر هذه مدينة الإسكندرية يطمع فيها عدو صقلية أبدا، ويجشم مراكبه بأهوال تصيبه عليها؛ فمنها ما أدركته عشية العاشر من محرم سنة [- أغسطس ١١٧٤] . وذلك أنه احتفل فى مراكب كثيرة ونزل فى ساحلها وحصن ما قدر وعزم على محاصرة البلد، فما كان إلا أن عزم على المقارعة حتى صاح فى الأعداء صائح وصرخ بينهم صارخ فولوا مدبرين ، وقتل بعضهم والحمد لله رب العالمين.\nوفتح الله تعالى ببركة هذا الأمر العزيز على المسلمين بديار مصر، عندما سمح بخاطر أمير البلاد بها، وهو يوسف بن أيوب الكردى، المخطط بصلاح الدين، أن يخاطب الخليفة الإمام أبا يوسف يعقوب بن الإمامين الخليفتين رضه أجمعين؛ فهزم روم الشام واستأصل شأفتهم، وفتح بيت المقدس شرفها الله، وجميع تلك البلاد التى كانت بأيدى أعداء الله. ونص الرسالة الواردة بصورة فتح، كلام مختصر من كتاب وصل من الإسكندرية ، تاريخه فى العشر الوسط من شعبان المكرم سنة [٥] [- أكتوبر ١١٨٧] ، يصف ما سناه الله تعالى ويسره بقدرته من الفتوحات فى الروم دمرهم الله تعالى . وذلك أن رسل ملكهم وصلوا إلى دمشق فى الصلح، فأراد يوسف بن أيوب أن يصالحهم ويعقد لهم الصلح على أن يدفع لهم ألف أردب من القمح مع المضاف إليه، وكان بن أخيه، المخطط عندهم بتقى الدين، قد تصاهر مع أمير التركمان وجاء بخلق كثير من الأتراك، فلما عاين عمه يريد الصلح عز عليه ذلك وغضب. فسأله عمه عن شأنه فقال له: يأتى الناس متطوعين مسارعين للجهاد وتصالح أنت الأعداء الروم، ماذا يقوله أهل العراق وأهل الأمصار عنا. فقال يوسف لابن أخيه: تعرف ما صنع أصحابنا\nيوم الرملة؛ وقد كان خرج معهم إلى لقاء الأعداء الروم فهربوا وتركوه، وكاد أن يقتل أو يؤسر، وأخذ له جميع ما كان معه من عدد وأمتعة، وذلك سنة ٥٧٢.\nفلما سمع الأجناد قالوا: صدق ونحن تائبون ونحلف له . فدخل تقي الدين مع الأمراء وأشياخ الأجناد على يوسف، وحلفوا له كلهم فى المصاحف أنه لا يشرب أحد منهم كأس خمرة أبدا ولا يرتكب معصية. فلما حلفوا كلهم.\nفرح يوسف بذلك وأرسل إلى الرسل، فاجتمع الرسل مع تقي الدين ومع على بن يوسف بن أيوب وجماعة أشياخ الأجناد فاشترطوا شروطا كثيرة فى مصالحتهم: منها ألا يؤخذ من أحد مكس؛ وأن ترد بعض البلاد. فغضب الرسل ووقع بينهم كلام كثير وقالوا بيننا وبينكم السيف، فاستخف الرسل بكلامهم وفارقوهم، فقامت قلوب المسلمين وليقضى الله أمرا كان مفعولا.\nوخرجوا بنيات صادقة وعزائم ناجحة، فأخذوا طبرية من فورهم، وبقيت قصبتها لأنها مانعة جدا . ووصل الروم دمرهم الله فى جمع حفيل طامعين فى المسلمين، فمنعهم المسلمون الماء، فعزموا على المقاتلة؛ وصفت الصفوف غرة جمادى الأول، وقيل إن المقابلة كانت فى يوم الجمعة ال من ربيع الآخر [٢٩ يونيه] ، فكان يوما عظيما، دفع عليهم الروم دمرهم الله دفعة والمسلمون بحمد الله ثابتون، فدفع عليهم المسلمون دفعة واحدة فلم يقف منهم أحد، فهم بين أسير وقتيل؛ وأحصى عدد من قتل وأسر ألفا. وأخذ ملوك الروم أسارى وأعيانهم وصاحب الكرك والشوبك، وقد كان هذا اللعين صالح يوسف ابن أيوب وغدره، فلما مثل بين يديه فى جملة الأسارى، لم يتمالك أن قام يوسف بن أيوب فقتله بخنجر كان بيده . ثم قاتل يوسف قصبة طبرية فرغبوا فى المصالحة، فحصن البلد وقصبته وبعث الأسارى إلى دمشق ؛ وأسرع السير إلى عكة فدخلها صلحا وأخرجهم منها دون سلاح ولا عدة .\nوقد كان سيف الدين، أخو يوسف المذكور، حصر يافا ودخلها صلحا،\nفوجد أهلها قد قتلوا أسارى المسلمين؛ فقتلهم أجمعين ، ونزل على عسقلان، واتصل به أخوه يوسف بعد أن ترك على صور عسكرا يحصرها، ودخل عسقلان آخر جمادى الثانى [- سبتمبر] .\n[وعدد البلاد التى فتح الله تعالى وأسماؤها هى هذه:]\nالداروم وغزة وعسقلان وأرسوف ويافا وحيفا وقيصارية وعكة وإسكندرية وصيداء وبيروت وجبلة- أسلم صاحبها وجماعة معه. وفتحت تبنين وجبل الطور والفولة وناصرة- مدينة المسيح عم- وطبرية وفلسطين ونابلس ويبنا وصفّورية والرملة. ونهض يوسف بن أيوب خارج عسقلان إلى بيت المقدس، وقال للأجناد: بيت المقدس لكم طعمة ، فدخله منتصف رجب سنة [٥] [٢٠ سبتمبر ١١٨٧] بعد سنة بأيد الروم أو نحوها، وقد كانوا تملكوه فى شعبان سنة هكذا [- أغسطس ١٠٩٥] .\nونص النسخات التى وصل بها الطائر إلى الإسكندرية من مصر بصورة فتحه هو هذا المسطر.\nبسم الله الرحمن الرحيم صلى الله على سيدنا محمد وآله سرح هذا الطير الطائر ورفيقه فى أول ساعة من نهار الأربعاء، عند ورود البشرى بالمكاتبة المعظمة السلطانية، بتاريخ يوم الجمعة من رجب سنة [- أكتوبر ١١٨٧] بما من الله تعالى به من فتح بيت المقدس، ورفع الأعلام الناصرية فى أشرف موضع فيه. وتقرر على كل من فيه لشراء أنفسهم الرجل ب دنانير والمرأة ب دنانير والطفل بدينارين، وتلك نعمة لا تحصر ولا تحصى. وعدد من خلص فيه من أسارى المسلمين أسير ، وكان له فى النفوس من الفرح والجذل ما لا خفاء فيه.\nوكل ذلك ببركة استجابة هذا الرجل لطاعة الإمام- مهد الله عمره- وقد بعث إرساله بما وجد فيه وفى تلك البلاد من الذخائر. وهم الآن فى مدينة فاس- حرسها الله- مستمعين للأوامر المطاعة؛ ونحن الآن فى شهر رمضان الفرد من سنة [- سبتمبر- أكتوبر ١١٩١] ؛ وكان اجتماع هذا الرسول وهو عبد الرحمن بن محمد بن منقذ الأزدى سادس مجرم سنة [٥] [- يناير ١١٩٢] بالخليفة الإمام أبى يوسف رضه؛ وخرج من الحضرة بعد ذلك بخمسة أيام ولم يعلم به .\n[ذكر المشهور من المدن والعمائر من بلاد مصر إلى آخر بلاد المغرب حسب المعرفة إن شاء الله تعالى]\nنجعل ذلك على قسمين: فالبلاد الساحلية أو ما يقرب من الساحل بمرحلة ونحوها بجهة؛ والبلاد التى تبعد من الساحل بمرحلة أو نحوها بجهة، ونضيف إليها ما كان فى الصحراء منها.\nفمن مدينة الإسكندرية على الساحل عمائر كثيرة للعرب ولقبائل من البربر سكنوا فى تلك الأحياء إلى مدينة سرت. ومدينة سرت مدينة كبيرة قديمة على ساحل البحر، وأهلها أخس الناس خلقا وأسوأهم معاملة، لا يبيعون ولا يبتاعون إلا بسعر قد اتفقوا عليه. وربما نزل المركب بساحلهم موسوقا بالزيت، وهم أحوج الناس إليه، فيعمدون إلى الزقاق الفارغة فينفخونها ويصففونها فى حوانيتهم، ليرى أهل المركب أن الزيت عندهم كثير بائر. فلو أقام أهل المركب ما شاء الله أن يقيموا، ما باعوا منهم إلا على حكمهم. وهم يعرفون بعبيد قرلة ويغضبون لذلك .","3-1":"ذكر بلاد إفريقية وما فيها من العجائب وذكر البلاد الساحلية منها والصحراوية وذكر ما فيها من الآثار مدينة أطرابلس\nفأول مدن إفريقية على الساحل مدينة أطرابلس. وهى مدينة كبيرة أزلية على ساحل البحر، والبحر يضرب فى سورها\xbb\n، وسورها من حجر جليل من صنعة الأولين. وقيل إن تفسير أطرابلس مدن، وقيل مدينة أياس .\nوبها سوق حافلة وحمامات كثيرة وبساتين فى شرقها، وهى كثيرة الفواكه جمة الخيرات، وأكثر أهلها تجار يسافرون برا وبحرا، ولهم سمح فى تجاراتهم، وهم أحسن الناس معاملة ضد أهل سرت. وداخل سورها بئر يعرف ببئر أبى الكنود، يقال إنه من شرب منه يحمق فهم يعيرون به؛ يقال للرجل منهم إذا أتى بما يلام عليه : لا عتب عليك لأنك شربت من بئر أبى الكنود.\nومن أطرابلس إلى نفوسة أيام، وطرف هذا الجبل الخارج فى البحر هو طرف أو ثان، ما بين أطرابلس والإسكندرية، وهو الطرف الذي إذا عدته المراكب استبشرت بالسلامة. وهذه المدينة تعد من بلاد إفريقية، وسنذكر ما ورد فيها من الآثار والله المستعان .\nقال الناظر كان فى مدينة أطرابلس المذكورة رجل غزى اسمه قراقوش استند إلى ذروة هذا الأمر العزيز- أيد الله دوامه-\nبعد شرود وفرار كان منه، وأسلم لأوليائه وآلائه ، وساعد غاويا شقيا لفظه البحر من جزيرة ميورقة- فتحها الله- ولم تزل سعادته مخلصة من تلك الورطات، إلى أن هلك الشقى الميورقى، وأناب قراقوش إلى حزب التوحيد، فغلب على طرابلس وأخرج منها المستولى عليها أبا زبا الفارسى ، وهو ثائر الزاب المذكور فى الأراجيز . قال الضبى:\nوثائر الزاب إن حلت عساكره ... بأرض سوسة ضاقت بالورى الحيل\nفأدرك أهل علم الحدثان اسما مركبا من الزاى والباء، فقالوا ثائر الزاب، لعلمهم بموضع ثورته وجهلهم باسمه، حتى أبرز الأمر العزيز أبا زبا فى الزاب. فلما توجه الخليفة أبو يوسف رضه لفتح بلاد إفريقية سنة [٥] [- ١١٨٧- ١١٨٨] ، خاطبه أبو زبا ضارعا راغبا فى الصلح والقبول، ثم نكث واستبد بطرابلس حتى أناب قراقوش وصح توحيده، فأخرجه منها وبعثه مقيدا، فحل بحضرة مراكش سنة [- ١١٩٠] ؛ ونحن الآن فى شهر رجب الفرد سنة [- يوليه- أغسطس ١١٩١] ، وكلمة التوحيد والهداية فى بلاد الصحراء متصلة من طرابلس إلى مدينة غانة وكوكو.\nقيل وإنما سميت إفريقية لأن قوما من الأفارق سكنوها، وهم أولاد فاروق بن مضر من العرب العاربة؛ وزعموا أن إفريقية اسم ملكة ملكت إفريقية؛ وقيل إنها إبريقية. وحد إفريقية طولا من برقة شرقا إلى مدينة طنجة غربا، وعرضها من البحر إلى الرمال التى هى حاجز بين بلاد\nإفريقية وبلاد السودان، وهى جبال من الرمال من المشرق إلى المغرب؛ وفيها يصاد الفنك الذي لا يوجد لجلده مثال. وجاء فى حديث رسول الله - صلى الله عليه وسلم -: \xabينقطع الجهاد من جميع الجهات ولا يبقى إلا ببلاد إفريقية، فبينما القوم بإزاء عدوهم نظروا إلى الجبال قد سيرت فيخرون لله سجدا فلا ينزع أطمارهم عنهم إلا أزواجهم من الحور العين\xbb . وروى عنه - صلى الله عليه وسلم - أنه بعث سرية فى سبيل الله، فلما قفلوا منها، شكوا شدة برد أصابهم، فقال رسول الله - صلى الله عليه وسلم -:\n\xabلكن إفريقية أكثر بردا وأعظم أجرا\xbb . وبإفريقية فى هذا الوقت من أبناء الإمام الخليفة وحفدته السادات النجباء- أدام الله نصرهم- ما تمهدت به أكنافها وعمرت لهم أوساطها وأطرافها؛ ولكن الشقى يحيى بن اسحاق، صنو الشقى على متوغل فى صحاريها، وقراقوش متصيد له متوثب عليه ؛ والله سبحانه ولى التوفيق بمنه وكرمه.\nمدينة قابس : وتعد أيضا من بلاد الجريد، بينها وبين طرابلس أيام، وهى مدينة كبيرة قديمة أزلية وعليها سور صخر جليل من بناء الأول، ولها حصن حصين وأرباض واسعة؛ وفيها فنادق وحمامات؛ وقد أحاط بجميعها خندق كبير يجرون إليه الماء إذا خافوا من نزول عدو إليهم فيكون أمنع شىء.\nولها واد يسقى بساتينها وأرباضها ومزارعها؛ وأصل هذا الوادى من عين خرارة\nفى جبل بين القبلة والمغرب، وهو يصب فى البحر. وبين مدينة قابس وبين البحر نحو أميال وجناتها أكثر إلى البحر ، وهى كثيرة الثمار والموز بها كثير وليس بإفريقية موز إلا فيها؛ وفيها شجر التوت كثير ويربى بها الحرير، وحريرها أطيب الحرير وأرقه وليس يعمل بإفريقية حرير إلا بها. وهى مدينة فخيرة بحرية صحراوية، والحصراء منها قريبة، فيقال إنه ما اجتمع فى مائدة رجل أشياء متضادة المواضع إلا فى مائدة من يسكن قابس: يجتمع فيها الحوت الطرى ولحم الغزال الطرى والرطب الجنى. فهى حاضرة هذا الإقليم وقطبه وروحه وقلبه، ومركز دائرته التى عليها يدور محيطه وبالاستناد إليه يتمهد رحبه، والله يعصمنا بعزته.\nذكر مدينة القيروان وكيفية وضعها سنة من الهجرة\nولى معاوية بن أبى سفيان عقبة بن نافع القرشى على إفريقية فافتتحها فى آلاف من المسلمين، ووضع السيف وأفنى من بها من النصارى. ثم قال، إنى أرى إفريقية إذا دخلها إمام تحرموا بالإسلام، فإذا خرج عنها رجع كل من أجاب منهم عن دين الله، فهل لكم يا معشر المسلمين أن تتخذوا مدينة تكون لكم عز الأبد. فأجابه الناس واتفقوا على أن يكون أهلها مرابطين فيها؛ وقالوا نقربها من البحر ليتم الجهاد والرباط. فقال لهم عقبة: نخاف من ملك القسطنطينية؛ فاتفق رأيهم على موضعها، فقال: قربوها من السبخة\nفإن أكثر دوابكم الإبل، تكون إبلكم على بابها فى مراعيها آمنة من البربر.\nفدعا ما كان فى الغيضة من الوحوش والهوام، وقال اخرجوا بإذن الله فخرج كل ما كان فيها حتى لم يبق من الحيوانات شئ؛ وهم ينظرون إليها.\nوقال ابن الرقيق فى تاريخه: فبقيت القيروان سنة لم ير فيها خشاش ولا هوام.\nوتنازعوا فى قبلة الجامع فبات عقبة مهموما، فرأى فى المنام قائلا يقول له: خذ اللواء بيدك فحيث ما سمعت التكبير فامش، فإذا انقطع التكبير فأركز اللواء فإنه موضع قبلتكم؛ ففعل عقبة ذلك فهو موضع القبلة، وهو محراب جامع القيروان إلى اليوم؛ وقد هدم حسان بن النعمان جامع القيروان وبناه حاشى المحراب فإنه تركه. ويقال إنه هدم وبنى مرات، كل وال يلى القيروان يريد أن يكون الجامع من بنيانه؛ وكانوا يتركون منه المحراب تبركا ببناء عقبة رحمه الله. ويقال إنه لما أراد معد بن إسماعيل بن عبيد الله الشيعى تحريف قبلة مسجد القيروان وذلك سنة [- ٩٥٦] بلغه أهل القيروان يقولون إن الله عز وجل يمنعه منه بدعاء عقبة بن نافع الفاضل فى وقت تأسيسه الجامع.\nفلما وصل ذلك إلى معد غضب، وأمر بنبش قبر عقبة بن نافع وإحراق رمته بالنار، وكان قبره بظاهر مدينة تهودا، حيث استشهد رحمه الله. وبعث معد لذلك ما بين فارس وراجل؛ قيل فلما دنوا من قبره وحاولوا ما أمرهم به، هبت عليهم ريح عاصفة ولاحت بروق خاطفة وقعقعت رعود قاصفة كادت تهلكهم، فأضربوا ولم يعرضوا له؛ فخافوا عقوبة معد فتاهوا فى صحارى إفريقية حتى سمعوا أنه هلك، فحينئذ أتوا إلى أوطانهم معتبرين مستبصرين . وبإزاء جامع القيروان الساريتان الحمراوان الموشاة بالصفرة، اللتان لم ير الراءون أحسن منها ولا مثلها؛ كانت فى كنيسة من كنائس الروم، فنقلها إلى جامع القيروان حسان بن النعمان؛ وهما مقابلتان المحراب، عليهما القبة المتصلة بالمحراب.\nوبخارج مدينة القيروان ما جلا للماء، هى سقايات لأهل القيروان، منها ما بنى فى أيام هشام بن عبد الملك بن مروان وفى أيام غيره من الخلفاء؛ وأعظمها شأنا وأفخمها منصبا، الماجل الذي بناه أحمد بن الأغلب بباب تونس من القيروان، وهو متناهى الكبر وفى وسطه صومعة مثمنة، وفى أعلاها قبة مفتحة على أبواب، فإذا وقف الرامى على ضفته، ورمى بأشد ما يكون من القسى لا يدرك الصومعة التى فى وسطه. وكان على ذلك الماجل قصر عظيم فيه من البناء العجيب والغرف المشرفة على ذلك الماجل كل شئ غريب؛ ويمر فى هذا الماجل ماجل لطيف متصل به، يقع فيه ماء الوادى إذا جرى، فتنكسر فيه حدة جريانه ، ثم يدخل الماجل الكبير. وهذا الوادى الذي يدخل الماجل إنما واد شتوى يجرى فى أيام الشتاء، فإذا امتلأ هذا الماجل وغيره من المواجل، شرب منه أهل القيروان ومواشيهم. ويرفع ماء هذا الماجل إلى أيام الصيف، فيكون ماؤه باردا عذبا صافيا لكثرة الماء فيه. وكان عبيد الله الشيعى يقول، رأيت بإفريقية شيئين ما رأيت مثلهما بالمشرق: الحفير الذي بباب تونس من القيروان، يعنى هذا الماجل الكبير، والقصر الذي برقادة المعروف بقصر البحر ، والله سبحانه وتعالى أعلم، وهو الموفق للصواب بمنه .\nمدينة صبرة : وهى متصلة بمدينة القيروان، وهى مدينة كبيرة بناها إسماعيل وسماها المنصورة، وكانت لها جبايا كثيرة ، يقال إنه كان يدخل أحد أبوابها كل يوم ألف درهم؛ والله أعلم بالصواب.\nمدينة رقّادة : وهى من القيروان على أميال؛ وهى مدينة كبيرة دورها ٢٤٠٤٠ ذراع. وكانت أكثر بلاد إفريقية بساتين وفواكه، وليس بإفريقية أعدل هواء من رقادة ولا أرق نسيما، ولا أطيب تربة. يقال إن من دخلها لم يزل يضحك مستبشرا مسرورا من غير سبب. وذكر أن واحدا من ملوك بنى الأغلب كان قد أصابه أرق شديد، وشرد عنه النوم أياما، فعالجه اسحاق المتطبب، وهو الذي ينسب إليه الأطرفيل، فأمر الملك بالخروج والتنزه والمشى. قيل فلما وصل إلى موضع رقادة نام، فسميت رقادة من يومئذ، واتخذت موضع فرجة ومنتزها للملوك. ويقال إن الملك الذي بنى مدينة رقادة هو إبراهيم بن أحمد بن [محمد بن] الأغلب [٢٦١- ٢٨٩- ٨٧٤- ٩٠٢] ، فجعلها دار مملكته ومسكنه. قيل ومنع بيع النبيذ بمدينة القيروان وأباحه بمدينة رقادة بسبب جنده وعبيده، فقال فى ذلك بعض الشعراء:\nيا سيّد الناس وابن سيّدهم ... ومن إليه القلوب منقادة\nما حرّم الشرب فى مدينتنا ... وهو حلال بأرض رقادة\nوفيها بويع عبيد الله الشيعى، ذكره ابن الجزار فى تاريخه ، والله أعلم.\nمدينة سفاقس : هى مدينة أزلية عليها غابة كبيرة من الزيتون.\nوزيتها أطيب من كل زيت إلا الشرقى، ومن الناس من يفضله عليه، ومنها\nيمتار أهل إفريقية الزيت، وتحمله المراكب إلى بلاد الروم، وعليه معول أهل صقلية، وإبطالية، وأنكبوردة، وقلورية، وجميع سواحل الأرض الكبيرة، لكثرته وطيبه. وقد كانوا ملكوا هذه الجهات الساحلية إلى أن أخرجهم منها أمير المؤمنين سنة [- ١١٦٠] .\nمدينة المهدية : وهى مدينة عظيمة بناها عبيد الله الشيعى إذ قام عليه [أبو] عبد الله الداعى وهو الذي أقامه ونصره، ودخل عليه سجلماسة وأخرجه من سجن ابن مدرار ثم استحال عليه، وأراد خلعه. وأعانه على ذلك أشياخ كتامة، وكان يقول للناس إنه هو يهودى وضعته مكان العلوى الفاطمى حتى يأتى، وأبحث عنه حتى أجده فإنه صاحب هذا الأمر، وقد آن وقته وخبرهما مشهور. وبين مدينة المهدية والقيروان ميلا، والبحر قد أحاط بمدينة المهدية من جميع جهاتها إلا من الجانب الغربى، وفيه بابها. ولها ربض كبير يسمى زويلة، وفيه الأسواق؛ وللمهدية أسواق مبنية بالصخر الجليل.\nولها بابان من حديد لا خشب فيهما زنة كل واحد منهما قنطار وطوله شبرا؛ وفيها صور الحيوان وهى من أعجب ما عمل فى الإسلام. وفى المهدية ماجلا لماء المطر سوى ما جرى إليها من القناة التى جلبها إليها عبيد الله من قرية مشانس ، وهى على مقربة\nمن المهدية. وللمهدية مرسى للمراكب من عجائب العالم، فإنه منقور فى حجر صلد، يسع مركبا، وكان على المرسى برجين بينهما سلسلة حديد من أغرب ما عمل. وإذا أرادوا أن تدخل سفينة أو مركب، أرسل حراس البحر السلسلة حتى تدخل السفينة ثم مدوها كما كانت، وذلك تحصينا لئلا تتطرقها مراكب الروم من صقلية وغيرها، كما كان فى أيام الحسن الذي دخلها الروم عليه ؛ وذلك مشهور فى جميع الأقطار.\nومن المهدية إلى قصر لخم ، وهو المعروف بقصر الكاهنة، ميلا.\nوذكر أن الكاهنة حصرها عدوها فى هذا القصر، فحفرت سربا فى صخرة صماء من هذا القصر إلى مدينة ملقطة يمشى فيه العدد الكثير، وبينهما ميلا. ويقال إن أخت الكاهنة كانت فى ملقطة، فكان الطعام يجلب إليها فى ذلك السرب على ظهور الدواب. وقصر لخم عجيب البنيان، قد بنى وأحكم بحجارة طول الحجر منها شبرا؛ وارتفاع القصر فى الهواء قامة. وهو من داخله كله مدرج إلى أعلاه؛ وأبوابه طاقات بعضها فوق بعض.\nمدينة تماجر : هى بغرب المهدية، كبيرة أزلية فيها آثار للأول؛ وبينها وبين المهدية الوادى.\nمدينة جلولا : مدينة قديمة أزلية لها حصن، وعين سرّة فى وسطها ، وهى كثيرة البساتين والأشجار، غزيرة الفواكه والثمار والأزهار، والرياحين بها كثيرة جدا وأكثر رياحينها الياسمين؛ وبطيب عسلها يضرب المثل لكثرة ياسمينها وحرش نحلها له، وأكثر فواكه القيروان تجلب إليها من جلولا.\nمدينة سوسة : مدينة أزلية قديمة فيها آثار للأول، وهى على ساحل البحر، وفيها بنيان عظيم يسمى الملعب، وهو من أغرب البنيان فيه أقباء معقودة بحجر النّشف الذي يطفو فوق الماء، المجلوب من بركان صقلية. وداخل سور المدينة هيكل عظيم يسميه البحريون الفنطاس، وهو أول ما يرون من البحر إذا قصدوا من صقلية وغيرها؛ وسوسة فى سند عال ترى دورها من بحر صقلية. وهى مخصوصة بكثير الأمتعة وجودة الثياب الرقاق، وقصارتها.\nوجميع أشغال الثياب الرفيعة من طرزها ، وكمدها لا يصنع ببلد مثل صنعته بهذه المدينة. والثياب السوسية معلومة لا يوجد لها نظير، لها بياض رائق وبصيص\nلا يوجد فى غيرها. ومنها تجلب الثياب الرفيعة مثل عمائم المعمور وغيرها، تساوى منها العمامة دينار وأزيد ؛ يحمله التجار إلى جميع البلاد شرقا وغربا؛ ويباع الغزل بها زنة المثقال بمثقالين.\nولحم سوسة من أطيب لحوم بلاد إفريقية لطيب مراعيها. وبالقرب منها محرس المنستير الذي جاء فى الأثر ، وهو حصن عالى البناء متقن العمل، وفيه جماعة من الصالحين الذين حبسوا أنفسهم فيه منفردين عن الأهل والعشائر؛ وأهل تلك البلاد يخرجون إليهم الصدقات .\nوبقربه نحو محارس متقنة البناء معمورة بالصالحين.\nمدينة تونس : مدينة عظيمة بينها وبين القيروان مسيرة أيام؛ وبينها وبين البحر نحو أيام؛ وبينها وبين قرطاجنة نحو أميال ومرساهما واحد يسمى رادس. ويقال إن ببحر رادس خرق الخضر عم السفينة ؛ وكان الملك المذكور فى القرآن ، الذي كان يأخذ كل سفينة غصبا، ملك قرطاجنة وكان يسمى ألجلندا. وبين المرسى وتونس بحيرة يقول أهل تونس إنها كانت [من] نحو سنة أرضا لهم، كثيرة الجنات والمياه والزرع طيبة الفواكه، فغلب عليها ماء البحر؛ وهم يعرفون موضع ضياعهم فيها إلى الآن. ومدينة تونس مدينة قديمة البناء لها سور عظيم ويدور بها حفير، يقال إن دورها ألف ذراع وبها جامع متقن البناء مليح الصنعة مطل على البحر، بناه عبيد الله بن الحبحاب هو ودار الصناعة، وأنفذ إليه البحر، وهو من عجائب الدنيا. ومدينة تونس فى سفح جبل، وبها مبان عجيبة، وأكثر عضادات أبواب دورهم رخام أبيض: لوحان قائمان وثالث معترض مكان العتبة.\nومن الأمثال بإفريقية: دور تونس أبوابها رخام وداخلها سخام. وهى دار علم\nوفقه، وأهلها موصوفون بالقيام على الولاة؛ يعد لأهلها القيام على أمرائهم نحو ال مرة، لأنها أكثر البلاد باعة وغوغاء؛ وإن سلامتها من شقى ميورقة لمن براهين هذا الأمر العالى ، وما ذلك إلا لسعادة سيدنا ومولانا أمير المؤمنين أيده الله.\nوبالقرب من تونس بنحو ال أميال نهر كبير يسمى بجردة، وهو على الطريق إلى المغرب؛ ويقال إن من شرب من مائه قسى قلبه فأكثر الناس يجتنبون شربه. ومدينة تونس أشرف مدن إفريقية وأطيبها ثمرة وأنفسها فاكهة، فمن ذلك اللوز الفريك، يفرك بعضه بعضا دون أن تمسه يد لرقة بشرته، وكذلك الرمان والأترج والسفرجل والتين وجميع الفواكه؛ لا يوجد لها نظير.\nوفيها من أجناس الحوت البحرى ما لا يحصى كثرة. وكان اسمها فى القديم ترشيش، وإنما سميت تونس فى أيام الإسلام. وذلك أن المسلمين إذ فتحوا إفريقية على الروم كانوا يضربون على بلادها، وكان بقرب ترشيش هذه صومعة راهب، فكانت سرايا المسلمين تنزل بإزاء تلك الصومعة، وتأنس بصوت الراهب، فيقولون هذه الصومعة تؤنس فلزمها هذا الاسم، فسميت تونس.\nمدينة قرطاجنّة : بينها توبين ونس أميال ومرساهما واحد.\nوهى من المدن المشهورة، فيها من الآثار وعجائب البنيان ما ليس فى بلد شرقا ولا غربا، وقيل لو دخلها إنسان ومشى فيها عمره يتأمل آثارها لرأى فيها كل يوم أعجوبة لم يرها قبل ذلك. ويقال إن ملكها كان ملكا عظيما جبارا، وكان ملك أكثر الأرض وكان يسمى أنبيل ، فدخل بلاد الروم، وقتل ملوكها، وأخذ بلادهم، وبعث لقرطاجنة من خواتم الملوك الذين قتل أمداد. ويقال إنه نازل مدينة رومة الكبرى التى هى دار مملكة الروم،\nفيصير فى خلق الغول والسعلاة، وإن عاش يعدو على الناس حتى يغل ويقيد. ولأجل ذلك يشتم أهل تلك البلاد وأهل إفريقية بعضهم بعضا يقولون: يا مبدول . وقد أخبر الثقات أنهم عاينوا ذلك وتحققوه.\nمدينة برقة : وهى مدينة كبيرة أزلية قديمة، فيها آثار كثيرة للأول؛ وهى فى صحراء حمراء التربة والمبانى فتحمر لذلك ثياب ساكنيها والمتصرفين فيها؛ وعلى أميال منها جبل كثير الخصب والفواكه والمياه السائحة. وأرض برقة كثيرة الخصب تصلح السائمة فى مراعيها؛ وأكثر ذبائح أهل مصر والإسكندرية من غنم برقة لعظم خلقها وكثرة شحمها ولذة لحمها . واسمها باللغة الإغريقية بنطابلس ، تفسيره مدن . ويذكر أن فى تلك الخرائب التى ببرقة والآثار القديمة دار منقورة فى حجر صلد، عليها باب من حجر صلد كذلك، من أغرب ما يكون فى الدنيا، لا تدخل الذرة بين العضادة والباب، ولا بين العتبة والباب؛ ولا يفتح الباب إلا للداخل، ولا يقدر أحد على الخروج منه إلا أن يدخل عليه آخر، ويقال إنه كان مفتوحا لا قفل له.\nوأخبرنى بعض من دخل ذلك الطريق أن رجلا دخل فيه ليرى الدار، فرأى دارا منقورة فى حجر صلد، وفيها من عظام الناس كثير، فهاله ذلك فأراد الخروج فوجد الباب قد انغلق ولم يقدر على فتحه، وأيقن بالهلكة حتى طلبه بعض أصحابه فجاء إلى ذلك الباب فسمع صوته يستغيث بفتح الباب، ففتحه فخرج الرجل.\nوفى تلك الآثار عجائب لمن يتأملها.\nمدينة أجدابية : هى مدينة كبيرة فى صحراء صفا، وآبارها منقورة فى ذلك الصفا ؛ طيبة الهواء والماء وبها عين ثائرة عذبة ، ولها بساتين ونخل يسير ؛ وبها جامع حسن البناء بناه الشيعى، وله صومعة مثمنة بديعة العمل.\nوبها حمامات وفنادق كثيرة، وأسواق حافلة مقصودة، وأهلها ذو يسار وأكثرهم أقباط ، وبها نبذ من صرحاء لواته. وليس لمبانيها سقوف من خشب، وإنما هى أقباء من الطوب لكثرة الرياح بها. ثم كذلك قبائل البربر والعرب إلى جبل نفوسة وطوله من المشرق إلى المغرب أيام؛ وبينه وبين القيروان أيام، وفيه مدن كثيرة. وفى هذا الجبل مواضع كثيرة فيها آثار قديمة للأول، عجيبة فيها غرائب لمن تأملها. ووصل عمرو بن العاص- رحمه الله- إلى جبل نفوسة وافتتحه وكان أهله نصارى، وفى جبل نفوسة رجع بكتاب عمر بن الخطاب رضه. وفى وسط هذا الجبل مدينة جادوا [وهى] مدينة كبيرة لها أسواق حافلة وأكثر أهلها يهود، وهى أم قرى جبل نفوسة.\nمدينة شروس : وهى مدينة كبيرة جليلة قديمة، فيها آثار للأول، وأهلها إباضية ، وليس بها جامع ولا فيما حولها من القرى؛ وفى نظرها أزيد من قرية. ولا يرون فى مذهبهم الجمعة، وفى هذا الجبل أمم كثيرة على مذاهب شتى، وأكثرهم إباضية . وليس لهم أمير يرجعون إلى أمره وإنما\nلهم شيوخ وفقهاء فى مذاهبهم يرجعون إلى أمرهم، ولهم رخص كثير فى مذاهبهم.\nأخبرنى الثقة قال: رأيت رجلا دخل بلادهم فرأى إنسانا قد أراد التطهر، فنزل على ماء ونزع ثيابه وجعل يشبر كأنه يغتسل، وكأنه يتوضأ، وكأنه يريق على رأسه وعلى جسده الماء. فقال له الرجل ما هذا، فسكت عنه حتى فرغ، فأخذه الرجل الغريب وحمله إلى حاكم البلد، وقال له رأيت هذا يفعل كيت وكيت.\nفقال له الحاكم: من أين أنت، فقال من المغرب؛ فقال والله لولا أنك غريب ببلدنا لأدبتك، وما يدريك لعل له عذرا؛ قال الله تعالى: \xabيريد بكم اليسر ولا يريد بكم العسر . وهذا أفضل مذاهبهم فإن فيهم من لا يرى الاغتسال بالماء جملة؛ وإذا كان على أحدهم غسل يتمرغ فى التراب ويتيمم مكان الوضوء؛ وببلاد إفريقية من هذا المذهب كثير. والزنا الحرام بجبل نفوسه فى مذهبهم: ما منهم رجل غنى إلا وله وصائف كثيرة يلبسهن فاخر الثياب ويحليهن بالحلى، ويبرزهن على الطريق للفواحش ؛ ولهم ديار معدة لذلك، وهذا عندهم معروف لا ينكر. ومن جبل نفوسة إلى بلد غدامس أيام فى الصحراء؛ والماء منها على مسيرة أيام وأكثر. وبلد غدامس بلد كبير ونظر واسع كثير النخل والمياه؛ وأهلها بربر مسلمون لا يلتثمون على عادة بربر الصحراء من لمتونة ومسوفة وغيرها.\nمدينة غدامس : مدينة لطيفة قديمة أزلية، وإليها ينسب الجلد الغدامسى. وبها دوامس وكهوف كانت سجونا للملكة الكاهنة التى كانت بإفريقية؛ وهذه الكهوف من بناء الأولين، فيها غرائب من البناء والآزاج المعقودة تحت الأرض ما يحار الناظر إليها إذا تأملها، تنبىء أنها آثار ملوك سالفة\nوأمم دارسة؛ وأن تلك الأرض لم تكن صحراء وإنما كانت خصيبة عامرة. وأكثر طعامهم التمر، والكمأة تعظم بتلك البلاد حتى تتخذ فيها اليرابيع والأرانب أحجارا. ومن غدامس يدخل إلى تادمكّة وغيرها من بلاد السودان.\nمدينة زويلة : مدينة كبيرة قديمة أزلية فى الصحراء، تقرب من بلاد كاتم وهى من السودان؛ وقد أسلموا بعد ال من الهجرة [- ١١٠٦] وهى مجتمع الرفاق وإليها يجلب الرقيق، ومنها يخرج إلى بلاد إفريقية وغيرها من البلاد. ولما فتح عمرو بن العاص برقة وجبل نفوسة بعث عقبة بن نافع حتى بلغ زويلة وافتتحها؛ وصار ما بين برقة وزويلة للمسلمين. وبلد زويلة كثير النخل والثمار، وبقربها قصر واجان ، وهو قصر عظيم على رأس جبل فى طرف المغازه، وهو مثل المدينة؛ فسار إليه يوما فنزل عليه وحاصره نحو شهر، فلم يقدر. فمضى أمامه على قصور كوار ففتحها، وأخذ ملكها فقطع أصبعه؛ فقال: لم فعلت فى هذا؛ قال عقبة: إذا نظرت إلى أصبعك لم تقاتل العرب . وفرض عليهم رأسا ثم سألهم: هل وراءكم أحد فلم يعلموا ما وراءهم، فكر راجعا على قصور واجان ولم يتعرض له ولا نزل عليه ، وسار أيام. فلما رأوا أنه لم يتعرض لهم أمنوا وانبسطوا، فأقام عقبة بموضع يسمى اليوم ماء الفرس ، فنفذ ماؤهم وأصابهم العطش حتى كاد يهلكهم.\nقال فصلى عقبة بأصحابه ركعتين ودعوا الله تعالى، فجعل فرس عقبة يبح بيده فى الأرض حتى انكشفت صفاة تنبعث ماء ؛ فنادى عقبة فى الناء أن يحتفروا، فاحتفروا فوجدوا ماء معينا زلالا يسمى ماء الفرس.\nوكان يقال له عقبة المستجاب لأنه قل ما دعا فى نيل شىء إلا استجيب له ثم كر راجعا إلى قصر واجان من غير طريقه الذي أقبل منه، فلم يشعروا حتى طرقهم ليلا فوجدهم مطمئنين، فاستباح ما فى مدينتهم من ذرارى وأموال ونساء، وقتل مقاتليهم ثم انصرف راجعا إلى زويلة. ومن زويلة كر إلى غدامسر بعد خمسة أشهر، وسار متوجها إلى المغرب. وجانب طريق الجادة، وأخذ أرض مزاته وهم قبيل كبير من البربر، فافتتح قصورهم إلى قفصة فافتتحها وافتتح بلاد قسطيلية، ثم انصرف إلى القيروان. ثم مضى فى بلاد المغرب حتى انتهى إلى أقصى بلاد السوس، ثم انصرف راجعا فتوفى شهيدا بتهودة من بلاد الزاب.\nبلاد الواحات : وهى بلاد كثيرة فى الصحراء ما بين بلاد إفريقية وبلاد مصر؛ ولولا قلة الماء فى هذه الصحراء لكان الطريق من إفريقيا إلى مصر على الواحات أقرب. والدخول إلى بلاد الواحات من أوجلة، وزلى ، وغيرها، التى فى صحراء مدينة طرابلس. وبلاد الواحات كثيرة التمر والنخل، وفيها مدن كثيرة مسورة وغير مسورة؛ وكل مدينة منها لها اسم يعود إلى الواح:\nأريس الواح ، وتنيس الواح، والواح الخارج، والواح صبروا؛ كلها لها اسم مثل هذا وأهلها مسلمون. وهى آخر بلاد الإسلام، بينهم وبين بلاد النوبة مراحل. وفى بعض مدن الواحات قبائل من لواتة، وإنما أهلها أقباط .\nوزعموا أن فى أقصى بلاد الواحات بلد يقال له واح صبروا، لا يقع عليه إلا من ضل فى الصحراء، وفى النادر من الزمان. وأنه بلد عظيم كثير الخيرات من النخل والزرع وجميع الفواكه ومعادن الذهب، وأنه أخصب بلاد الدنيا وأن الواقع عندهم يكون فى أخصب عيش؛ فإذا أرادوا خروجه من بلادهم، أروه طرف بلاده فتاقت نفسه إليها، فلم يلبث عندهم ورحل كيفما استطاع. وقد وقع فى هذا البلد رجل من عرب بنى قرة، وبقى فيه مدة ورجع إلى بلاده، وأخبر بما رأى فيه من الخيرات وبما فى أيدى أربابه من الأموال، وليس لها مدافعة ولا بصر بالحرب ولا سلاح لأنهم لم يعهدوا الحرب. فأهاج ذلك أمير بنى قرة وكان اسمه مقرب بن ماض ، وعزم على النهوض إليهم. فأعد أزودة كثيرة وماء كثيرا، وذهب فى الصحراء يطلب واح صبروا، وضل به الرجل الذي دخل ذلك البلد فوصل مدينة الواح الخارج فسأل عن واح صبروا. فقالوا كلهم: ما نعرف له طريقا ولا يجده إلا من ضل فى الصحراء فى النادر من الزمان، وهو كما ذكر لك وأكثر.\nفخرج من الواح الخارج يطلب واح صبروا؛ فبقى يجول فى الصحراء مدة فلم يجده ولا قدر على الوصول إليه، فخاف نفاد الزاد فكر راجعا. فنزل فى رجوعه ذات ليلة ربوة من الأرض فى بهاء تلك الصحراء، فوجد بعض أصحابه فى نواحى تلك الربوة بيتا للأول، فبحثوا عليه فإذا هو لبن من نحاس أحمر، فزادوا فى البحث فوجدوا أساس سور من نحاس أحمر للأول. فأوقروا جميع ما عندهم من الظهر من تلك اللبن، وساروا حتى أتوا مدينة الواح الخارج فباعوا\nذلك النحاس بأموال كثيرة. ثم أرادوا أن يرجعوا إلى الربوة التى وجدوا فيها النحاس، فلم يقدروا عليها وضلوا طريقها؛ ولو وجدوها لكان فيها غناهم إلى آخر الدهر.\nقيل أتى رجل من أهل الواح الخارج إلى مقرب بن ماض فأخبره أنه دخل حائط نخل كان له فوجد أكثر تمره قد أكل، ووجد فيه أثر قدم إنسان لا يشبه هذا الخلق فى العظم. قال فاحترسه هو وأهله ليال حتى طرقهم ذلك الشخص فرأوا خلقا عظيما لم يعهد مثله، فجعل يأكل التمر، فلما هموا به فاتهم فلم يعلموا به أمرا. قال فنهض معهم حتى وقف على أثر ذلك الشخص فاستعظمه، وأمرهم أن يحفروا زبية فى الموضع الذي كان يدخل فيه، وغطوا أعلاها بالحشيش ويرقبوه. ففعلوا ذلك ورقبوه ليال متتابعة؛ فلما كان ذات ليلة أقبل ذلك الشخص على عادته، فتردى فى الزبية فبادروا إليه بجميعهم وغلبوه بكثرتهم حتى أخذوه، فإذا بامرأة سوداء عظيمة الخلقة مفرطة الطول والعرض لا يفقه منها كلمة. فرآها مقرب بن ماض فهاله أمرها، فكلموها بكل لغة علموها من لغات السودان فلم تجاوب بواحدة منها، وتكلمت بكلام لا يفهم. وبقيت عندهم أياما يأتمرون فى أمرها، فقال لهم مقرب: نرى أن ترسل، وتركب الخيل العتاق السوابق والنجب العشار فى إثرها إلى أن يوقف على موضعها ويعلم حقيقة أمرها . فلما أرسلت، فاتت الخيل والنجب وبارت الرياح فلم يقفوا على حقيقة خبرها . ويذكر أن بين بلاد الواح وبلاد الجريد من إفريقية رمال عريضة فيها بقاع تعرف بالجزائر وهى كثيرة النخل والعيون، لا عمران فيها، ولا أنيس بها. ويقال إنه يسمع فيها أبدا عزف الجن، ولا شك أنها كانت بلادا عامرة. ويتكدس هناك من التمر تحت النخل أكوام لا يقع عليها أحد إلا الطير والوحش، وربما انتجعه الناس فى السنين الجدبة وعند الضرورة.\nقال الناظر: وصح عندنا أن قبيلة سليم المنقطعين فى صحراء طرابلس ينتجعون تمر هذه المواضع، ومنها يتعيشون، وإليها يلجأون عند المطلبة لهم وفيها يعتصمون؛ وسمعت هذا قبل الوقوف عليه بمنه .\nذكر بلاد الجريد من إفريقية\nوإنما سميت بلاد الجريد لكثرة النخيل بها؛ وهى مدن كثيرة وأقطار واسعة وعمائر متصلة، كثيرة الخصب والتمر والزيتون والفواكه وجميع الخيرات. وهى آخر بلاد إفريقية على طرف الصحراء.\nوفيها المياه السائحة والأنهار والعيون الكثيرة. فأولها من جهة الساحل مدينة قابس وقد ذكرناها فى البلاد الساحلية.\nمدينة حامّة مطماطة : وهى مدينة قديمة مسورة، وعليها هزم الخليفة أبو يوسف- أدام الله تأييده- شقى ميورقة وأستأصل شأفته ؛ وسكانها قوم من البربر يعرفون بمطماطة. وهى كثيرة التمر والزيتون والفواكه؛ وفى المدينة عين كبيرة شديدة الحرارة فإذا استقى منها الماء برد لحينه، ومنها يشربون ويسقون غابتهم وغلاتهم.\nمدينة قفصة : مدينة كبيرة قديمة أزلية، كان لها سور حصين من صخر جليل بأحكم صناعة يخال لرائيه أنه كما فرغ من عمله. ويقال إن الذي بناه شيبان غلام النمرود بن كنعان الجبار، وكان اسمه منقوشا على باب\nمن أبوابها؛ وكانت له أربعة أبواب. فلم تزل أهواء أهلها تضطرب وقلوبهم تنقلب من حين توحيدهم بزعمهم سنة [- ١١٦٠] ، فثاروا على الموحدين وسفكوا دماءهم وقدموا على أنفسهم رجلا منهم يعرف بعلى بن الرند ، فملكهم إلى سنة [٥] [- ١١٨٠] وأخرجه منها الخليفة أبو يعقوب بن الإمام الخليفة أمير المؤمنين وولاه عمل مدينة سلا، فمات بها. وبقى أهل قفصة إلى سنة [٥] [١١٨٥] فمر عليهم الغاوى الشقى الميورقى، فأدخلوه البلد وملكوه.\nوترك بها جماعة من الأغزاز الموالين له، فحصرهم بها الخليفة أبو يوسف- رضى الله عنه- فرغبوا فى عتق رقابهم على أن يكونوا عبيدا للأمر العزيز مماليكا للخليفة، وأسلموا من سواهم، فعفا الخليفة عن جرمهم وأعتقهم، وترك أهل قفصة فى بلدهم، وقتل المارقين الميورقيين لنفاقهم وشقاقهم كما قيل:\nيا ذلة التلثيم عند الكر ... إذ يبتغون عودة للأمر\nولما تقرر نفاق أهلى قفصة وترددهم وشكهم وعتوهم وإفكهم، رأى الإمام أمير المؤمنين رضه أن كف شرهم وخسف مكرهم لا يكون إلا بهدم سورهم، وكشف ستورهم. فأمر للحين بهدمه فلم يكن فيه للمحلة إلا من ظهر يوم العصر الثالث منه، ولم يبق إلا أساسه وبرج بقرب برج بن زواج شاهدا\nعلى عتاقه بنيانها وعظم شأنها ، وإنه لمن آيات هذا الأمر العزيز التى تتبين بها عظمته لذى الفحص والتزليم .\nوكان اسم مدينة قفصة مدينة الحنيّة لأن فيها بنيانا قديما مثل الحنية فكانت تسمى بها؛ وهى متوسطة بين القيروان وبين مدينة قابس. وفى داخلها عيون كثيرة منها عينان كبيرتان معينتان ليس لهما نظير فى عذوبة مائهما وصفائه وكثرته؛ إحداهما عند باب الجامع تسمى بالوادى الكبير، وهى عين عظيمة مبنية بالصخر الجليل من بنيان الأول سعتها نحو ذراعا فى مثلها، وفوقها عين أصغر منها تسمى رأس العين، وبينهما قنطرة من بنيان الأول، ولا شك أن ماءهما واحد. وماء هذه العين الأولى أزرق شديد الصفاء يرئى قعر العين من أعلاها وفيها الماء نحو قيام؛ والعين الأخرى تحت قصر قفصة وتسمى بالطرميد، عليها بنيان عجيب قديم؛ وبإزائها مسجد يعرف بمسجد الحواريين. ومنبع هذه العين من حجر صلد من ثقب وسع فم الإنسان ، وينبعث منه بقوة عظيمة. وقد بنى له صهريج عليه دكاكين مبنية بالحجارة وعليه أقباء، وقد بنى فوقه مسجد عظيم. فإذا اجتمع ماء هذه العين مع ماء العين الكبيرة، التى عند الجامع، جاء منها نهر كبير تطحن عليه أرحاء كثيرة، ويسقى نصف غابة قفصة ونصف أرضها ومز درعاتها. والنصف الثانى من غابة قفصة يسقى من عين عظيمة خارج المدينة يسمى عين المنستير، وهى عين كبيرة معينة عذبة يخرج منها نهر كبير. وهذه العين من أحسن ما يرى من العيون، وهى فى جانب النهر الكبير المسمى بوادى بايش ، وهو يشق غابة قفصة ويسقى بعض بساتينها، وهو نهر مشهور يأتى من جبال شرقى قفصة لكنه فى أيام الصيف يقل جريانه ولا ينشع ، وأرض هذا الوادى كله تنشع . وفيه تورد العرب إبلها، تحفر فيها احساء فتخرج ماء عذبا معينا. ولأهل قفصة فى سقى جناتهم هندسة عظيمة وبرشام شديد وتدقيق حساب. يقول أهل قفصة: إذا رأيت قوما يتخاصمون وقد علا بينهم الكلام\nفتعلم أنهم فى أمر الماء. وكان على أحد أبوابها كتابة منقوشة فى حجر من عمل الأول ترجم فإذا هو: هذا بلد تحقيق وتدقيق.\nوكذلك ليس بإفريقية حريم أجمل من حريم قفصة مع ملاحة أخلاقهن ورخامة منطقهن ؛ ويسمون الماء الذي يخرج من المدينة فيسقى نصف جناتهم \xabالماء الداخل\xbb ، ويسمون الماء الذي خارج المدينة، وهو عين المنستير وماء وادى بايش \xabبالماء الخارج\xbb . ولهم مياه غير هذه تسمى بالماء الصغير ، وهى عيون كثيرة بقرب المدينة تسقى بعض جناتهم. وسقيهم بها بالساعات؛ وترى خدام تلك الجنات والبساتين أعرف الناس بأوقات النهار. إذا سألت رجلا منهم لا يفقه شيئا عما مضى من ساعات النهار، وقف ونظر إلى الشمس واكتال بقدميه فى موضع ظله، ويقول لك مضى كذا وكذا ساعة وكذا وكذا سدس من الساعة. وأهل قفصة يتنافسون فى هذه المياه، ويتابعون سقيها بأغلى ثمن. ولمدينة قفصة غابة كبيرة قد أحاطت بها من كل ناحية مثل الإكليل، فى تكسير دائرتها نحو أميال ، فيها من المنازل التى تعرف بالقرى منزلا. وعلى الغابة والمنازل والكل حائط يسمونه \xabسور الغابة\xbb . وفى ذلك السور أبواب عظام عليها أبراج مسكونة، يسمون تلك الأبواب: الدروب. وغابة قفصة كثيرة النخل والزيتون وجميع الفواكه التى ليس فى بلد مثلها: فيها تفاح عجيب جليل زكى الرائحة يسمونه السدسى، لا يوجد فى بلد مثله؛ وكذلك الرمان والأترج والموز لا يوجد مثلها فى بلد. وفيها نوع من التمر يسمى بالكسبا، ليس مثله فى بلد وهو أكثر تمرهم؛ يكون فى التمرة فتر فى جرم بيض الدجاج، تكاد تنفذها ببصرك لصفاء لونها ورقة بشرتها. وهم يجعلونه فى أزيار، فإذا أخرجوه منها بقى فى قعر الزير عسل ألذ من عسل النحل وأعطر؛ وهم يصرفونه فى طعامهم كما يصرف العسل عندنا وتعمل منه الحلاوات . وقفصة أكثر البلاد فستقا حتى إننى أظن أنه ليس بإفريقية فستق إلا فيها؛ ومنها يجلب إلى إفريقية وبلاد المغرب، وبلاد الأندلس وبلاد مصر. فإن الذي يجلب من بلاد الشام صغير الجرم ليس مثل\nالقفصى، فإن القفصى يكاد أن يكون فى جرم اللوز. وهو إذا كان فى شجره أجمل ثمرة خلقها الله تعالى، فإنه يكون عناقيدا مثل عناقيد العنب، وهو زكى الرائحة حتى إنه لا يقدر أحد أن يسرق منه شيئا، فإنه تشتم عليه رائحته.\nوفى بساتين قفصة من الرياحين كثير: مثل الآس والياسمين والنارنج والنرجس والسوسان والبنفسج وغير ذلك. ووردها أكثره أبيض، وماؤه أزكى ماء يكون للورد، يشبه الجورى الذي يجلب من بلاد مصر.\nويصنع بقفصة أردية وطيالس وعمائم من صوف فى نهاية الرقة تضاهى ثياب الشّرب ؛ وتصنع بها أوان للساء من خزف تعرف بالريحية، شديدة البياض فى نهاية من الرقة ليس يعلم لها نظير فى جميع البلاد.\nويصنع بها زجاج حسن، وأوان عجيبة وأوان مذهبة غريبة. وهى حاضرة فى جميع أمورها، وأهلها ذوو يسار وفيهم خير كثير ولهم صدقات، وهم يعظمون يوم عاشوراء تعظيما كثيرا وهو عندهم مثل الأعياد؛ ولهم فيه صدقات كثيرة وكساء للمساكين. وكانت مدينة قفصة أعظم بلاد إفريقية نظرا: كان حولها نحو قصر آهلة عامرة، فيها الأشجار والنخل والزيتون والفستق وجميع الثمار؛ وفيها العيون والأنهار والآبار ، وتسمى قصور قفصة. ومن قصورها مدينة طوارق ، وهى فى منتصف الطريق من قفصة إلى فج الحمار وأنت تريد القيروان؛ وكانت مدينة آهلة كبيرة فيها جامع. وكانت القوافل إذا خطرت بين هذه القصور تكم إبلها ودوابها لئلا ترعى ورق الشجر لكثرته على ذلك الطريق. وهى اليوم خربة لا أنس (ط) بها من وقت دخلت العرب بلاد إفريقية، وأفسدت بلاد القيروان وغيرها من البلاد والقرى والعمائر وكثيرا من المدن بإفريقية .","3-2":"فلما حاصرها وضيق على ملكها، وأفسد أقطارها، أرسل ملك رومة قائدا من قواده، فحشر من كان ببلاده من الروم والجيوش، وأمرهم بالوصول إلى بلاد إفريقية؛ ونزلوا على قرطاجنة ولم يكن فيها من يعاونهم، فأرسلوا إلى ملكهم أنبيل يعلمونه بما حل ببلادهم من البلاء من أهل رومة، ويسألونه الإسراع لأغاثتهم. قال فعجب من ذلك ملك قرطاجنة، وقال: أردت قطع رسم الرومانيين من الدنيا، وأظن إله السماء أراد غير ذلك. ثم رجع إلى بلاده مسرعا، فزحف إليه شبيون قائد صاحب رومة، فهزمه مرارا عديدة حتى قتله واستأصل عسكره، ودخل فى قرطاجنة فهدمها وأحرقها؛ وخرب المسلمون بقيتها وذلك مشهور. وليس يسكن منها الآن إلا قصر واحد، يسمى بالمعلّقة ، وبناؤه من أغرب ما يكون من البناء، مفرط العظم والعلو، أقباء معقودة بعضها فوق بعض طبقات كثيرة ؛ وهو مطل على البحر، وهو حصن عظيم.\nوبقرطاجنة دار الملعب ويسميه أهل تلك البلاد بالطياطير، هو كله أقباء معقودة على سوارى رخام، وعليها مثلها نحو أربع مرات، وقد أحاطت بالدار. والدار دائرة من أغرب ما يكون من البناء، ولها أبواب كثيرة وقد صور على كل منها صورة نوع من الحيوان؛ وقد صور فى الحيطان صور جميع الصناع بأيديهم آلاتهم. وفى هذه الدار من الرخام ما لو أجمع أهل إفريقية على نقله ما قدروا عليه لكثرته. وكان فيها قصران يعرفان بالأختين ، ليس فيهما حجر سوى الرخام، ورخام الواحد لا يشبه رخام الثانى؛ ويوجد فيها لوح رخام طوله شبرا وعرضه شبرا؛ ويقال إنه وجد فى غربيها بيت من لوح واحد . والناس ينقلون من رخام هذين القصرين، لحسنه على قديم الزمان، وما فرغ إلى الآن. وبهذين القصرين ماء مجلوب من ناحية الجوف لا يعرف منبعه؛ وكانت عليه نواعير وسواقى تسقى\nبساتينهم. وكان بها قصر عظيم مطل على البحر يسمى قومس ، وهو من أعجب ما فيها، لأنه مبنى على سوارى رخام مفرطة الكبر والعظم- يجلس على رأس السارية رجلا بينهم سفرة طعام أو شراب- وهى مشطبة، كالثلج بياضا، يكون دور السارية منها نحو ال شبرا فى علو مفرط، وعليها سوارى أخر معترضة. وقد بنى القصر على أقباء معقودة بعضها فوق بعض بأغرب صناعة وأحكم بناء، فكان هذا القصر حصنا وإنما هدم من عهد قريب؛ وذلك أنه تحصن فيه قوم من القطاع، فكانوا يقطعون بتلك الجهات، ويلجأون إليه، فخرج إليهم أهل تونس وقتلوهم وهدموا القصر.\nوبقربه موضع فيه أقباء ودهاليز تحت الأرض يهاب الدخول فيها؛ وفيها جثث الموتى على حالها، فإذا مست تلاشت لقدمها .\nوداخل ميناء المدينة تدخله المراكب بقلوعها. وفيها مواجل كثيرة للماء، وبعضها تسمى مواجل الشياطين، بسبب [أن] من يقرب منها يسمع فيها دويا. والناس يتقايسون فى الدخول فيها، فمن جسر على الدخول فيها، علم أنه جرئ قوى القلب. وقد دخلتها بالنهار مع أصحاب لى ، فرأيت منظرا هائلا، من تكلم فيها بأدنى كلمة يسمع لها دوى عظيم؛ وأغرب ما رأيت فيها الماء باق إلى الآن. وليس يدخلها ماء المطر وذلك لاحكام سطوحها؛ وهى صهريجا منفوذة بعضها إلى بعض، فى ارتفاعها نحو ال ذراع، فى عرض كبير. وفيها من الماء نحو ال قيام، ولا يعلم من أين يدخل ذلك الماء. وكذلك ذكر أبو عبيد [الله] البكرى، فى كتاب المسالك والممالك، أن أغرب ما فى قرطاجنة الماء الذي فى المواجل المعروف بمواجل الشيطان، الذي لا يعلم له عهد .\nومن عجائب الدنيا بنيان القناة التى كان يأتى فيها الماء المجلوب من عين جفان إلى مدينة قرطاجنة على مسيرة أيام؛ وهى قناة عظيمة كان يأتى عليها ماء كثير ب أرحاء أو أكثر. وعرض القناة نحو أشبار، وارتفاع مائها\nنحو القامة ونصف، تغيب مرة تحت الأرض فى المواضع المرتفعة، فإذا جازت على المواقع المنخفضة، تكون على قناطر فوقها قناطر حتى تساوى السحاب علوا، وهى من أغرب بنيان الأرض. وفى وسط المدينة صهريج كبير حوله، فى وقتنا هذا، نحو حنية سوى ما تهدم منها؛ وكان يقع فيه الماء المجلوب فى هذه القناة؛ ويخرج من هذا الصهريج إلى بعض تلك المواجل. ورأيت فى بعض أرجل تلك القناطر كتابة فى حجر، قيل إنها ترجمت فوجدت: \xabهذا من عمل أهل سمرقند\xbb ؛ فانظر إلى سعة مملكة هذا الملك الذي جلب هذا الماء، وقيل إن ذلك الماء جلب فى سنة ، ولو قيل فى سنة لكان أعجب.\nقال أبو جعفر أحمد بن ابراهيم المتطبب ، فى كتاب مغازى إفريقية، إن موسى ابن نصير لما فتح جزيرة الأندلس، قال لهم: \xabدلونى على أسن شيخ عندكم\xbb .\nقال، فأتى بشيخ قد رفعت حاجباه عن عينيه بعصابة من الكبر، قال له موسى:\n\xabمن أين أنت يا شيخ\xbb ، قال: \xabمن إفريقية من مدينة قرطاجنة\xbb . فقال له موسى:\n\xabفما الذي سيرك هنا وكيف كان خبر قرطاجنة\xbb ، قال له الشيخ: \xabبناها قوم من بقية العاديين، فسكنوها ما شاء الله، ثم خربت ألف سنة، فبناها أرمين الملك ابن الأزد بن نمرود الجبار، وجلب إليها الماء بالقناطر على الأودية، وشق لها الجبال حتى أوصلها إلى مدينة قرطاجنة، فسكنها قومى ما شاء الله أن يسكنوها، إلى أن حفر إنسان أساس تلك القناطر، فوجد حجر عليه كتابة هى:\n\xabان هذه المدينة ستخرب إذا ظهر فيها الملح\xbb . قال الشيخ فبينما نحن فى ندى قومنا جلوسا، إذا ملح على حجر قد عقد عليه؛ قال: \xabفتأملنا فإذا ذلك فى جميع المدينة، فعند ذلك رحلت إلى هنا\xbb . وروى الثقات عن عبد الرحمن بن زياد ابن أنعم قال: \xabكنت أمشى مع عمى بقرطاجنة نتأمل آثارها، ونعتبر\nعجائبها، فإذا بقبر عليه مكتوب بالحميرية: أنا عبد الله رسول الله صالح، بعثنى الله إلى أهل تلك القرية أدعوهم إلى الله، فقتلونى ظلما، فحسبهم الله وهو نعم الوكيل. فهذا لا شك خراب قرطاجنة.\nمدينة بنزرت : هى مدينة على البحر، بينها وبين تونس نحو يومين، وفيها آثار للأول وسور صخر قديم، ولها نهر كبير يصب فى البحر، وفيه حوت كثير. وبالقرب منها بحيرة كبيرة تنسب إلى بنزرت، يدخل إليها ماء البحر، وهى ملحة وفيها من أنواع الحوت ما لا يحصى، يصطاد فيها فى كل شهر من الشهور الأعجمية نوع من الحوت لا يوجد ذلك النوع إلى ذلك الشهر بعينه فى العام القابل؛ ولها غلة عظيمة فإن منها يحمل الحوت إلى جميع بلاد إفريقية.\nوأكثر حوت تونس إنما هو من بنزرت؛ وأجناس هذا الحوت وأنواعه تتصبر، فتبقى أعواما صحيحة الجرم لذيذة الطعم. وأكثر ما يتمكن من صيد الحوت ما بين البحر وهذه البحيرة، وذلك أن الحوت يتوالد فى البحر ويخرج منه صغيرا كالذر فيتربى فى هذه البحيرة، ثم يرجع فى وقت سفاده وولادته إلى البحر، فيصطاد فى البحر الذي بينهما؛ ومنه ما يصطاد بالنقّازة كما يصطاد الحمام. وهذه النقّازة، هى أنثى الحوت المعروف بالبورى. فيأتى التاجر إلى الصياد، فيتفق معه على عدد معلوم، فيخرج النقازة ويرسلها وقد ربط خيطا فى خرص وثيق فى شفتها؛ فتسير فى البحر ويتبعها بزورقه وشبكته، فتدور عليها الذكور فيطرح عليهم شبكته ويخرج ما قدر له ؛ ويعيد أبدا حتى يستوفى أربه. وعلى مقربة من هذه البحيرة إلى جهة البر بحيرتان:\nإحداهما حلوة والأخرى ملحة من غير أن يدخلها ماء البحر، تنصب كل واحدة منها بالأخرى ستة أشهر على التوالى لا يتغير لواحدة منها طعم، فلا الحلوة تصير ملحة ولا الملحة تصير حلوة.\nمدينة طبرقة : هى مدينة قديمة فيها آثار كثيرة للأول، وهى على نهر كبير. بقرب البحر، تدخل السفن حتى إلى باب المدينة. وبالقرب منها مرسى الحزر ، وهى مدينة قديمة قد أحاط بها البحر من كل جهة إلا مسلك لطيف، وربما قطعه البحر فى زمن الشتاء، وعليها سور قديم، وبها كانت تنشأ المراكب لغزو بلاد الروم. وفيها يخرج المرجان، ومنها يحمل إلى بلاد الدنيا.\nوهناك قوم لهم مراكب وزوارق ليس لهم حرفة إلا إخراج المرجان من قعر البحر؛ وهو نبات مشجر له أغصان. وصورة إخراجه من البحر [أن] لهم خشبا قد صلب بعضها على بعض، ويلقون عليها جرات الكتان أو القنب ، يثقلونها بمراسم، ويلقونها فى البحر ويمشون بالزوارق، فينجر ذلك الكتان على قعر البحر فينكسر المرجان ويتعلق بالكتان، فيتفقدونه ويأخذون ما تعلق منه. ويقال إن المرجان إذا كان فى قعر البحر إنما هو رطب لين فإذا مسه الهواء اشتد. ويخرج منه فى ذلك البحر كل سنة من القناطير؛ وهو أنفس مرجان الدنيا، وهو أنفق شىء بالهند والصين. ويكون فى بحر الزقاق بساحل قرية بليونش من قرى سبتة؛ وهو مثل هذا فى الطيب أو أجل، ويكون فى بحر الأندلس، ويكون فى بعض جزائر البحر الأخضر، وهذا أنفذها.\nوبالقرب من مدينة طبرقة، بينها وبين مدينة باجة، بحيرة عظيمة فى دورها نحو أربعين ميلا تصب فى البحر، ويصب البحر فيها، وماؤها لاملح ولاحلو وفيها أنواع كثيرة من الحوت. وبها بورى ليس له فى الدنيا نظير، يقال إنه يوجد فى الحوت الكبير منها أرطال وأزيد؛ وأهل تلك النواحى يستخرجون دهنه ويستعملونه فى مصابيحهم .\nمدينة بونة : مدينة قديمة من بناء الأول وفيها آثار كثيرة؛ وهى على ربوة مشرفة على فحوصها وقراها ؛ وهى من أنزه البلاد وأكثرها لبنا ولحما وعسلا وحوتا. والبحر يضرب فى سورها، وفيها بئر على ضفة البحر منقورة فى حجر صلد، ماؤها أعذب ماء وأنفقه؛ ومنها يشرب أكثر أهلها لعذوبة مائها. وبغرب هذه المدينة ماء سائح يسقى بساتينها وأرضها؛ وموضع جناتها منتزه حسن مشرف على البحر. ويطل على مدينة بونة جبل زغوغ وهو كثير الثلج والبرد، ومن العجائب أن فيه مسجدا قديما لا ينزل عليه شىء من ذلك الثلج؛ فإذا عم الثلج الجبل كله رأيت المسجد فى وسطه كأنه شامة. وبغربى مدينة بونة بركة فى دورها نحو أميال، وفيها سمك كثير جليل. وفيها طائر يعرف بالكيكل ويسمى بالحوّاص ، وهو يعشش على وجه الماء ويفرخ، فإن أحس بحيوان أو إنسان يروم أخذه، رفع عشه بفراخه برجليه حتى يصيره فى وسط البركة حيث يأمن. وهو طائر حسن وهو الذي يسمى بمصر بالخواص، ويتخذ بمصر من جلوده ثياب للينها وجمالها؛ وتباع بالأثمان الغالية. ومرسى مدينة بونة يسمى مرسى الأزقاق، وهو من المراسى المشهورة . وبونة فى جون من البحر يسمى جون الأزقاق، وهو صعب، وفيه عطب مركب القيطانى ومركب الفخرى ومراكب كثيرة.\nمدينة القلّ : مدينة قديمة فيها آثار كثيرة للأول من الروم؛ وهى على ضفة البحر، وهى مرسى مدينة القسطنطنية. وهى كثيرة الفواكه والخيرات والعنب فيها كثير، وفيها تفاح جليل؛ ولها نظر وجباية عظيمة وهى برية بحرية.\nمدينة جيجل : مدينة قديمة على البحر وكان لها سور قديم يضرب البحر فيه؛ وهى على نظر كبير. وهى كثيرة العنب والتفاح والفواكه، ومنها تحمل الفواكه والعنب والرّب إلى مدينة بجاية. وعلى هذه المدينة جبل كتامة، ويسمى جبل زلدوى ، وهو كثير الخصب فيه قبائل كثيرة من البربر؛ وفيه كانت دعوة [أبى] عبد الله الداعى. وبين جيجل وبجاية، على ساحل البحر؛ موضع يسمى بالمنصورية عليه جبل عظيم، مما يلى البر منه حافة مثل الحائط، فيها ثقب فى غلظ حجر الربع الموزون به، ينبعث منه ماء فى كل وقت من الأوقات المعهودة بالصلوات الخمس ، يسمع قبل انبعاثه دوى كدوى الرحى الفارغة، ينبعث الماء هكذا ليلا ونهارا فى أوقات الصلاة خاصة.\nأخبر بذلك من شاهده وسهر الليل كله.\nمدينة بجاية : هى مدينة عظيمة على ضفة البحر، والبحر يضرب فى سورها. وهى محدثة من بناء ملوك صنهاجة، أصحاب قلعة أبى طويل، وتعرف بقلعة حماد اليوم. وكان سبب بنائها، أن العرب لما دخلوا إفريقية وأفسدوا القيروان وأكثر مدن إفريقية، هرب منهم صاحب القيروان الصنهاجى، وتحصن بمدينة المهدية. وكان ابن عمه صاحب القلعة، المنصور بن حماد، أشد\nشوكة من صاحب القيروان وأكثر جيشا، فخرج لنصرة ابن عمه وجيش جيشا كبيرا. فلقيته العرب بجملتها بفحص سبيبة، على مقربة من القيروان، فكان بينهم يوم عظيم حتى هزم المنصور وقتل أخوه وأكثر صنهاجة. وذلك أن أخاه كان أسن منه فنهاه عن مقابلة العرب، وقال له: \xabأقم أنت ببلادك وابعث إليهم وصانعهم يأتوك خاضعين وفى جبائك طامعين، فهذا من خلق العرب قديما فلا تلقاهم\xbb . فلما كان ذلك اليوم، وهزم، قال له أخوه. \xabألم أنهك أن تلقاهم بنفسك، ولكن اعطنى تاجك والراية أقم على الجيش، وانج بنفسك، فإن كانت السلامة فمن الله، وإلا بقيت أنت للناس، فليس منك الخلف\xbb .\nوهذا من أغرب ما يصنع الأخ مع أخيه والولى مع وليه. فأعطاه عمامته ورايته وكانت مشهورة، فسار بالجيش حتى لحق وقتل. وكانت لملوك صنهاجة عمائم شرب مذهبة يغلون فى أثمانها، تساوى العمامة ال دينار وال دينار وأزيد. وكانوا يعممونها بأتقن صنعة فتأتى تيجانا وكان ببلادهم صناع لذلك، يأخذ الصانع على تعميم عمامة منها دينارين وأزيد. وكانت لهم قوالب من عود فى حوانيتهم، يسمونها الرءوس، يعممون عليها تلك العمائم.\nفلما نجا المنصور إلى القلعة، نزلت عليه جيوش العرب وضيقوا [عليه] ببلاده، فكان يصانعهم حتى ضاق ذرعا بهم، وكان لا يقدر على التصرف فى بلاده؛ فطلب موضعا يبنى فيه مدينة ولا يلحقه فيها العرب فدل على موضع بجاية وكان مرسى. ويقال إنه كانت فيه آثار قديمة وإنها كانت مدينة فيما سلف، فبناها المنصور، وسماها المنصورية، وانتقل ملكهم من القلعة إلى بجاية، واتخذها دار مملكتهم؛ وبينها وبين قلعة حماد مسيرة أربعة أيام.\nوهى مدينة عظيمة، ما بين جبال شامخة قد أحاطت بها، والبحر منها فى جهات: فى الشرق والغرب والجنوب. ولها طريق إلى جهة المغرب يسمى بالمضيق على ضفة النهر المسمى بالوادى الكبير، وطريق القبلة إلى قلعة حماد على عقاب وأوعار، وكذلك طريقها إلى الشرق. وليس لها طريق\nسهلة إلا من جهة الغرب، فلم يكن للعرب إليها سبيل، ولا كان يدخل من العرب إلا من يبعث إليه الملك لمصانعه على بلاد القلعة وغيرها؛ فيدخلها أفراد وفرسان دون عسكر. فبقى صاحب بجاية فى ملك شامخ وعزباذخ يضاهى فى ملكه صاحب مصر، فإن بجاية على نظر كبير وفائد عظيم. وبجاية معلقة من جبل وقد دخل فى البحر يسمى مسيون ، وعليها سور عظيم، والبحر يضرب فيه. ولها داران لصناعة المراكب، وإنشاء السفن، ومنها تغزا بلاد الروم فإنها ليس بينها وبين صقلية غير مجار .\nوهى مرسى عظيمة تحط فيه سفن الروم من الشام وغيرها من أقصى بلاد الروم، وسفن المسلمين من الإسكندرية بطرف بلاد مصر وبلاد اليمن، والهند، والصين، وغيرها. ومدينة بجاية كثيرة الفواكه والأثمار، وجميع الحيرات.\nوهى مشرفة، نزيهة، ومطلة على البحر وعلى فحص قد أحاطت به جبال دوره نحو أميال، تسقيه أنهار وعيون، وفيه أكثر بساتينهم. ولها نهر كبير يقرب منها بنحو الميلين أو دونهما، وعليه كثير من جناتهم، وقد صنعت عليه نواعير تسقى من أنهر، وله منتزه عظيم. وفى بجاية موضع يعرف باللؤلؤة، وهو أنف من الجبل قد خرج فى البحر، متصل بالمدينة، فيه قصور من بناء ملوك صنهاجة لم ير الراءون أحسن منها بناء، ولا أنزه موضعا؛ فيها طاقات مشرفة على البحر عليها شبابيك الحديد والأبواب المخرمة المحنية، والمجالس المقرّصة المبنية حيطانها بالرخام الأبيض من أعلاها إلى أسفلها؛ قد نقشت أحسن نقش وأنزلت بالذهب واللازورد، وقد كتبت فيها الكتابات المحسنة، وصورت فيها الصور الحسنة، فجاءت من أحسن القصور وأتمها منتزها وجمالا. وهذا الجبل مسيون ، الذي فيه بجاية، جبل عظيم عال قد ذهب فى الجو، وقد خرج فى البحر، وفيه مياه سائحة، وعيون كثيرة وبساتين، وهو كثير القردة؛ ويكون فيه الحيوان المشوك المسمى بالذرب .\nقال الناظر: لما كانت هذه المدينة على ما وصفت، وكان فيها بقية صنهاجة الموتورين ، جعلوا يداخلون أمثالهم ممن وترت دنياه وأخراه، كأهل ميورقة المنقطعين فيها من أبناء جنسهم، فدهم بجاية منهم على بن اسحاق بن حمو بن غانية المسوفى سنة [- ١١٨٤] أول ولاية الخليفة أمير المؤمنين أبى يوسف، أيد الله أمره وأعز نصره. وعاث فيها وفى ذواتها ودرج منها إلى قسطنطينية فطردته منها عساكر الموحدين، فتوغل فى بلاد الجريد، وعاث فيها، وسفك الدماء، وأخذ الأموال، وأباح الحريم، وفعل ما هو لائق بجدته ووخامة مولده . فسارع لغزوه أمير المؤمنين، واستأصل شأفته ، ومات- لعنة الله عليه- برشقة سهم على توزر، عقب سنة [- ١١٨٩] .\nمدينة مرسى الدجاج : مدينة أزلية على شاطئ البحر، والبحر يضرب فى سورها. وهى قديمة البناء وفيها آثار عجيبة للأول، ولها بساتين وجنات، وبها الطير المسمى بالسمانى كثير من البحر، ويقابلها جزيرة ميورقة.\nمدينة جزائر بنى مزغنّاى : مدينة أزلية على ضفة البحر، والبحر يضرب فى سورها. وهى قديمة البناء أزلية فيها آثار عجيبة تدل على أنها كانت دار مملكة لسابق الأمم؛ وفيها دار ملعب قد فرش صحنه بحجارة ملونة مثل الفسيفساء، فيها صور الخيل والحيوان بأحكم صناعة، وأبدع عمل. ويتصل بجزائر بنى مزغناى فحص كبير يسمى فحص متيجة، وهو فحص عظيم كثير الخصب والقرى والعمائر تشقه الأنهار؛ وهو مرحلتين فى مثلها قد أحدقت به جبال مثل الإكليل. وفى آخر هذا الفحص جبل عليه الطريق، وهو وعر المجاز، يسمى حلق واجر ، ويسميه أهل البلاد باب الغرب؛ وليس يدخل إلى بلاد الغرب إلا منه. وكانت بمدينة بنى مزغنّاى كنيسة عظيمة فيها عجائب من البنيان، بقى اليوم منه جدار هو قبلة الشريعة للعيدين ، وهو كثير النقوش والصور. ومرساها مأمون، وفيه عين عذبة يقصد إليها أصحاب السفن؛ ويقابل هذا المرسى من الأندلس مرسى شكله. وتليها بجهة الغرب مدينة لغانية.\nمدينة لغانية : هى مدينة كبيرة قديمة فيها آثار كثيرة للأول؛ وهى غير مسكونة، ولها نهر يصب فى البحر. ويقابل هذا المرسى- فى بر الأندلس- مرسى مدينة دانية أو هو أوسع بوسطه فى هذا البحر.\nمدينة شرشال : مدينة كبيرة فيها آثار للأول، وهى غير مسكونة.\nوفيها بنيان عجيب يسمى محراب سليمان قد علا فى الهواء؛ ويقابله من الأندلس مرسى ألاقنت .\nمدينة تنّس : بينها وبين البحر ميلان؛ وهى مدينة مسورة حصينة، وداخلها قصبة صعبة المرتقى ينفرد بسكناها عامل تنس لمنعتها. وبها مسجد جامع وأسواق حفيلة كثيرة؛ ولها نهر يسمى تامن يأتيها من جبال القبلة مم يستدير بها من جهة الشرق والجوف، ويصب فى البحر. وهى كثيرة الزرع، رخيصة الأسعار، منها يحمل الطعام إلى الأندلس وإلى بلاد إفريقية وإلى بلاد المغرب لكثرة الزرع عندهم. ولكنها وبيّة، من يدخلها لا يسلم من المرض، وكثيرا ما يموت بها الغرباء. ولذلك قال بعض الشعراء فيها:\nأيها السائل عن أرض تنس ... بلد اللؤم لعمرى والدنس\nبلد لا ينزل القطر بها ... للندى فى أهلها حرف درس\nفصحاء النطق فى لا أبدا ... وهم فى نعم بكم خرس\nماؤها من قبح ما خصت به ... نجس يجرى على أرض نجس\nفمتى تلعن بلادا مرة ... فاجعل اللعنة اذا بالتنس\nوأعلمنى الثقة أن بها فيران ضخمة.\nمدينة قصر الفلوس : هى مدينة كبيرة، مرسى للمراكب، فيها آثار كثيرة للأول تنبىء أنها كانت دار مملكة؛ وهى اليوم خراب. وفيها ماء مجلوب على قناطر بأغرب ما يكون من البناء القديم.\nمدينة وهران : هى مدينة على ضفة البحر بناها جماعة من الأندلسيين البحريين بسبب المرسى، بالاتفاق مع قبائل البربر المجاورين لها؛ فسكنوها مع قبائل من البربر يقال لهم بنو مسكين نحو أعوام. ثم إنه\nزحف إليهم قبائل كثيرة من البربر يطلبون ثأرا بينهم وبين بنى مسكين فأبى من كان فيها من الأندلسيين، وكان عندهم جماعة منهم، فنصبوا عليهم الحرب.\nفلما ضيقوا عليهم هربوا بنى مسكين فى الليل؛ وتغلب البربر المحاصرون لها عليها وأخرجوا من كان فيها، وأضرموا نارا فخربت وهران عند ذلك، وبقيت سنين خربة؛ ثم تراجع الناس إليها وبنوا فعادت أحسن مما كانت. وهى مدينة كثيرة البساتين والثمار، ولها ماء سائح وأنهار كثيرة وأرحاء وعيون، وهى من أعز البلاد. ولها نظر كبير فيه قرية كبيرة فيها آثار قديمة؛ وأهلها موصوفون بعظم الخلق وكمال القامة والإباء والشدة.\nقال أبو عبيد البكري: أخبرنى غير واحد ممن دخل هذه القرية ورأى أهلها أن الرجل الكامل من غيرهم يكون إلى منكب الرجل منهم. وأنه كان.\nرجل منهم أراد أن يقيم بيتا، فاقتطع ألف كلخة وحملها على ظهره وسوى منها بيتا كبيرا وسكنه. ولوهران مرسى كبير، مشتى للسفن، يكن من الريح لأنه فى حوز جبل مطل على وهران مرتفع.\nمدينة أرشجول : مدينة قديمة أزلية فيها آثار كثيرة؛ وهى على نهر تأفنى وهو نهر كبير تدخل فيه السفن. والمدينة قريبة من البحر تصل إليها المراكب اللطاف. وهى ساحل تلمسان، بينها وبين تلمسان فحص زيدور لحرث القمح وهو مبارك مشهور البركة.\nمدينة أسلى : وهى بشرقى أرشجول بمقربة منها؛ وكانت مدينة قديمة عليها سور من صخر؛ وكانت حصينة، ولها نهر يسقى بساتينها وثمارها.\nمدينة فكّان : هى مدينة أزلية كبيرة فيها آثارة كثيرة للأول، ثم إنها خربت، فبعث إليها المنصور بن أبى عامر من بناها وعمرها.\nوهى قريبة من البحر.\nحصن زيّان : له نهر كثير الثمار والأشجار؛ وبالقرب منه حصن الفروس وهو على قنة جبل على ضفة البحر؛ وبالقرب من هذا الحصن، الوردانية، وحصن وهنين ، ومرساه مقصود وله بساتين كثيرة.\nمدينة ندرومة : من طرف جبل تاجرا؛ وهى مدينة حسنة كثيرة الزرع والفواكه رخيصة الأسعار. ولها بسائط خصيبة ومزارع كثيرة؛ وبينها وبين البحر نحو أميال. وبساحلها نهر ماء يسيل؛ وهو نهر كثير الثمار، وله مرسى مأمون مقصود، وعليه رباط حسن فيتبرك به. وقيل إنه من أتى [فيه] منكرا لم تتأخر عقوبته؛ وقد عرف ذلك من بركته، وحسن صنع الله فيه.\nمدينة ترنانا : كانت مدينة كبيرة مشهورة على ساحل البحر، وكانت محطا للسفن ومقصدا لقوافل سجلماسة وغيرها. وكان سكانها من قبائل البربر ومطغرة ؛ وهم أعدل من هناك من البربر. وعلى هذا الساحل مدن كثيرة قد خربت، وكانت فى سالف الأزمان آهلة كثيرة الخصب، مثل مدينة تا مجريت وهى ساحل، وبه مدينة مليلة ، وهى مدينة قديمة\nمشهورة ولها سور صخر وداخلها قصبة مانعة. ودخلها الناصر سنة [- ٩٢٦] ، وبنى سورها.\nمدينة عجرود : مدينة قديمة على البحر فيها آثار كثيرة ومرسى مقصود.\nمدينة نكر : وهى مدينة كبيرة، بينها وبين البحر نحو أميال؛ وهى بين رواب وجبال، ولها نهران أحدهما يسمى نكر وبه سميت، ومخرجه من بلاد كزناية من جبل كوين ؛ ومن هذا الجبل ينبعث النهر المعروف بورغة، وهو نهر كبير مشهور من أنهار المغرب. ومدينة نكر كثيرة البساتين طيبة الفواكه لاسيما الكمثرى والرمان، فليس يوجد مثلها فى بلدة. وهى قديمة أزلية افتتحها سعيد بن إدريس بن صالح الحميرى، وهو المعروف بالعبد الصالح، فى أيام الوليد بن عبد الملك بن مروان. وكان دخل أرض المغرب فى الافتتاح الأول قبل موسى بن نصير، وعلى يديه أسلم البربر المجاورين لهذه المدينة، وهم صنهاجة وغمارة. ثم ارتد منهم بشر كثير لما ثقلت عليهم شرائع الإسلام، ثم تلافاهم الله بهدايته ؛ ومات سعيد المذكور ودفن بقرية أقطى على شط البحر، وولى ذلك البلد بنوه.\nوكانت لهم حروب كثيرة مع قبائل البربر، وكانوا قد تصاهروا مع الحسنيين من بنى إدريس ملوك المغرب. ويجاور مدينة نكر جبل غمارة، وتحته مراسى كثيرة، منها مرسى باديس ، عليه عمارة كثيرة من البربر، وفيه السعر رخيص ومنه تحمل المراكب الطعام.\nمدينة تيطوان : وهى مدينة قديمة كثيرة العيون والفواكه والزرع، طيبة الهواء والماء.\nمدينة سبتة : وهى على ضفة البحر، وهو بحر الزقاق؛ والبحر قد أحاط بها شرقا وجوفا وقبلة؛ وليس لها إلى البر غير طريق واحد من ناحية الغرب، لو شاء أهلها أن يقطعوه لقطعوه . ولها بابان أحدهما محدث .،\nولها من جهة البحر أبواب كثيرة. وفى آخر المدينة بشرقها جبل كبير فى شعراء كثيفة يسمى جبل المينا ، وقد كان محمد بن أبى عامر أمر أن يبنى بهذا الجبل مدينة وينقل إليها أهل سبتة، فبنى سورها ومات ولم يتم ما أراد؛ والسور باق إلى وقتنا هذا كأنه مبنى بالأمس؛ وهو يظهر من بر الأندلس لبياضه.\nومن غريب ما فى ذلك السور أن فيه شقة مستطيلة بأبراجها مبنية بالزيت عوضا من الماء، وكان غرضه إتمام عمله على هذا لولا الإنفاق الكثير، فان البناء بالزيت أصلب وأبقى على مرور الدهور والأزمان، فلم يساعده الأجل رحمه الله.\nومدينة سبتة مدينة قديمة سكنها الأول، فيها آثار كثيرة وكان لها ماء مجلوب من نهر قرية أو يات على أميال منها، يجرى الماء فى قناة مع ضفة البحر القبلى الذي يعرف ببحر بسول ، وكان يدخل كنيستها التى هى اليوم جامع سبتة.\nوأمر الخليفة أمير المؤمنين أبو يعقوب رضه سنة [- ١١٨٤] بجلب الماء إليها من قرية بليونش المذكورة ، على أميال من سبتة، فى قناة تحت الأرض\nحسب ما جلبه الأوائل فى قرية قرطاجنة وغيرها. وشرع العمل فعرضت أمور أوجبت التربص إلى حين يأذن الله تعالى بذلك، والرجاء الآن مؤمل ونحن فى سنة [٥] [- ١١٩١] . وعلى قرية بليونش المذكورة جبل عظيم فيه القردة، عبر من تحته موسى بن نصير إلى ساحل طريفة فسمى به وهو الصحيح. وكان عليه حصن هدمه مصمودة المجاورون له، ثم بناه الناصر عبد الرحمن المروانى، فهدموه ثانية. وتحته أرض خصيبة فيها مياه عذبة، ومنه إلى مرسى باب اليم ، وعليه قرية تعرف بقصر مصمودة، ولها نهر يصب فى البحر عذب؛ ومنه يقرب الجواز إلى جزيرة طريفة ميلا.\nمدينة طنجة : هى مدينة كبيرة أزلية، فيها آثار كثيرة للأول وقصور وأقباء وغيرها. وكان فيها ماء مجلوب فى قناة كبيرة، وبخارجها ماء طيب يسمونه برقال حمل شناعة الحمق فهم يعيرون بشربه؛ فيقال لمن تهافت منهم: \xabشربت ماء بر قال لا جناح عليك\xbb ؛ وفيه يقول الشاعر:\nبطنجة عين ماء وسط رمل ... لذيذ ماؤه كالسلسبيل\nخفيف وزنه عذب ولكن ... يطير بشاربه ألف ميل\nوكان فيها رخام وصخر منجور جليل؛ منها كانت القنطرة على بحر الزقاق إلى ساحل أندلس التى لم يكن فى العالم مثلها. وكانت تمر عليها القوافل والعساكر من ساحل طنجة إلى ساحل الأندلس؛ فلما كان قبل فتح المسلمين جزيرة الأندلس بنحو سنة، طغى ماء البحر وخرج من البحر المحيط إلى بحر الزقاق، فغرق هذه القنطرة وغيرها من المواضع المجاورة لها. ويذكر أن طولها كان ميلا، وسعة المجاز اليوم فى موضعها ميلا ونحوها. وتبدو هذه\nأعدت لورود المحلات عليها- إذ [أن] وضعها على المجاز والمعبر - إلى حضرة مراكش كلأها الله. وعلى هذا المعبر قنطرة مركبة على معدية، مدت عليها أوصال الخشب وصلبت عليها الألواح والفرش الوثيق الذي لا يؤثر فيه الحافر، تجوز عليها العساكر والمسافرون؛ وحولها يتصيد أنواع السمك والشابل . ويمد البحر فترتفع القنطرة ويتغطى الجسر، فتعوم عليه المراكب وترسو دونه الأجفان الكبار؛ وقل ما تسلم عند دخولها وخروجها لصعوبة المدخل، وهو مشهور عند أهل صنعة البحر. ويقابله من مراسى بر الأندلس وادى شلب ، وبينهما فى البحر يوم وليلة. وهذه المدينة قد شرفها هذا الأمر العزيز وكرمها بما أحدثه فيها من المبانى الرفيعة والمنارة البديعة، وما هى وقت مرور المحلات عليها إلا من عجائب منتزهات الدنيا، لا سيما فى الأعوام الخصبة والفصول المعتدلة. وناهيك من ساحل طوله نحو الميلين وعرضه نحو الميل مملوء بالبشر، والزوارق فى الوادى بركابها، والمنارة المطلة، وعلاقات الثمار، وعقد الزيتون، وجدر الكرمات، وقبب الجلوس للسادات أيدهم الله ظاهرة، وقبلة الجامع وأكثر منارة ذلك الحصن المشرف ظاهرة من المدينة.\nوما هى فى أوقاتها إلا أملح من ديار مصر، وما يحكى عن دجلة والفرات؛ فإنا لله على الفناء والممات؛ ولله در من قال:\nالناس مثل حباب ... والدهر بركة ماء\nفعالم فى طفو ... وعالم فى انطفاء\nوقد ذكرت البلاد الساحلية والتى تقرب من الساحل أو دونهما، مثل القيروان، للضرورة الباعثة على ذلك. ومن الناس من يرى أن طنجة آخر بلاد الساحل، ويعتقد أن بحر أقناش إنما مدخله من هناك حيث أشبر تيال ؛\nوأنا أقول إن مدخل هذا البحر إنما هو من طرف ايغير الذي خلفه بلد نول؛ ويقابله طرف الريحانة حتى لو قطعه مركب بريح مصطحبة لأخذ أحدهما من مقابله .\nذكر البلاد الصحراوية والتى تقرب من الصحراء بمرحلة أو أكثر من الإسكندرية إلى آخر بلاد المغرب\nمدينة المنى : هى أول مدينة تلى الاسكندرية على طريق الصحراء، وهى مدن قائمة البناء خالية، فيها قصور شريفة فى صحراء رمل، يقطع فيها العرب على القوافل. ويسكن فى بعض تلك القصور الرهبان؛ وبعدها كنيسة غريبة البناء فيها عجائب من الصور والنقوش، توقد قناديلها ليلا ونهارا لا تطفأ؛ وفيها صور الأنبياء عليهم السلام وصورة مريم عم فى عمود من رخام.\nوخارج الكنيسة صور جميع الحيوان والصناع والتجار، ومن جملتها صورة تاجر الرقيق، وبين يديه خريطة مفتوحة فى الأسفل، تنبىء أن التاجر فى الرقيق لا ربح له. وفى وسط الكنيسة قبة فيها صور يزعمون أنها صور الملائكة ، وفى جهة من الكنيسة مسجد محرابه إلى القبلة يصلى فيه المسلمون. وبقربها مدينة خربها الروم فيها قصور تعرف بقصور أبى معد ، يسكنها من قريش نحو بيتا، وحواليها قبائل كثيرة من العرب من بنى مذجح وغيرهم؛ وقبائل كثيرة من البربر. ويذكر أن كثيرا ما تتبدل صورة المولود عندهم\n[ذكر كورة قسطيلية من بلاد الجريد]\nوهو قطر كبير فيه مدن كثيرة قاعدتها توزر كلاها الله. وهى المدينة السعيدة التى هلك عليها عدو الله شقى ميورقة. رشقه سهم فى ترقوته فقضى نحبه. ولها هذه الفضيلة التى اختصت بها. وكان قد انتقم من أهلها سنة [٥] [- ١١٨٦] ، وحصرها مدة وضيق عليها حتى دخلها ثم أخرجه عنها الأمر العزيز، وفر إلى الصحراء على وجهه وأتصل ببنى قرة فعند قفول المحلة المنصورة عن بلاد إفريقية أقبل إليها وظن أن كل بيضاء شحمة، فأتاه الموت من حيث لم يحتسب. وقيل إنه كان سهم قوس اللولب .\nوهى مدينة كبيرة قديمة عليها سور مبنى بالحجارة والطوب، وحولها أرباض واسعة، ولها أبواب وعليها غابة كبيرة. وهى أكثر بلاد الجريد تمرا ومنها تمتار جميع بلاد إفريقية وبلاد الصحراء التمر لكثرته بها ورخصه. ولأنها على طرف الصحراء لا يعلم ما وراءها ولا قدر أحد على الدخول فى الصحراء التى فى قبلتها؛ ويقال إن فى تلك الصحراء وادى رمل يجرى كما يجرى الماء؛ وهذا مستفاض. وأهلها من بقايا الروم الذين كانوا قبل استفتاح المسلمين لها؛ وكذلك أكثر أهل قسطيلية وبلاد الجريد، لأنهم فى حين دخول المسلمين إفريقية أسلموا على أموالهم. وفيهم من العرب الذين سكنوا فيها من المسلمين عند استفتاحها. وفيهم من البربر الذين دخلوها فى قديم الزمان عند خروجهم من بلادهم وانجلائهم عنها. وذلك أن بلاد البربر إنما كانت أرض فلسطين من ديار الشام، وما جاور تلك الأصقاع، وكان ملكهم جالوت الجبار العنية ، وجالوت سمة لسائر ملوك البربر، إلى أن قتل داود عم جالوت كما ذكر الله تعالى فى محكم كتابه، ودخلت بلادهم تفرقوا فى البلاد. فمشى أكثرهم نحو المغرب ونزل بعضهم بالقرب من بلاد مصر، وتفرقت البرابر فى بلاد إفريقية وبلاد المغرب حتى وصلوا إلى أقاصى بلاد المغرب، على أزيد من ميل من بلاد القيروان، واستوطنوها إلى وقتنا هذا. وكانت بلاد إفريقية للافرنج فأجلتها البربر عنها إلى جزائر\nمن البحر مثل صقلية وغيرها ثم تراجعت الإفرنجة إلى مدنها وعمائرها على موادعة وصلح مع البربر، واختارت البربر سكنى الجبال والرمال والبرارى وأطراف البلاد، فصارت الروم بالمدن والعمائر حتى افتتح المسلمون إفريقية فانجلت الروم أمام المسلمين مرة ثانية إلى جزائر البحر وغيرها إلا من أسلم وبقى فى بلاده على ماله مثل أهل قسطيلية وغيرهم من البلاد. وأهل توزر يبيعون زبل مراحضهم وهم يعيرون بذلك لأنهم لا يدخلون المراحض بالماء لئلا يفسد الزبل؛ فإذا دخل أحدهم المرحاض مشى إلى بعض السواقى التى تشق مدينتهم أو الوادى فاغتسل. ويمشى عندهم دلال المرحاض بالزبل فى الإناء، فإذا كان جافا حرص عليه، وإذا كان رطبا زهد فيه. ويضعون فى جناتهم مراحض على الطرق العامرة لمن كان مضطرا أو غريبا ليس من أهلها. وأما البلدى فلو أمسك ذلك يوما أو يومين ما رماه إلا فى مرحاضه. وإنما ذلك لتدمين أرضهم لأنها فى غاية الجفوف لقربها من الصحراء؛ وتتفاضل بلاد الجريد فى رطوبة الأرض ودهنيتها وتوزر أيبسها.\nومن بلاد قسطيلية مدينة نفطة : بينها وبين توزر ميلا.\nوهى مدينة كبيرة قديمة عليها سور من بناء الأول، ولها غابة كثيرة النخل والبساتين وجميع الفواكه. وهى كثيرة الخصب ولها نهر يسقى بساتينها؛ وهى قديمة خصيبة وأهلها ذو ويسار. وهم من بقايا الروم كما ذكرنا.\nومن بلاد قسطيلية بلد تقيوس : وهى مدن متقاربة عليها أسوار، يكاد يكلم بعض أهلها بعضا لتقاربها. ولهم غابات كثيرة النخل والزيتون وجميع الفواكه؛ وهى أكثر بلاد قسطيلية زيتونا وأكثر جباية وأحسن هواء؛ فيها العيون الكثيرة العذبة، والمياه السائحة.\nومن بلاد قسطيلية مدينة الحامّة : وتعرف اليوم بحامة بنى بهلول، وبنى بهلول من سادات بلاد قسطيلية بل هم أغنى من فيها، وهم من بقايا الروم الذين أسلموا على أموالهم. وعندهم كرم كثير وبر بالأضياف وحرص على التضييف، وهو الذي رفع ذكرهم فى تلك البلاد. وهذه المدينة لها حصن يسمونه القصر؛ وهو مختص ببنى بهلول وحاشيتهم. ولها أرباض واسعة يسكنها الناس؛ وهى كثيرة التمر والزيتون وجميع الفواكه؛ ومن مدن نفزاوة ما يضاهيها. ومياه هذه المدينة كلها حامة حارة. وليس ببلاد الجريد أكثر عنبا منها ولا أطيب، وشرابه أطيب من كل شراب وأعطر. ويزعم أهلها أنه يسرج به السراج كما يسرج بالزيت. وفيها نوع من التمر يسمونه الخنفس، وهو أسود اللون شديد الحلاوة كبير الجرم. وفى قسطيلية قصور كثيرة وعمائر متصلة أعرضنا عنها وعن ذكرها.\nومن بلاد الجريد بلاد نفزاوة : وهو قطر مثل قسطيلية فيه مدن وقصور وعمائر كثيرة متصلة آهلة.\nفمن مدن نفزاوة مدينة طرّة : وهى مدينة مسورة حصينة، لها غابة كثيرة النخل والزيتون وجميع الفواكه.\nومن مدن نفزاوة أيضا مدينة بشرى : وهى مدينة مسورة قديمة، لها غابة كبيرة كثيرة النخل والزيتون وجميع الفواكه.\nومن مدن نفزاوة أيضا مدينة أيتملين : وهى مدينة لطيفة حصينة لها أرباض ولها غابة نخيل وزيتون وجميع الفواكه. قال بعض الأدباء:\nايتملين سبعة أحرف على لطفها وخمول ذكرها، ومصر ثلاثة أحرف على عظمها وسمو ذكرها.\nوبنفزاوة مدن وقصور وعمائر مثل قسطيلية، وهى كثيرة النخل والبساتين كثيرة الخصب. وفى بلد نفزاوة عين كبيرة تسمى بالبربرية تاورغى ، وهى من بناء الأول؛ وليس ببلاد الجريد عين أعظم منها، لا يدرك لها قعر. وبقرب نفزاوة مدينة أزلية غير مسكونة فيها آثار كثيرة للأول تعرف بالمدينة . وبين نفزاوة وقسطيلية مرحلة، والطريق بينهما فى أرض سواخة وسباخ وملاحات لا يهتدى للطريق بها إلا بخشب قد نصبت فى دهس تشبه الصابون فى الرطوبة. فإن أخطأ أحد طريق تلك الخشب المنصوبة على الطريق سلك فى تلك السباخ. وقد هلك فيه العساكر والجماعات على قديم الزمان؛ ممن دخلها ولا يعرف أمرها أو خانته تلك الخشب وتلك السباخ لا يعلم لها آخر، إنما هى قد اتسعت فى تلك الصحارى، ولا يسلك منها إلا الطريق إلى توزر، وإلى بلاد قسطيلية ما يقرب من البر بتلك العلامات. ويقال إنها متصلة ببلاد غدامس. وهذه السباخ كلها ملاليح وفيها موضع بين نفطة والحامّة يعرف \xabبالسبع سباخ\xbb . وفى وسط الطريق المار من مدينة توزر إلى نفزاوة جزيرة صغيرة فيها عين عذبة يشرب منها من يسير على ذلك الطريق. وإذا دخل المسافرون هذا الطريق فى أيام الصيف يكادون يهلكون من حرارة الملح ويرجع ماؤهم وهو فى الزقاق ملحا، ولا تقدر على شربه إلا أن يمزج بسكر أو بعسل؛ رأيت ذلك وشاهدته.\nقال الناظر: وعندها هزم الخليفة أبو يوسف رضى الله عنه الشقى الميورقى بظهر مدينة حامة مطماطة المذكورة، فر الشقى منهز ما بخديعة الذهن آخذا على هذه السباخ، فتبعه الموحدون أعزهم الله، سالكين أثره قاصين خبره حتى أشرفوا على مدينة توزر، فلقوه قد توغل فى صحرائها. وخاطب الخليفة رضى الله عنه بلاد المغرب معلما بذلك. فمن فصل من الرسالة : \xab ... نهض الموحدون- أعزهم الله- من قابس- كلأها الله- آخذين على صحرائها وقاصدين إلى البلاد الجريدية من ورائها على طرق لا عهد لها بالعساكر، ولا علم فيها لعابر، ولا منفذ أمامها لوارد ولا صادر، بحيث منقطع التراب، ومتصل القفر اليباب، ولا ماء ينبع فى الأرض ولا يستقر من صوب السحاب ، وإن سلوكها لمن العجائب العجاب ، وآيات هذا الأمر الميسر للطلاب ... \xbb .\nوآخر بلاد الجريد مدينة درجين : وهى مدينة قديمة بقرب نفطة، وهى مدينة كبيرة وفيها تصنع الكسى الدرجينى، وهو يشبه السجلماسى فى ثوبه ولونه، ولكنه دونه فى الجودة. وبالقرب منه بلد سوف، ولا يعرف خلفه عمران ولا حيوان إلا جبال من رمل يصاد فيها الفنك الذي لا يوجد لجلده نظير فى الدنيا. وأهل تلك البلاد يخبرون أن قوما أرادوا معرفة ما وراء قسطيلية مثل توزر وغيرها، فأستعدوا بالأزودة والمياه، وذهبوا فى تلك الصحارى والرمال أياما، فلم يروا أثرا لعمران وهلك أكثرهم فى تلك الرمال. قال الناظر: ركب هذه الرمال، وشق صحراءها هذا الشقى فى حين طلب الموحدين له، أيام إقامة أمير المؤمنين على قفصة، وإنما نبه على ركوبها ما تعوده أيام كونه مع أبيه بميورقة، فإن من أفعال عدو الله ركوب ظهر اللجج طول النهار، فإذا أقبل العشى طلب أهل البر للفرضه. وكذلك فعل الشقى،\nركب هذه الصحراء طول إقامة الخليفة ببلاد إفريقية، فلما أقبل عنها، رجع إلى أقرب البلاد لها وهى توزر فقضى نحبه عليها، وإنها من براهين هذا الأمر العلى، وأخذه الله تعالى بذنوبه المتقدمة من سفك الدماء وإباحة الأموال والحريم فى بلاد إفريقية. قال المؤلف: وأهل الجريد يأكلون الكلاب ويستطيبونها، وهم يسمنونها، ويعلفونها بالتمر، فيزعمون أن لحمها يأتى ألذ اللحوم . ولا يجذم أحد ببلاد الجريد، وإن دخلها مجذوم توقفت عنه علته. ويقول أهل بلاد الجريد إن التمر إذا أكل أخضرا، وهو الذي يسمى البهر يفعل ذلك، وإنه من بدت به علة الجذام، فأكثر من أكل البهر وطبخه وشرب مائه برأ باذن الله.\nومن مدن إفريقية المشهورة مدينة باجة : وهى مدينة كبيرة أزلية قديمة فيها آثار للأول. ولها حصن حصين أزلى مبنى بالصخر الجليل، أتقن البناء، يقال إنه من عهد عيسى عم. ومدينة باجة على جبل شديد البياض، يسمى الشمس لبياضه، وهى كثيرة الأنهار والعيون؛ ومن تلك العيون عين كبيرة تسمى عين الشمس، وهى تحت سور المدينة؛ وباب المدينة بإزاء العين ويسمى الباب باب عين الشمس. ومدينة باجة رخيصة الأسعار جدا، فإذا أخصبت البلاد لم تكن للحنطة بها قيمة. وتسمى باجة هرى إفريقية، فإن بها تمتاز جميع البلاد، عربها، وبربرها، لكثرة طعامها ورخصه. وباسمها سميت باجة الغرب بجزيرة الأندلس. وباجة إفريقية على مقربة من فحص قلّ المشهور بكثرة الزرع، وأرض هذا الفحص أرض مشققة سوداء، يجود فيها جميع البذر، ويكون فيه حمص وفول قل ما يوجد مثله فى موضع.\nومدينة باجة نظر كبير، ولها قرى كبيرة عامرة ومن بعض قرى باجة، قرية تعرف بالمغيرية وهى كبيرة وبها آثار كثيرة للأول، من كنائس قائمة\nالبنيان، محكمة العمل، كأنها رفعت عنها الأيدى بالأمس؛ وكلها مفروشة بالرخام النفيس. وفى هذه الكنائس أعجوبة، يجتمع على حيطانها من الغربان عدد لا يحصى، يظن الرائى لها أن غربان الأرض قد جمعت هناك. ويقال إن لها بها طلسم. وكان الولاة يتنافسون فى ولاية بجاية، ويقولون من يترك قمح عندة وسفرجل دانة وعنب باطة وحوت درنة. وذرنة بحيرة كبيرة ما بين مدينة باجة، ومدينة طبرقة. وعلى الطريق من القيروان إلى قلعة أبى طويل وهى قلعة حماد، مما يلى بلاد الصحراء، مدن كثيرة خربتها العرب عند دخولهم بلاد إفريقية، منها\nمدينة سبيبة : وهى مدينة قديمة أزلية، ذات أنهار، ومياه سائحة تطحن عليها أرحية. وكانت على نظر كبير ومز درعات كثيرة وقرى عامرة.\nوفيها اليوم بعض سكنى لقبائل من البربر والعرب، ويسمى اليوم ذلك النظر القرى . ولم يكن بإفريقية أخصب أرضا منها، ولا أكثر بساتينا وثمارا وعيونا جارية. ولمدينة سبيبة عين عظيمة كبيرة، وهى من بنيان قديم، من عمل الأوائل، ويقال إن فيها أخباء كثيرة . ومن أغرب ما يهتف به أهلها، أنهم يقولون إنه يوجد فيها فى رأس كل شهر دينار كبير، زنته عشرة مثاقيل ، ولا يجده إلا من يعرف رقية العين، ويقولون إن رجلا كان يعرف رقية العين المذكورة، فكان يبخر ببخور، ويرقى بكلام غير مفهوم، فكان يجد فيها كل يوم دينارا من تلك الدنانير، حتى كسب من ذلك مالا كثيرا.\nمدينة مجّانة : وتعرف بمجانة المطاحن ، لأن بها معدنا لقطع حجارة الأرحاء ليس على الأرض مثله؛ وهى مدينة قديمة أزلية ذات مياه وعيون.\nمدينة مرما جنّة : كانت مدينة كبيرة قديمة أزلية. فيها آثار كثيرة للأول ولها عيون سائحة، وهى على نظر واسع كثير الزرع والخيرات.\nمدينة تبسا : وهى مدينة قديمة أزلية، فيها آثار كثيرة للأول ومبان عجيبة، ما بإفريقية بعد قرطاجنة أعظم منها. فيها دار ملعب قد تهدم أكثره، أغرب ما يكون من البناء. وفيها هيكل يظن الرائى انه كما رفع اليد عنه، ما يكاد يعرف الفرق بين أحجاره ، ولو غرست الإبرة بين حجرين من أحجاره ما وجدت منفذا. وفى داخله أقباء معقودة بعضها فوق بعض، وبيوت تحت الأرض وآزاج كثيرة لها منظر هائل. ويقال إن ذلك الهيكل كان لاستنزال الروحانيات، لأن فيه أثر الدخان، وفيه صور جميع الحيوانات وصور شاذة لا يعلم ما هى. وفى وسط المدينة هيكل عظيم، مبنى على سوارى رخام عظام، وقد صور خارج حيطان هذا الهيكل من صور جميع الحيوانات بأغرب ما يكون من التصوير، ويقال إنها كلها طلاسم. وتوجد فى خرائبها طلاسم، ولقد دخلتها فأعطانى إنسان من أهلها طلسما، وهو على صورة أسدين من نحاس أحمر، عجز الواحد منهما إلى عجز الآخر، قد صورتا بأعجب ما يكون من التصوير. وأخبرنى أن بلدهم تبسّا كان لا يدخلها عقرب، ولو أدخل فيها مات، حتى حفر إنسان أساس داره، فوجد قدر نحاس فيها عقارب من نحاس، فسبكها، وصرفها فيما يحتاج، فدخلت حينئذ العقارب المدينة، وأضرت بالناس فيها. والمسكون اليوم من تبسا إنما هو قصرها، وعليه سور من حجر جليل، متقن العمل كأنما فرغ منه بالأمس، وهو حصن عظيم. وفى مدينة تبسّا أقباء تدخلها الرفاق بدوابهم فى أيام الشتاء، يسع القبول منها ألفى دابة وأكثر. وبقرب مدينة تبسا، واد يعرف بوادى\nملان. وهو يقل فى أيام الصيف؛ وهو صعب المجاز كثير الدهس ، وعليه جبل يسمى ملان يرى على مسيرة أيام لعلوه، وذهابه فى الجو. وعلى مقربة من تبسا جبل يعرف بالكتف ، وفى أعلاه مغارة لا يقدر على الوصول إليها لا من فوق الجبل، ولا من أسفله. ويقال إن فيها مالا عظيما، فإن الطير إذا نزلت فى تلك المغارة وطارت عنها سقطت منها دنانير كبار من ذهب نفيس، وهذا متعارف فى تلك البلاد. ولمدينة تبسا بساتين كثيرة، وفواكه عجيبة، ويجود فيها الجوز حتى يضرب به المثل بإفريقية\nمدينة باغاية : وهى مدينة عظيمة جليلة، فيها آثار للأول، ولها أنهار عامرة، وعيون، ومزارع، ومسارح. وهى تحت جبل أوراس، وهذا الجبل يشق بلاد المغرب وإفريقية: فطرفه من البحر الغربى ايغريطوق على البحر المحيط، حيث انتهى عقبة المستجاب، رحمه الله؛ وطرفه الثانى فى البحر الشرقى بقرب الإسكندرية، وهو المسمى بطرف أوثان الذي إذا عبرته المراكب استبشرت بالسلامة. ومبدؤه بالمغرب، وهو جبل المصامدة المسمى بجبل درن، وهو جبل جزولة المسمى بانكسيت وهو جبل أوراس هذا، ويسكنه لواته، وهو جبل نفوسة. ويدخل طرفه فى البحر نحو ميل وأزيد. وله جون عظيم فإذا أدخلت الرياح سفينة من السفن فى هذا الجون، وعدمت الرياح التى تخرجها منه فلا تجد هناك مرسى لأنه جبل صلد أملس مثل الحائط، وهذا الجون من أحد عجائب الدنيا.\nوبقرب باغاية قبر مادغوس وهو قبر مثل الجبل العظيم مبنى بآجر رقيق معقود بالرصاص، وبنيت بجانبه طبقات صغار وصورت فيه جميع الصور من الإنس والطير والوحش . وهو مدرج النواحى؛ وقد رام كثير من الأمم هدم هذا القبر فلم يقدروا على ذلك لقوة بنيانه، ولمانع يمنع عنه. ولا يعلم على الحقيقة ما هو: هل هو قبر أو هيكل. إنما هو بناء قديم لا يعلم له أول، وهو مجمع لكل طائر؛ ويقال إن لهم هناك طلاسم.\nومن الجبال المشهورة بإفريقية جبل أوراس : وهو جبل خصيب فيه مدن كثيرة وفيه آثار كثيرة للأول ومدن خربة مثل مدينة طنفة .\nوكانت مدينة قديمة فيها آثار عجيبة. لقد رأيت فيها بيتا له عضادتان من حجرين مثل جبلين وعليهما عتبة من حجر واحد مثل الجبل الضخم قد قرضت ونقشت على النوع الذي يعمل عندنا فى العمود بأتقن صناعة وأغربها، وإنما العجب كيف رفعت تلك العتبة أو زحزحت من الأرض.\nمدينة الموس : فيها كذلك أثار عجيبة ومبانى غريبة تنبئ أنها كانت مدينة عظيمة كبيرة.\nمدينة شقبنارية : وهى مدينة كبيرة فيها آثار عظيمة وهى على طرف هذا الجبل أوراس. وكانت فيما يقال من أعظم مدن إفريقية، وكان لها ماء مجلوب وبقى فيها اليوم مواجل عظام ما تغير منها شئ، وفيها عين عظيمة عذبة\nولها سرب كبير تحت الجبل يمشى فيه الفارس بأطول ما يكون من الرماح فلا يلحق سماك ذلك السرب. ويقال إن فيه كنوزا وأموالا كثيرة؛ ويقال إنه كان بمدينة شقبنارية كنيسة وفيها مرآة صنعت من أخلاط عجيبة؛ إذا اتهم الرجل أهله بأحد، نظر فى تلك المرآة فيرى وجه الرجل المتهم. فيقال إنه كان فى تلك الناحية رجل بربرى يدعى أنه من أهل الخير والصلاح، فاتهم ملك شقبنارية أهله بذلك البربرى فنظر فى المرآة فرأى صورة البربرى مع امرأته، فأوقف على ذلك الشهود وأخذ البربرى فقتله، فغضب لذلك أهل البربرى ودخلوا تلك الكنيسة فكسروا تلك المرآة ونزعوها. وفى هذا الجبل مدن قديمة كثيرة خربة فيها آثار عظيمة وهو كثير العمائر والقرى وهو بلد الزرع والضّرع.\nومما يقرب من هذا الجبل من المدن المشهورة بإفريقية مدينة قسنطينة :\nوهى مدينة كبيرة عامرة قديمة أزلية، فيها آثار كثيرة للأول. وكان لها ماء مجلوب يأتيها على بعد على قناطر تقرب من قناطر قرطاجنة؛ وفيها مواجل عظام مثل الذي بقرطاجنة. ومدينة قسنطينة حصينة فى نهاية من المنعة والحصانة لا يعرف بإفريقية أمنع منها، ليس لها فى المنعة نظير غير مدينة رندة بالأندلس، فإنها تشبهها فى وضعها والخندق المحيط بها والحافة المحدقة بها شبها كثيرا. ولكن قسنطينة أعظم وأكبر وأعلى، على جبل عظيم من حجر صلد، وقد شق الله تعالى ذلك الجبل فكان فيه خندق عظيم يدور بالمدينة من جوانب. ونهرها الكبير يدخل على ذلك الخندق ويدور بالمدينة فيسمع لجريانه فى ذلك الخندق دوى عظيم هائل وصوت مفزع لمن يقرب منه. وقد عقد الأولون على هذا الخندق قنطرة عظيمة بل هى بعضها على بعض. و [هى] بالجو قربت من أعلى الخندق، وعليها الدخول إلى باب المدينة وهى متصلة بالباب. وقد بنى على طرف القنطرة مما يلى باب المدينة بيت على أقباء يسميه أهل المدينة \xabالعبور\xbb يعنون الشّعرى لأنه معلق فى جو السماء، فإذا كنت فى وسط هذه القنطرة تعبر إلى\nالضفة الثانية نظن أنك تطير فى الهواء، وترى ماء النهر الكبير فى قعر الخندق البعيد المهوى مثل الجدول الصغير. وهذه المدينة من عجائب العالم قد دخلتها مرارا وتأملت آثارها ودخلت مواضع كثيرة فيها آثار للأول فتأملتها، وكان لى فى ذلك غرض. وهى على نظر واسع وقرى كثيرة عامرة آهلة، وهى كبيرة الخصب والزرع ولها بساتين كثيرة الفواكه، لكنها شديدة البرد والثلج كثيرة الرياخ لعلوها وارتفاعها. وأقرب بمدينة القسنطينة من رأس البحر مدينة القلّ بينهما نحو المرحلتين أو أقل.\nمدينة ميلة : مدينة أزلية فيها بعض آثار للأول تدل على أنها كانت مدينة كبيرة. وهى الآن عامرة آهلة كثيرة الخصب رخيصة السعر، على نظر واسع وقرى عامرة. وميلة كثيرة الأسواق والمتاجر، عليها سور صخر جليل من بناء الأولين. وفى وسط المدينة عين خرارة عذبة من بناء الأوائل لها سرب كبير يدخل فيه فلا يوجد له آخر، ولا يعلم من أين يأتى ذلك الماء. ويقال إنه مجلوب من جبل بالقرب منها يسمى تامروت، وتعرف هذه العين بعين أبى السباع. وبالقرب من ميلة جبل العنصل يسمى اليوم جبل بنى زلدوى وهم قبائل كثيرة من البربر سكنوا بذلك الجبل، ولهم خلاف كثير على الولاة بسبب منعة جبلهم؛ وفيه مدن وعمائر وقرى كثيرة وهو أخصب جبال إفريقية؛ فيه جميع الفواكه من التفاح الجليل والسفرجل الذي لا يوجد مثله فى بلد والأعناب الكثيرة. وعلى الطريق من مدينة ميلة إلى قلعة أبى طويل وهى قلعة حماد، مدينة سطيف ، بينها وبين ميلة مرحلة. وهى مدينة قديمة أزلية كان عليها سور صخر قديم خربه كتامة مع أبى عبد الله الشيعى.\nومدينة سطيف رخيصة الأسعار كثيرة الفواكه والثمار، غزيرة المياه والأنهار والبساتين والأشجار.\nمدينة الغدير : وهى مدينة كبيرة أزلية بين جبال قد أحدقت بها، ولها نهر يجتمع من العيون فى موضع دهس يخرج منه هذا النهر، ويسمى نهر سهر ويمشى من هناك إلى مدينة المسيلة وهو نهرها. والمسيلة من بلاد الزاب، وسيأتى ذكرها عند ذكرنا بلاد الزاب إن شاء الله. وبقرب مدينة الغدير فحص عجيسة، وهو فحص مديد ، كثير الزرع والضرع إلا أنه شديد البرد والثلج. ولقد دخلت هذا الفحص فى زمان الصيف فرأيت الجليد ينزل فيه بالغدو. ومن أمثال تلك البلاد، برد بلد عجيسة فى الصيف وأما الشتاء فسكرات الموت وعندهم النيلة المشهورة .\nمدينة قلعة أبى طويل : وهى قلعة حماد وهى مدينة عظيمة قديمة أزلية على نظر عظيم كثير الزرع وجميع الخيرات. وهى فى جبل عظيم، وهى حصينة منيعة لا تمكن بقتال. وكانت دار مملكة بنى حماد من صنهاجة، وهم كانوا ملوك إفريقية [أيام بنى عبيد] فلما رحلوا إلى بلاد مصر، ولوا على إفريقية [بلجين بن زيرى بن مناد الصنهاجى، فكان كذلك على طاعتهم إلى أن مات ثم ولى بعده ابنه حبوس فكان كذلك على طاعتهم إلى أن مات فولى بعده ابنه باديس؛ ثم ولى بعده أبنه المعز وهو الذي خلع طاعة الشيعة وقتلهم بإفريقية قتلا ذريعا. وكان سبب ذلك أن هذا المعز بن باديس كان يضمر حب الصحابة رضه، وكان يظهر التشيع والقليل من أهل إفريقية سنية لكون\nالدولة للشيعة ، فقيل إن المعز كان ماشيا يوما بالقيروان، وكانت دار مملكة إفريقية، إذ كبت به دابته فقال \xabأبو بكر وعمر\xbb ، فلما سمع منه أهل القيروان ذلك قاموا على الشيعة فقتلوهم حيث ما وجدوهم وقتلوا فى جميع إفريقية؛ ويقال إنه قتل منهم بالقيروان وأحوازها نيف على ألفا. وملك بنو زيرى ابن مناد الصنهاجى بلاد إفريقية إلى أن دخلها عليهم العرب، فرجع صاحب القيروان يسكن مدينة المهدية. وقد كان حماد بن حبوس قام على ابن عمه باديس بهذه المدينة، فسميت قلعة حماد؛ ونزل عليه ابن عمه فى جيوش لا تحصى فما قدر عليه، ورجع عنه خاسرا ؛ ويقال إنه مات عليها وحمل منها إلى القيروان.\nوولى بعده ابنه المعز وهو لم يبلغ الحلم فعند ذلك عظم ملك حماد بقلعة أبى طويل، وأخذ كثيرا من مدن إفريقية. فلما دخل العرب إفريقية هرب منهم صاحب القيروان إلى المهدية، وخرج المنصور من بنى حماد لنصرة ابن عمه وهزم الهزيمة المشهورة على مدينة سبيبة، وقد ذكرنا ذلك فى أخبار بجاية، وعظم ملك بنى حماد بجهة القلعة، وبجاية، وتلك البلاد.\nولبنى حماد بالقعلة مبان عظيمة وقصور منيعة متقنة البناء عالية السناء منها قصر يسمى بدار البحر، وقد وضع فى وسطه صهريج عظيم تلعب فيه الزوارق، يدخله ماء كثير من ماء مجلوب على بعد. وهذا القصر مشرف على نهر كبير وفيه من الرخام والسوارى ما يقصر عنه الوصف، وفيه قصور غير هذا ومبان عجيبة؛ وفيها آثار للأول عجيبة. ويقال إن حماد بن مناد صاحب القلعة التى تنتسب إليه كان له دهاء وفطنة وتجربة فى الحروب، وكانت له فراسة حسنة وذكاء وله أخبار مشهورة محفوظة. فمن المحفوظ عنه من الذكاء والفطنة أن رجلا شيخا خرج مع امرأته من بعض البلاد يريد القلعة فصحبه فى الطريق فتى شاب وكان له جمال، فكلفت به المرأة وكلف بها فتواطآ على أن يدعى فى زوجيتها وتفعل هى كذلك، ويسقط الشيخ، فلما وصلوا القلعة فعلا ذلك. قال فتعرض الشيخ إلى حماد وشكا إليه\nما دهاه. وكان الشيخ مولعا بالمرأة فأمر حماد بإحضار الفتى والجارية، فسألهما عما ذكره الشيخ فأنكرا ما قال الشيخ وتعارفا أمامه بالزوجية. فجعل حماد يسأل الشيخ من صحبه فى الطريق، أو هل له بينة أو شبهة؛ فقال له الشيخ ما صحبنى وامرأتى غير هذا الكلب، خرج معنا من البلد الفلانى، وهو تربيتنا؛ فأمر حماد بربط الكلب إلى شجرة، ثم أمر المرأة أن تحله، فقربت منه فهش الكلب إليها، فحلته، ثم أمرها فربطته ثم حلته، والكلب فى ذلك كله يهش إليها ولا ينكر شيئا مما تفعل به. ثم قال للفتى قم إلى الكلب وحله واربطه فلما دنا منه خجّه الكلب وأنكره ولم يقدر على الدنو منه. فقال حماد للشيخ قم إلى الكلب، فقام إليه فهش الكلب كما هش للمرأة، فأمر بضرب عنق الفتى، وقال للشيخ شأنك والجارية. وكان له من هذا الباب كثير. ويذكر أنه قال : ما تداهى على أحد قط ولا خدعنى غير امرأة وكعاء من البربر.\nقيل له وكيف كان ذلك؛ قال كان لى صاحب من البربر نشأت معه بالقيروان ولم يفرق بيننا ريب الزمان، وكنت خالطته بنية نفسى وجعلته محل أنسى، فلما صرت إلى ما أنا فيه من الرياسة، فقدته، فجعلت أطلبه فلا أقدر عليه، فلما نزلت على مدينة باغاية ، ودخلتها عنوة واستبحت جميع ما فيها فإذا أنا فى صبيحة ذلك اليوم بصائح يصيح: \xabأنا بالله وبالأمير\xbb ؛ فقلت: \xabمالك ومن أنت\xbb . فقال أنا فلان، فإذا بصاحبى الذي كنت أطلب مع أهل باغاية، قد حبسه عنى نسكه، وغلب على هواه وورعه؛ فأظهرت البشر بمكانه والجزل بشأنه، ولو شفع إلى فى أهل باغاية لشفعته. فجعلت أوانسه وهو كالوالد فسألته عن أمره، فقال إنه فقد بنتا كانت له فيمن فقد من النساء؛ فقلت له والله لو خرجت إلى بالأمس لحقنت دم أهل بلدك لحرمتك عندى؛ فقال القدر غالب والمحروم خالب. قال حماد ثم أمرت القواد فأحضروا جميع ما كان فى أخبئتهم من النساء، فعرف الرجل أن ابنته فيهن. قال حماد فأمرت بسترها وترفيهها وحملها مع أبيها فى أحسن حال، قال فرفعت صوتها قائلة، والله يا حماد لا\nرجعت مع أبى ولا مع الذي غصبنى، قال فقلت لها فما الذي تريدين؟ قالت إنى لا أصلح إلا للملوك فلا حاجة لى بسواهم، فلما سمع ذلك أبوها سكن ما كان فى نفسه لها من الإشفاق، وظن أنها قد فتنت وفسدت. قال حماد ومن أين تقولين أنك تصلحين للملوك؟ قالت، لأن عندى علما لا أشارك فيه ولا يدعيه غيرى، فقلت لها ألا أريتينا شيئا من علمك، قالت نعم تأمر بقتل إنسان وتحضر أمضى سيف عندك، أتكلم عليه بكلمات تمنع من تأثيره فى أحد ويعود فى كف حامله أكل من قبله. قال حماد فقلت إن الذي يجرب هذا فيه لمغرور، فقالت لى، أويتهم أحد فى قتل نفسه؟ قلت لها لا، فقالت إنى أريد أن تجرب ذلك فىّ حتى تروا عجبا. قال فأتى بسيف ماض فتكلمت عليه وأشارت إلى السماء مرارا ومدّت عنقها، فضربها السياف ضربة أبان رأسها من جسدها؛ فاستيقظت من غفلتى، وعلمت أنها تداهت على، وكرهت العيش بعد الذي جرى عليها واستبان لأبيها ذلك فجعل يلقى نفسه عليها، ويتمرغ فى دمها اغتباطا بما رأى من عظيم أنفاسها، إذ اختارت الموت على ما نزل بها، وقال لا شك أن إشارتها إلى السماء إنما كان ذكرا للشهادة والدعاء لله تعالى أن يغفر لها. وتصنع بمدينة قلعة حماد أكسية ليس لها مثيل فى الجودة والرقة إلا الوجدية التى تصنع بوجدة؛ يساوى كساء عيد من عمل القلعة دينارا.\nمدينة أشير : بناها زيرى بن مناد الصنهاجى وتعرف بأشير زيرى، وكانت مدينة قديمة فيها آثار عجيبة، وإنما بنى زيرى سورها وحصنها وعمرها فليس فى تلك الأقطار أحسن منها. وهى بين جبال شامخة محيطة بها. وداخل المدينة عينان لا يبلغ لهما غور ولا يدرك لهما قعر من بناء الأول، وبالقرب من المدينة بنيان عظيم يعرف بمحراب سليمان لم ير بنيان أعظم منه ولا أحكم، فيه من الرخام والأعمدة والنقوش ما يقصر عنه الوصف.\nمدينة مليانة : قريبة من مدينة أشير، وهى مدينة كبيرة من بنيان الروم جددها زيرى بن مناد أيضا وفيها آثار قديمة. وهى مدينة حصينة فى سفح جبل يسمى نكار، وشعراء هذا الجبل كلها ريحان، وينبعث من هذا الجبل عين خرارة عظيمة تطحن عليها الأرحية لقوتها. ولمدينة مليانة مياه سائحة وأنهار وبساتين فيها جميع الفواكه، وهى من أخصب بلاد إفريقية وأرخصها أسعارا. ومدينة مليانة مشرفة على فحوص واسعة وقرى كثيرة عامرة ومزارع واسعة؛ وحولها قبائل كثيرة من البربر. ويشق تلك الفحوص نهر شلف وهو نهر كبير مشهور. وعلى نهر شلف مدينة قديمة أزلية فيها آثار أولية تسمى شلف، وإليها ينسب النهر الكبير، وهى اليوم خراب.\nمدينة الخضراء : وإنما سميت الخضراء لكثرة بساتينها، وكانت مدينة كبيرة قديمة فيها آثار أولية وهى على نهر إذا حمل دخل بعضها، وأظنه نهر شلف.\nذكر بلاد الزاب : وهى على طرف الصحراء، فى سمت بلاد الجريد، وهى مثلها فى حر هوائها وكثرة نخلها. وهى مدن كثيرة، وأنظار واسعة وعمائر متصلة، فيها المياه السائحة والأنهار والعيون الكثيرة.\nمدينة المسيلة : أقرب بقلعة حماد من بلاد الزاب مدينة المسيلة، وهى فى بسيط من الأرض على نهر كبير يسمى بسهر، ومنبعه من مدينة\nالغدير وقد ذكرناه. مدينة المسيلة أحدثها أبو القاسم إسماعيل بن عبيد الله الشيعى منذ سنة [- ٩٢٥] وكان المتولى لبنائها على بن حمدون بن سماك المعروف بابن الأندلسى، فلم يزل بها أميرا حتى مات فى فتنة أبى يزيد ، وبقى ابنه جعفر أميرا فيها، وولى على بلاد الزاب كلها. وهذا جعفر ممدوح محمد بن هانئ الأندلسى الشاعر المشهور، له فيه مدائح كثيرة حسان، وكان من أكثر أهل زمانه إحسانا. ومدينة المسيلة كثيرة النخل والبساتين تشقها جداول المياه العذبة، وكانت مدينة عظيمة على نظر كبير، وحواليها قبائل كثيرة من البربر من عجيسة وهوّارة، وبنى برزال.\nمدينة نقاوس : مدينة كثيرة الأنهار والثمار والمزارع، كثيرة شجر الجوز، منها يحمل الجوز إلى قلعة حماد وإلى بجاية وإلى أكثر تلك البلاد.\nمدينة طبنة : وهى مدينة كبيرة قديمة عليها سور من طوب ولها حصن قديم عليه سور من صخر جليل ضخم متقن البناء من عمل الأوائل، ولها أرباض واسعة وهى مما افتتح موسى بن نصير حين دخل بلاد إفريقية والمغرب وبلاد الأندلس فبلغ سبيها ألف رأس. ويشق مدينة طبنة جداول الماء العذب ولها بساتين كثيرة النخل والثمار ولها نهر يشق غابتها، وقد بنى له صهريج كبير يقع فيه وتسقى منه جميع بساتينها وأرضها، ولم يكن من القيروان إلى سجلماسة مدينة أكبر منها\nمدينة بسكرة : وهى مدينة كبيرة، وحواليها حصون كثيرة وقرى عامرة وهى قاعدتها ، ولها غابة كبيرة كثيرة النخل والزيتون وجميع الثمار، ببسكرة النخل لكثرته بها ، وفى جميع البلاد إنما يصيحون عليه \xabبسكرة\xbb .\nوأكثر تمرها الجنس المعروف بالكسبا وهو المعروف ببلاد المشرق وبمدينة الرسول عم وغيرها بالسيمانى ، وببسكرة أيضا جنس من التمر يعرف بالليارى وهو أبيض أملس وكان صاحب القيروان يأمر عماله بالمنع من بيعه، وبعث ما هناك منه إليه لطيبه وحسنه. ويشق غابة بسكرة نهر كبير ينحدر من جبل أوراس يسقى بساتينها ونخلها، وهو نحو أميال فى غابة متصلة بالمدينة يشق غابتها وقراها. وبسكرة دار فقه وعلم، فيها العلماء. ومن قرى بسكرة قرية تسمى ملسون ، ومنها كان أبو عبيد الله الملسونى، وكان عالما فقيها يحمل عنه العلم، وهو الذي أخبرنى أن فى طريق بسكرة جبلا وفيه كهف فيه رجل قتيل لم يعرف أحد من أى عهد هو ، ولم تغيره الدهور ولا تقادم الأزمان كأنما جراحه تقطر دما كأنه قد قتل من يومين، وتخبر الكافة عن الكافة والخلف عن السلف، أنهم كذا عرفوه منذ كانوا؛ وقد نقله أهل تلك النواحى ودفنوه بأقبيتهم تبركا به ثم لم يلبثوا أن وجدوه فى الكهف على حاله، يحدث بذلك ثقات أهل النواحى، ويقال إنه من الحواريين. ذكر محمد بن يوسف فى كتابه أن هذا القتيل فى شق جبل بشرقى عين أو بان، وهذه العين عظيمة بين مدينة مرماجنة وبين مدينة سبيبة، وذكر أنه يخيل لرائيه أنه كما ذبح من يومه وإنه هناك من قبل فتح إفريقية ولم يذكر أمر نقله ودفنه. وقد ذكر المسعودى رحمه الله، هذا القتيل والله أعلم بحقيقة أمره.\nمدينة تهودة : بالقرب من بسكرة مدينة تهودة وهى مدينة كبيرة قديمة أزلية عليها سور عظيم مبنى بالحجر الجليل، ولها رياض كبيرة ولها أرباض كثيرة يدور بجميعها خندق، ولها نهر كبير ينصب إليها من جبل أوراس، فإذا كانت بينهم وبين أحد حرب، وخافوا النزول إليهم أجروا ماء ذلك النهر فى الخندق المحيط ببلدهم فامتنعوا منه. وهى كثيرة البساتين والزرع والنخل وجميع الثمار. وفى هذه المدينة خبر مشهور عن رسول الله - صلى الله عليه وسلم -، يروى عن شهر بن حوشب أن النبي - صلى الله عليه وسلم - نهى عن سكنى هذه البقعة الملعونة التى يقال لها تهودة؛ وقال له سوف يقتل بها رجال من أمتى على الجهاد فى سبيل الله ثوابهم كثواب أهل بدر وأهل أحد، والله ما بّدلوا حتى ماتوا. وكان شهر بن حوشب يقول:\nوا شوقاه إليهم، وقال شهر سألت جماعة من التابعين عن هذه الصحابة التى ذكرها رسول الله - صلى الله عليه وسلم -، فقالوا ذلك عقبة بن نافع وأصحابه قتلهم البربر والنصارى بمدينة يقال لها تهودة، فمنها يحشرون يوم القيامة وسيوفهم على عواتقهم حتى يقفوا بين يدى الله تعالى. وروى أبو المهاجر قال: قدم عقبة بن نافع مصر وعليها عمرو بن العاص فى خلافة معاوية بن أبى سفيان فنزل منزلا من بعض قرى مصر ومعه جماعة من أصحاب رسول الله - صلى الله عليه وسلم - فيهم عبد الله بن عمرو بن العاص فوضعت بين أيديهم سفرة فيها طعام فلما تناولوا من الطعام، ضربت حدأة على ما بين أيديهم من الطعام فأخذت منه عرقا، فقال عقبة اللهم دق عنقها، قال وأقبلت منقضة حتى ضربت بنفسها الأرض فأندقت عنقها، فأسترجع ابن عمرو فسمعه عقبة يترجع فقال: ما لك يا أبا عبد الله، فقال بلغنى أن قوما يغزون إلى هذه الناحية فيستشهدون بها جميعا، فقال عقبة اللهم أنا ومنهم، وكان مستجاب الدعوة. قال ثم إن عقبة بن نافع خرج فى أيام يزيد بن معاوية على جيش كبير غازيا إلى بلاد المغرب، فمر على عبد الله بن عمرو بمصر فقال له:\n\xabيا عقبة لعلكم من الجيش الذي يدخل الجنة\xbb ، قال أبو المهاجر فافتتح عقبة بلاد المغرب حتى وصل إلى أقصاها وعلى ضفة البحر المحيط، وقد ذكرناها.\nويقال إنه أدخل فرسه فى البحر حتى بلغ تلبيب سرجه، وقال اللهم إنى\nأطلب السبب الذي طلب عبدك ذو القرنين، فقيل له يا ولى الله وما السبب الذي طلب، قال ألا يعبد فى الأرض إلا الله وحده، وانصرف إلى إفريقية.\nفلما دنا منها تفرق أصحابه عنه فوجا فوجا، فلما وصل إلى مدينة طبنة من نظر الزاب، أذن لسائر جيشه وبقى فى عدة يسيرة من أصحابه، وقد كان فى دخوله بلاد المغرب خطر على مدينة تهودة وعلى مدينة بادس، فرأى فيها قوة كثيرة من النصارى والبربر، وكانت فى ذلك الوقت أعظم مدن المغرب. فلما رجع قال أمر على مدينة تهودة وبادس، أعرف ما فيهما من القوة والجيش، فلما انتهى إلى مدينة تهودة اعتمده كسيلة بن أقدم وكان أميرها فى جيوش من الروم، وقد كان سمع تفرق جيش عقبة عنه، وأقبلت عليه عساكر من البربر، فلما رآهم عقبة وأصحابه كسروا أجفان سيوفهم ورجعوا إليهم فقاتلوا حتى قتلوا جميعا رحمهم الله؛ وقبر عقبة اليوم بمدينة تهودة على مقربة منها بمرحلة.\nمدينة بادس : وهى مدينة كبيرة، لها حصنان وأرباض واسعة وبسائط كثيرة ومزارع جليلة يزدرعون فيها الشعير مرتين فى السنة على مياه سائحة ونخل كثير وجميع الفواكه والثمار. وهى مدينة قديمة فيها آثار للأولين ولها مياه وعيون كثيرة، وبالقرب منها قيطون بياضة وهو أول بلاد سماطة، ومنه تفترق الطرق إلى بلاد السودان وإلى القيروان وإلى بلاد الجريد وطرابلس وغيرها. وقيطون بياضة قرية كبيرة كثيرة النخل فيها تجتمع الرفاق، ومنها تخرج إلى جميع البلاد، وهى آخر بلاد الزاب.\nذكر المغرب الأوسط\nوفيه مدن كثيرة، وقاعدتها مدينة تلمسان، وحّد المغرب الأوسط من وادى مجمع وهو فى نصف الطريق بين مدينة مليانة ومدينة تلمسان بلاد تازا من بلاد المغرب فى الطول، وفى العرض من البحر الذي على ساحل البلاد التى ذكرنا فى البلاد الساحلية، مثل مدينة وهران ومليلة وغيرها من البلاد الساحلية إلى مدينة تنزل ، وهى مدينة فى أول الصحراء وهى على الطريق إلى سجلماسة.\nمدينة تلمسان : مدينة عظيمة قديمة فيها آثار كثيرة أزلية تنبئ أنها كانت دار مملكة لأمم سالفة، وهى فى سفح جبل أكثر شجره الجوز، وكان لها ماء مجلوب من عمل الأوائل من عيون يسمى بوريط، بينها وبين المدينة أميال؛ ولها نهر كبير يسمى سطفسيف. وكانت تلمسان دار مملكة زناتة وحواليها قبائل كثيرة من زناتة وغيرهم من البربر. وهى كثيرة الخصب رخيصة الأسعار كثيرة الخيرات والنعم، ولها قرى كثيرة وعمائر متصلة ومدن كثيرة ترجع إلى نظرها.\nوفى الجنب من مدينة تلمسان قلعة منيعة كثيرة الثمار غزيرة المياه والأنهار ويتصل بها جبل تاورناية، وهو جبل كبير معمور فيه القرى الكثيرة والعمائر المتصلة.\nوفى الجنوب من مدينة تلمسان قرية كبيرة تسمى باب القصر، فوقها جبل يسمى البغل، كثير الخصب والعمارة ينبعث تحته نهر سطفسيف ويصب فى بركة\nعظيمة منقورة فى حجر صلد من عمل الأولين فيسمع لوقوعه فى تلك البركة خرير شديد هائل على مسافة أميال، ثم يخرج من تلك البركة بحكمة مدبرة إلى موضع يسمى المهماز ، فيسقى هناك مزارع وأولاجا كثيرة تسمى أولاج الجنان ؛ وتلك المواضع من أجمل بقاع تلك البلاد؛ ثم يصب فى نهر أسر ثم يصب فى نهر ثافي وهو النهر الذي يتصل بمدينة أرشقول فى البلاد الساحلية. ومدينة تلمسان مدينة علم وخير ولم تزل دار العلماء والمحدثين.\nوكان هذا المغرب الأوسط قد تملكه العلويون من بنى إدريس وأمرهم مشهور، وتملكوا بلاد الأندلس وتسموا بالخلافة.\nمدينة وجدة : وهى مدينة كبيرة مسورة قديمة أزلية، كثيرة البساتين والجنات والمزدرعات، كثيرة المياه والعيون طيبة الهواء جيدة التربة، يمتاز أهلها من غيرهم بنضارة ألوانهم وتنعم أجسامهم. ومراعيها أنجع المراعى وأصلحها للماشية، يذكر أنه يوجد فى الشاة من شياههم مائتى أوقية شحما، ويصنعون من صوفها أكسية ليس لها نظير فى الجودة مثل العبيدى، يساوى الكساء الجيد منها دينارا وأزيد. وعلى مدينة وجدة طريق المار والصادر من بلاد المشرق إلى بلاد المغرب وسجلماسة وغيرها.\nمدينة أجر سيف : مدينة كبيرة لها بساتين كثيرة وهى على نهر ملوية وهو نهر كبير من الأنهار المشهورة، وكانت أجر سيف قرية كبيرة على نهر ملوية حتى خرج الملثمون من الصحراء فنزلوها ومدنوها، وبنوا عليها سورا من طوب.\nومن مدن المغرب الأوسط المشهورة ، مدينة تاهرت : وهى مدينة مشهورة قديمة كبيرة، عليها سور صخر، ولها قصبة منيعة على سوقها تسمى المعصومة. ومدينة تاهرت فى سفح جبل يسمى قرقل، وهى على نهر كبير يأتيها من تاحية المغرب، يسمى منية ، ولها نهر آخر يجرى من عيون تجتمع يسمى تانس، [ومنه] تشرب أرضها وبساتينها، وكان لها بساتين كثيرة فيها جميع الثمار، وفيها سفر جل يفوق سفرجل جميع البلاد حسنا وطعما ورائحة. وبلد تاهرت شديدة البرد، كثيرة الغيوم والثلج، قال أبو بكر ابن حماد يصفها :\nما أصعب البرد وريعته ... وأظرف الشمس بتاهرت\nتبدو من الغمام إذا ما بدت ... كأنها تنشر من تحت\nنفرح بالشمس إذا أشرقت ... كفرحة الذمى بالسبت\nويقال إن رجلا من أهل تاهرت حج فرأى توقد الشمس بمكة فقال لها وقد أحرقته: احرقى ما شئت فو الله إنك بتاهرت لذليلة.\nوقرب هذه المدينة قلعة هوّارة : وهى قلعة منيعة فى جبل خصيب فيه بساتين وثمار وأشجار ومزارع، وأعناب، وتحتها فحص طوله نحو ميلا يشقه نهر سيرات ويسقى أكثر أرضه، يسمى ذلك الفحص سيرات بأسم النهر. ونهر سيرات نهر كبير مشهور يقع فى البحر عند مدينة أزواوا، وهى مدينة قديمة رومية. وفحص سيرات يسكنه قبائل كثيرة من البربر،\nومطغرة وغيرهم من قبائل زناته، وزناته تتشعب على قبائل كثيرة، وبلادهم واسعة يخالطهم من جهة إفريقية بنو زغبة من العرب من بنى هلال بن عامر، ومن جهة المغرب بلاد مسوفة، وهم القبائل كثيرة من صنهاجة، يسكنون بتلك الصحراء لا يستوطنون بلدا، وإنما عيشهم على اللبن واللحم، وهم خلق كثير. وفى صحارى بلادهم جبل عظيم يعرف بقلقل وهو كثير الخصب والعيون والأنهار، وفيه آثار عمائر كثيرة، وبيوت محصنة وقرى واسعة لا أنيس بها ولا يسكنها خلق، ويقال إن الجن أخلت تلك العمائر والبلاد. ويرى فى تلك الصحارى بالليل نيران الجن، ويسمع عزفهم وغناؤهم وهم كثيرا ما يختطفون الأناس ويحملونهم معهم وربما يفلت الإنس من بينهم فيرجع إلى أهله فيحدث بما رأى عندهم، وهذا متعارف. ويقال إنهم يبدلون أولاد الإنس، ولذلك يقول أهل إفريقية: يا مبدول، وقد ذكرنا السر فى ذلك. وبقرب تلك البلاد أرض فجيج، وهى بلاد خصبة، وفيها نخل كثير وتسكنها أمم شتى.\nوللمغرب الأوسط مدن كثيرة قد ذكرنا أكثرها فى البلاد الساحلية، وهى كثيرة الخصب والزرع كثيرة الغنم والماشية، طيبة المراعى ومنها تجلب الأغنام إلى بلاد المغرب وبلاد الأندلس لرخصها وطيب لحومها.\nذكر بلاد المغرب\nفيه مدن كثيرة، وأقطار واسعة، وعمائر متصلة، يحد بلاد المغرب من آخر المغرب الأوسط إلى بلاد تازا، إلى آخر بلاد المغرب على ساحل البحر الكبير الداخل من البحر المحيط عند مرسى أزّمور طولا. وأما عرضا من بلاد طنجة وسبتة إلى بلاد ملوية وأحوازها، وهو أول بلاد سجلماسة إلى الصحراء، وآخر بلاد المغرب.","4-1":"وقاعدة بلاد المغرب مدينة فاس- كلأها الله : هى أعظم مدينة من مصر إلى آخر بلاد المغرب، ومدينة فاس مدينتان كبيرتان مفترقتان، يشق بينهما نهر كبير يسمى بوادى فاس، يدور عليها سور عظيم. وبين المدينتين قناطر كثيرة، وتطرد فيها جداول ماء لا تحصى، تخترق كلتى المدينتين تسمى بالسوانى لابد لكل دار من ديار المدينتين منها. وفيها عيون كثيرة لا تحصى عددا، وفيها من أرحية الماء نحو رحى، وهى فى المزيد، وربما وصلت ٤٠٠؛ والنهر الذي يخترق مدينة فاس ينبعث من عين عظيمة لها منظر عجيب، فيها نحو ال فوارة، فى دائرة، يجتمع منها هذا النهر الكبير، بينها وبين المدينة نحو أميال فى بسيط من الأرض، يكاد لا يتبين جرى الماء فيه لاستواء أرضه.\nومدينة فاس محدثة، أسست عدوة الأندلس فى سنة [- ٨٠٨] ، وعدوة القرويين فى سنة [- ٨٠٩] فى ولاية إدريس بن إدريس الفاطمى؛ ومن ذريته بفاس إلى اليوم ونحن فى سنة [- ١١٩١] . ومدينة فاس اليوم فى نهاية العمارة والصلاح، قد بنيت أكثر جناتها الملاصقة لها دورا، وأضيفت إليها.\nوفيها اليوم جوامع للخطبة: جامع عدوة الأندلس، وهو جامع كبير متقن البناء، يقال إن ابن عامر زاد فيه، وجامع عدوة القرويين، جامع كبير أكبر من جامع الأندلس، وزيد فى هذه المدة فى هذا الجامع باب كبير مشرف جميل المنظر، [و] من جهة الجوف سقاية متقنة البناء ملاصقة له، ماؤها من الوادى، وجلب لها ماء عين هو فى أيام الحر فى نهاية البرودة، وفى أيام البرد فيها بعض الحرارة. وكذلك صنعت فى جوف جامع القرويين سقاية متقنة البناء، ومياه جارية مع عتبة الباب الجوفى ، وفوارة فى بيلة مرتفعة نصف قامة داخل\nالصحن ، وزيد فيه من جهة الغرب باب كبير، مرتفع البناء عالى السناء يسمى باب النجارين ، كل ذلك فى حدود سنة [- ١١٩١] ، فكملت منافع هذا الجامع المكرم وشرفت حومته بما شرفه الله تعالى به. وكذلك بقصبة السلطان جامع شريف معظم فيه الخطبة، وأحدثها فيه هذا الأمر العزيز- أدام الله اعتلاءه- لأن القصبة منحازة عن البلد بسور، فوجب أن يكون فيها جامع وفى كل عدوة شريعة لخطبة العيدين. ومدينة فاس كثيرة الخصب والرخاء، كثيرة البساتين والمزدرعات والفواكه، وجميع الثمار، ولها أقطار واسعة متصلة العمائر. وعدوة القرويين من هذه المدينة أكثرها بساتين وأشجار ومياه وعيون من عدوة الأندلس، وكلاهما خصبة عظيمة القدر، جليلة الخطر ويقال إن رجال عدوة الأندلس أشجع وأنجد من رجال عدوة القرويين، ونساؤهم أجمل من نساء القرويين، ورجال عدوة القرويين أجمل من رجال عدوة الأندلس. ويقال إن بعدوة الأندلس تفاح حلو يعرف بالأطرابلسى، جليل حسن الطعم والرائحة، يصلح بها ولا يصلح بعدوة القرويين. وكذلك بعدوة القرويين أترج جليل، يجود بها ولا يجود بعدوة الأندلس، وكذلك سميد عدوة الأندلس أطيب من سميد عدوة القرويين. وهذه المدينة قصبة بلاد المغرب، بل وبلاد المشرق والأندلس، لا سيما فى هذا الأمر العزيز- أيد الله دوامه- ومنها يتجهّز إلى بلاد السودان وإلى بلاد المشرق، ومنها يحمل النحاس الأصقر إلى جميع الآفاق. قال الناظر هذه المدينة العظيمة، لما كانت على هذا الوضع المتقدم، وفاضت عليها بركة الواضع لها، وهو إدريس بن إدريس العلوى الفاطمى رضه، ترتب على هذا اتساع مكاسب أهلها، ورغد عيشهم، وكثرة تنعمهم، لجمال المدينة، وعظم حماماتها وكثرتها، وهى أصل التنعيم. قال الشاعر:\nإذا زفر الحمام، واشتد غيضه ... وهاجت لو اعيج به وحميم\nرأيت نعيما فى الحميم وراحة ... وذاك غريب فى الجحيم نعيم\nفعطفت نفوس أربابها، وشمخت أنوفهم، وكبرت هممهم. وكان فيها من الولاة الملثمين رجال عظماء، عقلاء فضلاء، بادروا إلى مخاطبة الخليفة أمير المؤمنين رضه ، وتساعدوا مع الوالى المتصرف بها ، فأدخلوا الموحدين أعزهم الله، يوم الاثنين فى العشر الأول من ذى حجة سنة [٢٣ مايو ١١٤٥] ، وسلمت لهم أملاكهم وأموالهم، ولم تزل أحوالهم تنعم، وأموالهم تتزايد مع الأمن والدعة والسكون فى ظل أمن هذا الأمر العالى بهدى الله. ومن شأن النفوس استدعاء الخيرات لذواتها، وجلب المكاسب والمنافع والمحاماة عليها، والرغبة فى تحصيلها، وهذا كله من دواعى الشح ، والبخل، والمنع، وقلة الجود، وترك البذل، ولو كان الجود موجودا مع استجلاب المنافع الجسمانية، لما تمكن تحصيلها لطالبها، للمتابعة اللازمة بين الضدين. فلما أحس بهذا من له نباهة، وخاصة الأدباء أظهروا أساليب القوم وأفشوها وخلدوا فيهم عجائب القبائح، مثلما فعل أبو بكر البكى عفا الله عنه، فمن أعجب ما حكى الشيخ العالم الصوفى الزاهد أبو الحسن بن حرزهم رحمة الله عليه، عتبه على ما خلده فيهم من القبائح، فأطرق البكى ساعة وأنشده.\nرأيت جنان عدن فى منامى ... وحور العين فى أسنى لباس\nفقلت بما أحصل بعض هذا ... فقال إذا هجوت لأهل فاس\nفدع عنك الصلاح وكل بر ... فهجوهم يؤمن كل باس\nفانظر يا أخى تحديه وتهديه إلى استنزال الشيخ الزاهد بذكره لجنان عدن، وحور العين، إلى أن أصغى له حتى دس فى سمعه هذه الإبرة، وسرت إلى فهمه هذه السمعة الفاسدة، ولو كان عمل الشرّ مهلكا لفاعله لمجرد لهلك البكى لحينه بأقل منظوماته فيهم ، لأن نفوس أهل المغرب مجبولة على الاستنصار، وقيل الحقد مغربى . وعلى الحقيقة فلا يجب أن يعاب أحد بشىء وضع فى جبلته وإنما يعاب المرء بما يحمله عليه نظره السيئ الفكرة وتخلقه العقربى الكسبى. فهؤلاء قوم وضعوا فى مدينة عظيمة النعيم، رغدة المعايش، ومن شأن النفوس جلب المنافع لذاتها، وتحصيل شهواتها ولذاتها، فهم يتأبدون على التحصيل لجميع منافعهم الشهوانية الجسمانية، فمن كان مثلهم طلبهم بأن يسهموه منها وقدمنا [أن] المنع الجبلى فى طباع البشر، كما فى دفع المطالب له، فلزم طرده وزجره، فنتج من هذا تخليد هذه الشناعات ، وقبلتها النفوس المناسبة لها فخلدت، ولو كان الذي يطلبهم غير مثلهم، لما عرج ولا ألتفت إليهم، وهو كما قيل:\nحسدوا الفتى إذ لم ينالوا سعيه ... فالناس أعداء له وخصوم\nكضرائر الحسناء قلن لوجهها ... حسدا وبغيا إنه لدميم\nوذكرنا أنه كان فى الدولة اللمتونية رجال فضلاء، عقلاء علماء حلماء، وشهرتهم فيها أغنت عن ذكرهم . لكنى أردت أن أذكر شيئا من المدح، وأوصاف المدح والخير، وشيئا من الذم وأوصاف المذمومين، فمن محبيهم أبو بكر البكى، فهو ممن مدحهم، والجوزى، وغيرهم من الأحباء؛\nوممن هجاهم كثيرا وأكثرت الرواة لذلك. وقد قدمت السبب فى ذلك أن من شأن النفوس استدعاء الخيرات لذواتها، وجلب المكاسب والمنافع، والمحاماة عليها، والرغبة فى تحصيلها، وهذا كله من دواعى البخل والمنع وقلة الجود، وترك البذل. قال الشاعر:\nقوم إذا أكلوا أخفوا كلامهم ... واستوثقوا برتاج الباب فى الدار\nقوم إذا استنبح الأضياف كلبهم ... قالوا لأمهم بولى على النار\nقال المؤلف، وموضع وادى فاس بوادى سبو على أميال من المدينة . وهذا الوادى نهر عظيم من أعظم أنهار بلاد المغرب، ومنبعه من جبل فى بلاد بنى وارتين ، ورأس العين فى بئر غامضة يهاب الدخول فيها، وهى دهسة عظيمة لا يدرك لها قعر . وللبربر المجاورين لذلك الموضع تجارب منها أن المريض إذا أرادوا أن يعلموا هل هو يستريح أو يموت، حملوه لرأس العين بذلك الموضع المهول، فيغطسونه فيه حتى يقرب أن يطفى، ثم يخرجونه، فإن خرج على فمه دم فيستبشرون بحياته، وإن لم يخرج من فمه دم، أيقنوا بهلاكه؛ وهذا عندهم متعارف لا ينكر.\nقال الناظر، ويتصيّد فى هذا الوادى الشابل الكثير ، ويطلع إلى رأس العين أو قرب منه، ويدخل فى هذا الوادى الحوت الكثير، ويتصيد فى بعض الأحيان البورى الكبير ؛ وذكر الثقات أنه بيع واحد ب درهما ، ورطل كبير منه بدرهم ونصف. ويصل إلى المدينة الحوت الكبير المسمى عندهم بالقرب يحمله الحمار؛ وأخبرنى الثقة أنه عاين لبيسا\nتصيد فيه، زنته رطلا ، ونازعنى فى القرب والشولى فغلبته .\nوأخبرنى الثقات أنه كان\xbb\nبمدينة فاس ومكناسة الحوت الذي يسمى بالشولى، وهو ألذ ما يوجد من أنواع السمك، تصنع منه الألوان بأصناف البقل، فلا تشم له رائحة سمك. ولو كان هذا النهر يخرج فى البطاح، لكانت البلاد التى يسقيها أشرف البلاد وأخصبها، وما أسهل خروجه فى بعض المواضع لو تنبه له الأمر العالى، وهذا لابد منه؛ وهو عنوان فتح ديار مصر، فنيل المغرب مفتاح نيل المشرق، فيظهر العجائب، ونيلها بعد له قيوم .\nقال المؤلف، وبوادى سبو فوق فاس نحو مسيرة يوم، مضيق ما بين جبلين، يسمى ذلك الموضع بتاغيت، معناه بلسانهم الحق ، وذلك المضيق نحو مسيرة يومين، وكان من يسكن بقرب تلك الحوافى، إنما يعبر الوادى فى زنبيل معلق بين الجانين فى حبل قد شد طرفاه فى الحافتين، يسع ذلك الزنبيل نفسين وثلاثة، وعلى ذلك المعبر حبل من الضفتين جميعا، فإذا دخل الزنبيل جذبه أهل الضفة الأخرى إليهم، وبين الزنبيل وبين الماء مهوى بعيد. قال الناظر، ورأيت مضيقا فى وادى وانسيفن بين معدن عرام وبين قلعة مهدى ببلد فزاز ، ينحدر الوادى كله فى سعة بلاط قدره شبرا أو نحوها، وعليه قنطرة محدثة وعليها لوح كبير؛ وهذا الوادى هو المعروف بأم ربيع، وهو مثل وادى سبو، ولو عاينه أهل الأمر، أدام الله نصرهم، لأحدثوا عليه قنطرة على قوس واحد مثل قنطرة السيف المشهورة . وبمثل هذه الآثار تفتخر الملوك، فهى من أعظم منافع البشر. قال الناظر، وبالقرب من مدينة فاس غربى عدوة القرويين، موضع يعرف بالشيخ يقال إنه ساخ بأهله.\nوبالقرب منها أيضا قلعة يقال لها قلعة زيد، فيها مسجد يقال إن عقبة بن نافع بناها، وفيها شجر زيتون، يذكر من يسكن بقرب ذلك المسجد أن كل دابة من حمار أو ثور أو جمل أو غير ذلك من الدواب، إذا دخله وأكل من ورق الزيتون مات؛ لا يشكون فى ذلك، وهو عندهم متعارف.\nوبين مدينة فاس ومدينة تلمسان، مسيرة عشرة أيام فى عمائر متصلة. وقد ذكرنا أن آخر بلاد المغرب الأوسط وأول بلاد المغرب بلاد تازا، وهى جبال عظيمة حصينة كثيرة التين والأعناب وجميع الفواكه، وأكثر شجرها الجوز، وهو يجود بها كثيرا. ويسكنها قبائل من البربر يعرفون بغياتة وقد بنى ببلاد تازا فى هذه المدة مدينة الرباط ، وهى مدينة كبيرة فى سفح جبل مشرفة على بسائطه، يشقها جداول المياه العذبة، وعليها سور عظيم، وقد بنى بالجير والحصى، يبقى مع الدهر. وهى فى فسحة على أميال ما بين جبال ينصب إليها من تلك الجبال مياه كثيرة، وأنهار تسقى جميع بساتينها فى أعلاها وأسفلها، ولها نظر كبير، كثير الزرع وجميع الفواكه والخيرات، ولا أعلم ببلاد المشرق والمغرب بلدا أخصب منها ولا أكثر فوائد. وأسست هذه المدينة من نحو سنة ، فى حين توجه الخليفة رضه إلى فتح بلاد بنى الناصر وشيدت سنة [- ١١٧٢- ١١٧٣] مدينة الرباط على الطريق المار من بلاد المغرب إلى بلاد المشرق، وتسمى مكناسة تازا. ومكناسة قبيلة كثيرة من البربر سكنوا هناك، يسمى الموضع بهم. وتحت مدينة الرباط بنحو الميل بركة كبيرة يذكر أنها تتصل بالبحر من تحت الأرض، وقيل إنه رئى فيها فى بعض الأزمان دابة من دواب البحر؛ ويقال إن ماء هذه البركة يحمر فى بعض الأوقات حتى يعود كالدم، أخبرنى بذلك رجل من الثقات\nالساكنين عليها. قال المؤلف، ومن الجبال المشهورة ببلاد المغرب فازار، وهو جبل كبير تسكنه أمم كثيرة من البربر، ويطردهم الثلج عنه فينزلون إلى ريف البحر الغربى. وهم أهل كسب من الغنم والبقر والخيل؛ وخيل هذا الجبل من أعتق الخيول لصبرها وخدمتها، وهى مدورة القدود حسنة الخلق والأخلاق؛ ولحوم غنمه أطيب اللحوم وكذلك أسمانها. وفى هذا الجبل أنواع النبات من العقاقير التى تنصرف فى العلاجات الرفيعة، وفيه خشب الأرز العتيق العالى، وهى مأوى القردة ، عاينتها تثب من الأرزة لأخرى وهى فى الجو الأعلى. وفى هذا الجبل قلعة كبيرة تنسب للمهدى بن توالى الجيفشى ، وهى فى نهاية المنعة، أقام عليها عسكر اللمتونيين أعوام، وبناؤها بالألواح. وإليها كان تغريب المعتمد بن عباد ، فقال متمثلا حزينا بنقض العهود لبلد أهله يهود، وبناؤه عود، وجيرانه قرود، وكان اليهود فى ذلك التاريخ أكثر سكانه ، لأنهم سوقة فيلجؤون للحصن حيطة على سلعهم.\nومن نظر مدينة فاس إلى جهة الغرب مدينة مكناسة الزيتون :\nوهى أربعة مدن وقرى كثيرة متصلة بالمدن والحصون. المدن منها تاقرارات وتفسيره المحلة، وهو محدث البناء وهو مشرف على بطاح وبقاع مملوءة نفيضات الثمار، وأكثرها الزيتون فسميت به. وهذه المدينة عليها سور كبير وأبراج عظيمة، وهى مدينة جليلة فيها أسواق حفيلة، وأحدث فيها الأمر العالى- أيد الله دوامه- بحائر عظيمة فى نهاية من الاتساع، وجلب لها ماء نهرها، وأمر بغرسها زيتونا وكروما،\nدار الأمة وهى الآن معلومة بها، ثم اختط سورها ولده على سنة [- ١١٢٠] ؛ وفتحها الخليفة أمير المؤمنين رضه يوم السبت بعد صلاة الظهر من شوال سنة [- مارس ١١٤٧] . وعلى أميال منها وادي تنسيفت، منبعه من بلد دمنات ، يصب فيه وادى وريكة ووادى نفيس وأودية كثيرة، ومصبه فى ساحل رباط جوز ويدخله الشابل الكثير الطيب.\nوهى مدينة طيبة التربة كأنها غطاء من حجر على حجر، عذب ماؤها قريب من قامة أو قامتين؛ وبساتينها تسقى من آبار منتفد بعضها ببعض حتى تخرج على وجه الأرض. وبينها وبين درن نحو ال ميلا، وهى كثيرة الزرع والضرع تحرثها دكّالة وجنتها نفيس، وحولها من البساتين والجنات التى يسمونها البحائر لعظمها ما لا يحصى كثرة؛ وإنما بناها واضعها ليملك منها جبل درن لكثرة من يعمره، وكان خروج هذه الشرذمة الصحراوية لقتال براغواطة الكفار المرتدين عن ديانة الإسلام.\nوكان إسلام قبائل الصحراء سنة [- ١٠٤٣] وخروجهم سنة ٤٥٠- ١٠٥٨] أو نحوها فقتل زعيمهم الذي أخرجهم ببلد برغواطة بموضع يسمى تيلمت، وبنى على قبره مسجد وولى بعده أبو بكر بن عمر اللمتونى المحمدى وبقى إلى سنة [- ١٠٦٥] قبل أن ينخلع ويولى يوسف بن تاشفين، ويطلق زوجته زينب بنت ابراهيم النفزاوى . ولم يكن فى زمانها أجمل منها ولا أعقل ولا أظرف، فتزوجها بعده يوسف وبنى لها مراكش، وسار أبو بكر بن عمر إلى الصحراء فقاتل السودان فرشقه سهم فمات. ومدينة مراكش اليوم من أعظم مدن الدنيا بهجة وجمالا بما زاد فيها الخليفة الإمام وخليفته أمير المؤمنين أبو يعقوب وخليفتهما أبو يوسف رضهم، فإن الخليفة الإمام بنى فيها جامعا عظيما ثم زاد فيه مثله أو أكثر فى قبلته؛ كان قصرا، ورفع بينهما المنار العظيم الذي لم يشيد فى الإسلام مثله، وأكمله ابنه وخليفته أبو يعقوب رضه. وجلب الخليفة الإمام المياه من أودية درن وغرس بحيرة عظيمة بغربى المدينة قبل نفيس دورها أميال، وبنى فيها\nوخارجها صهريجين عظيمين كنا فى تلك المدة نعوم فيهما فلا يكاد القوى منا يقطع الصهريج إلا عن مشقة، وكنا نتفاخر بذلك. وأحدث الخليفة بعده ابنه أبو يعقوب رضه بحائر مثلها فى الغرس بل أجمل، وجلب لها المياه وأخذها فى صهاريج أعظم من المتقدمة، وزاد فى قبلة المدينة حصنا أنفذه الآن ابنه الإمام الخليفة أبو يوسف رضه، وزاد عليه مدينة أخرى تقارب الأولى فى دورها؛ وكانت بحائر عظيمة فبناها قصورا وجامعا وأسواقا وفنادق، وجلب التجار إلى قيسارية عظيمة لم يبق فى مدن الأرض أعظم منها، وأمر بعمارتها أول سنة [١١٨٩] . ومدينة مراكش أكثر بلاد المغرب جنات وبساتين وأعناب وفواكه وجميع الثمرات، وكانت قبل ذلك يطير الطائر حولها فيسقط من العطش والرمضاء، وأكثر شجرها الزيتون ففى مراكش اليوم من الزيتون والزيت ما تستغنى به عن غيرها من البلاد وتمير بلادا كثيرة، وكان زيتها قبل اليوم دهن الهرجان لأنه بتلك البلاد كثير جدا. وزيتون مراكش أكثر من زيتون مكناسة وزيتها أرخص وربما أطيب.\nومما شرف به سيدنا ومولانا أمير المؤمنين أبو يوسف حضرته المكرمة رضه أن أرسل فى وسط المدينة ساقية ظاهرة ماؤها ماء قصره المكرم، تشق المدينة من القبلة إلى الجوف، وعليها السقايات لسقى الخيل والدواب واستقاء الناس، فهى اليوم أشرف مدن الدنيا وأعدلها هواء. ومن بركاته وضع دار الفرج فى شرقى الجامع المكرم، وهو مارستان المرضى، يدخله العليل فيعاين ما أعد فيه من المنازه والمياه والرياحين والأطعمة الشهية والأشربة المفوهة ، ويستطعمها ويسيغها فتنعشه من حينه بقدرة الله تعالى. وكان فى سنة [- ١١٨٩] قد استدعى العلماء ورواة الحديث وأمر بتدريس حديث النبي - صلى الله عليه وسلم -.\nمدينة فروجة : يسمونها أفروجى، بينها وبين مراكش مرحلة، وهى فى بطحاء كثيرة المياه والفواكه والخيرات. وبالقرب منها مدينة\nتامروت بينهما نحو مرحلتين. وهى مدينة لطيفة طيبة الهواء والماء، ومنها يرقى إلى جبل درن ، ويقال إنه أكبر جبال الدنيا وإنه يتصل بجبل المقطم الذي ببلاد مصر، وفيه قبائل كثيرة من المصامدة، ويقال إنهم من العرب قد دخلوا تلك البلاد وسكنوا تلك الشعاب فى الفتنة الواقعة عند هزيمة ميسرة التى تسمى غزوة الأشراف ، فكان البربر يطلبون العرب فتوغلوا فى تلك الجبال وتناسلوا فهم أهلها على الحقيقة لأنهم أحيوها. قال رسول الله - صلى الله عليه وسلم -: \xabمن أحيا أرضا ميتة فهى له ولعقبه\xbb . وجبل درن أخصب البلاد وأكثرها أنهارا وأشجارا وأعنابا؛ وفيه أمم لا تحصى من المصامدة وأكثر عيشهم إنما هو من العنب والزبيب والرّب، وهم لا يستغنون عن شربه لشدة برد الجبل وثلجه؛ وخلفه بلاد السوس.\nذكر بلاد السوس الأقصى\nوهى مدن كثيرة وبلاد واسعة يسقيها نهر عظيم يصب فى البحر المحيط يسمى وادى ماسة وجريه من القبلة إلى البحر كجرى نيل مصر، وعليه القرى المتصلة والعمائر الكثيرة والبساتين والجنات بأنواع الفواكه والثمار والأعناب وقصب السكر. ولم يتخذ الساكنون على هذا الوادى قط رحى فإذا سئلوا عن ذلك قالوا: كيف يتخذ هذا الماء المبارك فى إدارة الأرحاء، وهم يتطييرون بها . وعلى هذا النهر قرية كبيرة جدا تعرف بتارودانت ، وهى أكثر","4-2":"فزينها أكثر زيت فى جميع المغرب. وبعده زيت النظر الكبير المسمى ببنى بسيل ومغيلة وجهاتها، وفيها اليوم تسع خطب: فى الحصن خطبة، وفى المدينة المسماة السوق القديم خطبة، وفى تاورا خطبة، وفى أولاد عطوش خطبة، وفى أولاد برنوس خطبة، وفى بنى موسى خطبة، وفى بنى زياد، وفى بنى ورزيعة وفى بنى مروان، ونحن فى سنة [- ١١٩١] .\nوهى من البلاد العتيقة المجيدة لو كان بها خدمة لغلاتها، فإن أرضها كريمة، طيبة المزارع كثيرة المياه، وبركات هذا الأمر العالى تعيش الموتى فكيف من فطر على الحياة الطبيعية. وهى من عز بلاد المغرب لها أنظار واسعة، وقرى عامرة، وعمائر متصلة، تشقها الأنهار والمياه السائحة والعيون الكثيرة، وتطحن عليها الأرحية، وتحم بها الحمامات، إلا أن فى صبيانها دعارة وسفاهة لأنهم أكثرهم حاكة يصنعون أشغالهم فى بيوتهم، فإذا خرجوا إلى الفضاء الواسع حركتهم طباعهم الذميمة، فلا يعرفون إلا تجرد الشررة، سيما من كان منهم يجد زعامة فى نفسه أو نجدة فى بدنه. وميتها طعمة للجرذان .\nقال المؤلف، ومن المدن المعمورة والعمائر من فاس إلى طنجة بلد جنيارة : وفيه قرى كثيرة عامرة زرعا وضرعا فى جبل سهل أبيض مثل الطيلسان، ويسمى الجبل الأشهب، وقل ما تخلف أرض جنيارة لا فى خصب ولا فى جدب . سأل رجل أراد أن يقتنى ضيعة ببلاد المغرب شيخا من العارفين، فقال له: عليك ببلد جنيارة فإنها مثل الدجاجة إن أصابها ديك أتت بالديك \xabهـ\xbb ، وإن لم يصبها ديك أتت بالبيض، تحتك بالغبار وتلد. ومنه إلى نهر ردات مرحلة، وهو نهر كبير فى أصل جبل وفى أعلاه.\nمدينة- كرت : وكانت مدينة كبيرة حصينة كثيرة الخير على نظر كبير، يعمرها قبائل من البربر يقال لهم بياتة، وهى اليوم قرية عامرة.\nثم منها إلى مدينة البصرة ، مدينة كبيرة على ربوة مشرفة على بسائط ونظر واسع، كثيرة الزرع والضرع ليس بتلك النواحى أوسع مرعى منها، وبكثرة ألبانها كانت تعرف ببصرة الألبان . وتعرف أيضا ببصرة الكتان، لأن أهلها كانوا يتبايعون بالكتان؛ وكانت تعرف بالحمراء لحمرة تربيتها. وكان عليها سور مبنى بالحجارة والطوب يحمر من بعيد، وكانت لها أبواب. ونساؤها مخصوصات بالجمال الفائق، والحسن الرائق، لم يكن ببلاد المغرب أجمل منهن.\nمدينة قصر صنهاجة : وهى على تل وتحته نهر لكس تدخله المراكب، وتعرف بقصر عبد الكريم، وكان من أشياخ كتامة القاطنين هناك فرأس فيهم وأستوطن ذلك الموضع. وكانت فيه آثار قديمة، فبنى فيه دارا سميت قصرا لعدم القصور بتلك الجهات، وأحدث الأمر العالى فى موضعه فى هذه المدة فندقين عجبين، وتمدن هذا الموضع، وشرف وقصده التجار وأستوطنوه. ومصب واديه فى البحر على ميلا أو نحوها؛ على المدخل حصن كبير قديم يسمى تشمّس قدمنا ذكره . وكان إدريس بن القاسم بن ابراهيم العلوى قد أحيار سمه وأظهره فهو إلى الآن معمور ويسكنه المتعيشون من البحر، وهو كثير الأمراض وبى الهواء وخم الماء، ومنه تشحن المراكب بالزرع.\nقلعة ابن جندوب : وكانت مدينة كبيرة فيها أسواق، ولها جنات وأشجار، وهى كثيرة الزرع والضرع ومنها إلى طنجة وقد ذكرناها.\nقال المؤلف، وهذه البلاد كلها فى هذا الأمر العزيز بحمد الله مشحونة بالعمائر، متصلة المحارث والمزارع فى السهول والجبال، منها جبل زالغ وهو مشرف على مدينة فاس، كان فيه حصن بناه المظفر بن المنصور بن أبى عامر.\nثم إلى عقبة الأفارق، ثم إلى نهر سبو حيث محجة القوافل، وهو نحو ال ميلا فى عمائر متصلة، وقرى حصينة مانعة كثيرة الزرع والضرع، ثم من نهر سبو إلى نهر ورغة إلى قصر كتامة المذكور فى عمائر متصلة. وطريق أخرى على جبل غمارة، وذلك أنك إذا أقمت من وادى سبو، أخذت على يمينك فى عمائر متصلة إلى مدينة تاودا ، وكانت مدينة كبيرة أسسها الملثمون، ليملكوا منها جبل عمارة لتتابع نفاقه عليهم، وكان يسكنها ولاة المغرب منهم بالعسكر. وكانت فى أيامهم معمورة بالمبانى الحسان والقصور المنيعة. وهى على وادى ورغة وحواليها قبائل، وهى على قطر واسع كثير الزرع والضرع، وعليها جبل منيف فيه حصن كبير من بناء الملثمين يسمى أمرجوا، وهو مبنى بالحجارة والجير لا يقدر أحد على هدم شئ منه إلا بالمشقة؛ وفى أعلى الجبل الماء الكثير. وجبل غمارة من أخصب جبال المغرب، وهو من الجبال المشهورة، يسكنه قبائل كثيرة من غمارة وهم أمم لا تحصى؛ وفى هذا الجبل بسائط كثيرة لا تحصى للحرث، ومدن قديمة، وآثار كثيرة للأوائل، تنبئ أن عمارته قديمة أزلية. وطول هذا الجبل مسيرة أيام وعرضه نحو أيام، وهو الآن كثير العمارة تشقه الأنهار والمياه السائحة، ففيه غياض وأودية ومنتزهات لا توجد فى غيره من الأماكن، وهو كثير الأعناب والفواكه\nوالعسل والضرع؛ وفيه جبال قد لحقت بأعنان السماء علوا، وحصون كثيرة تمتنع فيها غمارة، وتنفق على الولاة، بذلك عرفوا حتى كسر الأمر العزيز شوكتهم، وأباد شرارهم واستأصل شأفتهم. ولأهل هذا الجبل مذاهب شتى، وسير مختلفة، وقد تنبأ عندهم إنسان يعرف بحاميم بن من الله ولقب بالمفترى . والجبل الذي تنبأ فيه ينسب إليه وهو جبل حاميم على مقربة من تيطاوان، وأجابه بشر كثير من غمارة، وأقروا بنبوته. ووضع لهم قرآنا بل شريعة أستهواهم برخصها، فرد لهم الصلاة صلاتين عند طلوع الشمس وعند غروبها، يسجدون على ظهور أكفهم . ووضع لهم قرآنا بلسانهم تفسيره: خلنى من الذنوب يا من يخلى النظر ينظر فى الدنيا، خلنى من الذنوب يا من أخرج من موسى من البحر. وفيه : آمنت بحاميم وآمنت بأبى يخلف وهو والد حاميم واسمه من الله، وفيه : آمنت بتاليت ، وكانت عمة حاميم كاهنة ساحرة. وكان لحاميم أخت تسمى دبّو ، وكانت ساحرة كاهنة وكانوا يستغيثون بها فى كل حرب وضيق. وكان حاميم فرض عليهم صوم يوم الخميس كله، وصوم يوم الأربعاء إلى الظهر، فمن أكل فيهما غرم أثوار لحاميم. ووضع لجميعهم صوم يوما من رمضان، وجعل عيدهم فى ثانى يوم فطرهم، وفرض عليهم الزكاة العشر من كل شىء، وأسقط عنهم الحج والطهر والوضوء؛ وأحل لهم أكل أنثى الخنازير وقال لهم إنما حرم قرآن محمد الذكر، وحرم عليهم الحوت حتى يذّكى، وحرم بيض كل طائر . ونظم عبد الله الكفيف الطنجى يهجوه:\nوقالوا افتراء إن حاميم مرسل ... إليهم بدين واضح الحق باهر\nفقلت كذبتم بدد الله شملكم ... فما هو إلا عاهر وابن عاهر\nفإن كان حاميم رسولا فإننى ... بإرسال حاميم لأول كافر\nروى عن عجوز ذات إفك ذميمة ... تقارن فى أسحارها كل ساحر\nأحاديث إفك حاك إبليس نسجها ... يسرّونها كتما وبئس السرائر\nوجهز إليه الناصر المروانى من قرطبة عسكرا، فالتقت معه بأحواز طنجة سنة [- ٩٢٧] فهزم وقتل لعنه الله، وحمل رأسه لقرطبة.\nويقال إنه كان فى بعض جبال مجسكة من بلاد غمارة رجل كان من السحرة المهرة يعرف بأبى كسيّة، وكان أهل موضعه يسمعون منه ولا يعصونه طرفة عين؛ فإن عصاه أحد منهم أو خالفه، حول كساه الذي يلتحف به فيصيب ذلك الإنسان فى ماله أو بدنه أو كليهما صائبة وعاهة، وإن كانوا جماعة أصابهم مثل ذلك، وكان يخيل إليهم كأن برقة تلوح من تحت كسائه. ولبنيه اليوم وعقبه فى تلك الناحية مزية وحظوة على من سواهم.\nومن عجائب غمارة أن عندهم قوما يعرفون بالرقّادة، يغشى على الرجل منهم يومين وثلاثة فلا يتحرك ولا يستيقظ، ولو بلغ به أقصى مبلغ من العذاب حتى يقطع قطعا، فإذا أستيقظ من غشيته كان كالسكران طول يومه لا يتجه لشئ ولا يخبر بشيء، فإذا كان بعد يوم، وصح ، أتى بعجائب وغرائب مما يكون فى ذلك العام من خصب أو جدب أو فتنة أو هدنة، وغير ذلك من الكوائن والأحداث، وهذا عندهم مستفيض مشهور.\nوكان ببلد غمارة المواربة مشهورة متعارفة يفتخر بها نساؤهم ، وذلك أن الرجل إذا دخل بامرأته البكر واربها شبان أهل ناحيتها، فإن رأوها جميلة حسنة احتملوها وأمسكوها عن زوجها شهرا أو أكثر ثم ردوها، وربما فعل ذلك مرارا على قدر جمالها ومقدار الرغبة فيها. ولا يتم إكرام الضيف عندهم إلا بأن يؤنسه بنسائهم الأيامى منهن: يبيت الرجل مع ضيفه أخته إذا كانت ثيبا أو ابنته أو من لم تكن ذات زوج من نسائه. وهم يرغبون فى الرجل الجميل أو الشجاع أن يأخذوا منه نسلا، ولا يتركون ذا عاهة يستقر ببلدهم،\nويقولون إنه يفسد النسل. وبلد غمارة جميل كبير، وكانت لهم فيما سلف شعور طوال يسد لونها كشعور النساء، ويتخذوها ضفائر ويطيبونها ويهتمون بها كثيرا حتى دخل الإسلام بلادهم وتخللها فألجأتهم الضرورة إلى التشمر والتوعر فى الجبال الشامخة فحلقوا رؤوسهم، وورث ذلك الأبناء عن الآباء .\nقال المؤلف، ومن المدن والعمائر من مدينة فاس إلى سجلماسة حرسها الله، مدينة صفروى : وهى مدينة لطيفة قديمة عليها سور، ذات أنهار ومياه جارية ولها جنات كثيرة الفواكه والأعناب، وأكثر شجرها اللوز ومنها يحمل إلى فاس وغيرها. ومنها إلى فاس مرحلة، ومنها إلى تاسغمرت وهو بلد خصب فيه قرى كثيرة وعمائر متصلة، ومنه يدخل إلى بلاد سجلماسة بعد أيام. ولها طريق آخر من قابس إلى لواتة مدين، وهو بلد خصيب على نهر سبو، وله قصبة منيعة، منها إلى فاس مرحلة؛ ثم إلى مغيلة القاط ، وهو حصن كبير له سوق حافلة وجامع، وهو كثير الأنهار ومنه يحمل التين المزبب إلى مدينة فاس وغيرها؛ ومنه إلى مطماطة أمكسور ، وهو بلد كبير على نهر ملوية، كثير الزرع والضرع. ونهر ملوية كبير مشهور فى أنهار بلاد المغرب، وعليه نظر واسع، وفيه قرى كثيرة، وعمائر متصلة تسقى كلها من نهر ملوية، وبعده نظر سجلماسة. وكانت مدينة فاس دار مملكة بنى إدريس العلويين، وملكوا منها بلاد المغرب إلى أقصى بلاد السوس طاعة فى معصية، وكانت فى أيامهم دولة برغواطة الذين تدينوا بديانة الغوى صالح بن طريف البرباطى، وسيأتى ذكره بعد هذا. وملك العلويون بعض بلاد الأندلس، وتسموا فيها بأمير المؤمنين، وخطب لهم فيها بالإمامة .\n[دخول العلويين بلاد الغرب]\nذكر أبو الحسن على بن محمد بن سليمان النوفلى أن إدريس بن عبد الله بن حسن بن الحسن بن على بن أبى طالب رضه انهزم فى وقيعة فخ سنة [- ٧٨٦] ، فاستتر مدة، وألح السلطان فى طلبه وضاقت عليه المذاهب، ورغب فى الهروب من بلاد المشرق فخرج معه راشد، وكان من موالى العلويين، وأصله من البربر ليثويه فى قومه، ويأمن من عدوه. وكان راشد عاقلا شجاعا أبدا، ذا فهم ولطف وحزم، فخرج به فى غمار الحاج وغيرّ زيه وألبسه مدرعة من وحش الثياب وصيّره كالغلام يخدمه، وإن أمره أو نهاه أسرع. فسار به مستخفيا من موضع إلى موضع حتى قربا من بلاد إفريقية، فترك الدخول به فى بلاد إفريقية ، وسار به إلى بلاد البربر حتى انتهى إلى بلاد فاس وطنجة، فنزل به فى مدينة وليلى ، وكانت مدينة رومية قديمة بطرف جبل زرهون فى الغرب منه؛ وتسمى الآن تيسرة. فنزل بها على اسحاق بن محمد بن عبد الحميد الأوربى، وكانت أوربة آن ذاك من أعظم قبائل بلاد المغرب، وكانت لها مدن كثيرة منها مدينة سكوما ، وكانت على مقربة من فاس، وكانت مدينة عظيمة لم يكن بالغرب أعظم منها. يقال إن موسى بن نصير لما دخل بلاد المغرب، نازل مدينة سكوما وحصرها حتى افتتحها عنوة، وأخذ فيها سبيا كثيرا، وكتب إلى أمير المؤمنين الوليد بن عبد الملك بن مروان يقول له: قد بعثت إليك بسبى مدينة سكوما، وهو مائة ألف رأس ؛ قيل فكتب إليه الوليد بن عبد الملك: ويحك أظنها من بعض كذباتك، فإن كنت صادقا، فهذا حشر الأمم؛ وكذلك يقال إنه قتل فيها ما لا يحصى له عدد . وكان اسحاق\nابن محمد الأوربى معتزلى المذهب فوافقه إدريس على مذهبه، وأقام عنده، وأمر اسحاق قبيلته بطاعته وتعظيمه. وكان ذلك فى خلافة هارون الرشيد أمير المؤمنين، فوصله خبره، فغمه ذلك، فشكا ذلك إلى يحيى بن خالد، فقال له أنا أكفيك خبره يا أمير المؤمنين. ثم أرسل إلى سليمان بن جرير الجزيرى وكان رجلا من ربيعة متكلما ممن يرى رأى اليزيدية متعصبا لآل أبى طالب، وكان جلدا شجاعا، أحد شياطين الإنس وكانت له إمامة فى اليزيدية، وهو الذي جمع الرشيد بينه وبين هشام بن عبد الحكم حين ناظره في أمر الإمامة، ولذلك قصة طويلة. قال فأرغبه يحيى بن خالد فى المال ووعده عن نفسه وعن أمير المؤمنين بمواعد عظيمة، ودعاه إلى قتل إدريس، والتلطف فى أمره.\nفأجابه إلى ذلك وأعطاه مالا جزيلا ودفع إليه قارورة فيها غالية مسمومة، ووجه معه رجلا من ثقاته. فانطلق سليمان مع صاحبه، فلم يزالا يتغلغلان فى البلاد حتى وصل إلى إدريس، وكان إدريس عالما برياسة سليمان باليزيدية ، فلما وصل إليه قال: إنما جئتك بنفسى وحملتها على ما حملتها عليه لمذهبى فيكم أهل البيت، فجئتك لا فى حاجة إليك إلا لأنصرك بنفسى؛ فسرّ إدريس بقوله، وقبله أحسن قبول، فأحسن نزله وأكرم مثواه وأنس به. فكان سليمان يجلس فى مجالس البربر ويظهر الدعاء إلى ولد رسول الله - صلى الله عليه وسلم -، ويحتج لأهل البيت كاحتجاجه بالعراق. فأعجب ذلك إدريس منه، ومكث عنده مدة، وهو يطلب الغرة فيه ويرتصد الفرصة فى أمره، فدخل عليه سليمان ومعه القارورة، فلما انبسط إليه إدريس وأخلى له وجهه، قال له سليمان:\nجعلنى الله فداك، هذه القارورة فيها غالية رفيعة أو صلتها معى وأعلم أنه ليس ببلدك طيب فجئتك بها، ووضعها بين يديه؛ ففتحها إدريس وشمها وتخلق بها. وقيل أخرج سكينا، وقطع به تفاحة، وأعطاه النصف الذي يلى الجهة المسمومة من السكين، ثم انصرف سليمان إلى صاحبه وقال له قم، قد تم مرادنا لنا، وقد كان أعد فرسين فركباهما، وخرجا يطلبان النجاة. فلما وصل السم إلى خياشيم إدريس، وتغلغل فى دماغه سقط مغشيا عليه لا يعقل، ولا يدرى من يحتضر به من أهله وحاشيته ما شأنه. قال فبعثوا إلى راشد فجاء مسرعا\nوتشاغل فى معالجته، وتحيروا فى أمره. وقطع سليمان مع صاحبه بلادا كثيرة فى تلك المدة، قيل فبقى إدريس فى غشيته عامة نهاره وليله، تضرب عروقه حتى مات رضى الله عنه. فتبين لهم أمر سليمان بن جرير، قال فركب راشد فى طلبه مع جماعة من أصحابه فجد السير حتى لحقهما وجده، لأن فرسه صبر أكثر من خيل أصحابه فأدركهما؛ فشد عليهما راشد، ففر صاحب سليمان ولم يغن شيئا، فضرب راشد سليمان ثلاث ضربات بالسيف على وجهه ورأسه، كل ذلك لا يصيب مقتلا، مع دفع سليمان عن نفسه، وعجز فرس راشد عن إدراكه. فلما رجع عنه راشد، نزل فعصب جراحاته، وسار حتى لحق بالمشرق. قال أبو الحسن النوفلى: فحدثنى من رآه بالعراق بعد ذلك مكتع اليد. قال النوفلى: كانت مدة إدريس الواصل من المشرق التى أجابته فيها البربر إلى أن مات بوليلى سنة [- ٧٩١] ثلاثة أعوام وستة أشهر.\nقال أبو الحسن: ومات إدريس ولا ولد له وترك جارية من جواريه حبلى، فقام راشد بأمر البربر حتى ولدت الجارية غلاما فسماه باسم أبيه، وقام بأمره، وأحسن تأديبه. وتوفى راشد فقام بأمر الغلام أبو خالد يزيد بن الياس، وأخذ له بيعة البربر سنة [- ٨٠٨] ؛ ثم مشى إدريس بن إدريس نحو فاس فاستوطنها واتخذها دار مملكة. وتوفى إدريس بن إدريس وهو ابن سنة، وكانت منيته بحبّة عنب اختنق بها، فلم يزل مفتوح الفم سائل اللعاب حتى مات.\nوترك من الولد ذكرا، فكان المتولى للأمر من بعده ابنه محمد بن إدريس، فاستوطن مدينة فاس؛ وفرق البلاد على إخوانه، وفعل ذلك برأى جدته كنزة أم إدريس. ويقال إنه خالف عليه بعض إخوانه، وكانت بينهم حروب يطول وصفها. ثم توارث الملك بنو إدريس بالمغرب، يأخذه الخلف عن السلف؛ وجاز منهم إلى جزيرة الأندلس على بن حمود . وكان فيما يذكر يميل إلى الفتوة، فاغتاله فتيان من الصقالبة فى حمام قرطبة فقتلوه ،\nوقتلوا به. وترك من الولد يحيى وإدريس، فولى عهده يحيى وكان صاحب بلاد المغرب: فاس وغيرها، وجعل إدريس بمدينة مالقة. فلما قتل على بن حمود وكان الابنان غائبين، استدعى البربر أخاه القاسم بن حمود، وأدخلوه القصر بقرطبة، وبايعه الناس وخطب له بالخلافة، فوصل الجند إلى ابن أخيه يحيى وهو بالمغرب، فأنف من ذلك لما كان عهد إليه أبوه، فبعث إلى أخيه إدريس بمالقة وجاز إليه فتركه مستخلفا بمدينة فاس وبلاد المغرب، وعبر يحيى إلى الأندلس لطلب حقه عند عمه القاسم. فلما قرب من قرطبة هرب عمه القاسم وبويع يحيى بقرطبة ويسمى بالمعتلى؛ ثم إن البربر اضطربوا فهرب من قرطبة إلى ما لقة، ورجع عمه القاسم إلى قرطبة وتسمى بالمأمون.\nثم أخرجه ابن أخيه يحيى من قرطبة مرة ثانية، فمشى إلى إشبيلية، وسكن بها حتى أخرجه محمد بن عباد؛ فسار إلى شريش، ونزل عليه يحيى، وحصره بها حتى أخذه بها مع بنيه وسجنه. واستوثق الأمر ليحيى بن على حتى قتل سنة [- ١٠٣٦] ، وقام زناتة على أخيه إدريس بالمغرب، وملكوا مدينة فاس وغيرها فسكن إدريس بسبته، فلما وصله موت أخيه يحيى خطب له بالخلافة وتسمى بالعزيز بالله، ثم عبر البحر إلى مالقة، وخطب له بالخلافة فيها، ثم اتصلت الفتن حتى انقطعت دولة بنى إدريس من بلاد المغرب.\nذكر ارتداد برغواطة ومن دخل معهم من قبائل البربر فى الإسلام، والسبب فى ذلك\nقال الناظر، دخل بلاد تامسنا رجل اسمه صالح بن طريف، وأصله من برباط الأندلس يهودى النسب من سبط شمعون، وكان رحل إلى المشرق، وقرأ على غيلان القدرى ورأى من السحر كثيرا، فدخل إلى بلاد تامسنا، فوجد فيها من زناتة قوما جهالا، وكان ذلك سنة [- ٧٤١] . فأظهر الإسلام والنسك حتى استفز عقولهم، فولوه على أنفسهم، فلما ولى شرع الديانة التى أخذوها عنه، وأنا أذكرها.\nقال المسعودى والبكرى وغيرهما من المؤرخين إنه كان يقول إنه صالح المؤمنين الذي ذكره الله فى قرآن محمد. وعهد صالح إلى ابنه إلياس بديانته وعلم شرائعه وفقهه فى دينه، وأمره بألا يظهر الديانة حتى يظهر أمره وينتشر ذكره فيقتل حينئذ من خالفه، وأمره بموالاة أمراء الأندلس. وخرج صالح إلى المشرق ووعد ابنه أنه يرجع فى دولة السابع من ملوكهم، وزعم أنه المهدى الأكبر الذي يكون فى آخر الزمان لقتال الدجال، وأن عيسى بن مريم يصلى خلفه، وأنه يملأ الأرض عدلا كما ملئت جورا.\nوذكر فى ذلك كلاما نسبه إلى موسى، وإلى سطيح الكاهن وإلى ابن عباس وزعم أن اسمه بالعربى صالح وكذلك فى السريانى، وأوربا بالعبرانى وورى ورابا بالبربرى. وتأول قول رسول الله - صلى الله عليه وسلم -: \xabلا نبى بعدى\xbb فأوله بضم الياء من نبى، وقال اسمي لا وأنا نبى بعده. فولى إلياس الأمر بعد خروج أبيه إلى المشرق بدعوة الإسلام وكتم الشريعة التى عهد إليه أبوه خوفا وتقية، ولم يظهر شيئا من ديانته إلى سنة [١] [٧٨٩- ٧٩٠] ، فكان ملكه سنة. فولى بعده ابنه يونس، فأظهر ديانتهم ودعا إليها، وقتل من خالفها إلى أن مات سنة [١] [- ٧٩١- ٧٩٢] ، فولى بعده أبو عفير معاد بن يونس ابن الياس بن صالح بن طريف، وأظهروا ديانتهم واشتدت شوكته، وكانت له وقائع كثيرة فى البربر؛ وكانت له من الزوجات زوجة. ومات أبو عفير سنة [- ٨٤٤- ٨٤٥] وولى ابنه أبو جعفر حفص، ولم يزالوا يتداولون هذه الديانة إلى غزو عبد الله بن ياسين الجزولى إياهم، فملك منهم سبعة وفنيت دولتهم سنة [- ١٠٥٧] . ولما كان أصل هذا الشيخ الملعون من برباط قيل لكل من دخل فى دينه برباطى فأحالتها العرب بألسنتها فقالت برغواطى، فمن أجل هذا سموا برغواطة، وإنما أصلهم زناتة وهم أعلم عباد الله بالسحر مما أخذوا عن أسلافهم.\nوأما الضلال الذي شرع لهم فإنهم يقرون بعد الإقرار بالنبين بنبوة صالح ابن طريف ومن يتولى الأمر من بعده، وأن الكلام الذي وضع لهم وحى من الله لا يشكون فيه؛ ويصومون رجب، ويأكلون رمضان، وأن الفروض عليهم\nخمس صلوات بالليل و صلوات بالنهار؛ وأن الأضحية واجبة فى من المحرم؛ وفى الوضوء غسل السرة والخاصرتين، ثم الاستنجاء ثم المضمضة ثم غسل الوجه ثم غسل العنق والقفا ثم غسل الذراعين من المنكبين وغسل الرأس مرات، ومسح الأذنين ثم غسل الرجلين؛ وبعض صلاتهم إنما يسجدون وبعضها على هيئة صلاتنا. ويسجدون سجدات، ويرفعون جباههم وأيديهم عن الأرض ويضع يده اليمنى على اليسرى ويقولون باسم باكش تفسيره: باسم الله؛ مقر ياكش مقريتجتن، تفسيره: العظيم الله العظيم الأعمال.\nويضعون أيديهم مبسوطة على الأرض طول ما يشتهون، ويقرءون نصف قراءتهم فى وقوفهم، ونصفا فى ركوعهم، ويقولون فى تسليمهم بالبربرية:\nالله فوقنا لم يغب عنه شئ فى السماء ولا فى الأرض، ثم يقولون بعد التسليم:\nالواحد الله، وردام ياكش معناه: لا شئ مثله. ويأخذون فى الزكاة العشر من جميع الثمار ولا يأخذون من المسلمين شيئا؛ ويتزوج الرجل من النساء ما قدر عليه، ولا يتزوج من بنات عمه إلا ما يحلوا من النساء ويطلقون ويراجعون.\nويقتلون السارق الذي عندهم، وعلى من قتل فدية من البقر، ورأس كل حيوان عندهم حرام، والحوت لا يؤكل حتى يذكى، ويرجم الزانى عندهم، كان بإقرار أو بشبهة. والديكة عندهم حرام، والدجاجة مكروهة إذا اضطر إليها. ولا إقامة للصلاة عندهم، ويقتدون فى الأوقات بصياح الديكة؛ ويبصق فى أيديهم فيتلقونه تبركا به ويحملونه إلى مرضاهم فيستشفون به.\nوكان الضلال الذي وضع لهم هذا سورة منسوبة بأسماء النبيين وغيرهم ففيها: سورة آدم وسائر النبيين المشهورين، وفيها سورة أيوب، وسورة يونس وسورة فرعون، وسورة الديك وسورة الحجل، وسورة الجرادة وسورة الجمل، وسورة هاروت وسورة ماروت، وسورة الحشر، وسورة غرائب الدنيا، فيها علمهم؛ وصلوات الله وسلامه على أنبيائه ورسله وملائكته تتجدد إلى يوم الدين.\nذكر كلمات هى استفتاح كتابهم؛ فمما ترجم منه: بسم الله الذي أرسل رسله إلى الناس وهو الذي بين لهم مع أخباره علم إبليس، أبى الله أن يعلم إبليس ما علم الله رسله من شئ، ويقلب الألسن فى الأقولة ليس يقلب الألسن فى الأقولة إلا لا إله إلا الله، بقضائه نطق اللسان الذي أرسل الله بالحق إلى الناس، وبه استقام الحق وأنار. محمد كان حين عاش استقام الناس للدين فلما مات فسد الدين، كذب من يقول إن الحق استقام وليس ثمّ رسول. وهى سورة طويلة، ولولا خروج الكتاب عن قصدنا لذكرنا قراءتهم، وشرحنا ديانتهم وبيّنا كفرهم.\nذكر القبائل الداخلين فى هذه الديانة: برغواطة، وجراوة، وزغاوة، وزواغة، والبرانس، وبنو أبى قاض، ونجطة، وبنو واعم، ومطغرة، وبنو يوزغ، وبنو دمر، ومطماطة، وبنو واكست، وبنو تاسليت.\nومن تدين لهم من المسلمين: زناتة الجبال، وبنو تليت، وبنو وانسيت، وبنو تانيت. ولم يزالوا على تلك الديانة إلى عام [- ١٠٦٠] .\nمدينة تادلا : هى مدينة قديمة فيها آثار للأول، وبنى فيها الملثمون حصنا عظيما منيفا، وهو الآن معمور، فيه الأسواق والجامع. والبلد كله كثير الخيرات والأرزاق، وأحاطت به القبائل من كل الجهات، فهو حقيق بالمملكة؛ والأمر العزيز أدام الله دوامه ملتفت له محتاط عليه.\nمدينة ثليث : هى مبسوطة بين القبائل القبيلة، وعليها تمر القوافل، وفيها حصن منيع رتبت فيه الجند، وعمره الوالى، وحوله الأعناب الكثيرة والثمار، والمياه المطردة، والعمائر.\nمدينة سجلماسة : مدينة عظيمة من أعظم مدن المغرب، وهى على طرف الصحراء لا يعرف فى قبليها ولا غربيها عمران؛ بينها وبين غانة صحراء\nمسيرة شهرين فى رمال وجبال غير عامرة قليلة الماء، يسكنها قوم من مسوفة رحالون لا يستقر بهم مكان، ليس لهم مدن ولا عمارة يأوون إليها إلا وادى درعة وبينه وبين سجلماسة أيام. ومدينة سجلماسة محدثة بنيت سنة [- ٧٥٧- ٧٥٨] ، أسسها مدرار بن عبد الله وكان رجلا من أهل الحديث، يقال إنه لقى بإفريقية عكرمة مولى بن عباس وسمع منه؛ وكان صاحب ماشية وكان كثيرا ما ينتجع سجلماسة وكان الموضع سوقا يجتمع فيه بربر تلك النواحى.\nفاجتمع إلى مدار قوم من الصّفرية فلما بلغوا رجلا قدموا على أنفسهم مدرارا وشرعوا فى بناء سجلماسة فبنوها ثم سورها أبو المنصور بن أبى القاسم ابن مدرار، ولم يشركه فى الإنفاق فى بنائه أحد. أنفق فيه مدى ألف مدّ طعاما.\nوذكر آخرون أن رجلا حدادا اسمه مدرار وكان من ربضية قرطبة خرج من الأندلس عند وقعة الربض فنزل منزلا بقرب سجلماسة، وموضع سجلماسة إذا ذاك سوق البربر بتلك النواحى، فأنشأ بها مدرار خيمة وسكنها فبنى الناس حوله، فكان ذلك أصل عمارتها، وكان رجلا أسود وأولاده قد هجوا بذلك.\nولمدينة سجلماسة بابا، ولها بساتين وهى كثيرة النخل والأعناب وجميع الفواكه، وزبيب عنبها المعرش الذي لا تناله الشمس لا يزبّب إلا فى الظل ويسمى الطلى، وما أصابته منه زبّب فى الشمس. وهى على نهرين من عنصر واحد فى موضع يسمى أكلف ، وتمده عيون كثيرة، ولهم مزارع كثيرة يسقونها من النهر فى حياض كحياض البساتين؛ وتزرع أرض سجلماسة عاما ويحصد من تلك الزريعة أعوام لأنه بلد مفرط الحر شديد القيظ.\nفإذا يبس الزرع تناثر عند الحصاد وأرضهم مشققة فيقع ما يتناثر من الحب فى تلك الشقاق، فإذا كان العام الثانى أخرجوا النهر على عادتهم لأن ماء المطر قليل فيها وحرثوا بلا بذر؛ وكذلك العام الثالث. وقمحهم رقيق الحب يسع مدّ النبي - صلى الله عليه وسلم - من قمحهم ألف حبة، وهم يأكلون الزرع إذا خرج شطئه وهو عندهم مستظرف وذلك لغلبة الجدب عندهم. ومن العجيب بمدينة سجلماسة أنها ليس بها ذئاب ولا كلاب لأنهم يسمّنونها ويأكلونها كما يصنع أهل\nالجريد: قسطيلية وغيرها. ويسمون الكنافين عندهم المجرمين، والبناؤون عندهم يهود لا يتجاوزون بهم هذه الصناعة؛ وكذلك كانوا ببلاد بنى الناصر.\nقال الناظر كان هذا فى الزمان المتقدم، وأما الآن فهم تجار أهل هذه البلاد كلها وأغنياؤها وخاصة بمدينة فاس فإنى عاينت منهم من يقال إن عنده المال الممدود رجالا كثيرين. وقد كان تنبه لهم الأمر العالى أيد الله دوامه سنة [٥] [- ١١٨٦] فلبس المرتشون وشوش المشوشون وخوف المفتشون، فأرجأ القدر السابق هذا إلى نهاية أمد عزهم وابتداء نكستهم إن شاء الله وذرهم وهى سنة من الهجرة. والسبب فى تسخير أهل سجلماسة لليهود فى هاتين الحرفتين الرذيلتين كونهم محبين فى سكنى بلدهم للاكتساب لما علموا أن التبر بها أمكن منه بغيرها من بلاد المغرب لكونها بابا لمعدنه، فهم يعاملون التجاربه ليخدعونهم بالسرقة وأنواع الخدائع. ولما علم منهم أبو عبد الله الداعى ما هم عليه من ذلك عند استخراج عبيد الله من سجن اليسع بن مدرار بها، وكان الذي نص عليه ونم به لليسع يهودى وحكى عبيد الله لأبى عبد الله ما جرى له معه، قتل منهم الأغنياء وأخذ أموالهم بالعذاب، وأمر من شاء أن يقيم منهم بالبلد فى أن يتصرف فى هاتين الخلتين، فمن دخل فى الكنّافين من أصناف الناس سموهم المجرمين لاجترامهم على حرفة موقوفة على اليهود.\nوقصروا البناء عليهم خاصة لأنهم خائفون أبدا من أن يخون أحدهم المسلم فيهلكه، فهم ينصحونهم فى البناء ويلازمون الخدمة دون خروج لفرائض الصلوات ولا لغير ذلك من ملازم العبادات، فتأتى خدمتهم موفرة سريعة.\nوهم الآن قد مازجوا المسلمين وداخلوهم وهو العز الذي كانوا يرتقبونه فى سالف الأزمان، وبعده الزلة الدانية لهم القاصمة إن شاء الله لظهورهم، المستأصلة لشأفتهم عما قريب كما قدمنا.\nذكر السبب فى ثورة الداعى ودخوله سجلماسة : كان الداعى محققا لوجود الإمام المهدى، جاهلا لزمنه طامعا أن يصادفه لمحبة المرء فى نفسه.\nقال الداعى خرجت يوما إلى شاطئ دجلة لأتفرج، فجلست على ضفة النهر أقرأ سورة الكهف فإذا بشيخ حسن الملبس والمركب معه غلام ففرش له على ضفة النهر، فجلس وأنا أقرأ حتى انتهيت إلى قوله تعالى: \xabحتى إذا لقيا غلاما فقتله\xbb إلى قوله: \xabفخشينا أن يرهقهما طغيانا وكفرا\xbb إلى آخر الآية. فقال لى الشيخ: أنت تزعم ممن يقول بالعدل والتوحيد؟ قلت له نعم. قال فكيف تقتل نفسا خشى أن يكون وأن لا يكون؛ فقلت له إنى لعلم هذا لفقير؛ فقال لى سأعلمك إذا التقينا إن شاء الله. ثم ركب دابته وانصرف، فسألت غلامه من هو فقال لى: هو محمد بن اسماعيل بن الحسن بن على بن جعفر بن على ابن موسى بن جعفر بن على الصادق بن على زين العابدين بن الحسين بن على ابن أبى طالب رضه وعن جميعهم. قال الداعى فعند ما سمعت ذلك لم أتمالك أن قبلت رأس الغلام وتعلقت بركاب الشيخ، وضرعت إليه أن يعلمنى السبيل إلى معرفة الإمام؛ فأشار إلى فى الوصول إلى منزله، فسرت معه فأدخلنى ووجدت ولده عبيد الله ومعه أحد عشر رجلا، فقال لهم هذا ثانى عشرتكم. فأنزلنى أرفع منزلة فلما استقربى المجلس قال لى: قدحان وقت ظهور الإمام وهذه الدعاة خارجة إلى الأقطار، وأنا أريد توجهها إلى المغرب لأن جعفر بن محمد الصادق زرع بالمغرب بذرا فأنت تحصده إن شاء الله؛ اذهب إلى مكة فإنك ستجد بها قوما من كتامة فاعرض نفسك لهم فى تعليم أبنائهم؛ فإذا وصلت معهم إلى بلادهم فأعلمهم بظهور الإمام وأن زمانه قدحان وخاطبنا. فإذا استوثق الأمر نهضنا إن شاء الله، ودفع إلى مالا وشيعنى فأنصرفت وأنا متعجب من دعواه، ومرتاب فى أمره. فلما عاينت خروج الدعاة وحدهم احتسبت نفسى من جملتهم، فسرت إلى مكة- كرمها الله- فألفيت كتامة، فعرضت نفسى عليهم، فتلقونى بالقبول، وسرت معهم إلى بلادهم فنزلت فى بجاية بالجبل المعروف ببنى زلدوى. وجعلت أعلم أبناءهم، فقالوا نحن أحوج إلى التعليم منك من أبنائنا فجعل يقول لهم: هذا زمان الإمام المهدى الفاطمى قد حضر، وذلك فى خلافة عبد الله سنة ٢٨٠- ٨٩٣] . وكان الداعى يأخذ صدقانهم، وعشوراتهم وأمرهم بالدعوة إلى ما دعاهم إليه، وقتل من خالفهم الى أن مات الشيخ والد عبيد الله، وهرب الولد فارا إلى مصر، فلم يعلم بدخوله فيها. وقد كانت\nمخاطبات المعتضد نفذت إلى ابن طولون بمصر وإلى اليسع بن مدرار والى سجلماسة فى طلبه. فلما خرج عبيد الله من مصر تنبه له فطلب فوجد راجعا قد طلب كلبا كان هرب لهم، فحمل إلى الوالى فذكر أنه صائد قد هرب له كلبه فطلبه، وشهدت له البينة بذلك وقيل أعطى للوالى ما كان معه من المال فأطلقه. ووصل لسجلماسة فنص عليه اليهودى كما قدمنا، وسجنه اليسع بن مدرار فى منزل أخته فى غرفة وكبله، وتبعه ولده القاسم فسجنه فى قرية بالقرب من سجلماسة؛ فخاطب أبا عبد الله الداعى وأعلمه بحاله من الأسر والخوف ورغب إليه فى استنقاذه، فاستنفر الداعى قبائل كتامة ومن استجاب لدعوته، وقصد سجلماسة فدخلها لحينه وفر اليسع فقتله طائفة من رعيته لحقد كانوا يجدونه له. ووصل الداعى من فوره لدار بنت مدرار واستخرج عبيد الله من سجنه وكسر كبله بيده وأركبه بغلة وكساه برنسه وقال لهم: هذا مولاى الإمام فهو مولاكم. فقال له عبيد الله: قل لهم هو المهدى بن المهدى سلالة الهداية، وسر من فورك واستخرج مولاك أبا القاسم من سجن عدو الله وعدو أوليائه. فنهض الداعى راحلا واستخرج أبا القاسم ابن عبيد الله وأركبه بغلة أخيه أبى العباس، واستخرج أهل سجلماسة من مواطنهم وقال لهم: لا يحل لكم أن تستوطنوا بلدا امتحن فيه الإمام؛ ففزعوا من سطوته لما عاينوا منه ما صنع باليهود كما قدمنا. فلما خرجوا معه أمر بسلبهم، ففتشوا كلهم رجالا ونساء وأخذ أموالهم وصرفهم: وقيل إنه تحصل له من التبر ومن الحلى وقر جملا أدخلها رقادة وبايع بها لعبيد الله وأقامه وأدخله القيروان وبنى المهدية. فكان عبيد الله يتساكر ويقتل جواريه ويرمى بهن خارج القصر. وأظهر مذهبه الذي يزعم الشيعة أنه مذهب أهل البيت، فأنكر كتامة ذلك واجتمعوا مع الداعى وأخيه أبى العباس وكان مصمما فقال لهم الداعى إن الدعاء لأهل بيت رسول الله - صلى الله عليه وسلم - واجب، وإن الإمام المهدى حق وإن الزمن مجهول عندى؛ وكنت ارتبت فى والد عبيد الله فكيف لا يرتاب\nفيه، سيروا إليه وقولوا له: إن أبا عبد الله وأبا العباس قد شكا فى الخاتم الذي ذكرت أنه بين كتفيك فأره لنا، فإن لم تعاينوه فشأنكم به. قال فعند ما وصلوا إليه، وقالوا له تلك المقالة، قال لهم ألم يعلما كما قيل إنهما أيقنا به؟ قالوا نعم فقال لهم: الشك لا يزيل اليقين. والتفت إلى صاحب شرطته فقال له: يا عروبة آتنى برأسيهما؛ ففى الحين نهض عروبة إليهما متنكرا فقال له أبو عبد الله وكان له عليه حق مرتبته: ما الذي أتى بك يا عروبة؟ فقال الذي أمرتنى بطاعته أمرنى بقتلك. فقتلهما وأتى برأسيهما بحضرة أشياخ كتامة، وأمر بالكتب إلى الأمصار أن أبا عبد الله أحدث حدثا فطهرناه بالسيف، ولم تكن تمنعنا رعاية الحق له من إقامة الحدّ عليه. وتمهد أمر عبيد الله. وهو الحقيقة كما ذكر أبو بكر محمد بن الطيب فى كتابه فى وصف القرامطة: أنه عبيد الله والده عبد الله بن سالم بن عبدان الباهلى، وأن جده سالم صلبه المهدى العباسى على الزندقة على ما قاله الذين فحصوا عن أمره. ومات عبيد الله بالمهدية سنة [- ٩٣٤] وولى ولده أبو القاسم فأظهر مذهبه وسماه مذهب أهل البيت نسبة إلى جعفر ابن محمد الصادق وإلى على بن أبى طالب رضهما- وحاشاهما منه والعياذ بالله من هذا المعتقد. فمنه توريث البنت إذا انفردت بجميع المال كله، والله تعالى يقول: \xabوإن كانت واحدة فلها النصف\xbb . وأسقط الرجم عن المحصنين فى الزنا، وأسقط المسح على الخفين، وأسقط من الأذان \xabالصلاة خير من النوم\xbb ونادى فى الصبح \xabحى على خير العمل وعلى خير البشر\xbb ، والصوم بالعلامة والفطر بها لا بالرؤية فيأتى قبل صوم المسلمين بيوم وقبل فطرهم بيوم فى أكثر الأعوام.\nوأحل المطلقة ثلاثا، وأسقط أيمان الحرج. ولولا خروجنا عما قصد إليه الواضع لشرحنا ديانتهم وبينا كفرهم. وسماعهم الأخوة والمؤمنين وأمر ألا يقيم الحد أحد إلا أبوه أو ابنه أو أخوه أو قريبه. ثم أمرهم بالجهاد لمن خالف مذهبهم. فقام عليه أبو زيد مخلد بن كيداد بن سعد الله بن مغيث بن كرمان بن مخلد بن عثمان بن رويب بن سيران بن يفرن بن صره بن يورسيف بن جنا بن يحيى بن ضرليس بن جالوت. وكان على مذهب الصفرية النكار وقر على عمار الأعمى فى المشرق، وكان قيامه فى أول سنة [- ٩٤٣] .\nذكر المؤرخون أنه كان يعمل أكواما من رؤوس المسلمين رعية الشيعى ويأمر المؤذنين (بالآذان) عليها. وأخذ لشيخ من المسيلة ألف مثقال وابنتين أبكارا فشغل الشيخ هم بنتيه عن ماله، فجعل يطلبهما فى المحلة حتى وجدهما عند باب خباء الشيخ الملعون- وكان يركب الحمار وتسمى بشيخ المؤمنين- فانكب على بنتيه وسألهما فقالتا له يا أبانا إن الملعون افتضنا فى فراش واحد، فمشى الرجل إليه وقال له: تتسمى بشيخ المؤمنين وأخذت مالى وافتضضت بنتى، أختين شقيقتين على فراشك دون استحياء من الله تعالى؟ فقال له: ذلك حلال لنا بملك اليمين وأمر بالرجل فضربت عنقه رحمة الله علينا وعليه. وقد كان هزم أبا القاسم الشيعى وهرب أمامه للمهدية فوصل أبو زيد فى أتباعه حتى ركز رمحه فى الباب، فأعلم أبو القاسم فقال لهم: والله لا عاد إليها أبدا وهو حتفه هكذا فى كتبنا. وأمر بالركوب والخروج إليه وأعطى الجند العطاء الجزيل؛ فلما خرجوا أراد أبو زيد أن يقتل من كان معه من حشد الرعية ليتفرغ لإفشاء كفره، فقال: لأصحابه انكشفوا عنهم فيقتلوا عن آخرهم. وأثخن أبو زيد بالجراح وقبض عليه حيا فأدخله المهدية فى قفص حديد وصلبه على الباب الذي طعن فيه برمحه، ودانت لأبى القاسم الشيعى بلاد المغرب كلها من إفريقية إلى درعة.\nمدينة درعة : وإنما تعرف درعة بواديها فإنه نهر كبير يجرى من المشرق إلى المغرب ومنبعه من جبل درن، وعليه عمارة متصلة نحو أيام وفيها أسواق حفيلة كثيرة. فيها يوم الجمعة أسواق فى مواضع كثيرة متقاربة وربما كان سوقان فى يوم واحد فى المواضع النائية وكذلك فى سائر البلاد، وعليه الجنات الكبيرة فيها جميع الفواكه من النخل والزيتون وغيرها. والحناء بدرعة كثيرة ومنها تجلب إلى جميع البلاد لطيبها، وله مزية فى البيع على سواها. وشجر الحناء\nبها شجر كبير يحتمل أن يرقى فيها الراقى، وبوادى درعة شجر التاكوت وهو شجر يشبه الطرفاء وبه يدبغ الجلد الغدامسى. وتوجد بوادى درعة حجارة تسمى تامضغيت تحك باليد فتلين إلى أن تأتى فى قوام الكتان فيصنع منها القيود للدواب والامره، وتغزل وينسج منها مناديل لا تؤثر فيها النار مثل الصندل؛ وقد صنع منها لبعض ملوك زناته كساء عنده من أعظم الذخائر.\nذكر البكرى أنه أخبره ثقة إنه رأى تاجرا قد جلب منه منديلا لبعض ملوك الروم، وأخبره أنه منديل كان لبعض الحواريين وجعله فى النار أمام الملك فلم تؤثر فيه شيئا، فوصله ذلك الملك عليه بصلة كان فيها غناه إلى آخر الزمان.\nويقال إن ذلك الملك بعثه إلى ملك الروم الأعظم وأخبره بخبره، ووضعوه فى الكنيسة العظمى، وبعث إليه بصلة سنية وأمره أن يتوج بتاج بعثه إليه ورفعه على من سواه .\nمدينة أغمات : وأغمات هما مدينتان إحداهما تسمى أغمات وريكة والأخرى أغمات هيلانة، وبينهما نحو أميال. وبأغمات وريكة يسكن الأعيان وبها ينزل التجار على القديم لأنها كانت دار التجهز للصحراء؛ وبها نهر جريه من القبلة إلى الجوف، يشق المدينة بعضه وعليه أرحاء وحوله بساتين كبيرة.\nوهو بلد متسع كثير الرخاء والخصب إلا أنه وخيم الهواء، ألوان أهله مصفرة والعقارب القتالة به كثيرة، وبينه وبين البحر مسيرة أيام. وأقرب المراسى إليه مرسى جوز هر تنانة من بلد رجراجة، وهومن آخر مراسى سواحل المغرب مما يقرب من البحر المحيط، تنزل به السفن ولا يخرج منه إلا برياح عاصفة فى زمن الشتاء عند تكدر الهواء واغبرار الجو؛ فحينئذ تصدق هناك الرياح فإن أصطحبهم الريح سلموا وإلا قذفهم البحر. وبين أغمات ومدينة نفيس مرحلة.\nمدينة نفيس : مدينة قديمة أزلية غزاها عقبة بن نافع رحمه الله، وحاصرها وفيها الروم والنصارى البربر فافتتحها وأصاب المسلمون فيها أموالا كثيرة ومغانم واسعة؛ وبنى فيها عقبة مسجدا وهو معروف بها اليوم. وكان دخول عقبة مدينة نفيس سنة [٦٨٢] من الهجرة، ويعرف بالبلد النفيس وليس فى جميع البلاد أطيب هواء منها ولا أجمل منظرا ولا أكثر أنهارا وأشجارا وثمارا.\nويشق بلد نفيس نهر منبعه من جبل درن حيث الروضة المقدسة المكرمة المعظمة؛ جدث الإمام المهدى وصاحبه وحواريه الخليفة الإمام أمير المؤمنين عبد المؤمن بن على رضهما؛ وهو فى مدينة البيضاء المعروفة بتنمل كرمها الله. وكانت على القديم معمورة فمدنها الإمام رضه، وبنى فيها الخليفة جامع الإمام رضهما ، وعليها سور حصين وهى أمنع حصن أو قلعة فى بلاد المغرب لو عورة الطريق من هذه البلاد لأن زيارة الأئمة الأطهرين لها على طرق مرصوفة من الخشب متى احتيج إلى إزالتها أزيلت فتعلقت السبل وحار الدليل، فتعاين مهوى بعيدا لا يدرك له قعر. وهى فى وسط القبائل المعروفين بالشهامة والنجدة. وبين أغمات ونفيس الحضرة العلية مرّاكش- صانها الله تعالى دار إسلام.\nمدينة مرّاكش- كلأها الله\nهى اليوم حاضرة بلاد المغرب ودار مملكتها، وهى مدينة عظيمة فى بسيط من الأرض، أسسها يوسف بن تاشفين سنة [١٠٦٧] ؛ وأول ما بنى فيها\nبلاد الله قصب سكر وفيها معاصر السكر كثيرة. وهذا البلد أخصب بلاد المغرب وأكثرها فواكه وخيرات، ومنها يجلب السكر إلى جميع بلاد المغرب والأندلس وإفريقية وهو المشهور بالطبرزد المذكور فى كتب الطب. وعلى مصب هذا الوادى فى البحر رباط مقصود له موسم عظيم ومجتمع جليل وهو مأوى للصالحين. ومن وادى سوس إلى مدينة نول مراحل فى عمارة متصلة يسكنها جزولة ولمطة، وهم أمم كثيرة.\nوقاعدة بلاد السوس مدينة أيجلى وهى مدينة عظيمة كبيرة قديمة أزلية فى سهل من الأرض على النهر الكبير المذكور، وهى كثيرة البساتين والتمر وجميع الفواكه، ربما بيع حمل التمر بما دون كراء الداية من الجنان إلى السوق، وقصب السكر بها كثير وله بها معاصر كثيرة، وأكثر شرب أهلها إنما هو ماء قصب السكر ؛ ويعمل بها النحاس المسبوك يتجهز به إلى بلاد السودان.\nووصل عقبة بن نافع إلى هذه المدينة عند دخوله إلى بلاد المغرب، وافتتحها فأخرج منها سبيا لم ير مثله حسنا؛ كانت تباع الجارية الواحدة منهن بألف دينار وأكثر لحسنها وتمام خلقها. ويعمل بهذه المدينة زيت الهرجان وشجره يشبه الكمثرى إلا أنه لا يعلو كعلو شجرة الكمثرى ولا يفوت اليد، وأغصانه نابتة من أصله لا ساق لشجرته ولها شوك وثمرته تشبه الأجاس المعروف عندنا بالعبقر، فيجمع ويترك حتى يذبل ثم يوضع فى مقلاة فخار على النار فيستخرج دهنه، وطعمه يشبه طعم القمح المقلو، وهو جيد محمود الغذاء يسخن الكلى ويدر البول. وبالسوس عسل يفوق عسل جميع الأمصار، يلقى النبيذيون على الكيل منه كيلا من الماء وحينئذ يأتى نبيذا، وإن كان الماء أقل من ذلك بقى حلوا ولا ينحل إلا بالماء الشديد الحرارة، ولونه أخضر فى لون الزمرد .\nوبالقرب من أيجلى على نحو مراحل مدينة تا مدلت ، وهى مدينة كبيرة أسسها عبد الله بن إدريس العلوى وتوفى بايجلى وبها قبره. وتا مدلت مدينة سهلية كثيرة العمارة حافلة الأسواق، على نهر عنصره من جبل على نحو أميال منها، وما بينهما عمائر وبساتين متصلة، وهذا النهر هو نهر درعة، وهذه المدينة تامدلت على رأس النهر، وبينها وبين مدينة درعة مسيرة أيام فى عمارة متصلة. ومن بلاد السوس مدينة نول لمطة ، وهى مدينة كبيرة فى أول الصحراء على نهر كبير يصب فى البحر المحيط، ومن مدينة نول إلى وادى درعة نحو مراحل. وإنما سميت نول لمطة لأن قبيلة لمطة يسكنونها وما وراءها وهى آخر بلاد السوس؛ ومن أراد الدخول من وادى درعة إلى بلاد السودان، غانة وغيرها، فليمشى من وادى درعة نحو مراحل إلى وادى ترجا وهو فى أول الصحراء، ثم يسير فى جبال وعرة فى طريق قد فتحت فى حجر صلد بالنار والخل من عمل الأول. ويزعم قوم أن ملوك بنى أمية فتحوها، وهذه الطريق من أحد أعاجيب العالم . ومنها إلى جبل يسمى بالبربرية جبل الحديد، ومن هذا الجبل يدخل إلى بلاد لمتونة وهم من صنهاجة؛ وأكثر لمتونة إنما هم رحالة لا يستقر بهم موضع ولا يعرفون الحرث ولا الزرع ولا الخبز، وإنما لهم الأغنام الكثيرة فيعيشون من لبنها ولحمها، فهم يجففون اللحم ويطحنونه ويصبون عليه الشحم المذاب والسمن ويأكلونه ويشربون عليه اللبن قد غنوا به عن الماء، فيبقى الرجل منهم الشهر لا يشرب ولا يأكل خبزا ولا يعرفونه وصحتهم من ذلك متمكنة ، ربما مرت بهم القوافل فيتحفون ملوكهم\nورؤساءهم بالخبز والدقيق. وببلادهم يكون اللمط الذي يعمل من جلوده الدرق، وهذا الحيوان المسمى باللمط دابة دون البقر لها قرون رقاق حادة تكون لذكرانها وإنائها، وكلما كبر هذا الحيوان طال قرنه حتى يكون أزيد من أشبار؛ وأجود الدرق وأغلاها ثمنا ما عمل من جلود الإناث المسنات التى قد طالت قرونها لكبر سنها حتى منعت الفحل أن يعلوها. وببلادهم أيضا الفنك الكثير، ومن عندهم تحمل جلودها إلى جميع البلاد، وعندهم الكباش الدمانية وهى على خلقته أيضا إلا أنها أعظم وشعرها كشعر المعز لا صوف عليها، وهى أحسن الغنم خلقا وألوانا. والريحان فى بلاد الصحراء وفى بلاد السوس عزيز لأن بلادهم لا تنبته، وهو عندهم من أطيب الطيب.\nومن عجائب هذه الصحراء أن بها معدن الملح تحفر عنه الأرض كما تحفر عن سائر المعادن، ويوجد هذا الملح تحت قامتين أو دونهما من وجه الأرض فيقطع كما تقطع الحجارة ويسمى هذا المعدن تاتنتال، وعليه حصن مبنى بالحجارة التى تخرج من المعدن، وجميع ما فيه من بيوت وغرف ومساكن إنما هو مبنى بحجارة الملح. وبهذا الملح يتجهز إلى بلاد السودان، غانة وغيرها، وله غلة عظيمة؛ وبإزاء معدن الملح الماء العذب الطيب، أخبرنى بذلك من عاينه.\nومعدن الملح أيضا فى بلاد جدالة بموضع يسمى وليلى على شاطئ البحر المحيط، ومن هناك تحمله الرفاق إلى ما جاوز تلك الجهة. وبقرب وليلى فى البحر جزيرة تسمى أيونا ، وهى عند المد لا يوصل إليها إلا بالمراكب\nوعند الجزر يوصل إليها بالقدم، ويوجد فيها العنبر الكثير؛ وأكثر معاش أهلها من لحوم السلاحف فهى أكثر شئ فى ذلك الموضع وهى مفرطة العظم، ربما دخل الرجل فى محار ظهورها يتصيد فى البحر كالقارب. وفى هذه الجزيرة أغنام كثيرة ومواشى، وهى منتهى المراكب وآخر مراسى المغرب. ومن مدينة نول إلى هذه الجزيرة على البر، لا تفارق السواحل، مسيرة شهرين فى أرض محجّرة أكثرها صفاء تنبو عنها المعاول، ويكل فيها الحديد ، وإنما يشرب من يمر على ذلك الطريق من حفر يحفرونها عند جزر البحر فينبع ماء عذبا وهو من العجائب. وإذا مات للمارين بهذه الطريق ميت لا يمكنهم مواراته بالتراب لصلابة الأرض وامتناعها من الحفر، فيسترونه بالحطام والحشيش أو يقذفونه فى البحر.\nوبين صحراء لمتونة وبلاد السودان ، مدينة أودغست .\nوهى مدينة عظيمة آهلة فيها أمم لا تحصى ولها بساتين كثيرة ونخل كثير، ويزرعون فيها القمح بالحفر بالفؤوس ويسقونه بالدلاء ، وكذلك يسقون بساتينهم، وإنما يأكل عندهم القمح الملوك وأهل اليسار منهم، وسائر أهلها يأكلون الذرة. والمقاتى تجود عندهم كثيرا، والبقر والغنم عندهم أكثر شئ وأرخصه:\nتشترى فى أودغست أكباش بدينار وأكثر من ذلك، وهم أرباب نعم جزيلة وأموال جليلة ولهم أسواق حافلة عامرة الدهر كله، لا يكاد يسمع الإنسان فيها صوت جليسه لكثرة غوغاء الناس، وتجارتهم إنما هى بالتبر وليس عندهم فضة. وبمدينة أودغست مبان حسنة ومنازل رفيعة وأهلها أخلاط من جميع الأمصار، وقد استوطنوها لكثرة خيرها، ونفاق أسواقها وتجارتها. وحريم أودغست لا يوجد مثله فى بلد، يجلب منها جوار حسان بيض الألوان مائسات القدود، لطاف ضخام الأرداف واسعات الأكتاف ضيقات الفروج، المستمتع باحداهن كأنما يستمتع ببكر أبدا، من غير أن ينكسر لإحداهن ثدى طول عمرها.\nأخبرنى ثقة من التجار أنه رأى بمدينة أودغست امرأة راقدة على جنبها، وكذلك يفعلن فى أكثر أحوالهن إشفاقا من الجلوس على أردافهن، ورأى ابنا لها طفلا يلعب حواليها وهو يدخل تحت خصرها ويخرج من الجهة الأخرى من غير أن تتجافى له، وذلك لعظم ردفها ورقة خصرها. ويجلب منها سودانيات طباخات محسنات، تباع الواحدة منهن ب دينار كبار وأزيد، يحسن عمل الأطعمة ولا سيما أصناف الحلاوات مثل الجوزينقات، والوزينجات، والقاهريات، والكنافات والقطائف والمشهوات، وأصناف الحلاوات، فلا يوجد أحذق يصنعتها منهن. ومنها تجلب الدرق الخصيفة الجياد فإن اللمط بأرض أودغست كثير جدا. يجلب أيضا منها العنبر الطيب لقربها من البحر المحيط، ويجلب منها الذهب الإبريز الخالص خيوطا مفتولة. وذهب أودغست أجود ذهب الأرض وأصحه، وكان صاحب مدينة أودغست فى سنة ٣٥٠- (٩٦١- ٩٧١) رجل من صنهاجة، وكانت له جيوش كثيرة فدان له أزيد من ملكا من ملوك السودان كلهم يؤدون له الجزية. وكان عمله مسيرة شهرين فى مثلها فى عمارة متصلة، وكان يعتد فى أزيد من ر نجيب فإن الخيل فى تلك البلاد قليلة، فيقال إنه غزا ملكا من ملوك السودان يقال له أوغام، فدخل بلده وأحرقها وقتل جنده والملك فى قصره ينظر إليه؛ فلما رأى ما حل فى بلده هان عليه الموت وخرج ورمى بدرقته إلى الأرض وقاتل حتى قتل. فلما عاين نساؤه ذلك تردين فى الآبار وقتلن أنفسهن بضروب من القتل أسفا على ملكهن وأنفة أن يملكهن البيضان. وبين مدينة أودغست وسجماسة نحو مرحلة، ومنها إلى غانة نحو ٢٠.","4-3":"القنطرة للمراكب فيتحفظون منها؛ ويقال إنها تنكشف فى آخر الزمان ويجوز عليها الناس، والله أعلم بغيبه.\nوقيل إن طنجة آخر حدود إفريقية فى المغرب؛ ومسافة ما بين طنجة والقيروان ميل. وهى طنجة البيضاء المذكورة فى التواريخ. وقيل إن عمل طنجة كان مسيرة شهر فى مثله، وإن ملوك المغرب من الروم وغيرهم من الأمم كانت دار مملكتهم مدينة طنجة، وذلك من أجل القنطرة لئلا يفجأ العدو إحدى الجهتين، والله بغيبه أعلم. وإذا حفرت خرائب طنجة وجدت فيها أصناف الجوهر، فيدل ذلك على أنها كانت دار مملكة لأمم سالفة.\nوقيل إنه يسامت طنجة فى البحر المحيط الأعظم الجزائر المسماة قرطناقش ومعناه السعيدة، سميت بذلك لأن أرضها تحمل الزرع دون حرث، وشعراؤها وغياضها كلها أصناف الفواكه الطيبة العجيبة دون غراسة ، وفيها أصناف الرياحين العطرة بدل الشوك. وهى متفرقة فى البحر متقاربة بغربى بلاد البربر، يذكر ذلك أهل سواحل المغرب؛ وقد رأيت من امتحن فى طلبها. ويقال، لطنجة وتأتى فيه سيول عظام تذهب ببعض دورها.\nمدينة أصيلا : كانت مدينة كبيرة أزلية عامرة آهلة كثيرة الخير والخصب. وكان لها مرسى مقصود، وكان سبب خرابها أن المجوس إذا خرجوا من البحر الكبير فأول ما يلقون مدينة أصيلا، فينزلون بمرساها ويخربون ما قدروا منها، فيجتمع البربر فيحاربونهم؛ فكانوا معهم على ذلك مع ما كان بين أهل تلك البلاد من الفتن. ويقال إن المجوس قصدوا إليهم مرة فاجتمع البربر لقتالهم، فقالوا لهم: \xabما جئنا لقتال وإنما لنا ببلادكم أموال وكنوز، فتنحوا عنا حتى نستخرجها ونشاطركم فيها\xbb . فرضى البربر بذلك واعتزلوا عن الموضع\nالذي ذكروا لهم، فحفر المجوس موضعا من تلك المواضع التى زعموا فوجدوا على الخبء مطامير من الدخن فاستخرجوه، فلما نظر البربر من بعيد إلى صفرة الدخن ظنوه تبرا، فبدروا إليهم ونقضوا عهدهم وهرب المجوس إلى مراكبهم.\nفلما أصاب البربر الدخن ندموا فرغبوا إلى المجوس أن يرجعوا إلى استخراج المال فأبوا؛ وقالوا: \xabقد رأينا منكم نقض العهد فلا نأمنكم أبدا\xbb .\nمدينة تشمّس : وهى مدينة قديمة أزلية فيها آثار للأول؛ وهى على نظر واسع كثيرة الخصب والزرع والضرع. وهى تشبه بلاد الأندلس، وبقربها بحيرة كبيرة تسمى أمسنا، يصب فيها البحر أعوام وتصب هى فى البحر أعوام؛ وينقطع البحر عنها فتظهر فيها جزائر بينها غدران يتصيد فيها أنواع السمك. وبين البحر والبحيرة مسجد مقصود يسكن حوله النساك وأهل الخيرة، وأمرهم مشهور بتلك الجهات معروف.\nمدينة سلا : اسمها بالعجمى شلّة ؛ وهى مدينة أزلية فيها آثار للأول. وهى معروفة بضفة الوادى، متصلة بالعمارة التى أحدثها الخليفة الإمام أمير المؤمنين وآباؤه المكرمون. وقد كان اتخذ أرباب البلد العشريون وأولياؤهم مدينة بالعدوة الشرقية، وهى المعروفة الآن بسلا، فيها ديارهم بحومة الجامع؛ ولم يبق منه سوى المنار، وأما السقف كله فتهدم واحتمى الغرباء فى بنائه فى سنة [- ١١٧٨] . وأمر الخليفة أبو يعقوب رضه ببناء مدينة كبيرة متصلة بالقصبة التى أحدثها الإمام أمير المؤمنين، وفى هذه القصبة جامع وقصور، وصهاريج الماء أمام الجامع وهو مجلوب من نحو ميلا. وفى هذه المدينة المحدثة قيصارية عظيمة وحمامات وفنادق وديار كثيرة ومياه مطردة وسقايات ومنافع","5-1":"ذكر بلاد السودان ومدنها المشهورة وعجائبها ونبذ من سير ملوكها\nقال المؤلف رحمه الله: أقرب بلاد الإسلام إلى بلاد السودان بلاد جدالة وأقرب مدينة من مدن السودان إليهم مدينة صنغانة وهى مدينة عظيمة على النيل. وبين آخر بلاد جدالة وبين مدينة صنغانة مسيرة أيام، وهما مدينتان على ضفة نيل مصر ولهاتين المدينتين نظر واسع وعمارات متصلة يقال إنه تتصل عمارتهما وقراهما بالبحر المحيط. وتلى مدينة صنغانة على النيل مدينة تكرور وكانوا على ما كان عليه سائر السودان فى المجوسية وعبادة الدكاكير، وهى بلغتهم الأصنام، حتى وليهم وزجاى بن ياسين فجبرهم على الإسلام بالسيف وحارب السودان حتى أسلموا وذلك سنة [- ١٠٤٣- ١٠٤٤] .\nمدينة سلى : هى مدينتان على ضفة النيل وأهلها مسلمون أسلموا على يد وزجاى، رحمه الله، وملكها واسع المملكة كثير العدد يقاوم صاحب غانة.\nوبينها وبين غانة مسيرة يوما فى عمارة متصلة للسودان القبيلة بعد القبيلة؛ وصاحب سلى يحارب من جاوره من كبار السودان، وتبايع أهل سلى إنما هو بالذرة والملح وحلق النحاس وأزر لطاف من قطن يسمونها الشّكيات وهى أنفق ما عندهم، وليس عندهم غنم ولا معز وأكثر نبات أرضهم الأبنوس ومنه يحتطبون. وبقرب مدينة سلى مدينة قلنبوا وهى مدينة كبيرة\nعلى ضفة النيل، فإن النيل يشق جميع تلك البلاد، ويسقى أكثرها. ومن عجائب تلك البلاد أن فيها حيوان يشبه الفيل فى عظيم خلقته وخرطومته وأنيابه، يسمونه جفو ويرعى فى البر ويأوى إلى النيل، ويصطادونه فيأكلون لحمه ويصنعون من جلده الأسواط التى تسمى بالسّريّاقات، ويقال لها بالأندلس ذنب الفأر.\nومن هناك تحتمل الأسواط إلى جميع الآفاق، ولهم فى صيده حيلة فإنهم يميزون فى النيل المواضع التى يأوى إليها هذا الحيوان [حيث] يتحرك الماء على ظهره لقلة استقراره، وعندهم مزارق حديد قصار فى أسافلها حلق قد شدت فيها حبال مديدة، فيزرقونه بالعدد الكثير منها، فيهرب منهم ويغوص فى أسفل النيل فيرخون له تلك الحبال فيضطرب حتى يموت. فإذا مات طفا على الماء فيجرونه إلى البر، ويأخذونه. وتلى مدينة قلنبوا مدينة ترنكة : وهى مدينة كبيرة على نظر واسع وبها تصنع الأزر المسمات بالشكيات التى تنفق فى مدينة قلنبوا وغيرها، وهى من القطن وليس بهذه المدينة قطن كثير وإنما هو مجلوب إليها، وهم يتبركون بشجره فقل ما عندهم منزل ولا دار إلا وفيه شجرة قطن. وحكم أهل هذه البلاد فى السارق أن يخير صاحب السرقة فى بيع السارق أو قتله، وحكمهم فى الزانى أن يسلخ من جلده.\nومن مدينة ترنكة تتصل ببلاد السودان إلى بلاد زافون وهم من البرابر لهم مدينة زافون، سميت بهم. وهم يعبدون ثعبانا عظيما له عرف وذنب ورأسه كرأس البختى، وهو فى مغارة فى أصل جبل، وعلى فم المغارة عريش وحوله مواضع يتعبدون فيها لذلك الثعبان، ويعلقون نفيس الثياب والمتاع على تلك المغارة، ويضعون لذلك الثعبان جفان الطعام وعساس اللبن والشراب، فهم إذا رأوا خروجه إلى ذلك العريش تكلموا كلاما معلوما عندهم، وصفروا تصفيرا كذلك فيبرز إليهم. فإذا هلك وال من ولاتهم جمعوا أولاده، إن كان له ولد ومن يصلح للملك بعده، وقربوه من ذلك الثعبان وتكلموا بكلام يعلمونه، فيدنوا ذلك الثعبان منهم فلا يزال يشمهم رجلا رجلا\nحتى ينطح أحدهم بأنفه، ثم يولى ذلك الثعبان راجعا إلى مغارته، فيتبعه ذلك الرجل والثعبان مسرعا إلى المغارة والرجل يجهد خلفه بالجرى بأشد ما يقدر عليه، فيجذب من ذنبه أو عرفه شعرات فتعد ويعلمون أنه يملك قومه تلك الشعرات سنين، لا يخطئهم ذلك بزعمهم. وأقول إن هذه الفتنة فيهم إنما هى لأن الثعبان يعمّر حتى يزيد على سنة، فنشأ على ذلك آباؤهم فلا يعرفون أوله، والواضع لهذه الفتنة إنما أراد أن يملكهم بذلك، وعقولهم فى نهاية الركاكة، فيصبح له منهم ما أراد- عصمنا الله من الفتن. وتلى هذه البلاد بلاد الفرويين ، ومن غرائب بلدهم أن عندهم بركة عظيمة يجتمع فيها الماء، ينبت فيها نبات أصله أبلغ شئ فى تقوية الجماع والمعونة عليه، وملك ذلك البلد يشح على إخراجه من بلده لئلا يصل منه إلى غيره شئ، وله من النساء عدد كثير، فإذا أراد أن يطوف عليهن أنذرهن من قبل ذلك بيوم، ثم استعمل ذلك الدواء، فلا يكاد ينكسر عن الطواف عليهن كلهن. وقد أهدى له بعض الملوك المجاورين لبلده هذه هدية نفيسة، واستهداه شيئا من ذلك العود، فعاوضه على هديته وكتب إليه أن المسلمين لا يحل لهم من النساء إلا القليل، وقد خفت عليك أن أبعث بهذا الدواء فلا تقدر على إمساك نفسك فتأتى ما لا يحل لك فى شريعتك، ولكنى بعثت لك عودا يأكله العقيم فيولد له. وببلاد الفرويين يبدل الملح بالذهب لعدمه عندهم، وفى هذه البلاد معادن الذهب، ترابه أحمر يستخرج كما يستخرج الحديد والرصاص والنحاس والفضة ببلادنا.\nذكر بلاد غانة وما جاورها من البلاد\nقيل إن غانة سمة لملوكها، وإنما اسم البلد أوكار ، ووقع إلى كتاب ملكها إلى يوسف بن تشفين، نصه: إلى أمير أغمات، قال غانة؛\nوهذا دليل على ما قيل. ومدينة غانة مدينتان، إحداهما يسكنها الملك والأخرى يسكنها الرعية والتجار والسوقة، بينهما الدور والمساكن نحو أميال متصلة.\nوفى مدينة الرعية جامع كبير ومساجد كثيرة، وفيها الأئمة المؤذنون والفقهاء والعلماء، وحواليها آبار عذبة منها يشربون، وعليها الخضر والمقاتى. ومدينة الملك تسمى الغابة، وللملك بها قصر عظيم وقباب، قد أحاط بذلك كله حائط مثل السور، وعلى مقربة مجلس حكم الملك، وحول قصره قباب وغابات وشعراء يسكنها السحرة وأهل ديانته، وفيها دكاكيرهم وقبور ملوكهم، ولها حرس فلا يمكن أحد من الغرباء دخولها ولا معرفة ما فيها، وهناك سجون الملك فإذا سجن أحدا انقطع خبره. وفى مدينة الملك مسجد يصلى فيه من يفد عليه من تجار المسلمين. والملك يجلس للناس للحكم فى قبة عظيمة وأمام القبة عشرة أفراس من عتاق الخيل، وعليها الحلل المذهبة من الحرير والديباج على عدمها ببلادهم. والملك يتحلى بحلى النساء فى عنقه وذراعيه، ويحمل على رأسه طرطورا مذهبا ويعمم عليه عمامة قطنية، وعن يمينه وعن يساره أبناء الملوك والوزراء وخاصته من أعيان بلده، قد ضفروا رؤوسهم بالذهب والجوهر وعليهم الثياب الرفيعة. ولا يلبس ثوبا مخيطا من أهل دينه إلا هو وولى عهده، ومن سواهما يلبسون ملاحف الحرير والديباج، وسائر أهل بلده يلبسون ملاحف القطن. والملك وسائر أهل بلده الذين على ديانته يحلقون لحاهم ونساؤهم يحلقن رؤوسهن. ولا يولى الملك عهده إلا لابن أخته وهو يشك فى ابنه ولا يقطع بصحة اتصاله به، وإذا جلس الملك فى قبته لمظالم الناس ينذرون لجلوسه بطبل عظيم يسمونه دبا ، وهو خشبة طويلة منقورة قد جلّدوها لها صوت هائل يجتمع الناس إليه، فإذا دنا منه أهل دينه جثوا على ركبهم وحثوا التراب على رؤوسهم. وأما المسلمون فتحيتهم عليه تصفيق باليدين، وجلوس الوزراء أمامه إنما هو على الأرض تواضعا للملك. وإذا مات الملك عملوا له قبة ووضعوا له الأطعمة والأشربة وكل من كان يخدم طعامه وشرابه، وأغلقوا عليهم باب القبة وجعلوا فوقها الحصى والأمتعة، واجتمع الناس فردموا فوق القبة بالتراب حتى يأتى الموضع مثل الجبل الضخم، ثم يحتفرون حوله حفيرا\nعظيما وعرا حتى لا يتوصل إلى ذلك الكوم ولا إلى شئ منه إلا من موضع واحد. ولملك غانة مملكة واسعة نحو الشهرين فى مثلها؛ وفى بلده يوجد الذهب الكثير، وهو يعم جميع بلاد الدنيا وأفضل الذهب بمملكته ما كان ببلد غياروا.\nمدينة غياروا : بينها وبين غانة نحو يوما متصلة بقبائل من السودان لا يحصى لهم عدد، وإذا وجد فى جميع معادن بلاد هذا الملك النّدرة من الذهب اصصفاها الملك لنفسه ولم يتركها تخرج من بلده لغيره. والنّدرة تكون من أوقية إلى رطل وإنما يتركون أن يخرج من بلادهم من الذهب ما كان رقيقا، ولو تركوا كل ما يوجد فى المعادن يخرج من بلادهم لكثر الذهب بأيدى الناس ولهان. ويذكر أن عند ملك غانة ندرة ذهب كالحجر الضخم؛ وقد ذكر أن عند بعض ملوك السودان من هذه الندرات حجر عظيم يجعل أمامه، فإذا ورد عليه رسل من غيره من الملوك أمر بفرسه فربطه إليه ليباهى بذلك. وبين مدينة غياروا والنيل ميلا وفيها كثير من المسلمين؛ وفى القرب منها على النيل مدينة يرسنى \xbb\n: وهى مدينة كثيرة الخيرات ولها معدن للذهب عظيم معروف فى بلاد السودان. ومن أعجب شئ فى هذه المدينة أن فيها معزا قصارى وعندهم شجر معلوم فتحتك هذه المعز إلى تلك الأشجار فتلقح من غير ذكر، ويذبحون ذكران المعز ويستحيون الإناث لاستغنائهم عن الفحل، وهذا معلوم عندهم غير منظور؛ حدث بذلك من دخل بلادهم من التجار والثقات، وهذا مثل جزيرة النساء التى ذكر المسعودى . ومن أعمال مدينة غانة ونظرها مدينة سامة ، ويعرف أهلها بالبكم، بينها وبين غانة مدة أربعة أيام. وهم يمشون عراة إلا أن المرأة تستر فرجها بسيور مضفورة، ونساؤهم يوفرن شعر العانة ويحلقن شعر الرأس. حدث رجل ثقة ممن دخل\nتلك المدينة إنه رأى منهن امرأة وقفت على رجل من العرب له لحية عظيمة طويلة، فتكلمت كلاما لم يفهمه العربى، فسأل الترجمان عن مقالتها فأخبره إنها تمنت أن يكون شعر لحيته فى عانتها، فغضب الأعرابى وأوسعها سبا. ويورث الرجل أكبر بنية ماله كله ويحرم الغير ولو كان أحب إليه. ولهم حذق بالرماية ويرمون بالسهام المسمومة. وبغربى غانة مدينة أنبارة : وهى مدينة كبيرة ولأهلها بأس شديد فى الحروب، وهم معاندون لملك غانة وإليها تسعة أيام.\nمدينة كوغة : وأهلها مسلمون وحواليها المشركون، وأكثر ما يتجهز إليها بالملح والودع والنحاس المسبوك والتاكوت وهو أنفق شئ عندهم للدبغ به. وحواليها معادن التبر، وهى أكثر بلاد السودان ذهبا. وبالقرب منها مدينة الوكن : وهى مدينة عظيمة يقال إن ملكها المعاصر لنا مسلم يخفى إسلامه. وببلاد غانة قوم يسمون بالهنيهين، من ذرية الجيش الذي كان بنوا أمية أنفذوه إلى غانة فى صدر الإسلام إلى بلاد السودان، وهم بيض الألوان حسان الوجوه لا يتناكحون فى السودان كثيرا. وإذا ست من غانة إلى جهة الشرق فإنك تسير فى بلاد السودان كثيرا وفى قبائل من البربر رحالة وهم مسلمون. وتسير مراحل كثيرة على النيل إلى مدينة تيرقىّ :\nوهى مدينة عظيمة لها أسواق حافلة يجتمع فيها أمم كثيرة من بلاد متفرقة من بلاد غانة وتادمكة وغيرها. وتعظم السلاحف بأرض تيرقى حتى تخرج عن القياس، وهى تحفر فى الأرض أسرابا يمشى فيها إنسان، وهم يأكلونها فلا يستطيعون إخراج واحد منها من تلك الأسراب إلا بعد شد الحبال فيها واجتماع\nالعدد الكثير. حدث رجل ثقة من المسافرين فى ذلك الطريق أن قوما انزلقوا فى بعض طريق تيرقى فغرسوا متاعهم، وبذلك الطريق الأرضة كثيرة وهى تفسد ما وجدت من متاع أو غيره، ولها بذلك الطريق أجحار وتخرج من التراب أكواما فوق أجحارها، ومن العجب أن ذلك التراب يرى ندى والماء هناك غير موجود على أبعد حفره، فلا يضع التجار أمتعتهم إلا على الحجارة المجموعة أو الخشب. فلما نزل أولئك التجار بذلك الموضع ارتاد كل واحد منهم لمتاعه حزنا من الأرض أو حجرا، فبدر أحدهم بالليل إلى صخرة كبيرة فيما ظن فأنزل عليها متاعه وكان وقر بعيرين، ثم نام بقرب رحله فلما انتبه من نومه سحرا لم يجد الصخرة ولا ما كان عليها، فارتاع فنادى بالويل والحرب فاجتمع إليه أهل القافلة يسألونه عن خطبه، فأخبرهم. فقالوا لو طرقك لص لذهب بالمتاع وبقيت الصخرة، فنظروا أثر سلحفاة ذاهبة بالموضع فاقتفوا أثرها ومشوا أميالا حتى أدركوا السلحفاة وحمل المتاع على ظهرها وهى تنهض به فى غير تكلف. فاعجب من عظم هذه السلحفاة التى تحمل وقر جملين.\nومدينة تيرقىّ على النيل ومن هناك يرجع نحو الجنوب. ويلى مدينة تيرقى إلى ناحية المغرب مدينة تادمكة : وهى مدينة كبيرة بين جبال وشعاب وهى أشبه البلاد بمكة كرمها الله؛ ومعنى تاد عندهم هيئة: على هيئة مكة.\nوأهلها بربر مسلمون وهم يتنقبون كما يتنقب بربر الصحراء، وعيشهم من اللبن واللحم وليس عندهم قمح ولا شعير، وعندهم حب تنبته الأرض من غير حرث يشبه الذرة. ولباسهم الثياب القطن المصبّغة، وملكهم يلبس الثياب الملونة فتكون عمامته حمراء وقميصه أصفر وسراويله زرق وما أشبه ذلك. ودنانيرهم تسمى الصلع لأنها من ذهب محض غير مختومة؛ ونساؤهم فائقات الجمال لا يعدل بهن نساء بلد حسنا. والزنا عندهم مباح وهن يتلقين التجار إذا أقبلوا إلى بلدهم ويتقارعن على الرجل الجميل منهم أيهن تحمله إلى منزلها. وبين مدينة تادمكة وغانة نحو ال مرحلة، وبينهما مدن وعمائر للسودان والبربر.\nفإذا سرت من غانة تريدها فأول ما تلقى مدينة سجنجوا : وهى على\nمراحل من غانة، وهى على النيل وهى آخر عمل غانة إلى الجنوب. ثم يصب النيل فى مدينة بوغرات : يسكنها قبيلة من صنهاجة يعرفون بمراسة.\nأخبر الفقيه عبد الملك أنه رأى فى بوغرات طائرا يشبه الخطاف يفهم من صوته قتل الحسين، يكون ذلك مرارا ويقول بكربلاء مرة واحدة؛ قال الفقيه سمعته وأنا ومن حضر من المسلمين معى. ثم من بوغرات إلى تيرقى المتقدم الذكر ثم إلى تادمكة. وإن أردت الطريق من تادمكة إلى القيروان فإنك تتوجه إلى ناحية الشمال، وتسير فى صحراء نحو يوما إلى بلد وارجلان فى طرف الصحراء مما يلى إفريقية: وهو بلد خصيب كثير النخل والبساتين، وفيه سبع مدن مسورة حصينة تقرب بعضها من بعض، أكبرها تسمى أغرم إن يكامن معناه بلاد الشهود، وفيه حصن العهود. وهى بلاد كثيرة الزرع والضرع والبساتين، كثيرة المياه، ولها أعجوبة ليست فى موضع من الأرض: يحفر الرجل بئرا يقوّم حفره ب دينار وأزيد فإن أرضهم صلبة، والماء بعيد يدرك على أزيد من قامة، فيجد على الماء طبقا من حجر صلد، فيستبشر عند وجوده، ويطعم أولياءه فرحا. ويدخل إليه من يعرف كيف ينقره مربوطا فى حبال وثيقة وينقره فيفور الماء فإن أبطأ الرجال فى رفعه حتى لا يدركه الماء هلك لحينه، ويبقى الماء يفور على مر الدهور، وهكذا هى جميع آبارهم؛ وهم يسقون جناتهم وزرعوهم ونخلهم. وتضرب ببلد وارجلان دنانير على نوع المرابطية، لكنها نازلة فيها تحميل كثير، والدنانير الورجلانية مشهورة . ومن ورجلان إلى بلد الجريد نحو يوما، ومن بلاد الجريد إلى القيروان أيام؛ وأهل القيروان بربر، وفيهم جمال كثير، ولا سيما نساؤهم، موصوفات بالحسن. ومن بلاد وارجلان إلى غدامس نحو يوما فى صحراء قليلة الماء؛ وفى هذه الصحراء معدن حجارة تشبه العقيق، وربما كان فى الحجر الواحد منها ألوانا من الحمرة والصفرة والبياض، وهذا\nالحجر أنفس شئ ببلاد السودان، غانة وغيرها، وهو عندهم مثل الياقوت وأجمل. وربما وجد من هذا الحجر فى النادر حجر كبير، وإذا وصل به إلى أهل غانة تغالوا فى ثمنه، وبذلوا فيه الرغائب؛ وهذا الحجر مثل الياقوت لا يعمل فيه الحديد شيئا، وإنما يصنع ويثقب بحجر آخر يسمى تنتواس كما يصنع بالياقوت، ويثقب بحجر السنبادج. ومعدن هذا الحجر لا يظهر حتى يذبح الإبل وينضح الموضع بدمها، فحينئذ تظهر هذه الحجارة وتلقط. وفى هذه الصحراء أيضا معدن الشب الأبيض الطيب الذي لا يوجد مثله ببلد، ومن هناك يحمل إلى جميع البلاد. ومن تادمكة أيام إلى مدينة كوكوا : وهى مدينة عظيمة فيها خلق كثير من السودان لا يحصى لهم عدد، وهى على النيل، ويقال إنما سموا كوكوا، لأن الذي يفهم من نغمة طبولهم كوكوا؛ وكذلك يذكر عن بلد زويلة إن الذي يفهم من نغمة طبولهم زويلة. ومن سار من مدينة كوكوا على شاطئ البحر غربا انتهى إلى مملكة يقال لها الدمدم ، يأكلون من وقع إليهم من البيضان، ولهم مملكة كبيرة وبلاد واسعة. وفى بلادهم قلعة عظيمة عليها صنم فى صورة امرأة وهم يعبدونه ويحجبونه. ومن غرائب بلاد السودان، أنه ينبت عندهم فى الرمال شجرة طويلة الساق دقيقة، يسمونها توريرى، لها ثمر كبير منتفخ، داخله صوف أبيض يغزل، ويصنع منه الثياب والأكسية فلا تؤثر النار فيها. أخبر بذلك من أخبره الفقيه عبد الملك، أن أهل اللامس من بلاد السودان ليس لهم لباس غير هذه الثياب، وأخبر أنه لو وقدت النار على هذه الثياب الدهر كله لم تؤثر فيها شيئا، غير أن النار تغسل من أوساخها؛ ومن هذا النوع الحجارة بوادى درعة، وقد تقدم ذكرها.\nقال الناظر: هنا انتهى ما وجدته من هذا الموضوع، ولقد أحسن واضعه، ورتب ما حقق، وهذا لعمرى أقرب وأخصر من غيره، ففيه ما فى غيره، وليس فى غيره ما فيه. وحققت وطرزت كتاب الواضع بما قيدت فى هذه المواضع، وأنا مؤمل أن أتفرغ لوضع كتاب كامل يحتوى على ذكر بلاد المغرب وممالكها إلى هذه الأيام السعيدة الإمامية، وأضيف إليها ما رفعته للحضرة العلية من مفاخر هذا الأمر العالى- أيد الله دوامه سنة [٥] [- ١١٨٤] وهو ما يزيد عندى من فتوحاته المستأصلة لشأفة الأعداء، إلى حيث يبلغ بى الزمان. فهو عملى وسعيى، ونصيبى من الجهاد ورأيى، إذ هو من أعمال القلوب، الماحية لما خط من الذنوب، والله تعالى يجعله عملا مقبولا لديه، فالاعتماد، والتكلان عليه، لا رب سواه.\nصلى الله على نبيه محمد، وعلى آله الطيبين الطاهرين، وسلم تسليما كثيرا إلى يوم الدين، والحمد لله رب العالمين."},t=[{id:"part1",title:"الباب الأول: مكة المكرمة والمدينة المنورة",sections:[{id:"1-1",title:"مكة المكرمة — حدود الحرم والجبال المحيطة",content:"يحدد الكتاب حدود حرم مكة من ناحية المدينة من ذى طوى على ثلاثة أميال، ومن طريق جدة على عشرة أميال، ومن طريق اليمن على سبعة أميال، ومن طريق العراق على ستة أميال، ومن طريق الطائف على أحد عشر ميلا، ليبلغ مجموع أميال الحرم ٣٧ ميلا. ومن جبالها المشهورة: جبل أبي قبيس وهو أول جبل خلقه الله تعالى وعليه منار إبراهيم، وجبل الخندمة العالي، وجبل قعيقعان، وجبل أجياد الأخضر الغربي."},{id:"1-2",title:"الكعبة المشرفة — الذرع والوصف الداخلي والخارجي",content:"طول وجه الكعبة الشق الذي فيه الباب من الركن الأسود إلى الركن الشامي ۲۷ ذراعا، وعرضها من اليماني إلى الركن الأسود ٣١ ذراعا ونصف ذراع. وقاع الكعبة مبسوط بالرخام الأبيض، وجدرها مرخمة بالرخام الأبيض قدر ٩ أذرع، وما فوق ذلك منقوش مذهب. ويذكر الكتاب صفة الحجر الأسود الواقع على ثلاثة أذرع من الأرض، وكيف أنه مكسور على ثلاثة قطع مرممة بالفضة."},{id:"1-3",title:"بئر زمزم والمقام والمسجد الحرام",content:"غور بئر زمزم من أعلاها إلى قاعها ۷۲ ذراعا، ومن وجه الماء إلى أعلى البئر ٣٤ ذراعا. وعلية قبة مربعة على ١٦ سارية منقوشة. وذكر صفة المقام الحجري الذي يحمل أثر قدمي إبراهيم عليه السلام مكسوا بغاشية فضة، ووصف أبواب المسجد الحرام البالغ عددها ١٧ باباً وسواريه البالغ عددها ٦٢١ عموداً مع الأعمدة والدارين المزيدتين."},{id:"1-4",title:"المدينة المنورة — المسجد النبوي والروضة الشريفة",content:"يصف الكتاب مسجد النبي صلى الله عليه وسلم بالمدينة، وروضته الشريفة التي بين القبر والمنبر والتي يبلغ طولها ٥٦ ذراعا، وموضع قبر النبي صلى الله عليه وسلم وصاحبيه أبي بكر وعمر رضي الله عنها في ثلث البلاط الأوسط من ناحية الشرق، إضافة إلى صفة المنبر والمحراب وأبواب المسجد وعدد عمدها البالغ ٢٧٦ عموداً."},{id:"1-5",title:"بقيع الغرقد ومسجد قبا وقبور الشهداء بأحد",content:"يصف المؤلف بقيع المدينة ومواضع قبور أهل البيت والصحابة، ثم مسجد قبا الواقع على ثلاثة أميال من المدينة، وبئر قبا التي مضمض فيها النبي صلى الله عليه وسلم، ويختتم هذا القسم بوصف قبور الشهداء عند سفح جبل أحد وحظيرتهم التي تضم سبع وثلاثين شهيداً وفي مقدمتهم حمزة بن عبد المطلب رضي الله عنه أسد الله وأسد رسوله."}]},{id:"part2",title:"الباب الثاني: مصر وعجائبها",sections:[{id:"2-1",title:"نيل مصر وعجائبه وخصوبة أراضيه",content:"يصف المؤلف نيل مصر وأمياله، وأنه مخالف لجميع أنهار الدنيا لأنه يجري من الجنوب إلى الشمال. ويذكر أطواره الأربعة في السنة كأنها درة بيضاء، مسكة سوداء، زبرجدة خضراء، وسبيكة حمراء. كما يتحدث عن التماسيح والسمك الرعاد والجبل الهامد الذي ترتعش السيوف عند مسه."},{id:"2-2",title:"أخبار ملوك مصر القدماء وبناء الأهرامات",content:"يسرد الكتاب روايات ملوك مصر الأوائل منذ نقراوش بن أضرم ومصرام بن حام بن نوح، وقصة بناء الأهرامات والبرابي من حجارة صلدة ورصاص مظبوط، لتكون خزائن للعلوم والكنوز، ويذكر محاولة الخليفة المأمون فتح أحد الأهرامات وما وجده في داخله من عجائب."},{id:"2-3",title:"الإسكندرية ومنارها العجيب",content:"وصف مفصل لمدينة الإسكندرية وأسوارها ومنارها العظيم الذي كان يرتفع على عدة طبقات، ويحتوي على المرآة العجيبة التي كانت تعكس سفن الأعداء وتكشفها من مسافات بعيدة. كما يتناول قصة فتح مصر على يد الصحابي الجليل عمرو بن العاص رضي الله عنه ومفاوضاته مع المقوقس."},{id:"2-4",title:"مدن مصر وعجائبها: الفسطاط، الفيوم، وتنيس",content:"استعراض لأبرز مدن مصر وعجائبها العمرانية والزراعية: مدينة الفسطاط ومسجد عمرو بن العاص، وقليم الفيوم وهندسته العجيبة في توزيع مياه النيل بفضل يوسف عليه السلام، ومدينتي تنيس ودمياط وصناعتهما للنسيج الرفيع والثياب الفاخرة (البدنة)، ومعادن الزمرد بصحراء قوص وأسوان."}]},{id:"part3",title:"الباب الثالث: إفريقية (تونس والجزائر)",sections:[{id:"3-1",title:"طرابلس والقيروان وتونس وسفاقس",content:"وصف لمدن الساحل الإفريقي وقرطاجنة وآثارها العجيبة، ومدينة القيروان ومسجدها العظيم الذي أسسه عقبة بن نافع، وما فيها من صهاريج ومصانع للمياه. ويشير إلى مدينة سفاقس وزيتها الذي يُصدر إلى صقلية وإيطاليا، ومدينة تونس وموقعها التجاري والزراعي الخصب."},{id:"3-2",title:"بوسة، المهدية، وبجاية",content:"وصف لمدينة المهدية وبنائها الحصين ومراسيها المحمية بسلاسل الحديد، ومدينة سوسة وما فيها من عجائب البناء فوق الماء، ومدينة بجاية بقلعتها الحصينة وأنهارها وبساتينها الغناء التي تشكل حاضرة كبرى في بلاد المغرب."}]},{id:"part4",title:"الباب الرابع: المغرب الأقصى",sections:[{id:"4-1",title:"فاس ومراكش وعواصم الموحدين",content:"يستعرض الكتاب عواصم المغرب الأقصى في العهد الموحدي، فوصف فاس وجامع القرويين وأسواقها وأنهارها، ومدينة مراكش في أوج عصرها مع إسهامات خلفاء الموحدين (وعلى رأسهم يعقوب المنصور) من قصور وبساتين ومنشآت عمرانية ومياه."},{id:"4-2",title:"أغمات وسوس الأقصى والصحراء",content:"وصف مدينة أغمات التاريخية وسوس الأقصى وتارودانت، ومدن الصحراء والواحات، والعيون العجيبة التي تتغير ألوانها، ومدن سجلماسة ودرعة."},{id:"4-3",title:"طنجة وبحر الظلمات ومضيق جبل طارق",content:"وصف مدينة طنجة باعتبارها أقدم مدن المغرب الأقصى على ساحل البحر ومضيق جبل طارق (بحر الظلمات والمحيط الأطلسي)، والآثار القديمة والقنوات المائية وقنطرة الزقاق التي كانت تصل المغرب بالأندلس قبل أن يطغي عليها البحر."}]},{id:"part5",title:"الباب الخامس: بلاد السودان",sections:[{id:"5-1",title:"بلاد السودان وغانة — المدن و العجائب وسير الملوك",content:"يصف المؤلف بلاد السودان ومدنها المشهورة: صنغانة وتكرور وسلى وقلنبوا وترنكة، ثم مملكة غانة وعاصمتاها وأخبار ملوكها، ومدينة غياروا ومعادن الذهب، ومدينة أودغست وما يجلب منها، وممالك كوكوا وتادمكة والدمدم، وما في تلك البلاد من عجائب الخلق والحيوان والنبات."}]}];t.forEach(n=>{n.sections.forEach(n=>{a[n.id]&&(n.content=a[n.id])})})}}]);